window.MT_DATA['th'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours en Thaïlande, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Bangkok","phrases":[{"fr":"Bienvenue à Bangkok !","tgt":"ยินดีต้อนรับสู่กรุงเทพครับ","ro":"Yin-dii tâwn-ráp sùu Krung-thêep khráp.","lit":"heureux · accueillir · vers · Bangkok · [politesse]"},{"fr":"Moi, je viens de France.","tgt":"ผมมาจากฝรั่งเศสครับ","ro":"Phǒm maa jàak fà-ràng-sèet khráp.","lit":"je (homme) · venir · de · France · [politesse]"},{"fr":"Mon ami vient de Paris.","tgt":"เพื่อนผมมาจากปารีสครับ","ro":"Phûean phǒm maa jàak Paa-rîit khráp.","lit":"ami · je · venir · de · Paris · [politesse]"},{"fr":"Je vais à l'hôtel.","tgt":"ผมไปโรงแรมครับ","ro":"Phǒm pai roong-raem khráp.","lit":"je · aller · hôtel · [politesse]"},{"fr":"Hier, je suis allé au marché.","tgt":"เมื่อวานผมไปตลาดครับ","ro":"Mûea-waan phǒm pai tà-làat khráp.","lit":"hier · je · aller · marché · [politesse]"},{"fr":"Demain, je vais travailler.","tgt":"พรุ่งนี้ผมไปทำงานครับ","ro":"Phrûng-níi phǒm pai tham-ngaan khráp.","lit":"demain · je · aller · faire · travail · [politesse]"},{"fr":"Ils habitent à Bangkok.","tgt":"พวกเขาอยู่กรุงเทพครับ","ro":"Phûak-khǎo yùu Krung-thêep khráp.","lit":"ils · habiter · Bangkok · [politesse]"},{"fr":"Je prends le métro aérien.","tgt":"ผมนั่งรถไฟฟ้าครับ","ro":"Phǒm nâng rót-fai-fáa khráp.","lit":"je · s'asseoir (prendre) · train · électrique · [politesse]"},{"fr":"Je parle un peu thaï.","tgt":"ผมพูดภาษาไทยได้นิดหน่อยครับ","ro":"Phǒm phûut phaa-sǎa thai dâai nít-nòi khráp.","lit":"je · parler · langue · thaï · pouvoir · un peu · [politesse]"},{"fr":"Elle parle très bien thaï.","tgt":"เขาพูดภาษาไทยเก่งมากครับ","ro":"Khǎo phûut phaa-sǎa thai kèng mâak khráp.","lit":"elle · parler · langue · thaï · doué · très · [politesse]"}],"tip":{"title":"Pas de conjugaison : le verbe ne change jamais","example":"Hier, je suis allé au marché. — เมื่อวานผม<b>ไป</b>ตลาดครับ","body":"En thaï, le verbe ne se conjugue jamais : pas de terminaisons, pas de temps, pas d'accord. « Pai » veut dire aller, et l'on dit « phǒm pai » pour je vais, « khǎo pai » pour il va, « rao pai » pour nous allons. Pour parler du passé ou du futur, on ajoute simplement un mot de temps, souvent au début de la phrase. Décomposons « Mûea-waan phǒm pai tà-làat khráp » : « mûea-waan » hier, « phǒm » je, « pai » aller, « tà-làat » marché, et « khráp » pour être poli. Littéralement : hier, je aller marché. Pour demain, on garde exactement le même verbe : « Phrûng-níi phǒm pai tham-ngaan », demain je vais travailler. C'est une excellente nouvelle : un verbe appris est un verbe que vous savez déjà utiliser partout. Astuce : pensez à un petit enfant qui dit « moi aller marché hier », c'est exactement la logique du thaï.","exampleRo":"Mûea-waan phǒm pai tà-làat khráp.","lit":"hier · je · aller · marché · [politesse]","say":{"Pai":"ไป","phǒm pai":"ผมไป","khǎo pai":"เขาไป","rao pai":"เราไป","Mûea-waan phǒm pai tà-làat khráp":"เมื่อวานผมไปตลาดครับ","mûea-waan":"เมื่อวาน","phǒm":"ผม","pai":"ไป","tà-làat":"ตลาด","khráp":"ครับ","Phrûng-níi phǒm pai tham-ngaan":"พรุ่งนี้ผมไปทำงาน"}}},{"title":"Au stand de riz au poulet","phrases":[{"fr":"Un riz au poulet, s'il vous plaît.","tgt":"ขอข้าวมันไก่หนึ่งจานครับ","ro":"Khǎw khâaw-man-kài nùeng jaan khráp.","lit":"demander · riz · gras · poulet · un · assiette · [politesse]"},{"fr":"Du riz nature, s'il vous plaît.","tgt":"ขอข้าวสวยครับ","ro":"Khǎw khâaw-sǔai khráp.","lit":"demander · riz · beau · [politesse]"},{"fr":"Un chien vient vers nous.","tgt":"หมาเดินมาหาเราครับ","ro":"Mǎa doen maa hǎa rao khráp.","lit":"chien · marcher · venir · chercher · nous · [politesse]"},{"fr":"Le poulet est très bon.","tgt":"ไก่อร่อยมากครับ","ro":"Kài à-ròi mâak khráp.","lit":"poulet · délicieux · très · [politesse]"},{"fr":"Le stand est près, pas loin.","tgt":"ร้านอยู่ใกล้ ไม่ไกลครับ","ro":"Ráan yùu klâi, mâi klai khráp.","lit":"stand · se trouver · près · ne pas · loin · [politesse]"},{"fr":"J'ai très faim.","tgt":"หิวมากครับ","ro":"Hǐw mâak khráp.","lit":"avoir faim · très · [politesse]"},{"fr":"Ce stand vient d'ouvrir.","tgt":"ร้านนี้เปิดใหม่ครับ","ro":"Ráan níi pòet mài khráp.","lit":"stand · ce · ouvrir · nouveau · [politesse]"},{"fr":"L'eau n'est pas fraîche.","tgt":"น้ำไม่เย็นครับ","ro":"Náam mâi yen khráp.","lit":"eau · ne pas · frais · [politesse]"},{"fr":"Je regarde les infos sur mon téléphone.","tgt":"ผมดูข่าวในมือถือครับ","ro":"Phǒm duu khàaw nai mue-thǔe khráp.","lit":"je · regarder · nouvelles · dans · téléphone portable · [politesse]"},{"fr":"Un peu plus de riz, s'il vous plaît.","tgt":"ขอข้าวเพิ่มอีกนิดครับ","ro":"Khǎw khâaw phôem ìik nít khráp.","lit":"demander · riz · ajouter · encore · un peu · [politesse]"}],"tip":{"title":"Les cinq tons du thaï","example":"Le stand est près, pas loin. — ร้านอยู่<b>ใกล้</b> ไม่<b>ไกล</b>ครับ","body":"Le thaï a cinq tons, et le ton change le sens du mot : c'est la mélodie de chaque syllabe. Le ton moyen reste plat, comme dans « maa », venir. Le ton bas reste grave et un peu descendant, comme dans « kài », le poulet. Le ton descendant monte puis chute, comme un « ah ! » de surprise : « khâaw », le riz. Le ton haut est aigu et tendu, comme dans « náam », l'eau, et le ton montant part du bas pour remonter, comme une question étonnée : « mǎa », le chien. Écoutez « klâi », près, avec un ton descendant, et « klai », loin, avec un ton plat : dans « ráan yùu klâi, mâi klai », le stand est près, pas loin, seule la mélodie fait la différence. Au début, n'hésitez pas à exagérer les mélodies, comme si vous chantiez. Astuce : dans la transcription, l'accent grave descend, l'accent aigu monte, le circonflexe dessine une montagne et le petit v dessine une vallée.","exampleRo":"Ráan yùu klâi, mâi klai khráp.","lit":"stand · se trouver · près · ne pas · loin · [politesse]","say":{"maa":"มา","kài":"ไก่","khâaw":"ข้าว","náam":"น้ำ","mǎa":"หมา","klâi":"ใกล้","klai":"ไกล","ráan yùu klâi, mâi klai":"ร้านอยู่ใกล้ ไม่ไกล"}}},{"title":"Premiers mots polis à la supérette","phrases":[{"fr":"Bonjour, je cherche de l'eau.","tgt":"สวัสดีครับ ผมหาน้ำครับ","ro":"Sà-wàt-dii khráp, phǒm hǎa náam khráp.","lit":"bonjour · [politesse] · je (homme) · chercher · eau · [politesse]"},{"fr":"Je suis pressée.","tgt":"ฉันรีบค่ะ","ro":"Chǎn rîip khâ.","lit":"je (femme) · se dépêcher · [politesse]"},{"fr":"Désolée, où sont les sacs ?","tgt":"ขอโทษค่ะ ถุงอยู่ที่ไหนคะ","ro":"Khǎw-thôot khâ, thǔng yùu thîi-nǎi khá?","lit":"pardon · [politesse] · sac · se trouver · où · [politesse]"},{"fr":"Ça fait combien ?","tgt":"เท่าไรครับ","ro":"Thâo-rài khráp?","lit":"combien · [politesse]"},{"fr":"Je suis ravie de vous rencontrer.","tgt":"ยินดีที่ได้รู้จักค่ะ","ro":"Yin-dii thîi dâai rúu-jàk khâ.","lit":"heureux · que · obtenir · connaître · [politesse]"},{"fr":"Je prends un café glacé.","tgt":"ผมเอากาแฟเย็นครับ","ro":"Phǒm ao kaa-fae yen khráp.","lit":"je (homme) · prendre · café · frais · [politesse]"},{"fr":"Oui, entendu.","tgt":"ครับ","ro":"Khráp.","lit":"[politesse] (oui)"},{"fr":"Je suis un peu perdue.","tgt":"ฉันหลงทางนิดหน่อยค่ะ","ro":"Chǎn lǒng-thaang nít-nòi khâ.","lit":"je (femme) · perdre · chemin · un peu · [politesse]"},{"fr":"Oui, je suis française.","tgt":"ค่ะ ฉันเป็นคนฝรั่งเศสค่ะ","ro":"Khâ, chǎn pen khon fà-ràng-sèet khâ.","lit":"[politesse] (oui) · je (femme) · être · personne · France · [politesse]"},{"fr":"Merci, je suis très contente.","tgt":"ขอบคุณค่ะ ฉันดีใจมากค่ะ","ro":"Khàwp-khun khâ, chǎn dii-jai mâak khâ.","lit":"merci · [politesse] · je (femme) · content · très · [politesse]"}],"tip":{"title":"« Khráp » et « khâ » : les petits mots de politesse","example":"Désolée, où sont les sacs ? — ขอโทษ<b>ค่ะ</b> ถุงอยู่ที่ไหน<b>คะ</b>","body":"En thaï, on termine presque chaque phrase polie par un petit mot qui ne se traduit pas : c'est la marque du respect. Un homme dit « khráp », avec un ton haut, et une femme dit « khâ », avec un ton descendant. Dans une question, la femme change de mélodie et dit « khá », avec un ton haut. Écoutez « Khǎw-thôot khâ, thǔng yùu thîi-nǎi khá ? », pardon, où sont les sacs : le premier « khâ » descend, le second « khá » monte, car c'est une question. Ces petits mots servent aussi à dire oui : un simple « khráp » ou « khâ » veut dire oui, d'accord, je vous écoute. Sans eux, une phrase peut sembler sèche, surtout avec un inconnu. Astuce : c'est le genre de la personne qui parle qui compte, jamais celui de la personne à qui l'on parle.","exampleRo":"Khǎw-thôot khâ, thǔng yùu thîi-nǎi khá?","lit":"pardon · [politesse] · sac · se trouver · où · [politesse]","say":{"Khráp":"ครับ","khâ":"ค่ะ","khráp":"ครับ","khá":"คะ","Khǎw-thôot khâ, thǔng yùu thîi-nǎi khá ?":"ขอโทษค่ะ ถุงอยู่ที่ไหนคะ"}}},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Moi, je m'appelle Thomas.","tgt":"ผมชื่อโทมัสครับ","ro":"Phǒm chûe Thoo-mát khráp.","lit":"je (homme) · s'appeler · Thomas · [politesse]"},{"fr":"Et vous, comment vous appelez-vous ?","tgt":"แล้วคุณชื่ออะไรครับ","ro":"Láew khun chûe à-rai khráp?","lit":"et puis · vous · s'appeler · quoi · [politesse]"},{"fr":"Je m'appelle Nok, je suis votre voisine.","tgt":"ฉันชื่อนกค่ะ เป็นเพื่อนบ้านคุณค่ะ","ro":"Chǎn chûe Nók khâ, pen phûean-bâan khun khâ.","lit":"je (femme) · s'appeler · Nok · [politesse] · être · voisin · vous · [politesse]"},{"fr":"Vous habitez à quel étage ?","tgt":"คุณอยู่ชั้นไหนครับ","ro":"Khun yùu chán nǎi khráp?","lit":"vous · habiter · étage · lequel · [politesse]"},{"fr":"J'habite au dixième étage.","tgt":"ผมอยู่ชั้นสิบครับ","ro":"Phǒm yùu chán sìp khráp.","lit":"je (homme) · habiter · étage · dix · [politesse]"},{"fr":"Elle est très gentille.","tgt":"เขาใจดีมากครับ","ro":"Khǎo jai-dii mâak khráp.","lit":"elle · cœur · bon · très · [politesse]"},{"fr":"Il travaille à Silom.","tgt":"เขาทำงานที่สีลมครับ","ro":"Khǎo tham-ngaan thîi Sǐi-lom khráp.","lit":"il · faire · travail · à · Silom · [politesse]"},{"fr":"Nous sommes voisins.","tgt":"เราเป็นเพื่อนบ้านกันครับ","ro":"Rao pen phûean-bâan kan khráp.","lit":"nous · être · voisin · ensemble · [politesse]"},{"fr":"Vous venez boire un café chez moi ?","tgt":"มาดื่มกาแฟที่ห้องผมไหมครับ","ro":"Maa dùem kaa-fae thîi hâwng phǒm mái khráp?","lit":"venir · boire · café · à · chambre · je · [question] · [politesse]"},{"fr":"Volontiers, c'est gentil !","tgt":"ยินดีค่ะ ใจดีจังเลยค่ะ","ro":"Yin-dii khâ, jai-dii jang loei khâ.","lit":"avec plaisir · [politesse] · cœur · bon · tellement · vraiment · [politesse]"}],"tip":{"title":"Les pronoms : « phǒm, chǎn, khun »","example":"Je m'appelle Nok, je suis votre voisine. — <b>ฉัน</b>ชื่อนกค่ะ เป็นเพื่อนบ้าน<b>คุณ</b>ค่ะ","body":"Pour dire je, le thaï distingue l'homme et la femme : un homme dit « phǒm » et une femme dit « chǎn », tous deux avec un ton montant. Pour dire vous, la forme polie passe-partout est « khun ». Pour il ou elle, on dit « khǎo », sans distinction, et pour nous, « rao ». Décomposons « Chǎn chûe Nók khâ » : je, s'appeler, Nok, petit mot poli féminin, donc je m'appelle Nok. Le pronom ne change jamais de forme : « khun » veut dire vous, mais aussi votre, comme dans « phûean-bâan khun », votre voisin, littéralement voisin vous. Très souvent, les Thaïlandais omettent même le pronom quand on comprend qui parle : « pai nǎi ? », où allez-vous, se dit sans aucun pronom. Astuce : un homme dit « phǒm » et « khráp », une femme dit « chǎn » et « khâ », gardez ces deux paires bien ensemble.","exampleRo":"Chǎn chûe Nók khâ, pen phûean-bâan khun khâ.","lit":"je (femme) · s'appeler · Nok · [politesse] · être · voisin · vous · [politesse]","say":{"phǒm":"ผม","chǎn":"ฉัน","khun":"คุณ","khǎo":"เขา","rao":"เรา","Chǎn chûe Nók khâ":"ฉันชื่อนกค่ะ","phûean-bâan khun":"เพื่อนบ้านคุณ","pai nǎi ?":"ไปไหน","khráp":"ครับ","khâ":"ค่ะ","phǒm, chǎn, khun":"ผม ฉัน คุณ"}}},{"title":"Se présenter","phrases":[{"fr":"Je suis professeur.","tgt":"ผมเป็นครูครับ","ro":"Phǒm pen khruu khráp.","lit":"je (homme) · être · professeur · [politesse]"},{"fr":"Elle est médecin.","tgt":"เขาเป็นหมอครับ","ro":"Khǎo pen mǎw khráp.","lit":"elle · être · médecin · [politesse]"},{"fr":"Je suis étudiante.","tgt":"ฉันเป็นนักศึกษาค่ะ","ro":"Chǎn pen nák-sùek-sǎa khâ.","lit":"je (femme) · être · étudiant · [politesse]"},{"fr":"Nok est ma collègue.","tgt":"นกเป็นเพื่อนร่วมงานผมครับ","ro":"Nók pen phûean-rûam-ngaan phǒm khráp.","lit":"Nok · être · ami · partager · travail · je · [politesse]"},{"fr":"Il est thaïlandais.","tgt":"เขาเป็นคนไทยครับ","ro":"Khǎo pen khon thai khráp.","lit":"il · être · personne · thaï · [politesse]"},{"fr":"Vous êtes chauffeur de tuk-tuk ?","tgt":"คุณเป็นคนขับตุ๊กตุ๊กใช่ไหมครับ","ro":"Khun pen khon-khàp túk-túk châi mái khráp?","lit":"vous · être · conducteur · tuk-tuk · exact · [question] · [politesse]"},{"fr":"Non, je suis cuisinier.","tgt":"ไม่ใช่ครับ ผมเป็นพ่อครัวครับ","ro":"Mâi châi khráp, phǒm pen phâw-khrua khráp.","lit":"ne pas · exact · [politesse] · je · être · cuisinier · [politesse]"},{"fr":"Mon père est ingénieur.","tgt":"พ่อผมเป็นวิศวกรครับ","ro":"Phâw phǒm pen wít-sà-wá-kawn khráp.","lit":"père · je · être · ingénieur · [politesse]"},{"fr":"Nous sommes touristes.","tgt":"เราเป็นนักท่องเที่ยวครับ","ro":"Rao pen nák-thâwng-thîaw khráp.","lit":"nous · être · touriste · [politesse]"},{"fr":"Bangkok est une très grande ville.","tgt":"กรุงเทพเป็นเมืองใหญ่มากครับ","ro":"Krung-thêep pen mueang yài mâak khráp.","lit":"Bangkok · être · ville · grand · très · [politesse]"}],"tip":{"title":"« Pen » : être, entre deux noms","example":"Je suis professeur. — ผม<b>เป็น</b>ครูครับ","body":"Le verbe « pen » sert à dire être, mais seulement entre deux noms, pour dire ce que l'on est : un métier, une nationalité, un rôle. « Phǒm pen khruu khráp » se décompose ainsi : je, être, professeur, petit mot poli, donc je suis professeur. De la même façon, « khǎo pen mǎw » veut dire il ou elle est médecin, et « rao pen nák-thâwng-thîaw », nous sommes touristes. Attention, on ne met jamais « pen » devant un adjectif : pour dire c'est bon, on ne dit pas « pen dii ». Pour dire non, on n'utilise pas « mâi pen » mais « mâi châi », qui veut dire ce n'est pas ça : « mâi châi khráp, phǒm pen phâw-khrua », non, je suis cuisinier. Et comme tous les verbes thaïs, « pen » ne change jamais de forme. Astuce : imaginez un signe égal, « pen » relie toujours un nom à un autre nom.","exampleRo":"Phǒm pen khruu khráp.","lit":"je (homme) · être · professeur · [politesse]","say":{"Pen":"เป็น","pen":"เป็น","Phǒm pen khruu khráp":"ผมเป็นครูครับ","khǎo pen mǎw":"เขาเป็นหมอ","rao pen nák-thâwng-thîaw":"เราเป็นนักท่องเที่ยว","pen dii":"เป็นดี","mâi pen":"ไม่เป็น","mâi châi":"ไม่ใช่","mâi châi khráp, phǒm pen phâw-khrua":"ไม่ใช่ครับ ผมเป็นพ่อครัว"}}},{"title":"Dans le métro aérien","phrases":[{"fr":"Ce train va à Siam ?","tgt":"รถไฟฟ้าขบวนนี้ไปสยามไหมครับ","ro":"Rót-fai-fáa khà-buan níi pai Sà-yǎam mái khráp?","lit":"métro aérien · rame · ce · aller · Siam · [question] · [politesse]"},{"fr":"Vous allez bien ce matin ?","tgt":"เช้านี้สบายดีไหมครับ","ro":"Cháao níi sà-baai dii mái khráp?","lit":"matin · ce · à l'aise · bien · [question] · [politesse]"},{"fr":"Vous avez froid dans le métro ?","tgt":"ในรถหนาวไหมครับ","ro":"Nai rót nǎaw mái khráp?","lit":"dans · véhicule · froid · [question] · [politesse]"},{"fr":"Oui, un peu froid.","tgt":"หนาวนิดหน่อยครับ","ro":"Nǎaw nít-nòi khráp.","lit":"froid · un peu · [politesse]"},{"fr":"Cette place est libre ?","tgt":"ที่นี่ว่างไหมครับ","ro":"Thîi-nîi wâang mái khráp?","lit":"place · ici · libre · [question] · [politesse]"},{"fr":"Oui, asseyez-vous.","tgt":"ว่างครับ เชิญนั่งครับ","ro":"Wâang khráp, choen nâng khráp.","lit":"libre · [politesse] · inviter · s'asseoir · [politesse]"},{"fr":"Vous descendez à la prochaine ?","tgt":"คุณลงสถานีหน้าไหมครับ","ro":"Khun long sà-thǎa-nii nâa mái khráp?","lit":"vous · descendre · station · devant (prochain) · [question] · [politesse]"},{"fr":"Vous êtes fatigué ?","tgt":"เหนื่อยไหมครับ","ro":"Nùeai mái khráp?","lit":"fatigué · [question] · [politesse]"},{"fr":"Le métro aérien est rapide ?","tgt":"รถไฟฟ้าเร็วไหมครับ","ro":"Rót-fai-fáa reo mái khráp?","lit":"métro aérien · rapide · [question] · [politesse]"},{"fr":"Oui, très rapide !","tgt":"เร็วมากครับ","ro":"Reo mâak khráp.","lit":"rapide · très · [politesse]"}],"tip":{"title":"« Mái » : transformer une phrase en question","example":"Cette place est libre ? — ที่นี่ว่าง<b>ไหม</b>ครับ","body":"Pour poser une question fermée, celle qui attend oui ou non, il suffit d'ajouter « mái » à la fin de la phrase. Pas d'inversion, pas de est-ce que : on dit la phrase normale, puis on ajoute ce petit mot avec un ton haut, juste avant « khráp ». « Thîi-nîi wâang mái khráp ? » se décompose ainsi : place ici, libre, question, petit mot poli, donc cette place est libre ? Pour répondre oui, on répète simplement le verbe ou l'adjectif : « wâang khráp », libre. Pour répondre non, on met « mâi » devant : « mâi wâang khráp », pas libre. Autres exemples : « nǎaw mái ? », vous avez froid ? et « reo mái ? », c'est rapide ? Astuce : pensez au petit « hein ? » que l'on ajoute en français à la fin d'une phrase, mais en plus poli et avec une voix qui monte.","exampleRo":"Thîi-nîi wâang mái khráp?","lit":"place · ici · libre · [question] · [politesse]","say":{"Mái":"ไหม","mái":"ไหม","khráp":"ครับ","Thîi-nîi wâang mái khráp ?":"ที่นี่ว่างไหมครับ","wâang khráp":"ว่างครับ","mâi":"ไม่","mâi wâang khráp":"ไม่ว่างครับ","nǎaw mái ?":"หนาวไหม","reo mái ?":"เร็วไหม"}}},{"title":"Un pad thaï pas épicé","phrases":[{"fr":"Un pad thaï, s'il vous plaît.","tgt":"ขอผัดไทยหนึ่งจานครับ","ro":"Khǎw phàt-thai nùeng jaan khráp.","lit":"demander · pad thaï · un · assiette · [politesse]"},{"fr":"Pas épicé, s'il vous plaît.","tgt":"ไม่เผ็ดนะครับ","ro":"Mâi phèt ná khráp.","lit":"ne pas · épicé · [douceur] · [politesse]"},{"fr":"Je ne mange pas de cacahuètes.","tgt":"ผมไม่กินถั่วครับ","ro":"Phǒm mâi kin thùa khráp.","lit":"je · ne pas · manger · arachide · [politesse]"},{"fr":"Sans sucre, s'il vous plaît.","tgt":"ไม่ใส่น้ำตาลครับ","ro":"Mâi sài náam-taan khráp.","lit":"ne pas · mettre · sucre · [politesse]"},{"fr":"Ce n'est pas cher.","tgt":"ไม่แพงครับ","ro":"Mâi phaeng khráp.","lit":"ne pas · cher · [politesse]"},{"fr":"Je ne suis pas thaïlandais.","tgt":"ผมไม่ใช่คนไทยครับ","ro":"Phǒm mâi châi khon thai khráp.","lit":"je · ne pas · exact · personne · thaï · [politesse]"},{"fr":"Désolé, je ne comprends pas bien.","tgt":"ขอโทษครับ ผมไม่ค่อยเข้าใจครับ","ro":"Khǎw-thôot khráp, phǒm mâi khâwy khâo-jai khráp.","lit":"pardon · [politesse] · je · ne pas · très · comprendre · [politesse]"},{"fr":"La vendeuse n'est pas là.","tgt":"แม่ค้าไม่อยู่ครับ","ro":"Mâe-kháa mâi yùu khráp.","lit":"vendeuse · ne pas · être là · [politesse]"},{"fr":"Je n'ai pas faim.","tgt":"ผมไม่หิวครับ","ro":"Phǒm mâi hǐw khráp.","lit":"je · ne pas · avoir faim · [politesse]"},{"fr":"Ce n'est pas mon plat.","tgt":"นี่ไม่ใช่จานของผมครับ","ro":"Nîi mâi châi jaan khǎwng phǒm khráp.","lit":"ceci · ne pas · exact · assiette · [de] · je · [politesse]"}],"tip":{"title":"« Mâi » : la négation, attention au ton","example":"Pas épicé, s'il vous plaît. — <b>ไม่</b>เผ็ดนะครับ","body":"Pour dire non, on place « mâi » juste devant le verbe ou l'adjectif, comme un ne pas français réduit à un seul mot. « Mâi phèt ná khráp » se décompose ainsi : pas, épicé, petit mot de douceur, petit mot poli, donc pas épicé, s'il vous plaît. Attention au ton : « mâi », la négation, a un ton descendant, alors que « mái », la question, a un ton haut. On peut même les entendre l'un après l'autre : « phèt mái ? », c'est épicé ? et la réponse « mâi phèt », pas épicé. D'autres exemples utiles : « mâi phaeng », pas cher, et « phǒm mâi hǐw », je n'ai pas faim. Pour nier « pen », on dit « mâi châi » : « phǒm mâi châi khon thai », je ne suis pas thaïlandais. Astuce : la négation descend comme une porte qui se ferme, la question monte comme une main qui se lève.","exampleRo":"Mâi phèt ná khráp.","lit":"ne pas · épicé · [douceur] · [politesse]","say":{"Mâi":"ไม่","mâi":"ไม่","Mâi phèt ná khráp":"ไม่เผ็ดนะครับ","mái":"ไหม","phèt mái ?":"เผ็ดไหม","mâi phèt":"ไม่เผ็ด","mâi phaeng":"ไม่แพง","phǒm mâi hǐw":"ผมไม่หิว","pen":"เป็น","mâi châi":"ไม่ใช่","phǒm mâi châi khon thai":"ผมไม่ใช่คนไทย"}}},{"title":"La cuisine de rue","phrases":[{"fr":"Le som tam est très épicé.","tgt":"ส้มตำเผ็ดมากครับ","ro":"Sôm-tam phèt mâak khráp.","lit":"som tam · épicé · très · [politesse]"},{"fr":"La nourriture est délicieuse ici.","tgt":"อาหารที่นี่อร่อยครับ","ro":"Aa-hǎan thîi-nîi à-ròi khráp.","lit":"nourriture · ici · délicieux · [politesse]"},{"fr":"Aujourd'hui, il fait vraiment chaud.","tgt":"วันนี้ร้อนมากครับ","ro":"Wan-níi ráwn mâak khráp.","lit":"aujourd'hui · chaud · très · [politesse]"},{"fr":"Le riz est trop salé.","tgt":"ข้าวเค็มไปครับ","ro":"Khâaw khem pai khráp.","lit":"riz · salé · aller (trop) · [politesse]"},{"fr":"Le jus de mangue est sucré.","tgt":"น้ำมะม่วงหวานครับ","ro":"Náam-má-mûang wǎan khráp.","lit":"eau · mangue · sucré · [politesse]"},{"fr":"Il y a beaucoup de monde au marché.","tgt":"ตลาดคนเยอะมากครับ","ro":"Tà-làat khon yóe mâak khráp.","lit":"marché · gens · nombreux · très · [politesse]"},{"fr":"Je suis bien rassasié.","tgt":"อิ่มมากครับ","ro":"Ìm mâak khráp.","lit":"rassasié · très · [politesse]"},{"fr":"Ce stand est vraiment bon marché.","tgt":"ร้านนี้ถูกมากครับ","ro":"Ráan níi thùuk mâak khráp.","lit":"stand · ce · bon marché · très · [politesse]"},{"fr":"Vous êtes très doué !","tgt":"คุณเก่งมากครับ","ro":"Khun kèng mâak khráp.","lit":"vous · doué · très · [politesse]"},{"fr":"Le thé glacé est un peu trop sucré.","tgt":"ชาเย็นหวานไปหน่อยครับ","ro":"Chaa-yen wǎan pai nòi khráp.","lit":"thé · froid · sucré · aller (trop) · un peu · [politesse]"}],"tip":{"title":"L'adjectif sans verbe être : « aa-hǎan à-ròi »","example":"La nourriture est délicieuse ici. — อาหารที่นี่<b>อร่อย</b>ครับ","body":"En thaï, les adjectifs fonctionnent comme des verbes : ils n'ont pas besoin du verbe être. Pour dire la nourriture est délicieuse, on dit simplement « aa-hǎan à-ròi », littéralement nourriture délicieuse. Décomposons « Aa-hǎan thîi-nîi à-ròi khráp » : nourriture, ici, délicieux, petit mot poli. Surtout, n'ajoutez pas « pen » : « aa-hǎan pen à-ròi » serait une faute que tout le monde remarquerait. Pour renforcer, on ajoute « mâak », très, après l'adjectif : « ráwn mâak », il fait très chaud, ou « phèt mâak », très épicé. Pour dire trop, on ajoute « pai » : « khem pai », trop salé. Astuce : en thaï, l'adjectif est un verbe à lui tout seul, un peu comme si l'on disait en français la soupe pique, le riz sale.","exampleRo":"Aa-hǎan thîi-nîi à-ròi khráp.","lit":"nourriture · ici · délicieux · [politesse]","say":{"aa-hǎan à-ròi":"อาหารอร่อย","Aa-hǎan thîi-nîi à-ròi khráp":"อาหารที่นี่อร่อยครับ","pen":"เป็น","aa-hǎan pen à-ròi":"อาหารเป็นอร่อย","mâak":"มาก","ráwn mâak":"ร้อนมาก","phèt mâak":"เผ็ดมาก","pai":"ไป","khem pai":"เค็มไป"}}},{"title":"Au marché de nuit","phrases":[{"fr":"Ça, c'est quoi ?","tgt":"นี่อะไรครับ","ro":"Nîi à-rai khráp?","lit":"ceci · quoi · [politesse]"},{"fr":"Ça, c'est un fruit du dragon.","tgt":"นี่คือแก้วมังกรครับ","ro":"Nîi khue kâew-mang-kawn khráp.","lit":"ceci · c'est · fruit du dragon (verre · dragon) · [politesse]"},{"fr":"Et ça, là-bas ?","tgt":"แล้วนั่นล่ะครับ","ro":"Láew nân lâ khráp?","lit":"et puis · cela · [insistance] · [politesse]"},{"fr":"Ça, c'est du durian.","tgt":"นั่นทุเรียนครับ","ro":"Nân thú-rian khráp.","lit":"cela · durian · [politesse]"},{"fr":"Combien coûte celui-ci ?","tgt":"อันนี้เท่าไรครับ","ro":"An níi thâo-rài khráp?","lit":"[classificateur] · ce · combien · [politesse]"},{"fr":"Celui-là est plus joli.","tgt":"อันนั้นสวยกว่าครับ","ro":"An nán sǔai kwàa khráp.","lit":"[classificateur] · ce…là · joli · plus · [politesse]"},{"fr":"D'accord, je prends celui-ci.","tgt":"ได้ครับ เอาอันนี้ครับ","ro":"Dâai khráp, ao an níi khráp.","lit":"pouvoir · [politesse] · prendre · [classificateur] · ce · [politesse]"},{"fr":"Voici mon ami, il s'appelle Lek.","tgt":"นี่เพื่อนผมชื่อเล็กครับ","ro":"Nîi phûean phǒm chûe Lék khráp.","lit":"ceci · ami · je · s'appeler · Lek · [politesse]"},{"fr":"Ici, c'est très animé.","tgt":"ที่นี่คึกคักมากครับ","ro":"Thîi-nîi khúek-khák mâak khráp.","lit":"ici · animé · très · [politesse]"},{"fr":"Là-bas, il y a des glaces.","tgt":"ที่นั่นมีไอศกรีมครับ","ro":"Thîi-nân mii ai-sà-kriim khráp.","lit":"là-bas · avoir · glace · [politesse]"}],"tip":{"title":"« Nîi » et « nân » : ceci et cela","example":"Ça, c'est quoi ? — <b>นี่</b>อะไรครับ","body":"Pour montrer quelque chose, le thaï utilise « nîi » pour ce qui est proche, ceci, et « nân » pour ce qui est plus loin, cela. Tous deux ont un ton descendant et se placent en début de phrase. « Nîi à-rai khráp ? » se décompose ainsi : ceci, quoi, petit mot poli, donc ça, c'est quoi ? Le mot interrogatif reste à la fin, là où viendra la réponse : « nân thú-rian », ça, c'est du durian. Après un nom ou un petit mot de classement, le même mot prend un ton haut : « an níi », celui-ci, et « an nán », celui-là. Pour les lieux, on dit « thîi-nîi », ici, et « thîi-nân », là-bas. Astuce : au marché, il vous suffit de pointer du doigt en disant « an níi », puis « thâo-rài ? », combien ?","exampleRo":"Nîi à-rai khráp?","lit":"ceci · quoi · [politesse]","say":{"Nîi":"นี่","nân":"นั่น","nîi":"นี่","Nîi à-rai khráp ?":"นี่อะไรครับ","nân thú-rian":"นั่นทุเรียน","an níi":"อันนี้","an nán":"อันนั้น","thîi-nîi":"ที่นี่","thîi-nân":"ที่นั่น","thâo-rài ?":"เท่าไร"}}},{"title":"Dans mon appartement","phrases":[{"fr":"Et voici mon appartement.","tgt":"แล้วนี่คือห้องของผมครับ","ro":"Láew nîi khue hâwng khǎwng phǒm khráp.","lit":"et puis · ceci · c'est · chambre · [de] · je · [politesse]"},{"fr":"C'est la clé de qui ?","tgt":"กุญแจของใครครับ","ro":"Kun-jae khǎwng khrai khráp?","lit":"clé · [de] · qui · [politesse]"},{"fr":"C'est la clé de Nok.","tgt":"กุญแจของนกครับ","ro":"Kun-jae khǎwng Nók khráp.","lit":"clé · [de] · Nok · [politesse]"},{"fr":"Ce téléphone est à moi.","tgt":"มือถือเครื่องนี้เป็นของผมครับ","ro":"Mue-thǔe khrûeang níi pen khǎwng phǒm khráp.","lit":"téléphone · [classificateur] · ce · être · [de] · je · [politesse]"},{"fr":"La chambre de ma sœur est très claire.","tgt":"ห้องของน้องสาวผมสว่างมากครับ","ro":"Hâwng khǎwng náwng-sǎaw phǒm sà-wàang mâak khráp.","lit":"chambre · [de] · petite sœur · je · clair · très · [politesse]"},{"fr":"Les affaires de Lek sont sur la table.","tgt":"ของของเล็กอยู่บนโต๊ะครับ","ro":"Khǎwng khǎwng Lék yùu bon tó khráp.","lit":"affaires · [de] · Lek · se trouver · sur · table · [politesse]"},{"fr":"Le chat du voisin est mignon.","tgt":"แมวของเพื่อนบ้านน่ารักครับ","ro":"Maew khǎwng phûean-bâan nâa-rák khráp.","lit":"chat · [de] · voisin · mignon · [politesse]"},{"fr":"La cuisine est petite mais propre.","tgt":"ครัวเล็กแต่สะอาดครับ","ro":"Khrua lék tàe sà-àat khráp.","lit":"cuisine · petit · mais · propre · [politesse]"},{"fr":"Le balcon de l'appartement est grand.","tgt":"ระเบียงของห้องใหญ่ครับ","ro":"Rá-biang khǎwng hâwng yài khráp.","lit":"balcon · [de] · chambre · grand · [politesse]"},{"fr":"Mon logement est près de la station.","tgt":"ห้องผมอยู่ใกล้สถานีครับ","ro":"Hâwng phǒm yùu klâi sà-thǎa-nii khráp.","lit":"chambre · je · se trouver · près · station · [politesse]"}],"tip":{"title":"« Khǎwng » : de, le possessif","example":"Et voici mon appartement. — แล้วนี่คือห้อง<b>ของ</b>ผมครับ","body":"Pour dire de, au sens de la possession, on utilise « khǎwng », avec un ton montant. L'ordre est l'inverse du français mon appartement : on dit d'abord l'objet, puis « khǎwng », puis le propriétaire. « Hâwng khǎwng phǒm » se décompose ainsi : chambre, de, moi, donc mon appartement, littéralement la chambre de moi. De même, « kun-jae khǎwng Nók » veut dire la clé de Nok, et « maew khǎwng phûean-bâan », le chat du voisin. À l'oral, on supprime très souvent « khǎwng » : « hâwng phǒm » suffit pour dire ma chambre. Amusant : « khǎwng » est aussi un nom qui veut dire les affaires, d'où la phrase « khǎwng khǎwng Lék », les affaires de Lek. Astuce : dites-vous la chambre de moi, la clé de Nok, et vous aurez exactement l'ordre thaï.","exampleRo":"Láew nîi khue hâwng khǎwng phǒm khráp.","lit":"et puis · ceci · c'est · chambre · [de] · je · [politesse]","say":{"Khǎwng":"ของ","khǎwng":"ของ","Hâwng khǎwng phǒm":"ห้องของผม","kun-jae khǎwng Nók":"กุญแจของนก","maew khǎwng phûean-bâan":"แมวของเพื่อนบ้าน","hâwng phǒm":"ห้องผม","khǎwng khǎwng Lék":"ของของเล็ก"}}},{"title":"Les courses au marché","phrases":[{"fr":"Deux bouteilles d'eau, s'il vous plaît.","tgt":"ขอน้ำสองขวดครับ","ro":"Khǎw náam sǎwng khùat khráp.","lit":"demander · eau · deux · bouteille [classificateur] · [politesse]"},{"fr":"Trois mangues, s'il vous plaît.","tgt":"ขอมะม่วงสามลูกครับ","ro":"Khǎw má-mûang sǎam lûuk khráp.","lit":"demander · mangue · trois · [classificateur] · [politesse]"},{"fr":"Ça fait cinquante bahts.","tgt":"ห้าสิบบาทครับ","ro":"Hâa-sìp bàat khráp.","lit":"cinq · dix · baht · [politesse]"},{"fr":"Combien coûte une banane ?","tgt":"กล้วยลูกละเท่าไรครับ","ro":"Klûai lûuk lá thâo-rài khráp?","lit":"banane · [classificateur] · chaque · combien · [politesse]"},{"fr":"Dix bahts pièce.","tgt":"ลูกละสิบบาทครับ","ro":"Lûuk lá sìp bàat khráp.","lit":"[classificateur] · chaque · dix · baht · [politesse]"},{"fr":"Quatre œufs, s'il vous plaît.","tgt":"ขอไข่สี่ฟองครับ","ro":"Khǎw khài sìi fawng khráp.","lit":"demander · œuf · quatre · [classificateur] · [politesse]"},{"fr":"Cent bahts, c'est trop cher.","tgt":"ร้อยบาทแพงไปครับ","ro":"Rói bàat phaeng pai khráp.","lit":"cent · baht · cher · aller (trop) · [politesse]"},{"fr":"Je vous donne deux cents bahts.","tgt":"ผมให้สองร้อยบาทครับ","ro":"Phǒm hâi sǎwng rói bàat khráp.","lit":"je · donner · deux · cent · baht · [politesse]"},{"fr":"Je vous rends vingt bahts.","tgt":"ทอนยี่สิบบาทครับ","ro":"Thawn yîi-sìp bàat khráp.","lit":"rendre la monnaie · vingt · baht · [politesse]"},{"fr":"Nous sommes cinq personnes.","tgt":"เรามีห้าคนครับ","ro":"Rao mii hâa khon khráp.","lit":"nous · avoir · cinq · personne [classificateur] · [politesse]"}],"tip":{"title":"Compter : « nùeng, sǎwng, sǎam »","example":"Trois mangues, s'il vous plaît. — ขอมะม่วง<b>สาม</b>ลูกครับ","body":"Voici les premiers nombres : « nùeng » un, « sǎwng » deux, « sǎam » trois, « sìi » quatre, « hâa » cinq, puis « hòk », « jèt », « pàet », « kâo » et enfin « sìp », dix. Ensuite, tout se construit comme un jeu de cubes : « sìp-èt » onze, « yîi-sìp » vingt, « hâa-sìp » cinquante, « rói » cent. Pour compter des objets, l'ordre est le nom, puis le nombre, puis un petit mot de classement qui dépend de la forme de l'objet. Décomposons « Khǎw má-mûang sǎam lûuk khráp » : demander, mangue, trois, petit mot pour les fruits ronds, poli. On dit de même « náam sǎwng khùat », deux bouteilles d'eau, et « khài sìi fawng », quatre œufs. Pour les gens, le mot de classement est « khon » : « hâa khon », cinq personnes. Astuce : pensez au français trois têtes d'ail ou deux pieds de salade, le thaï fait la même chose pour presque tout.","exampleRo":"Khǎw má-mûang sǎam lûuk khráp.","lit":"demander · mangue · trois · [classificateur] · [politesse]","say":{"nùeng":"หนึ่ง","sǎwng":"สอง","sǎam":"สาม","sìi":"สี่","hâa":"ห้า","hòk":"หก","jèt":"เจ็ด","pàet":"แปด","kâo":"เก้า","sìp":"สิบ","sìp-èt":"สิบเอ็ด","yîi-sìp":"ยี่สิบ","hâa-sìp":"ห้าสิบ","rói":"ร้อย","Khǎw má-mûang sǎam lûuk khráp":"ขอมะม่วงสามลูกครับ","náam sǎwng khùat":"น้ำสองขวด","khài sìi fawng":"ไข่สี่ฟอง","khon":"คน","hâa khon":"ห้าคน","nùeng, sǎwng, sǎam":"หนึ่ง สอง สาม"}}},{"title":"Au marché de Chatuchak","phrases":[{"fr":"Vous avez de l'eau fraîche ?","tgt":"มีน้ำเย็นไหมครับ","ro":"Mii náam yen mái khráp?","lit":"avoir · eau · frais · [question] · [politesse]"},{"fr":"Oui, il y en a au fond.","tgt":"มีครับ อยู่ข้างหลังครับ","ro":"Mii khráp, yùu khâang-lǎng khráp.","lit":"avoir · [politesse] · se trouver · derrière · [politesse]"},{"fr":"Il n'y a pas de glaçons.","tgt":"ไม่มีน้ำแข็งครับ","ro":"Mâi mii náam-khǎeng khráp.","lit":"ne pas · avoir · glace (eau · dur) · [politesse]"},{"fr":"J'ai un nouveau téléphone portable.","tgt":"ผมมีมือถือใหม่ครับ","ro":"Phǒm mii mue-thǔe mài khráp.","lit":"je · avoir · téléphone portable · nouveau · [politesse]"},{"fr":"Vous avez de la monnaie, s'il vous plaît ?","tgt":"มีเงินทอนไหมครับ","ro":"Mii ngoen-thawn mái khráp?","lit":"avoir · argent · rendre · [question] · [politesse]"},{"fr":"Désolé, je n'ai pas de petite monnaie.","tgt":"ขอโทษครับ ผมไม่มีเงินทอนครับ","ro":"Khǎw-thôot khráp, phǒm mâi mii ngoen-thawn khráp.","lit":"pardon · [politesse] · je · ne pas · avoir · argent · rendre · [politesse]"},{"fr":"Il y a un distributeur dans le coin ?","tgt":"แถวนี้มีตู้กดเงินไหมครับ","ro":"Thǎew-níi mii tûu-kòt-ngoen mái khráp?","lit":"coin · ce · avoir · armoire · appuyer · argent · [question] · [politesse]"},{"fr":"J'ai deux grands frères.","tgt":"ผมมีพี่ชายสองคนครับ","ro":"Phǒm mii phîi-chaai sǎwng khon khráp.","lit":"je · avoir · aîné · homme · deux · [classificateur] · [politesse]"},{"fr":"Il y a des mangues aujourd'hui ?","tgt":"วันนี้มีมะม่วงไหมครับ","ro":"Wan-níi mii má-mûang mái khráp?","lit":"aujourd'hui · avoir · mangue · [question] · [politesse]"},{"fr":"Je n'ai pas le temps aujourd'hui.","tgt":"วันนี้ผมไม่มีเวลาครับ","ro":"Wan-níi phǒm mâi mii wee-laa khráp.","lit":"aujourd'hui · je · ne pas · avoir · temps · [politesse]"}],"tip":{"title":"« Mii » : avoir, il y a","example":"Vous avez de l'eau fraîche ? — <b>มี</b>น้ำเย็นไหมครับ","body":"Le verbe « mii » veut dire avoir, mais aussi il y a : c'est exactement le même mot. « Phǒm mii mue-thǔe mài » signifie j'ai un téléphone neuf, et « mii tà-làat » veut dire il y a un marché. Pour demander quelque chose dans une boutique, on dit simplement « mii », puis l'objet, puis « mái ». « Mii náam yen mái khráp ? » se décompose ainsi : avoir, eau, fraîche, question, poli, donc vous avez de l'eau fraîche ? La réponse est tout aussi simple : « mii khráp », oui, il y en a, ou « mâi mii khráp », non, il n'y en a pas. Pas besoin de sujet quand la situation est claire. Astuce : « mii » est votre mot magique pour faire les courses, avec lui vous pouvez tout demander en montrant du doigt.","exampleRo":"Mii náam yen mái khráp?","lit":"avoir · eau · frais · [question] · [politesse]","say":{"Mii":"มี","mii":"มี","Phǒm mii mue-thǔe mài":"ผมมีมือถือใหม่","mii tà-làat":"มีตลาด","mái":"ไหม","Mii náam yen mái khráp ?":"มีน้ำเย็นไหมครับ","mii khráp":"มีครับ","mâi mii khráp":"ไม่มีครับ"}}},{"title":"Sur la rivière Chao Phraya","phrases":[{"fr":"Où est l'embarcadère ?","tgt":"ท่าเรืออยู่ที่ไหนครับ","ro":"Thâa-ruea yùu thîi-nǎi khráp?","lit":"quai · bateau · se trouver · où · [politesse]"},{"fr":"L'embarcadère est près du pont.","tgt":"ท่าเรืออยู่ใกล้สะพานครับ","ro":"Thâa-ruea yùu klâi sà-phaan khráp.","lit":"quai · bateau · se trouver · près · pont · [politesse]"},{"fr":"Je suis sur le bateau.","tgt":"ผมอยู่บนเรือครับ","ro":"Phǒm yùu bon ruea khráp.","lit":"je · se trouver · sur · bateau · [politesse]"},{"fr":"Wat Arun est sur l'autre rive.","tgt":"วัดอรุณอยู่อีกฝั่งครับ","ro":"Wát À-run yùu ìik fàng khráp.","lit":"Wat Arun · se trouver · autre · rive · [politesse]"},{"fr":"Vous êtes où, maintenant ?","tgt":"ตอนนี้อยู่ที่ไหนครับ","ro":"Tawn-níi yùu thîi-nǎi khráp?","lit":"maintenant · se trouver · où · [politesse]"},{"fr":"Je suis encore au marché aux fleurs.","tgt":"ผมยังอยู่ที่ตลาดดอกไม้ครับ","ro":"Phǒm yang yùu thîi tà-làat dàwk-máai khráp.","lit":"je · encore · se trouver · à · marché · fleur · [politesse]"},{"fr":"Elle habite au bord de la rivière.","tgt":"เขาอยู่ริมแม่น้ำครับ","ro":"Khǎo yùu rim mâe-náam khráp.","lit":"elle · habiter · bord · rivière (mère · eau) · [politesse]"},{"fr":"Les toilettes sont à l'arrière du bateau.","tgt":"ห้องน้ำอยู่ท้ายเรือครับ","ro":"Hâwng-náam yùu tháai ruea khráp.","lit":"toilettes (pièce · eau) · se trouver · arrière · bateau · [politesse]"},{"fr":"Mon hôtel est au bord de la Chao Phraya.","tgt":"โรงแรมผมอยู่ริมแม่น้ำเจ้าพระยาครับ","ro":"Roong-raem phǒm yùu rim mâe-náam Jâo-phrá-yaa khráp.","lit":"hôtel · je · se trouver · bord · rivière · Chao Phraya · [politesse]"},{"fr":"Il n'est pas à la maison.","tgt":"เขาไม่อยู่บ้านครับ","ro":"Khǎo mâi yùu bâan khráp.","lit":"il · ne pas · se trouver · maison · [politesse]"}],"tip":{"title":"« Yùu » : être à un endroit","example":"Je suis sur le bateau. — ผม<b>อยู่</b>บนเรือครับ","body":"Le verbe « yùu », avec un ton bas, veut dire être quelque part, se trouver, et aussi habiter. Il ne faut pas le confondre avec « pen », qui relie deux noms : pour un lieu, c'est toujours « yùu ». Décomposons « Phǒm yùu bon ruea khráp » : je, se trouver, sur, bateau, poli, donc je suis sur le bateau. Pour demander où se trouve quelque chose, on dit « yùu thîi-nǎi ? », littéralement se trouver où : « thâa-ruea yùu thîi-nǎi ? », où est l'embarcadère ? Avec la négation, « khǎo mâi yùu bâan » veut dire il n'est pas à la maison. Et « khǎo yùu rim mâe-náam » signifie elle habite au bord de la rivière. Astuce : « yùu » répond à la question où, « pen » répond à la question quoi.","exampleRo":"Phǒm yùu bon ruea khráp.","lit":"je · se trouver · sur · bateau · [politesse]","say":{"Yùu":"อยู่","yùu":"อยู่","pen":"เป็น","Phǒm yùu bon ruea khráp":"ผมอยู่บนเรือครับ","yùu thîi-nǎi ?":"อยู่ที่ไหน","thâa-ruea yùu thîi-nǎi ?":"ท่าเรืออยู่ที่ไหน","khǎo mâi yùu bâan":"เขาไม่อยู่บ้าน","khǎo yùu rim mâe-náam":"เขาอยู่ริมแม่น้ำ"}}},{"title":"Les vêtements et les couleurs","phrases":[{"fr":"Je cherche une chemise blanche.","tgt":"ผมหาเสื้อเชิ้ตสีขาวครับ","ro":"Phǒm hǎa sûea-chóet sǐi khǎaw khráp.","lit":"je · chercher · chemise · couleur · blanc · [politesse]"},{"fr":"Ce chapeau rouge est joli.","tgt":"หมวกสีแดงใบนี้สวยครับ","ro":"Mùak sǐi daeng bai níi sǔai khráp.","lit":"chapeau · couleur · rouge · [classificateur] · ce · joli · [politesse]"},{"fr":"Vous avez une taille plus grande ?","tgt":"มีไซซ์ใหญ่กว่านี้ไหมครับ","ro":"Mii sai yài kwàa níi mái khráp?","lit":"avoir · taille · grand · plus · ceci · [question] · [politesse]"},{"fr":"Un pantalon léger, c'est mieux.","tgt":"กางเกงบางๆดีกว่าครับ","ro":"Kaang-keeng baang-baang dii kwàa khráp.","lit":"pantalon · fin · fin · bien · plus · [politesse]"},{"fr":"Il fait chaud, je porte un tee-shirt.","tgt":"อากาศร้อน ผมใส่เสื้อยืดครับ","ro":"Aa-kàat ráwn, phǒm sài sûea-yûet khráp.","lit":"air · chaud · je · porter · tee-shirt (haut · s'étirer) · [politesse]"},{"fr":"J'aime les chaussures noires.","tgt":"ผมชอบรองเท้าสีดำครับ","ro":"Phǒm châwp rawng-tháao sǐi dam khráp.","lit":"je · aimer · chaussure · couleur · noir · [politesse]"},{"fr":"Elle porte une robe bleue.","tgt":"เขาใส่ชุดสีฟ้าครับ","ro":"Khǎo sài chút sǐi fáa khráp.","lit":"elle · porter · robe · couleur · ciel · [politesse]"},{"fr":"Je prends le petit sac vert.","tgt":"เอากระเป๋าสีเขียวใบเล็กครับ","ro":"Ao krà-pǎo sǐi khǐaw bai lék khráp.","lit":"prendre · sac · couleur · vert · [classificateur] · petit · [politesse]"},{"fr":"Ce haut est très cher.","tgt":"เสื้อตัวนี้แพงมากครับ","ro":"Sûea tua níi phaeng mâak khráp.","lit":"haut · [classificateur] · ce · cher · très · [politesse]"},{"fr":"J'achète des sandales confortables.","tgt":"ผมซื้อรองเท้าแตะใส่สบายครับ","ro":"Phǒm súe rawng-tháao-tàe sài sà-baai khráp.","lit":"je · acheter · sandale · porter · confortable · [politesse]"}],"tip":{"title":"L'adjectif après le nom","example":"Je cherche une chemise blanche. — ผมหา<b>เสื้อเชิ้ตสีขาว</b>ครับ","body":"En thaï, l'adjectif se place toujours après le nom, comme souvent en français dans une chemise blanche. Mais le thaï va plus loin : tout ce qui décrit vient après, dans l'ordre la chose, puis sa couleur, puis le reste. Décomposons « Phǒm hǎa sûea-chóet sǐi khǎaw khráp » : je, chercher, chemise, couleur, blanc, poli. Pour les couleurs, on dit d'ailleurs souvent « sǐi », couleur, devant le nom de la couleur : « sǐi daeng » rouge, « sǐi dam » noir, « sǐi khǐaw » vert. Quand on ajoute ce ou cette, le mot arrive tout à la fin : « mùak sǐi daeng bai níi », ce chapeau rouge, littéralement chapeau couleur rouge celui-ci. Astuce : en thaï, on part toujours de la chose, puis on la décrit petit à petit, comme si l'on zoomait dessus.","exampleRo":"Phǒm hǎa sûea-chóet sǐi khǎaw khráp.","lit":"je · chercher · chemise · couleur · blanc · [politesse]","say":{"Phǒm hǎa sûea-chóet sǐi khǎaw khráp":"ผมหาเสื้อเชิ้ตสีขาวครับ","sǐi":"สี","sǐi daeng":"สีแดง","sǐi dam":"สีดำ","sǐi khǐaw":"สีเขียว","mùak sǐi daeng bai níi":"หมวกสีแดงใบนี้"}}},{"title":"Demander son chemin","phrases":[{"fr":"Vous cherchez quoi ?","tgt":"คุณหาอะไรครับ","ro":"Khun hǎa à-rai khráp?","lit":"vous · chercher · quoi · [politesse]"},{"fr":"Où est la station de métro ?","tgt":"สถานีรถไฟใต้ดินอยู่ที่ไหนครับ","ro":"Sà-thǎa-nii rót-fai-tâi-din yùu thîi-nǎi khráp?","lit":"station · train · sous · terre · se trouver · où · [politesse]"},{"fr":"Allez tout droit, puis tournez à gauche.","tgt":"ตรงไปแล้วเลี้ยวซ้ายครับ","ro":"Trong pai láew líaw sáai khráp.","lit":"droit · aller · puis · tourner · gauche · [politesse]"},{"fr":"Qui est cet homme ?","tgt":"ผู้ชายคนนั้นเป็นใครครับ","ro":"Phûu-chaai khon nán pen khrai khráp?","lit":"homme · [classificateur] · ce…là · être · qui · [politesse]"},{"fr":"C'est le gardien de l'immeuble.","tgt":"เขาเป็นยามของตึกครับ","ro":"Khǎo pen yaam khǎwng tùek khráp.","lit":"il · être · gardien · [de] · immeuble · [politesse]"},{"fr":"Le marché ouvre quand ?","tgt":"ตลาดเปิดเมื่อไรครับ","ro":"Tà-làat pòet mûea-rài khráp?","lit":"marché · ouvrir · quand · [politesse]"},{"fr":"Comment va-t-on à l'embarcadère ?","tgt":"ไปท่าเรือยังไงครับ","ro":"Pai thâa-ruea yang-ngai khráp?","lit":"aller · quai · bateau · comment · [politesse]"},{"fr":"C'est loin si on marche ?","tgt":"เดินไปไกลไหมครับ","ro":"Doen pai klai mái khráp?","lit":"marcher · aller · loin · [question] · [politesse]"},{"fr":"Vous venez d'où ?","tgt":"คุณมาจากไหนครับ","ro":"Khun maa jàak nǎi khráp?","lit":"vous · venir · de · où · [politesse]"},{"fr":"Vous rentrez quand en France ?","tgt":"คุณกลับฝรั่งเศสเมื่อไรครับ","ro":"Khun klàp fà-ràng-sèet mûea-rài khráp?","lit":"vous · rentrer · France · quand · [politesse]"}],"tip":{"title":"Les mots interrogatifs : « à-rai, thîi-nǎi, khrai, mûea-rài »","example":"Où est la station de métro ? — สถานีรถไฟใต้ดินอยู่<b>ที่ไหน</b>ครับ","body":"Les mots interrogatifs les plus utiles sont « à-rai » quoi, « thîi-nǎi » où, « khrai » qui, et « mûea-rài » quand. Bonne nouvelle : on ne déplace rien, le mot interrogatif se met à la place de la réponse, le plus souvent à la fin. Décomposons « Sà-thǎa-nii rót-fai-tâi-din yùu thîi-nǎi khráp ? » : station, métro, se trouver, où, poli, donc où est la station de métro ? On dit de même « khun hǎa à-rai ? », vous cherchez quoi ? et « tà-làat pòet mûea-rài ? », le marché ouvre quand ? La phrase garde son ordre normal, comme en français familier. Pour dire comment, on ajoute « yang-ngai » à la fin : « pai thâa-ruea yang-ngai ? », comment va-t-on à l'embarcadère ? Astuce : posez votre question comme un Parisien pressé, tu vas où, tu cherches quoi, et vous aurez l'ordre thaï.","exampleRo":"Sà-thǎa-nii rót-fai-tâi-din yùu thîi-nǎi khráp?","lit":"station · train · sous · terre · se trouver · où · [politesse]","say":{"à-rai":"อะไร","thîi-nǎi":"ที่ไหน","khrai":"ใคร","mûea-rài":"เมื่อไร","Sà-thǎa-nii rót-fai-tâi-din yùu thîi-nǎi khráp ?":"สถานีรถไฟใต้ดินอยู่ที่ไหนครับ","khun hǎa à-rai ?":"คุณหาอะไร","tà-làat pòet mûea-rài ?":"ตลาดเปิดเมื่อไร","yang-ngai":"ยังไง","pai thâa-ruea yang-ngai ?":"ไปท่าเรือยังไง","à-rai, thîi-nǎi, khrai, mûea-rài":"อะไร ที่ไหน ใคร เมื่อไร"}}},{"title":"La routine du matin","phrases":[{"fr":"Je me réveille à six heures du matin.","tgt":"ผมตื่นหกโมงเช้าครับ","ro":"Phǒm tùen hòk moong cháao khráp.","lit":"je · se réveiller · six · heure · matin · [politesse]"},{"fr":"Je prends une douche fraîche.","tgt":"ผมอาบน้ำเย็นครับ","ro":"Phǒm àap-náam yen khráp.","lit":"je · se laver · eau · frais · [politesse]"},{"fr":"Ma femme se lève tôt, elle aussi.","tgt":"ภรรยาผมก็ตื่นเช้าด้วยครับ","ro":"Phan-rá-yaa phǒm kâw tùen cháao dûai khráp.","lit":"épouse · je · [aussi] · se réveiller · tôt · aussi · [politesse]"},{"fr":"Je bois un café, et un jus d'orange aussi.","tgt":"ผมดื่มกาแฟ แล้วก็น้ำส้มด้วยครับ","ro":"Phǒm dùem kaa-fae, láew kâw náam-sôm dûai khráp.","lit":"je · boire · café · et puis · eau · orange · aussi · [politesse]"},{"fr":"Un pain grillé aussi, s'il vous plaît.","tgt":"ขอขนมปังปิ้งด้วยครับ","ro":"Khǎw khà-nǒm-pang pîng dûai khráp.","lit":"demander · pain · griller · aussi · [politesse]"},{"fr":"Moi aussi, j'ai faim.","tgt":"ผมก็หิวด้วยครับ","ro":"Phǒm kâw hǐw dûai khráp.","lit":"je · [aussi] · avoir faim · aussi · [politesse]"},{"fr":"Je prends le métro, mon collègue aussi.","tgt":"ผมนั่งรถไฟใต้ดิน เพื่อนร่วมงานก็นั่งด้วยครับ","ro":"Phǒm nâng rót-fai-tâi-din, phûean-rûam-ngaan kâw nâng dûai khráp.","lit":"je · prendre · métro · collègue · [aussi] · prendre · aussi · [politesse]"},{"fr":"Il fait chaud, et humide aussi.","tgt":"ร้อนแล้วก็ชื้นด้วยครับ","ro":"Ráwn láew kâw chúen dûai khráp.","lit":"chaud · et puis · humide · aussi · [politesse]"},{"fr":"Je pars au travail à huit heures.","tgt":"ผมไปทำงานแปดโมงครับ","ro":"Phǒm pai tham-ngaan pàet moong khráp.","lit":"je · aller · travailler · huit · heure · [politesse]"},{"fr":"Je prends mon parapluie aussi.","tgt":"ผมเอาร่มไปด้วยครับ","ro":"Phǒm ao rôm pai dûai khráp.","lit":"je · prendre · parapluie · aller · aussi · [politesse]"}],"tip":{"title":"« Dûai » : aussi","example":"Moi aussi, j'ai faim. — ผม<b>ก็</b>หิว<b>ด้วย</b>ครับ","body":"Pour dire aussi, on ajoute « dûai » à la fin de la phrase, avec un ton descendant, juste avant « khráp ». Très souvent, on le combine avec « kâw », placé juste avant le verbe, qui ajoute lui aussi l'idée de également : les deux ensemble rendent la phrase très naturelle. Décomposons « Phǒm kâw hǐw dûai khráp » : moi, aussi, avoir faim, aussi, poli, donc moi aussi, j'ai faim. Dans une commande, « dûai » permet d'ajouter quelque chose : « khǎw khà-nǒm-pang pîng dûai », un pain grillé aussi, s'il vous plaît. Pour enchaîner deux choses, on dit « láew kâw », et puis : « ráwn láew kâw chúen dûai », il fait chaud, et humide aussi. Astuce : « dûai » est comme le petit sac où l'on glisse ce qu'on ajoute, il vient toujours en dernier.","exampleRo":"Phǒm kâw hǐw dûai khráp.","lit":"je · [aussi] · avoir faim · aussi · [politesse]","say":{"Dûai":"ด้วย","dûai":"ด้วย","khráp":"ครับ","kâw":"ก็","Phǒm kâw hǐw dûai khráp":"ผมก็หิวด้วยครับ","khǎw khà-nǒm-pang pîng dûai":"ขอขนมปังปิ้งด้วย","láew kâw":"แล้วก็","ráwn láew kâw chúen dûai":"ร้อนแล้วก็ชื้นด้วย"}}},{"title":"Dire l'heure","phrases":[{"fr":"Il est quelle heure, là ?","tgt":"กี่โมงแล้วครับ","ro":"Kìi moong láew khráp?","lit":"combien · heure · [accompli] · [politesse]"},{"fr":"Il est huit heures du matin.","tgt":"แปดโมงเช้าครับ","ro":"Pàet moong cháao khráp.","lit":"huit · heure · matin · [politesse]"},{"fr":"On se retrouve à midi.","tgt":"เจอกันเที่ยงครับ","ro":"Joe kan thîang khráp.","lit":"rencontrer · ensemble · midi · [politesse]"},{"fr":"Le cours commence à une heure de l'après-midi.","tgt":"เรียนเริ่มบ่ายโมงครับ","ro":"Rian rôem bàai moong khráp.","lit":"étudier · commencer · après-midi · heure · [politesse]"},{"fr":"Il est quatre heures de l'après-midi.","tgt":"สี่โมงเย็นครับ","ro":"Sìi moong yen khráp.","lit":"quatre · heure · fin de journée · [politesse]"},{"fr":"On dîne à sept heures du soir.","tgt":"กินข้าวเย็นตอนหนึ่งทุ่มครับ","ro":"Kin khâaw yen tawn nùeng thûm khráp.","lit":"manger · riz · soir · au moment de · un · [heure du soir] · [politesse]"},{"fr":"Je rentre à neuf heures du soir.","tgt":"ผมกลับบ้านสามทุ่มครับ","ro":"Phǒm klàp bâan sǎam thûm khráp.","lit":"je · rentrer · maison · trois · [heure du soir] · [politesse]"},{"fr":"Je me couche à minuit.","tgt":"ผมนอนเที่ยงคืนครับ","ro":"Phǒm nawn thîang-khuen khráp.","lit":"je · dormir · midi · nuit · [politesse]"},{"fr":"Le marché ouvre à cinq heures du matin.","tgt":"ตลาดเปิดตีห้าครับ","ro":"Tà-làat pòet tii hâa khráp.","lit":"marché · ouvrir · frapper · cinq · [politesse]"},{"fr":"Il est huit heures et demie.","tgt":"แปดโมงครึ่งครับ","ro":"Pàet moong khrûeng khráp.","lit":"huit · heure · moitié · [politesse]"}],"tip":{"title":"L'heure en thaï : un système à part","example":"On dîne à sept heures du soir. — กินข้าวเย็นตอน<b>หนึ่งทุ่ม</b>ครับ","body":"À l'oral, l'heure thaïe découpe la journée en tranches, avec un mot différent pour chaque moment. Le matin, de six à onze heures, on dit le nombre suivi de « moong cháao » : « pàet moong cháao », huit heures du matin. Midi se dit « thîang ». L'après-midi, on utilise « bàai » : « bàai moong », une heure, « bàai sǎam moong », trois heures. De quatre à six heures, on dit « moong yen » : « sìi moong yen », quatre heures de l'après-midi. Puis le soir, on recompte à partir de un avec « thûm » : « nùeng thûm », sept heures du soir, « sǎam thûm », neuf heures du soir. La nuit, on dit « tii » : « tii hâa », cinq heures du matin, et minuit se dit « thîang-khuen ». Astuce : « thûm » imite le son du tambour qui marquait autrefois les heures du soir, et « tii » veut dire frapper, comme le gong de la nuit.","exampleRo":"Kin khâaw yen tawn nùeng thûm khráp.","lit":"manger · riz · soir · au moment de · un · [heure du soir] · [politesse]","say":{"moong cháao":"โมงเช้า","pàet moong cháao":"แปดโมงเช้า","thîang":"เที่ยง","bàai":"บ่าย","bàai moong":"บ่ายโมง","bàai sǎam moong":"บ่ายสามโมง","moong yen":"โมงเย็น","sìi moong yen":"สี่โมงเย็น","thûm":"ทุ่ม","nùeng thûm":"หนึ่งทุ่ม","sǎam thûm":"สามทุ่ม","tii":"ตี","tii hâa":"ตีห้า","thîang-khuen":"เที่ยงคืน"}}},{"title":"Un tour en tuk-tuk","phrases":[{"fr":"Je veux aller au marché de nuit.","tgt":"ผมอยากไปตลาดนัดกลางคืนครับ","ro":"Phǒm yàak pai tà-làat-nát klaang-khuen khráp.","lit":"je · vouloir · aller · marché · nuit · [politesse]"},{"fr":"Vous voulez aller où ?","tgt":"อยากไปไหนครับ","ro":"Yàak pai nǎi khráp?","lit":"vouloir · aller · où · [politesse]"},{"fr":"J'ai envie de voir la rivière.","tgt":"ผมอยากดูแม่น้ำครับ","ro":"Phǒm yàak duu mâe-náam khráp.","lit":"je · vouloir · regarder · rivière · [politesse]"},{"fr":"C'est combien jusqu'à Siam ?","tgt":"ไปสยามเท่าไรครับ","ro":"Pai Sà-yǎam thâo-rài khráp?","lit":"aller · Siam · combien · [politesse]"},{"fr":"Cent cinquante bahts.","tgt":"ร้อยห้าสิบบาทครับ","ro":"Rói-hâa-sìp bàat khráp.","lit":"cent · cinq · dix · baht · [politesse]"},{"fr":"Je ne veux pas payer autant.","tgt":"ผมไม่อยากจ่ายแพงขนาดนั้นครับ","ro":"Phǒm mâi yàak jàai phaeng khà-nàat nán khráp.","lit":"je · ne pas · vouloir · payer · cher · taille · ce…là · [politesse]"},{"fr":"Cent bahts, c'est possible ?","tgt":"ร้อยบาทได้ไหมครับ","ro":"Rói bàat dâai mái khráp?","lit":"cent · baht · pouvoir · [question] · [politesse]"},{"fr":"Je veux boire un thé glacé.","tgt":"ผมอยากดื่มชาเย็นครับ","ro":"Phǒm yàak dùem chaa-yen khráp.","lit":"je · vouloir · boire · thé · froid · [politesse]"},{"fr":"Ma copine a envie de manger du som tam.","tgt":"แฟนผมอยากกินส้มตำครับ","ro":"Faen phǒm yàak kin sôm-tam khráp.","lit":"copine · je · vouloir · manger · som tam · [politesse]"},{"fr":"Je voudrais descendre ici.","tgt":"ผมอยากลงตรงนี้ครับ","ro":"Phǒm yàak long trong-níi khráp.","lit":"je · vouloir · descendre · endroit · ce · [politesse]"}],"tip":{"title":"« Yàak » : vouloir","example":"Je veux aller au marché de nuit. — ผม<b>อยาก</b>ไปตลาดนัดกลางคืนครับ","body":"« Yàak », avec un ton bas, veut dire vouloir ou avoir envie de, et se place juste devant un autre verbe. Décomposons « Phǒm yàak pai tà-làat-nát klaang-khuen khráp » : je, vouloir, aller, marché, nuit, poli, donc je veux aller au marché de nuit. Comme toujours, rien ne se conjugue : « yàak kin », vouloir manger, « yàak dùem », vouloir boire. Pour la négation, on met simplement « mâi » devant : « mâi yàak », je n'ai pas envie. En tuk-tuk, le chauffeur vous demandera sûrement « yàak pai nǎi ? », vous voulez aller où ? Pour commander un objet, on préfère souvent « khǎw », je demande, qui est plus poli. Astuce : « yàak » suivi d'un verbe exprime votre envie, « khǎw » suivi d'un nom passe votre commande.","exampleRo":"Phǒm yàak pai tà-làat-nát klaang-khuen khráp.","lit":"je · vouloir · aller · marché · nuit · [politesse]","say":{"Yàak":"อยาก","Phǒm yàak pai tà-làat-nát klaang-khuen khráp":"ผมอยากไปตลาดนัดกลางคืนครับ","yàak kin":"อยากกิน","yàak dùem":"อยากดื่ม","mâi":"ไม่","mâi yàak":"ไม่อยาก","yàak pai nǎi ?":"อยากไปไหน","khǎw":"ขอ","yàak":"อยาก"}}},{"title":"Un appel entre amis","phrases":[{"fr":"Allô, c'est Thomas.","tgt":"ฮัลโหล ผมโทมัสนะครับ","ro":"Han-lǒo, phǒm Thoo-mát ná khráp.","lit":"allô · je · Thomas · [douceur] · [politesse]"},{"fr":"Allons manger ensemble !","tgt":"ไปกินข้าวกันเถอะครับ","ro":"Pai kin khâaw kan thòe khráp.","lit":"aller · manger · riz · ensemble · [proposition] · [politesse]"},{"fr":"Allons au marché de nuit ce soir !","tgt":"คืนนี้ไปตลาดนัดกันเถอะครับ","ro":"Khuen-níi pai tà-làat-nát kan thòe khráp.","lit":"nuit · ce · aller · marché · ensemble · [proposition] · [politesse]"},{"fr":"D'accord, à quelle heure ?","tgt":"ได้ครับ กี่โมงครับ","ro":"Dâai khráp, kìi moong khráp?","lit":"pouvoir · [politesse] · combien · heure · [politesse]"},{"fr":"On se retrouve à la station à six heures du soir.","tgt":"เจอกันที่สถานีหกโมงเย็นนะครับ","ro":"Joe kan thîi sà-thǎa-nii hòk moong yen ná khráp.","lit":"rencontrer · ensemble · à · station · six · heure · soir · [douceur] · [politesse]"},{"fr":"Prenons le bateau !","tgt":"นั่งเรือกันเถอะครับ","ro":"Nâng ruea kan thòe khráp.","lit":"s'asseoir (prendre) · bateau · ensemble · [proposition] · [politesse]"},{"fr":"Il pleut, rentrons.","tgt":"ฝนตกแล้ว กลับกันเถอะครับ","ro":"Fǒn tòk láew, klàp kan thòe khráp.","lit":"pluie · tomber · [accompli] · rentrer · ensemble · [proposition] · [politesse]"},{"fr":"Je te rappelle plus tard.","tgt":"เดี๋ยวผมโทรกลับนะครับ","ro":"Dǐaw phǒm thoo klàp ná khráp.","lit":"tout à l'heure · je · appeler · retour · [douceur] · [politesse]"},{"fr":"Mon téléphone n'a plus de batterie.","tgt":"มือถือผมแบตหมดครับ","ro":"Mue-thǔe phǒm bàet mòt khráp.","lit":"téléphone · je · batterie · épuisé · [politesse]"},{"fr":"Bon, allons-y !","tgt":"ไปกันเถอะครับ","ro":"Pai kan thòe khráp.","lit":"aller · ensemble · [proposition] · [politesse]"}],"tip":{"title":"« Kan thoe » : allons-y, proposer","example":"Allons manger ensemble ! — ไปกินข้าว<b>กันเถอะ</b>ครับ","body":"Pour proposer de faire quelque chose ensemble, on termine la phrase par « kan thòe ». « Kan » veut dire ensemble, et « thòe », avec un ton bas, ajoute une nuance d'invitation, comme allez, viens. Décomposons « Pai kin khâaw kan thòe khráp » : aller, manger, riz, ensemble, proposition, poli, donc allons manger ensemble ! Notez que « kin khâaw », littéralement manger du riz, veut simplement dire manger ou prendre un repas. Avec le même schéma, on dit « nâng ruea kan thòe », prenons le bateau, et « klàp kan thòe », rentrons. Et le plus court de tous : « pai kan thòe », allons-y. Astuce : prenez n'importe quel verbe, collez « kan thòe » derrière, et vous avez une invitation.","exampleRo":"Pai kin khâaw kan thòe khráp.","lit":"aller · manger · riz · ensemble · [proposition] · [politesse]","say":{"Kan thoe":"กันเถอะ","kan thòe":"กันเถอะ","Kan":"กัน","thòe":"เถอะ","Pai kin khâaw kan thòe khráp":"ไปกินข้าวกันเถอะครับ","kin khâaw":"กินข้าว","nâng ruea kan thòe":"นั่งเรือกันเถอะ","klàp kan thòe":"กลับกันเถอะ","pai kan thòe":"ไปกันเถอะ"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Bonjour à tous !","tgt":"สวัสดีทุกคนครับ","ro":"Sà-wàt-dii thúk khon khráp.","lit":"bonjour · chaque · personne · [politesse]"},{"fr":"Cette première série de leçons est terminée.","tgt":"บทเรียนชุดแรกจบแล้วครับ","ro":"Bòt-rian chút râek jòp láew khráp.","lit":"leçon · série · premier · finir · [accompli] · [politesse]"},{"fr":"Je parle un peu mieux le thaï.","tgt":"ผมพูดภาษาไทยได้ดีขึ้นนิดหน่อยครับ","ro":"Phǒm phûut phaa-sǎa thai dâai dii khûen nít-nòi khráp.","lit":"je · parler · langue · thaï · pouvoir · bien · monter · un peu · [politesse]"},{"fr":"Le thaï n'est pas si difficile.","tgt":"ภาษาไทยไม่ยากเท่าไรครับ","ro":"Phaa-sǎa thai mâi yâak thâo-rài khráp.","lit":"langue · thaï · ne pas · difficile · tant que ça · [politesse]"},{"fr":"Pardon pour mes erreurs de tons !","tgt":"ขอโทษที่ผมพูดเสียงผิดครับ","ro":"Khǎw-thôot thîi phǒm phûut sǐang phìt khráp.","lit":"pardon · que · je · parler · son · faux · [politesse]"},{"fr":"Ce n'est rien, continuez !","tgt":"ไม่เป็นไรครับ พูดต่อไปครับ","ro":"Mâi pen rai khráp, phûut tàw pai khráp.","lit":"ne pas · être · quoi · [politesse] · parler · continuer · aller · [politesse]"},{"fr":"Merci de m'avoir aidé.","tgt":"ขอบคุณที่ช่วยผมครับ","ro":"Khàwp-khun thîi chûai phǒm khráp.","lit":"merci · que · aider · je · [politesse]"},{"fr":"Le prochain module parle de voyage.","tgt":"บทต่อไปเป็นเรื่องการเดินทางครับ","ro":"Bòt tàw pai pen rûeang kaan doen-thaang khráp.","lit":"chapitre · suivant · être · sujet · voyage · [politesse]"},{"fr":"Continuons ensemble !","tgt":"เรียนต่อกันเถอะครับ","ro":"Rian tàw kan thòe khráp.","lit":"étudier · continuer · ensemble · [proposition] · [politesse]"},{"fr":"Merci et à bientôt !","tgt":"ขอบคุณครับ แล้วเจอกันใหม่ครับ","ro":"Khàwp-khun khráp, láew joe kan mài khráp.","lit":"merci · [politesse] · puis · rencontrer · ensemble · de nouveau · [politesse]"}],"tip":{"title":"Les formules magiques : « sà-wàt-dii, khàwp-khun, khǎw-thôot, mâi pen rai »","example":"Ce n'est rien, continuez ! — <b>ไม่เป็นไร</b>ครับ พูดต่อไปครับ","body":"Quatre formules vous ouvriront toutes les portes en Thaïlande. « Sà-wàt-dii » veut dire bonjour, mais aussi au revoir, à n'importe quelle heure de la journée. « Khàwp-khun » signifie merci, et « khàwp-khun mâak », merci beaucoup. « Khǎw-thôot » veut dire pardon, et sert aussi à interpeller quelqu'un poliment, comme excusez-moi. Enfin, « mâi pen rai » est presque un art de vivre : décomposé, c'est ne pas, être, quoi, donc ce n'est rien, pas de souci. On l'entend partout, pour répondre à un merci comme à une excuse, et il exprime la douceur thaïe face aux petits tracas. N'oubliez jamais d'ajouter « khráp » ou « khâ » à la fin de chacune. Astuce : répétez-les en boucle pendant votre trajet, elles feront très vite partie de vous.","exampleRo":"Mâi pen rai khráp, phûut tàw pai khráp.","lit":"ne pas · être · quoi · [politesse] · parler · continuer · aller · [politesse]","say":{"Sà-wàt-dii":"สวัสดี","Khàwp-khun":"ขอบคุณ","khàwp-khun mâak":"ขอบคุณมาก","Khǎw-thôot":"ขอโทษ","mâi pen rai":"ไม่เป็นไร","khráp":"ครับ","khâ":"ค่ะ","sà-wàt-dii, khàwp-khun, khǎw-thôot, mâi pen rai":"สวัสดี ขอบคุณ ขอโทษ ไม่เป็นไร"}}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus en Thaïlande.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à l'aéroport de Bangkok","phrases":[{"fr":"Où est la sortie, s'il vous plaît ?","tgt":"ทางออกอยู่ที่ไหนครับ","ro":"Thaang-àwk yùu thîi-nǎi khráp?","lit":"chemin · sortir · se trouver · où · [politesse]"},{"fr":"Je cherche le bus pour le centre.","tgt":"ผมหารถเข้าเมืองครับ","ro":"Phǒm hǎa rót khâo mueang khráp.","lit":"je (homme) · chercher · véhicule · entrer · ville · [politesse]"},{"fr":"Le bus est par là-bas.","tgt":"รถอยู่ทางนั้นครับ","ro":"Rót yùu thaang nán khráp.","lit":"véhicule · se trouver · direction · là-bas · [politesse]"},{"fr":"Bienvenue en Thaïlande !","tgt":"ยินดีต้อนรับสู่ประเทศไทยครับ","ro":"Yin-dii tâwn-ráp sùu prà-thêet-thai khráp.","lit":"content · accueillir · vers · pays · thaï · [politesse]"},{"fr":"Je suis ici pour faire du tourisme.","tgt":"ผมมาเที่ยวครับ","ro":"Phǒm maa thîao khráp.","lit":"je (homme) · venir · se promener · [politesse]"},{"fr":"Vous restez ici combien de jours ?","tgt":"อยู่กี่วันครับ","ro":"Yùu kìi wan khráp?","lit":"rester · combien · jour · [politesse]"},{"fr":"Dix jours seulement.","tgt":"แค่สิบวันครับ","ro":"Khâe sìp wan khráp.","lit":"seulement · dix · jour · [politesse]"},{"fr":"Pardon, où sont les toilettes ?","tgt":"ขอโทษครับ ห้องน้ำอยู่ที่ไหนครับ","ro":"Khǎw-thôot khráp, hâwng-náam yùu thîi-nǎi khráp?","lit":"pardon · [politesse] · toilettes · se trouver · où · [politesse]"},{"fr":"Cet aéroport est vraiment immense.","tgt":"สนามบินใหญ่มากครับ","ro":"Sà-nǎam-bin yài mâak khráp.","lit":"aéroport · grand · très · [politesse]"},{"fr":"Qu'est-ce qu'il fait chaud ici !","tgt":"ที่นี่ร้อนจังครับ","ro":"Thîi-nîi ráwn jang khráp.","lit":"ici · chaud · vraiment · [politesse]"}]},{"title":"Le programme des prochains jours","phrases":[{"fr":"Aujourd'hui, on reste à Bangkok.","tgt":"วันนี้เราอยู่กรุงเทพครับ","ro":"Wan-níi rao yùu Krung-thêep khráp.","lit":"aujourd'hui · nous · rester · Bangkok · [politesse]"},{"fr":"Demain, on va à Ayutthaya.","tgt":"พรุ่งนี้เราไปอยุธยาครับ","ro":"Phrûng-níi rao pai À-yút-thá-yaa khráp.","lit":"demain · nous · aller · Ayutthaya · [politesse]"},{"fr":"Hier, je suis arrivé en Thaïlande.","tgt":"เมื่อวานผมมาถึงเมืองไทยครับ","ro":"Mûea-waan phǒm maa thǔeng mueang-thai khráp.","lit":"hier · je (homme) · venir · atteindre · pays · thaï · [politesse]"},{"fr":"Vous partez demain ?","tgt":"พรุ่งนี้ไปไหมครับ","ro":"Phrûng-níi pai mái khráp?","lit":"demain · partir · [question] · [politesse]"},{"fr":"Non, je pars aujourd'hui même.","tgt":"ไม่ครับ ไปวันนี้เลยครับ","ro":"Mâi khráp, pai wan-níi loei khráp.","lit":"non · [politesse] · partir · aujourd'hui · [insistance] · [politesse]"},{"fr":"Hier, il a beaucoup plu.","tgt":"เมื่อวานฝนตกหนักครับ","ro":"Mûea-waan fǒn tòk nàk khráp.","lit":"hier · pluie · tomber · fort · [politesse]"},{"fr":"Aujourd'hui, le temps est beau.","tgt":"วันนี้อากาศดีครับ","ro":"Wan-níi aa-kàat dii khráp.","lit":"aujourd'hui · temps · bon · [politesse]"},{"fr":"Demain, le musée est fermé.","tgt":"พรุ่งนี้พิพิธภัณฑ์ปิดครับ","ro":"Phrûng-níi phí-phít-thá-phan pìt khráp.","lit":"demain · musée · fermer · [politesse]"},{"fr":"Hier, j'étais très fatigué.","tgt":"เมื่อวานผมเหนื่อยมากครับ","ro":"Mûea-waan phǒm nùeay mâak khráp.","lit":"hier · je (homme) · fatigué · très · [politesse]"},{"fr":"On se retrouve demain.","tgt":"พรุ่งนี้เจอกันครับ","ro":"Phrûng-níi joe kan khráp.","lit":"demain · rencontrer · ensemble · [politesse]"}],"tip":{"title":"« Wan-níi, phrûng-níi, mûea-waan » : aujourd'hui, demain, hier","example":"Demain, on va à Ayutthaya. — <b>พรุ่งนี้</b>เราไปอยุธยาครับ","body":"En thaï, le verbe ne change jamais : il n'y a ni passé, ni futur, ni conjugaison. Pour situer une action dans le temps, on ajoute simplement un mot comme « wan-níi », aujourd'hui, « phrûng-níi », demain, ou « mûea-waan », hier. Ce mot se place en général tout au début de la phrase, exactement comme en français quand on dit « demain, on va à Ayutthaya ». Décomposons : « phrûng-níi rao pai À-yút-thá-yaa khráp », c'est mot à mot demain, nous, aller, Ayutthaya, politesse. Avec « mûea-waan », le même verbe devient un passé : « mûea-waan fǒn tòk », hier il a plu, et « wan-níi fǒn tòk », il pleut aujourd'hui. Attention aux tons : « wan-níi » finit sur un ton haut, « phrûng-níi » commence sur un ton descendant, et « mûea-waan » aussi. Pour retenir, remarquez que « níi » veut dire ce ou cette : « wan-níi », c'est littéralement ce jour-ci. Il suffit donc de changer le premier mot de la phrase pour voyager dans le temps.","exampleRo":"Phrûng-níi rao pai À-yút-thá-yaa khráp.","lit":"demain · nous · aller · Ayutthaya · [politesse]","say":{"Wan-níi, phrûng-níi, mûea-waan":"วันนี้ พรุ่งนี้ เมื่อวาน","wan-níi":"วันนี้","phrûng-níi":"พรุ่งนี้","mûea-waan":"เมื่อวาน","phrûng-níi rao pai À-yút-thá-yaa khráp":"พรุ่งนี้เราไปอยุธยาครับ","mûea-waan fǒn tòk":"เมื่อวานฝนตก","wan-níi fǒn tòk":"วันนี้ฝนตก","níi":"นี้"}}},{"title":"Un billet pour le train de nuit","phrases":[{"fr":"Je vais partir pour Chiang Mai.","tgt":"ผมจะไปเชียงใหม่ครับ","ro":"Phǒm jà pai Chiang-mài khráp.","lit":"je (homme) · [futur] · aller · Chiang Mai · [politesse]"},{"fr":"Le train de nuit part à quelle heure ?","tgt":"รถไฟกลางคืนออกกี่โมงครับ","ro":"Rót-fai klaang-khuen àwk kìi moong khráp?","lit":"train · nuit · partir · combien · heure · [politesse]"},{"fr":"À six heures du soir.","tgt":"หกโมงเย็นครับ","ro":"Hòk moong yen khráp.","lit":"six · heure · soir · [politesse]"},{"fr":"Il reste encore des couchettes ?","tgt":"ยังมีเตียงไหมครับ","ro":"Yang mii tiang mái khráp?","lit":"encore · avoir · lit · [question] · [politesse]"},{"fr":"Oui, en haut ou en bas ?","tgt":"มีครับ ข้างบนหรือข้างล่างครับ","ro":"Mii khráp, khâang-bon rǔe khâang-lâang khráp?","lit":"avoir · [politesse] · côté haut · ou · côté bas · [politesse]"},{"fr":"En bas, c'est mieux.","tgt":"ข้างล่างดีกว่าครับ","ro":"Khâang-lâang dii kwàa khráp.","lit":"côté bas · bien · plus · [politesse]"},{"fr":"Le train est-il climatisé ?","tgt":"รถไฟมีแอร์ไหมครับ","ro":"Rót-fai mii ae mái khráp?","lit":"train · avoir · clim · [question] · [politesse]"},{"fr":"Le trajet dure douze heures.","tgt":"ใช้เวลาสิบสองชั่วโมงครับ","ro":"Chái wee-laa sìp-sǎwng chûa-moong khráp.","lit":"utiliser · temps · douze · heure · [politesse]"},{"fr":"D'accord, je le prends.","tgt":"ผมเอาครับ","ro":"Phǒm ao khráp.","lit":"je (homme) · prendre · [politesse]"},{"fr":"Tenez, votre billet, et bonne route.","tgt":"นี่ตั๋วครับ เดินทางปลอดภัยนะครับ","ro":"Nîi tǔa khráp, doen-thaang plàwt-phai ná khráp.","lit":"voici · billet · [politesse] · voyager · sûr · [douceur] · [politesse]"}]},{"title":"À la réception de l'hôtel","phrases":[{"fr":"Je voudrais une chambre, s'il vous plaît.","tgt":"ขอห้องหนึ่งห้องครับ","ro":"Khǎw hâwng nùeng hâwng khráp.","lit":"demander · chambre · un · [classificateur] · [politesse]"},{"fr":"Pour deux nuits.","tgt":"สองคืนครับ","ro":"Sǎwng khuen khráp.","lit":"deux · nuit · [politesse]"},{"fr":"Je peux voir votre passeport, s'il vous plaît ?","tgt":"ขอดูหนังสือเดินทางหน่อยครับ","ro":"Khǎw duu nǎng-sǔe-doen-thaang nàwy khráp.","lit":"demander · voir · passeport · un peu · [politesse]"},{"fr":"Donnez-moi la clé, s'il vous plaît.","tgt":"ขอกุญแจครับ","ro":"Khǎw kun-jae khráp.","lit":"demander · clé · [politesse]"},{"fr":"Un peu d'eau, s'il vous plaît.","tgt":"ขอน้ำหน่อยครับ","ro":"Khǎw náam nàwy khráp.","lit":"demander · eau · un peu · [politesse]"},{"fr":"Une serviette de plus, s'il vous plaît.","tgt":"ขอผ้าเช็ดตัวอีกผืนครับ","ro":"Khǎw phâa-chét-tua ìik phǔen khráp.","lit":"demander · serviette · encore · [classificateur] · [politesse]"},{"fr":"Le petit-déjeuner est à quelle heure ?","tgt":"อาหารเช้ากี่โมงครับ","ro":"Aa-hǎan-cháo kìi moong khráp?","lit":"nourriture · matin · combien · heure · [politesse]"},{"fr":"À sept heures du matin.","tgt":"เจ็ดโมงเช้าครับ","ro":"Jèt moong cháo khráp.","lit":"sept · heure · matin · [politesse]"},{"fr":"Un plan de la ville, s'il vous plaît.","tgt":"ขอแผนที่เมืองหน่อยครับ","ro":"Khǎw phǎen-thîi mueang nàwy khráp.","lit":"demander · plan · ville · un peu · [politesse]"},{"fr":"Laissez-moi un instant, s'il vous plaît.","tgt":"ขอเวลาสักครู่ครับ","ro":"Khǎw wee-laa sàk-khrûu khráp.","lit":"demander · temps · un instant · [politesse]"}],"tip":{"title":"« Khǎw » : donnez-moi, s'il vous plaît","example":"Un peu d'eau, s'il vous plaît. — <b>ขอ</b>น้ำหน่อยครับ","body":"Voici sans doute le mot le plus utile du voyage : « khǎw », qui veut dire je demande, donnez-moi. Il se prononce avec un ton montant, comme une petite question en français. On le place au tout début de la phrase, puis on dit simplement la chose voulue, et on termine par « khráp » si l'on est un homme, ou « khâ » si l'on est une femme. Décomposons « khǎw náam nàwy khráp » : demander, eau, un peu, politesse, c'est-à-dire un peu d'eau, s'il vous plaît. Le petit mot « nàwy », un peu, adoucit la demande, un peu comme notre « s'il vous plaît ». Avec ce seul modèle, vous dites déjà « khǎw kun-jae », la clé s'il vous plaît, ou « khǎw phǎen-thîi », un plan s'il vous plaît. Et si vous ajoutez « duu », voir, vous obtenez « khǎw duu », est-ce que je peux voir. Pour retenir, pensez à une main tendue : « khǎw », puis l'objet, puis le sourire de « khráp ».","exampleRo":"Khǎw náam nàwy khráp.","lit":"demander · eau · un peu · [politesse]","say":{"Khǎw":"ขอ","khǎw":"ขอ","khráp":"ครับ","khâ":"ค่ะ","khǎw náam nàwy khráp":"ขอน้ำหน่อยครับ","nàwy":"หน่อย","khǎw kun-jae":"ขอกุญแจ","khǎw phǎen-thîi":"ขอแผนที่","duu":"ดู","khǎw duu":"ขอดู"}}},{"title":"Une nuit dans le train","phrases":[{"fr":"Ma couchette est juste ici.","tgt":"เตียงผมอยู่ตรงนี้ครับ","ro":"Tiang phǒm yùu trong-níi khráp.","lit":"lit · je (homme) · se trouver · juste ici · [politesse]"},{"fr":"Pardon, cette place est la mienne.","tgt":"ขอโทษครับ นี่ที่ของผมครับ","ro":"Khǎw-thôot khráp, nîi thîi khǎwng phǒm khráp.","lit":"pardon · [politesse] · ceci · place · [de] · je (homme) · [politesse]"},{"fr":"Où se trouve le wagon-restaurant ?","tgt":"ตู้เสบียงอยู่ไหนครับ","ro":"Tûu-sà-biang yùu nǎi khráp?","lit":"wagon-restaurant · se trouver · où · [politesse]"},{"fr":"J'ai un tout petit peu faim.","tgt":"ผมหิวนิดหน่อยครับ","ro":"Phǒm hǐw nít-nàwy khráp.","lit":"je (homme) · avoir faim · un peu · [politesse]"},{"fr":"Le train roule très lentement.","tgt":"รถไฟวิ่งช้ามากครับ","ro":"Rót-fai wîng cháa mâak khráp.","lit":"train · courir · lent · très · [politesse]"},{"fr":"On arrive vers quelle heure ?","tgt":"ถึงกี่โมงครับ","ro":"Thǔeng kìi moong khráp?","lit":"arriver · combien · heure · [politesse]"},{"fr":"Vers sept heures du matin.","tgt":"ประมาณเจ็ดโมงเช้าครับ","ro":"Prà-maan jèt moong cháo khráp.","lit":"environ · sept · heure · matin · [politesse]"},{"fr":"Il fait très froid dans le wagon.","tgt":"ในตู้หนาวมากครับ","ro":"Nai tûu nǎao mâak khráp.","lit":"dans · wagon · froid · très · [politesse]"},{"fr":"Vous avez une couverture ?","tgt":"มีผ้าห่มไหมครับ","ro":"Mii phâa-hòm mái khráp?","lit":"avoir · couverture · [question] · [politesse]"},{"fr":"Bon, je vais me coucher.","tgt":"ผมไปนอนก่อนนะครับ","ro":"Phǒm pai nawn kàwn ná khráp.","lit":"je (homme) · aller · dormir · d'abord · [douceur] · [politesse]"}]},{"title":"Le marché de nuit de Chiang Mai","phrases":[{"fr":"Celui-ci, c'est combien ?","tgt":"อันนี้เท่าไรครับ","ro":"An-níi thâo-rài khráp?","lit":"[classificateur] · ceci · combien · [politesse]"},{"fr":"Cent bahts.","tgt":"ร้อยบาทครับ","ro":"Ráwy bàat khráp.","lit":"cent · baht · [politesse]"},{"fr":"C'est un peu trop cher.","tgt":"แพงไปหน่อยครับ","ro":"Phaeng pai nàwy khráp.","lit":"cher · trop · un peu · [politesse]"},{"fr":"Vous pouvez faire un prix ?","tgt":"ลดได้ไหมครับ","ro":"Lót dâi mái khráp?","lit":"baisser · pouvoir · [question] · [politesse]"},{"fr":"Quatre-vingts bahts, c'est possible ?","tgt":"แปดสิบบาทได้ไหมครับ","ro":"Pàet-sìp bàat dâi mái khráp?","lit":"huit · dix · baht · pouvoir · [question] · [politesse]"},{"fr":"Cette chemise coûte combien ?","tgt":"เสื้อตัวนี้เท่าไรครับ","ro":"Sûea tua níi thâo-rài khráp?","lit":"chemise · [classificateur] · ce · combien · [politesse]"},{"fr":"Deux cents bahts pour les deux.","tgt":"สองตัวสองร้อยบาทครับ","ro":"Sǎwng tua sǎwng ráwy bàat khráp.","lit":"deux · [classificateur] · deux · cent · baht · [politesse]"},{"fr":"Et pour le tout, ça fait combien ?","tgt":"ทั้งหมดเท่าไรครับ","ro":"Tháng-mòt thâo-rài khráp?","lit":"en tout · combien · [politesse]"},{"fr":"Le porc grillé, c'est combien la brochette ?","tgt":"หมูปิ้งไม้ละเท่าไรครับ","ro":"Mǔu-pîng mái lá thâo-rài khráp?","lit":"porc · griller · bâton · chaque · combien · [politesse]"},{"fr":"Dix bahts la brochette.","tgt":"ไม้ละสิบบาทครับ","ro":"Mái lá sìp bàat khráp.","lit":"bâton · chaque · dix · baht · [politesse]"}],"tip":{"title":"« Thâo-rài » : demander un prix, les bahts","example":"Celui-ci, c'est combien ? — อันนี้<b>เท่าไร</b>ครับ","body":"Au marché, un seul mot vous ouvre toutes les portes : « thâo-rài », combien. La première syllabe descend, la seconde est basse, comme si la voix tombait doucement. Contrairement au français, le mot interrogatif ne se met pas au début mais tout à la fin, juste avant « khráp ». Décomposons « an-níi thâo-rài khráp » : chose, ceci, combien, politesse, donc celui-ci, c'est combien. On peut remplacer « an-níi » par n'importe quel objet : « sûea tua níi thâo-rài », cette chemise, combien. La réponse arrive avec le mot « bàat », le baht, placé après le nombre : « ráwy bàat », cent bahts, « sìp bàat », dix bahts. Pour le total, demandez « tháng-mòt thâo-rài », combien en tout. Astuce pour retenir : on montre d'abord la chose du doigt, puis on pose « thâo-rài » au bout de la phrase, comme un point d'interrogation.","exampleRo":"An-níi thâo-rài khráp?","lit":"[classificateur] · ceci · combien · [politesse]","say":{"Thâo-rài":"เท่าไร","thâo-rài":"เท่าไร","khráp":"ครับ","an-níi thâo-rài khráp":"อันนี้เท่าไรครับ","an-níi":"อันนี้","sûea tua níi thâo-rài":"เสื้อตัวนี้เท่าไร","bàat":"บาท","ráwy bàat":"ร้อยบาท","sìp bàat":"สิบบาท","tháng-mòt thâo-rài":"ทั้งหมดเท่าไร"}}},{"title":"Les ruines d'Ayutthaya","phrases":[{"fr":"Le site historique est immense.","tgt":"โบราณสถานใหญ่มากครับ","ro":"Boo-raan-sà-thǎan yài mâak khráp.","lit":"site ancien · grand · très · [politesse]"},{"fr":"On loue un vélo ?","tgt":"เช่าจักรยานไหมครับ","ro":"Châo jàk-krà-yaan mái khráp?","lit":"louer · vélo · [question] · [politesse]"},{"fr":"Oui, c'est plus pratique.","tgt":"ครับ สะดวกกว่าครับ","ro":"Khráp, sà-dùak kwàa khráp.","lit":"oui · commode · plus · [politesse]"},{"fr":"Ce temple est très ancien.","tgt":"วัดนี้เก่ามากครับ","ro":"Wát níi kào mâak khráp.","lit":"temple · ce · vieux · très · [politesse]"},{"fr":"C'est vraiment magnifique.","tgt":"สวยจริงๆครับ","ro":"Sǔay jing-jing khráp.","lit":"beau · vrai · vrai · [politesse]"},{"fr":"On peut prendre des photos ici ?","tgt":"ถ่ายรูปได้ไหมครับ","ro":"Thàai rûup dâi mái khráp?","lit":"prendre · photo · pouvoir · [question] · [politesse]"},{"fr":"À midi, il fait très chaud.","tgt":"ตอนเที่ยงร้อนมากครับ","ro":"Tawn thîang ráwn mâak khráp.","lit":"moment · midi · chaud · très · [politesse]"},{"fr":"Buvons un peu d'eau.","tgt":"ดื่มน้ำกันเถอะครับ","ro":"Dùem náam kan thòe khráp.","lit":"boire · eau · ensemble · [incitation] · [politesse]"},{"fr":"Il y a beaucoup de touristes.","tgt":"นักท่องเที่ยวเยอะมากครับ","ro":"Nák-thâwng-thîao yóe mâak khráp.","lit":"touriste · nombreux · très · [politesse]"},{"fr":"Ayutthaya me plaît beaucoup.","tgt":"ผมชอบอยุธยามากครับ","ro":"Phǒm châwp À-yút-thá-yaa mâak khráp.","lit":"je (homme) · aimer · Ayutthaya · beaucoup · [politesse]"}]},{"title":"En bus vers Chiang Rai","phrases":[{"fr":"De Chiang Mai à Chiang Rai, il faut combien d'heures ?","tgt":"จากเชียงใหม่ถึงเชียงรายกี่ชั่วโมงครับ","ro":"Jàak Chiang-mài thǔeng Chiang-raai kìi chûa-moong khráp?","lit":"depuis · Chiang Mai · jusqu'à · Chiang Rai · combien · heure · [politesse]"},{"fr":"Environ trois heures.","tgt":"ประมาณสามชั่วโมงครับ","ro":"Prà-maan sǎam chûa-moong khráp.","lit":"environ · trois · heure · [politesse]"},{"fr":"Le bus part de la gare routière.","tgt":"รถออกจากสถานีขนส่งครับ","ro":"Rót àwk jàak sà-thǎa-nii khǒn-sòng khráp.","lit":"véhicule · sortir · depuis · gare routière · [politesse]"},{"fr":"Un billet pour Chiang Rai, s'il vous plaît.","tgt":"ขอตั๋วไปเชียงรายหนึ่งใบครับ","ro":"Khǎw tǔa pai Chiang-raai nùeng bai khráp.","lit":"demander · billet · aller · Chiang Rai · un · [classificateur] · [politesse]"},{"fr":"De l'hôtel à la gare, c'est loin ?","tgt":"จากโรงแรมถึงสถานีไกลไหมครับ","ro":"Jàak roong-raem thǔeng sà-thǎa-nii klai mái khráp?","lit":"depuis · hôtel · jusqu'à · gare · loin · [question] · [politesse]"},{"fr":"Non, à dix minutes seulement.","tgt":"ไม่ไกลครับ แค่สิบนาที","ro":"Mâi klai khráp, khâe sìp naa-thii.","lit":"ne pas · loin · [politesse] · seulement · dix · minute"},{"fr":"Le bus s'arrête en route ?","tgt":"รถจอดระหว่างทางไหมครับ","ro":"Rót jàwt rá-wàang-thaang mái khráp?","lit":"véhicule · s'arrêter · en cours de route · [question] · [politesse]"},{"fr":"De la gare au centre, on peut marcher.","tgt":"จากสถานีถึงตัวเมืองเดินได้ครับ","ro":"Jàak sà-thǎa-nii thǔeng tua-mueang doen dâi khráp.","lit":"depuis · gare · jusqu'à · centre-ville · marcher · pouvoir · [politesse]"},{"fr":"De Bangkok à Chiang Mai, c'est très loin.","tgt":"จากกรุงเทพถึงเชียงใหม่ไกลมากครับ","ro":"Jàak Krung-thêep thǔeng Chiang-mài klai mâak khráp.","lit":"depuis · Bangkok · jusqu'à · Chiang Mai · loin · très · [politesse]"},{"fr":"Ce bus est bien confortable.","tgt":"รถคันนี้สบายดีครับ","ro":"Rót khan níi sà-baai dii khráp.","lit":"véhicule · [classificateur] · ce · confortable · bien · [politesse]"}],"tip":{"title":"« Jàak... thǔeng... » : de... à...","example":"De Bangkok à Chiang Mai, c'est très loin. — <b>จาก</b>กรุงเทพ<b>ถึง</b>เชียงใหม่ไกลมากครับ","body":"Pour parler d'un trajet, le thaï utilise deux petits mots qui encadrent les lieux : « jàak », depuis, avec un ton bas, et « thǔeng », jusqu'à, avec un ton montant. L'ordre est le même qu'en français : on dit d'abord le point de départ, puis l'arrivée. Décomposons « jàak Krung-thêep thǔeng Chiang-mài klai mâak » : depuis Bangkok, jusqu'à Chiang Mai, loin, très. Remarquez que le mot « loin » vient après le trajet, sans aucun verbe être. On peut ensuite poser une question avec « kìi chûa-moong », combien d'heures : « jàak Chiang-mài thǔeng Chiang-raai kìi chûa-moong ». Le mot « jàak » s'emploie aussi tout seul après un verbe : « àwk jàak sà-thǎa-nii », partir de la gare. Et « thǔeng » tout seul veut dire arriver : « thǔeng láew », on est arrivé. Pour retenir, imaginez une ligne de bus : « jàak » au départ en bas, « thǔeng » à l'arrivée, la voix qui remonte.","exampleRo":"Jàak Krung-thêep thǔeng Chiang-mài klai mâak khráp.","lit":"depuis · Bangkok · jusqu'à · Chiang Mai · loin · très · [politesse]","say":{"Jàak... thǔeng...":"จาก ถึง","jàak":"จาก","thǔeng":"ถึง","jàak Krung-thêep thǔeng Chiang-mài klai mâak":"จากกรุงเทพถึงเชียงใหม่ไกลมาก","kìi chûa-moong":"กี่ชั่วโมง","jàak Chiang-mài thǔeng Chiang-raai kìi chûa-moong":"จากเชียงใหม่ถึงเชียงรายกี่ชั่วโมง","àwk jàak sà-thǎa-nii":"ออกจากสถานี","thǔeng láew":"ถึงแล้ว"}}},{"title":"Des bagages à gérer","phrases":[{"fr":"Ma valise est très lourde.","tgt":"กระเป๋าผมหนักมากครับ","ro":"Krà-pǎo phǒm nàk mâak khráp.","lit":"valise · je (homme) · lourd · très · [politesse]"},{"fr":"Je peux laisser ma valise ici ?","tgt":"ฝากกระเป๋าไว้ที่นี่ได้ไหมครับ","ro":"Fàak krà-pǎo wái thîi-nîi dâi mái khráp?","lit":"confier · valise · garder · ici · pouvoir · [question] · [politesse]"},{"fr":"Bien sûr, jusqu'à quelle heure ?","tgt":"ได้ครับ ถึงกี่โมงครับ","ro":"Dâi khráp, thǔeng kìi moong khráp?","lit":"pouvoir · [politesse] · jusqu'à · combien · heure · [politesse]"},{"fr":"Jusqu'à trois heures de l'après-midi.","tgt":"ถึงบ่ายสามโมงครับ","ro":"Thǔeng bàai sǎam moong khráp.","lit":"jusqu'à · après-midi · trois · heure · [politesse]"},{"fr":"J'ai deux valises avec moi.","tgt":"ผมมีกระเป๋าสองใบครับ","ro":"Phǒm mii krà-pǎo sǎwng bai khráp.","lit":"je (homme) · avoir · valise · deux · [classificateur] · [politesse]"},{"fr":"Ce sac-là est à moi.","tgt":"กระเป๋าใบนี้ของผมครับ","ro":"Krà-pǎo bai níi khǎwng phǒm khráp.","lit":"sac · [classificateur] · ce · [de] · je (homme) · [politesse]"},{"fr":"Où est passé mon sac à dos ?","tgt":"เป้ของผมอยู่ไหนครับ","ro":"Pêe khǎwng phǒm yùu nǎi khráp?","lit":"sac à dos · [de] · je (homme) · se trouver · où · [politesse]"},{"fr":"Il est sous le lit.","tgt":"อยู่ใต้เตียงครับ","ro":"Yùu tâi tiang khráp.","lit":"se trouver · sous · lit · [politesse]"},{"fr":"Attention, c'est fragile.","tgt":"ระวังนะครับ ของแตกง่าย","ro":"Rá-wang ná khráp, khǎwng tàek ngâai.","lit":"faire attention · [douceur] · [politesse] · chose · casser · facile"},{"fr":"Merci pour votre aide.","tgt":"ขอบคุณที่ช่วยครับ","ro":"Khàwp-khun thîi chûay khráp.","lit":"merci · que · aider · [politesse]"}]},{"title":"Bien arrivés à Chiang Rai","phrases":[{"fr":"Ça y est, on est arrivés !","tgt":"ถึงแล้วครับ","ro":"Thǔeng láew khráp.","lit":"arriver · [accompli] · [politesse]"},{"fr":"J'ai déjà réservé l'hôtel.","tgt":"ผมจองโรงแรมแล้วครับ","ro":"Phǒm jawng roong-raem láew khráp.","lit":"je (homme) · réserver · hôtel · [accompli] · [politesse]"},{"fr":"Vous avez déjà mangé ?","tgt":"กินข้าวหรือยังครับ","ro":"Kin khâao rǔe yang khráp?","lit":"manger · riz · ou · pas encore · [politesse]"},{"fr":"Oui, j'ai déjà mangé.","tgt":"กินแล้วครับ","ro":"Kin láew khráp.","lit":"manger · [accompli] · [politesse]"},{"fr":"Le bus est déjà reparti.","tgt":"รถออกไปแล้วครับ","ro":"Rót àwk pai láew khráp.","lit":"véhicule · sortir · aller · [accompli] · [politesse]"},{"fr":"Les billets, je les ai déjà achetés.","tgt":"ผมซื้อตั๋วแล้วครับ","ro":"Phǒm súe tǔa láew khráp.","lit":"je (homme) · acheter · billet · [accompli] · [politesse]"},{"fr":"Tiens, il commence à pleuvoir.","tgt":"ฝนตกแล้วครับ","ro":"Fǒn tòk láew khráp.","lit":"pluie · tomber · [accompli] · [politesse]"},{"fr":"La boutique a déjà fermé.","tgt":"ร้านปิดแล้วครับ","ro":"Ráan pìt láew khráp.","lit":"boutique · fermer · [accompli] · [politesse]"},{"fr":"Ça y est, je suis prêt.","tgt":"ผมพร้อมแล้วครับ","ro":"Phǒm phráwm láew khráp.","lit":"je (homme) · prêt · [accompli] · [politesse]"},{"fr":"Il est déjà tard.","tgt":"ดึกแล้วครับ","ro":"Dùek láew khráp.","lit":"tard dans la nuit · [accompli] · [politesse]"}],"tip":{"title":"« Láew » : l'action accomplie","example":"J'ai déjà réservé l'hôtel. — ผมจองโรงแรม<b>แล้ว</b>ครับ","body":"Puisque le verbe thaï ne se conjugue pas, comment dire que quelque chose est fait ? On ajoute « láew », avec un ton haut, à la fin de la phrase, juste avant « khráp ». Ce petit mot signifie c'est fait, ça y est, déjà. Décomposons « phǒm jawng roong-raem láew khráp » : je, réserver, hôtel, accompli, politesse, c'est-à-dire j'ai déjà réservé l'hôtel. « Láew » marque aussi un changement de situation : « fǒn tòk láew », voilà qu'il pleut, ou « dùek láew », il est déjà tard. Le mot le plus célèbre est « thǔeng láew », on est arrivés, que vous entendrez dans tous les bus. Pour demander si c'est fait, on dit « rǔe yang », ou pas encore : « kin khâao rǔe yang », vous avez mangé. On répond « kin láew », c'est fait, ou « yang », pas encore. Astuce : pensez à « láew » comme à un petit tampon posé en fin de phrase, qui dit c'est réglé.","exampleRo":"Phǒm jawng roong-raem láew khráp.","lit":"je (homme) · réserver · hôtel · [accompli] · [politesse]","say":{"Láew":"แล้ว","láew":"แล้ว","khráp":"ครับ","phǒm jawng roong-raem láew khráp":"ผมจองโรงแรมแล้วครับ","fǒn tòk láew":"ฝนตกแล้ว","dùek láew":"ดึกแล้ว","thǔeng láew":"ถึงแล้ว","rǔe yang":"หรือยัง","kin khâao rǔe yang":"กินข้าวหรือยัง","kin láew":"กินแล้ว","yang":"ยัง"}}},{"title":"Perdu avec un plan","phrases":[{"fr":"Je crois que je me suis perdu.","tgt":"ผมหลงทางครับ","ro":"Phǒm lǒng thaang khráp.","lit":"je (homme) · s'égarer · chemin · [politesse]"},{"fr":"On est où sur le plan ?","tgt":"เราอยู่ตรงไหนในแผนที่ครับ","ro":"Rao yùu trong-nǎi nai phǎen-thîi khráp?","lit":"nous · se trouver · à quel endroit · dans · plan · [politesse]"},{"fr":"Ici, à côté du marché.","tgt":"ตรงนี้ครับ ข้างตลาด","ro":"Trong-níi khráp, khâang tà-làat.","lit":"juste ici · [politesse] · à côté · marché"},{"fr":"Le musée, c'est par où ?","tgt":"พิพิธภัณฑ์ไปทางไหนครับ","ro":"Phí-phít-thá-phan pai thaang nǎi khráp?","lit":"musée · aller · direction · quel · [politesse]"},{"fr":"Allez d'abord tout droit.","tgt":"ตรงไปก่อนครับ","ro":"Trong pai kàwn khráp.","lit":"droit · aller · d'abord · [politesse]"},{"fr":"Puis tournez à gauche.","tgt":"แล้วเลี้ยวซ้ายครับ","ro":"Láew líao sáai khráp.","lit":"puis · tourner · gauche · [politesse]"},{"fr":"C'est sur la droite ?","tgt":"อยู่ทางขวาไหมครับ","ro":"Yùu thaang khwǎa mái khráp?","lit":"se trouver · côté · droite · [question] · [politesse]"},{"fr":"Non, c'est juste en face.","tgt":"ไม่ใช่ครับ อยู่ตรงข้ามครับ","ro":"Mâi châi khráp, yùu trong-khâam khráp.","lit":"ne pas · exact · [politesse] · se trouver · en face · [politesse]"},{"fr":"Vous pouvez me le montrer sur le plan ?","tgt":"ช่วยชี้ในแผนที่หน่อยครับ","ro":"Chûay chíi nai phǎen-thîi nàwy khráp.","lit":"aider · montrer du doigt · dans · plan · un peu · [politesse]"},{"fr":"Merci beaucoup, j'ai compris.","tgt":"ขอบคุณมากครับ เข้าใจแล้ว","ro":"Khàwp-khun mâak khráp, khâo-jai láew.","lit":"merci · beaucoup · [politesse] · comprendre · [accompli]"}]},{"title":"Comment on y va ?","phrases":[{"fr":"Le Temple Blanc, on y va comment ?","tgt":"ไปวัดร่องขุ่นยังไงครับ","ro":"Pai Wát-râwng-khùn yang-ngai khráp?","lit":"aller · Temple Blanc · comment · [politesse]"},{"fr":"Vous pouvez y aller en bus.","tgt":"นั่งรถเมล์ไปได้ครับ","ro":"Nâng rót-mee pai dâi khráp.","lit":"s'asseoir · bus · aller · pouvoir · [politesse]"},{"fr":"Comment ça se dit en thaï ?","tgt":"ภาษาไทยพูดยังไงครับ","ro":"Phaa-sǎa thai phûut yang-ngai khráp?","lit":"langue · thaï · dire · comment · [politesse]"},{"fr":"Cette machine, ça marche comment ?","tgt":"เครื่องนี้ใช้ยังไงครับ","ro":"Khrûeang níi chái yang-ngai khráp?","lit":"machine · ce · utiliser · comment · [politesse]"},{"fr":"Ce plat, on le mange comment ?","tgt":"อาหารนี้กินยังไงครับ","ro":"Aa-hǎan níi kin yang-ngai khráp?","lit":"plat · ce · manger · comment · [politesse]"},{"fr":"Avec du riz gluant.","tgt":"กินกับข้าวเหนียวครับ","ro":"Kin kàp khâao-nǐao khráp.","lit":"manger · avec · riz gluant · [politesse]"},{"fr":"Alors, Chiang Rai, c'est comment ?","tgt":"เชียงรายเป็นยังไงบ้างครับ","ro":"Chiang-raai pen yang-ngai bâang khráp?","lit":"Chiang Rai · être · comment · [un peu] · [politesse]"},{"fr":"C'est calme et joli.","tgt":"เงียบและสวยครับ","ro":"Ngîap láe sǔay khráp.","lit":"calme · et · beau · [politesse]"},{"fr":"Comment je rentre à l'hôtel ?","tgt":"ผมกลับโรงแรมยังไงครับ","ro":"Phǒm klàp roong-raem yang-ngai khráp?","lit":"je (homme) · rentrer · hôtel · comment · [politesse]"},{"fr":"Prenez donc un tuk-tuk.","tgt":"นั่งตุ๊กตุ๊กครับ","ro":"Nâng túk-túk khráp.","lit":"s'asseoir · tuk-tuk · [politesse]"}],"tip":{"title":"« Yang-ngai » : comment","example":"Le Temple Blanc, on y va comment ? — ไปวัดร่องขุ่น<b>ยังไง</b>ครับ","body":"Pour demander comment, le thaï parlé utilise « yang-ngai », deux syllabes au ton moyen, bien à plat. Comme tous les mots de question en thaï, il se place à la fin de la phrase, juste avant la politesse. Le français parlé fait d'ailleurs pareil quand on dit « on y va comment ». Décomposons « pai Wát-râwng-khùn yang-ngai khráp » : aller, Temple Blanc, comment, politesse. Il suffit de changer le verbe pour poser mille questions : « chái yang-ngai », ça s'utilise comment, « kin yang-ngai », ça se mange comment, « phûut yang-ngai », ça se dit comment. Avec le verbe être, « pen yang-ngai bâang » sert à demander des nouvelles ou un avis : « Chiang-raai pen yang-ngai bâang », alors, Chiang Rai, c'est comment. Astuce pour retenir : dites d'abord l'action que vous voulez faire, puis ajoutez « yang-ngai » comme un haussement d'épaules.","exampleRo":"Pai Wát-râwng-khùn yang-ngai khráp?","lit":"aller · Temple Blanc · comment · [politesse]","say":{"Yang-ngai":"ยังไง","yang-ngai":"ยังไง","pai Wát-râwng-khùn yang-ngai khráp":"ไปวัดร่องขุ่นยังไงครับ","chái yang-ngai":"ใช้ยังไง","kin yang-ngai":"กินยังไง","phûut yang-ngai":"พูดยังไง","pen yang-ngai bâang":"เป็นยังไงบ้าง","Chiang-raai pen yang-ngai bâang":"เชียงรายเป็นยังไงบ้าง"}}},{"title":"Un passage à la pharmacie","phrases":[{"fr":"Il y a une pharmacie dans le coin ?","tgt":"แถวนี้มีร้านขายยาไหมครับ","ro":"Thǎeo-níi mii ráan-khǎai-yaa mái khráp?","lit":"par ici · avoir · pharmacie · [question] · [politesse]"},{"fr":"J'ai un peu mal à la tête.","tgt":"ผมปวดหัวนิดหน่อยครับ","ro":"Phǒm pùat hǔa nít-nàwy khráp.","lit":"je (homme) · avoir mal · tête · un peu · [politesse]"},{"fr":"J'ai mal au ventre depuis hier.","tgt":"ผมปวดท้องตั้งแต่เมื่อวานครับ","ro":"Phǒm pùat tháwng tâng-tàe mûea-waan khráp.","lit":"je (homme) · avoir mal · ventre · depuis · hier · [politesse]"},{"fr":"Vous avez de la fièvre ?","tgt":"มีไข้ไหมครับ","ro":"Mii khâi mái khráp?","lit":"avoir · fièvre · [question] · [politesse]"},{"fr":"Non, je n'ai pas de fièvre.","tgt":"ไม่มีครับ","ro":"Mâi mii khráp.","lit":"ne pas · avoir · [politesse]"},{"fr":"Prenez ce médicament-ci.","tgt":"กินยานี้นะครับ","ro":"Kin yaa níi ná khráp.","lit":"manger · médicament · ce · [douceur] · [politesse]"},{"fr":"Combien de fois par jour ?","tgt":"วันละกี่ครั้งครับ","ro":"Wan lá kìi khráng khráp?","lit":"jour · chaque · combien · fois · [politesse]"},{"fr":"Trois fois, après les repas.","tgt":"สามครั้งหลังอาหารครับ","ro":"Sǎam khráng lǎng aa-hǎan khráp.","lit":"trois · fois · après · repas · [politesse]"},{"fr":"Les moustiques m'ont piqué.","tgt":"ยุงกัดผมครับ","ro":"Yung kàt phǒm khráp.","lit":"moustique · mordre · je (homme) · [politesse]"},{"fr":"Vous avez une pommade ?","tgt":"มียาทาไหมครับ","ro":"Mii yaa-thaa mái khráp?","lit":"avoir · médicament · appliquer · [question] · [politesse]"}]},{"title":"Est-ce qu'on peut ?","phrases":[{"fr":"On peut payer par carte ?","tgt":"จ่ายด้วยบัตรได้ไหมครับ","ro":"Jàai dûay bàt dâi mái khráp?","lit":"payer · avec · carte · pouvoir · [question] · [politesse]"},{"fr":"Oui, sans aucun problème.","tgt":"ได้ครับ ไม่มีปัญหา","ro":"Dâi khráp, mâi mii pan-hǎa.","lit":"pouvoir · [politesse] · ne pas · avoir · problème"},{"fr":"Je n'arrive pas à dormir, c'est trop bruyant.","tgt":"ผมนอนไม่ได้ครับ เสียงดังมาก","ro":"Phǒm nawn mâi dâi khráp, sǐang dang mâak.","lit":"je (homme) · dormir · ne pas · pouvoir · [politesse] · bruit · fort · très"},{"fr":"Vous parlez français ?","tgt":"พูดภาษาฝรั่งเศสได้ไหมครับ","ro":"Phûut phaa-sǎa fà-ràng-sèet dâi mái khráp?","lit":"parler · langue · France · pouvoir · [question] · [politesse]"},{"fr":"Juste un tout petit peu.","tgt":"ได้นิดหน่อยครับ","ro":"Dâi nít-nàwy khráp.","lit":"pouvoir · un peu · [politesse]"},{"fr":"Moi, je parle un peu thaï.","tgt":"ผมพูดภาษาไทยได้นิดหน่อยครับ","ro":"Phǒm phûut phaa-sǎa thai dâi nít-nàwy khráp.","lit":"je (homme) · parler · langue · thaï · pouvoir · un peu · [politesse]"},{"fr":"Vous pouvez parler lentement ?","tgt":"พูดช้าๆได้ไหมครับ","ro":"Phûut cháa-cháa dâi mái khráp?","lit":"parler · lent · lent · pouvoir · [question] · [politesse]"},{"fr":"On peut se baigner ici ?","tgt":"ว่ายน้ำที่นี่ได้ไหมครับ","ro":"Wâai-náam thîi-nîi dâi mái khráp?","lit":"nager · ici · pouvoir · [question] · [politesse]"},{"fr":"Non, ce n'est pas autorisé.","tgt":"ไม่ได้ครับ","ro":"Mâi dâi khráp.","lit":"ne pas · pouvoir · [politesse]"},{"fr":"Je peux entrer avec mes chaussures ?","tgt":"ใส่รองเท้าเข้าไปได้ไหมครับ","ro":"Sài rawng-tháao khâo pai dâi mái khráp?","lit":"porter · chaussures · entrer · aller · pouvoir · [question] · [politesse]"}],"tip":{"title":"« Dâi » : pouvoir","example":"On peut payer par carte ? — จ่ายด้วยบัตร<b>ได้</b>ไหมครับ","body":"Le mot « dâi », avec un ton descendant, veut dire pouvoir, être possible. Sa grande particularité, c'est sa place : il ne se met pas avant le verbe comme en français, mais après toute l'action. On dit donc littéralement payer par carte pouvoir. Décomposons « jàai dûay bàt dâi mái khráp » : payer, avec, carte, pouvoir, question, politesse, soit on peut payer par carte. La réponse est toute simple : « dâi », oui c'est possible, ou « mâi dâi », non ce n'est pas possible. Pour la négation, « mâi » se glisse juste devant « dâi » : « nawn mâi dâi », je n'arrive pas à dormir. « Dâi » sert aussi pour les langues : « phûut phaa-sǎa thai dâi », je sais parler thaï. Astuce pour retenir : faites d'abord le geste dans votre tête, puis demandez à la fin « dâi mái », c'est possible, avec un sourire.","exampleRo":"Jàai dûay bàt dâi mái khráp?","lit":"payer · avec · carte · pouvoir · [question] · [politesse]","say":{"Dâi":"ได้","dâi":"ได้","jàai dûay bàt dâi mái khráp":"จ่ายด้วยบัตรได้ไหมครับ","mâi dâi":"ไม่ได้","mâi":"ไม่","nawn mâi dâi":"นอนไม่ได้","phûut phaa-sǎa thai dâi":"พูดภาษาไทยได้","dâi mái":"ได้ไหม"}}},{"title":"La vieille ville de Chiang Mai","phrases":[{"fr":"La vieille ville n'est pas très grande.","tgt":"เมืองเก่าไม่ใหญ่มากครับ","ro":"Mueang-kào mâi yài mâak khráp.","lit":"ville · vieux · ne pas · grand · très · [politesse]"},{"fr":"On peut tout visiter à pied, tranquillement.","tgt":"เดินเที่ยวได้สบายครับ","ro":"Doen thîao dâi sà-baai khráp.","lit":"marcher · se promener · pouvoir · tranquille · [politesse]"},{"fr":"Voici la porte Tha Phae.","tgt":"นี่คือประตูท่าแพครับ","ro":"Nîi khue prà-tuu Thâa-phae khráp.","lit":"ceci · c'est · porte · Tha Phae · [politesse]"},{"fr":"Il y a énormément de temples.","tgt":"มีวัดเยอะมากครับ","ro":"Mii wát yóe mâak khráp.","lit":"avoir · temple · nombreux · très · [politesse]"},{"fr":"Les rues sont étroites.","tgt":"ถนนแคบครับ","ro":"Thà-nǒn khâep khráp.","lit":"rue · étroit · [politesse]"},{"fr":"On boit un café ici ?","tgt":"ดื่มกาแฟที่นี่ไหมครับ","ro":"Dùem kaa-fae thîi-nîi mái khráp?","lit":"boire · café · ici · [question] · [politesse]"},{"fr":"Ce café est vraiment agréable.","tgt":"ร้านนี้น่านั่งมากครับ","ro":"Ráan níi nâa-nâng mâak khráp.","lit":"boutique · ce · agréable · s'asseoir · très · [politesse]"},{"fr":"Le dimanche, il y a un marché.","tgt":"วันอาทิตย์มีตลาดครับ","ro":"Wan aa-thít mii tà-làat khráp.","lit":"jour · dimanche · avoir · marché · [politesse]"},{"fr":"La cuisine du Nord est délicieuse.","tgt":"อาหารเหนืออร่อยมากครับ","ro":"Aa-hǎan nǔea à-ràwy mâak khráp.","lit":"nourriture · nord · délicieux · très · [politesse]"},{"fr":"Je veux goûter le khao soi.","tgt":"ผมอยากลองข้าวซอยครับ","ro":"Phǒm yàak lawng khâao-sawy khráp.","lit":"je (homme) · vouloir · essayer · khao soi · [politesse]"}]},{"title":"Des allers et venues","phrases":[{"fr":"On y va tous les deux ?","tgt":"ไปด้วยกันไหมครับ","ro":"Pai dûay-kan mái khráp?","lit":"aller · ensemble · [question] · [politesse]"},{"fr":"Venez par ici, s'il vous plaît.","tgt":"มานี่หน่อยครับ","ro":"Maa nîi nàwy khráp.","lit":"venir · ici · un peu · [politesse]"},{"fr":"Je vais au marché de nuit.","tgt":"ผมไปตลาดกลางคืนครับ","ro":"Phǒm pai tà-làat-klaang-khuen khráp.","lit":"je (homme) · aller · marché · nuit · [politesse]"},{"fr":"Et vous, vous venez d'où ?","tgt":"คุณมาจากไหนครับ","ro":"Khun maa jàak nǎi khráp?","lit":"vous · venir · depuis · où · [politesse]"},{"fr":"Moi, je suis de France.","tgt":"ผมมาจากฝรั่งเศสครับ","ro":"Phǒm maa jàak fà-ràng-sèet khráp.","lit":"je (homme) · venir · depuis · France · [politesse]"},{"fr":"Mon ami arrive ce soir.","tgt":"เพื่อนผมมาคืนนี้ครับ","ro":"Phûean phǒm maa khuen-níi khráp.","lit":"ami · je (homme) · venir · ce soir · [politesse]"},{"fr":"Je reviens tout de suite.","tgt":"เดี๋ยวกลับมาครับ","ro":"Dǐao klàp maa khráp.","lit":"un instant · retourner · venir · [politesse]"},{"fr":"Où est-il parti ?","tgt":"เขาไปไหนครับ","ro":"Khǎo pai nǎi khráp?","lit":"il · aller · où · [politesse]"},{"fr":"Apportez de l'eau, s'il vous plaît.","tgt":"เอาน้ำมาหน่อยครับ","ro":"Ao náam maa nàwy khráp.","lit":"prendre · eau · venir · un peu · [politesse]"},{"fr":"Emportez votre sac avec vous.","tgt":"เอากระเป๋าไปด้วยครับ","ro":"Ao krà-pǎo pai dûay khráp.","lit":"prendre · sac · aller · aussi · [politesse]"}],"tip":{"title":"« Pai » et « maa » : aller et venir, partout","example":"Apportez de l'eau, s'il vous plaît. — เอาน้ำ<b>มา</b>หน่อยครับ","body":"Deux petits verbes au ton moyen reviennent sans cesse en thaï : « pai », aller, qui s'éloigne de celui qui parle, et « maa », venir, qui se rapproche de lui. On les utilise d'abord seuls : « phǒm pai tà-làat », je vais au marché, « maa nîi », viens ici. Mais leur vraie magie, c'est qu'ils se collent après d'autres verbes pour indiquer la direction. Décomposons « ao náam maa nàwy khráp » : prendre, eau, venir, un peu, politesse, donc apportez de l'eau. Avec « pai » à la place, « ao krà-pǎo pai » veut dire emporter le sac, le prendre en s'éloignant. De même, « klàp maa » signifie revenir ici, alors que « klàp pai » veut dire repartir là-bas. Le français a besoin de deux verbes différents, apporter et emporter, alors que le thaï change seulement le dernier mot. Astuce pour retenir : « maa » vient vers moi, comme le son « m » de moi, et « pai » part au loin.","exampleRo":"Ao náam maa nàwy khráp.","lit":"prendre · eau · venir · un peu · [politesse]","say":{"Pai":"ไป","maa":"มา","pai":"ไป","phǒm pai tà-làat":"ผมไปตลาด","maa nîi":"มานี่","ao náam maa nàwy khráp":"เอาน้ำมาหน่อยครับ","ao krà-pǎo pai":"เอากระเป๋าไป","klàp maa":"กลับมา","klàp pai":"กลับไป"}}},{"title":"Un imprévu : le bus raté","phrases":[{"fr":"Zut, j'ai raté le bus.","tgt":"ผมตกรถครับ","ro":"Phǒm tòk rót khráp.","lit":"je (homme) · tomber · véhicule · [politesse]"},{"fr":"Le prochain part à quelle heure ?","tgt":"คันต่อไปกี่โมงครับ","ro":"Khan tàw-pai kìi moong khráp?","lit":"[classificateur] · suivant · combien · heure · [politesse]"},{"fr":"Dans une heure.","tgt":"อีกหนึ่งชั่วโมงครับ","ro":"Ìik nùeng chûa-moong khráp.","lit":"encore · un · heure · [politesse]"},{"fr":"Ce n'est rien, je peux attendre.","tgt":"ไม่เป็นไรครับ ผมรอได้","ro":"Mâi pen rai khráp, phǒm raw dâi.","lit":"ne pas · être · quoi · [politesse] · je (homme) · attendre · pouvoir"},{"fr":"Mon téléphone est déchargé.","tgt":"โทรศัพท์ผมแบตหมดครับ","ro":"Thoo-rá-sàp phǒm bàet mòt khráp.","lit":"téléphone · je (homme) · batterie · épuisé · [politesse]"},{"fr":"Il y a une prise par ici ?","tgt":"ที่นี่มีปลั๊กไหมครับ","ro":"Thîi-nîi mii plák mái khráp?","lit":"ici · avoir · prise · [question] · [politesse]"},{"fr":"J'ai perdu mon billet.","tgt":"ผมทำตั๋วหายครับ","ro":"Phǒm tham tǔa hǎai khráp.","lit":"je (homme) · faire · billet · disparaître · [politesse]"},{"fr":"Je dois en racheter un ?","tgt":"ต้องซื้อใหม่ไหมครับ","ro":"Tâwng súe mài mái khráp?","lit":"devoir · acheter · nouveau · [question] · [politesse]"},{"fr":"Oui, je suis désolé.","tgt":"ครับ ขอโทษด้วยครับ","ro":"Khráp, khǎw-thôot dûay khráp.","lit":"oui · pardon · aussi · [politesse]"},{"fr":"À l'aide, s'il vous plaît !","tgt":"ช่วยด้วยครับ","ro":"Chûay dûay khráp!","lit":"aider · aussi · [politesse]"}]},{"title":"C'est loin ou c'est près ?","phrases":[{"fr":"Est-ce que c'est loin d'ici ?","tgt":"ไกลจากที่นี่ไหมครับ","ro":"Klai jàak thîi-nîi mái khráp?","lit":"loin · depuis · ici · [question] · [politesse]"},{"fr":"Non, ce n'est pas loin, c'est très près.","tgt":"ไม่ไกลครับ ใกล้มาก","ro":"Mâi klai khráp, klâi mâak.","lit":"ne pas · loin · [politesse] · près · très"},{"fr":"L'hôtel est près du marché.","tgt":"โรงแรมอยู่ใกล้ตลาดครับ","ro":"Roong-raem yùu klâi tà-làat khráp.","lit":"hôtel · se trouver · près · marché · [politesse]"},{"fr":"L'aéroport est loin du centre.","tgt":"สนามบินอยู่ไกลจากตัวเมืองครับ","ro":"Sà-nǎam-bin yùu klai jàak tua-mueang khráp.","lit":"aéroport · se trouver · loin · depuis · centre-ville · [politesse]"},{"fr":"Il y a un restaurant près d'ici ?","tgt":"ใกล้ๆนี้มีร้านอาหารไหมครับ","ro":"Klâi-klâi níi mii ráan-aa-hǎan mái khráp?","lit":"près · près · ici · avoir · restaurant · [question] · [politesse]"},{"fr":"Le marché de nuit est tout proche.","tgt":"ตลาดกลางคืนอยู่ใกล้ๆครับ","ro":"Tà-làat-klaang-khuen yùu klâi-klâi khráp.","lit":"marché · nuit · se trouver · près · près · [politesse]"},{"fr":"C'est trop loin, je ne peux pas marcher.","tgt":"ไกลเกินไปครับ เดินไม่ไหว","ro":"Klai koen pai khráp, doen mâi wǎi.","lit":"loin · dépasser · trop · [politesse] · marcher · ne pas · tenir le coup"},{"fr":"Mieux vaut y aller en voiture.","tgt":"นั่งรถไปดีกว่าครับ","ro":"Nâng rót pai dii kwàa khráp.","lit":"s'asseoir · véhicule · aller · bien · plus · [politesse]"},{"fr":"Chiang Rai est très loin de Bangkok.","tgt":"เชียงรายไกลจากกรุงเทพมากครับ","ro":"Chiang-raai klai jàak Krung-thêep mâak khráp.","lit":"Chiang Rai · loin · depuis · Bangkok · très · [politesse]"},{"fr":"Ma chambre est près de l'ascenseur.","tgt":"ห้องผมอยู่ใกล้ลิฟต์ครับ","ro":"Hâwng phǒm yùu klâi líp khráp.","lit":"chambre · je (homme) · se trouver · près · ascenseur · [politesse]"}],"tip":{"title":"« Klai » et « klâi » : loin et près, attention au ton","example":"L'hôtel est près du marché. — โรงแรมอยู่<b>ใกล้</b>ตลาดครับ","body":"Voici le piège préféré des débutants : « klai » et « klâi » ont exactement les mêmes sons, seule la mélodie change. « Klai », avec un ton moyen bien plat, veut dire loin. « Klâi », avec un ton descendant, comme quand on dit « ah non » en français, veut dire près. Se tromper de ton, c'est donc dire le contraire de ce qu'on pense. Décomposons « roong-raem yùu klâi tà-làat khráp » : hôtel, se trouver, près, marché, politesse. Pour dire loin de quelque chose, on ajoute « jàak », depuis : « klai jàak thîi-nîi », loin d'ici. En revanche, « klâi » se met directement devant le lieu, sans petit mot. En répétant le mot, « klâi-klâi », on obtient tout près, dans les environs. Astuce pour retenir : pour loin, la voix reste tranquille et s'étire au loin, et pour près, elle tombe tout de suite, comme si on était déjà arrivé.","exampleRo":"Roong-raem yùu klâi tà-làat khráp.","lit":"hôtel · se trouver · près · marché · [politesse]","say":{"Klai":"ไกล","klâi":"ใกล้","klai":"ไกล","Klâi":"ใกล้","roong-raem yùu klâi tà-làat khráp":"โรงแรมอยู่ใกล้ตลาดครับ","jàak":"จาก","klai jàak thîi-nîi":"ไกลจากที่นี่","klâi-klâi":"ใกล้ๆ"}}},{"title":"Retour à l'aéroport","phrases":[{"fr":"Je quitte l'hôtel aujourd'hui.","tgt":"ผมจะออกจากโรงแรมวันนี้ครับ","ro":"Phǒm jà àwk jàak roong-raem wan-níi khráp.","lit":"je (homme) · [futur] · sortir · depuis · hôtel · aujourd'hui · [politesse]"},{"fr":"Vous pouvez m'appeler une voiture ?","tgt":"ช่วยเรียกรถให้หน่อยครับ","ro":"Chûay rîak rót hâi nàwy khráp.","lit":"aider · appeler · véhicule · pour moi · un peu · [politesse]"},{"fr":"Mon avion décolle à midi.","tgt":"เครื่องบินผมออกเที่ยงครับ","ro":"Khrûeang-bin phǒm àwk thîang khráp.","lit":"avion · je (homme) · partir · midi · [politesse]"},{"fr":"Je dois aller à quel guichet ?","tgt":"ต้องไปช่องไหนครับ","ro":"Tâwng pai châwng nǎi khráp?","lit":"devoir · aller · guichet · quel · [politesse]"},{"fr":"Votre valise pèse vingt kilos.","tgt":"กระเป๋าหนักยี่สิบกิโลครับ","ro":"Krà-pǎo nàk yîi-sìp kì-loo khráp.","lit":"valise · peser · vingt · kilo · [politesse]"},{"fr":"C'est au-dessus de la limite ?","tgt":"หนักเกินไหมครับ","ro":"Nàk koen mái khráp?","lit":"lourd · dépasser · [question] · [politesse]"},{"fr":"Non, ça passe.","tgt":"ไม่เกินครับ","ro":"Mâi koen khráp.","lit":"ne pas · dépasser · [politesse]"},{"fr":"C'est la porte cinq.","tgt":"ประตูห้าครับ","ro":"Prà-tuu hâa khráp.","lit":"porte · cinq · [politesse]"},{"fr":"L'avion part en retard.","tgt":"เครื่องบินออกช้าครับ","ro":"Khrûeang-bin àwk cháa khráp.","lit":"avion · partir · lent · [politesse]"},{"fr":"Au revoir, Chiang Mai.","tgt":"ลาก่อนเชียงใหม่","ro":"Laa kàwn Chiang-mài.","lit":"prendre congé · d'abord · Chiang Mai"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"J'ai déjà pris le train de nuit.","tgt":"ผมเคยนั่งรถไฟกลางคืนแล้วครับ","ro":"Phǒm khoei nâng rót-fai klaang-khuen láew khráp.","lit":"je (homme) · avoir déjà · s'asseoir · train · nuit · [accompli] · [politesse]"},{"fr":"Vous êtes déjà allé à Chiang Rai ?","tgt":"เคยไปเชียงรายไหมครับ","ro":"Khoei pai Chiang-raai mái khráp?","lit":"avoir déjà · aller · Chiang Rai · [question] · [politesse]"},{"fr":"Oui, j'y suis déjà allé.","tgt":"เคยครับ","ro":"Khoei khráp.","lit":"avoir déjà · [politesse]"},{"fr":"Avant, je n'avais jamais goûté le riz gluant.","tgt":"ก่อนนี้ผมไม่เคยกินข้าวเหนียวครับ","ro":"Kàwn-níi phǒm mâi khoei kin khâao-nǐao khráp.","lit":"avant · je (homme) · ne pas · avoir déjà · manger · riz gluant · [politesse]"},{"fr":"Nous avons voyagé partout en Thaïlande.","tgt":"เราเที่ยวทั่วเมืองไทยแล้วครับ","ro":"Rao thîao thûa mueang-thai láew khráp.","lit":"nous · voyager · partout · pays thaï · [accompli] · [politesse]"},{"fr":"Maintenant, je sais demander mon chemin.","tgt":"ตอนนี้ผมถามทางได้แล้วครับ","ro":"Tawn-níi phǒm thǎam thaang dâi láew khráp.","lit":"maintenant · je (homme) · demander · chemin · pouvoir · [accompli] · [politesse]"},{"fr":"J'ai déjà parlé thaï avec des marchandes.","tgt":"ผมเคยพูดไทยกับแม่ค้าแล้วครับ","ro":"Phǒm khoei phûut thai kàp mâe-kháa láew khráp.","lit":"je (homme) · avoir déjà · parler · thaï · avec · marchande · [accompli] · [politesse]"},{"fr":"Le thaï devient plus facile.","tgt":"ภาษาไทยง่ายขึ้นแล้วครับ","ro":"Phaa-sǎa thai ngâai khûen láew khráp.","lit":"langue · thaï · facile · monter · [accompli] · [politesse]"},{"fr":"La suite, ce sera bavarder entre amis.","tgt":"บทต่อไปเป็นเรื่องคุยกับเพื่อนครับ","ro":"Bòt tàw-pai pen rûeang khui kàp phûean khráp.","lit":"leçon · suivant · être · sujet · bavarder · avec · ami · [politesse]"},{"fr":"À très bientôt pour la suite.","tgt":"แล้วเจอกันใหม่ครับ","ro":"Láew joe kan mài khráp.","lit":"puis · rencontrer · ensemble · de nouveau · [politesse]"}],"tip":{"title":"« Khoei » : l'expérience, j'y suis déjà allé","example":"Vous êtes déjà allé à Chiang Rai ? — <b>เคย</b>ไปเชียงรายไหมครับ","body":"Pour raconter une expérience vécue, le thaï place « khoei », au ton moyen, juste devant le verbe. Il signifie avoir déjà fait quelque chose au moins une fois dans sa vie, comme notre « il m'est déjà arrivé de ». Décomposons « khoei pai Chiang-raai mái khráp » : avoir déjà, aller, Chiang Rai, question, politesse, soit vous êtes déjà allé à Chiang Rai. Pour répondre oui, inutile de répéter la phrase, on dit simplement « khoei khráp ». Pour dire jamais, on ajoute « mâi » devant : « mâi khoei », je n'ai jamais, par exemple « mâi khoei kin khâao-nǐao », je n'ai jamais mangé de riz gluant. On peut aussi ajouter « láew » à la fin pour insister : « phǒm khoei nâng rót-fai láew », j'ai déjà pris le train. Attention à ne pas le confondre avec « láew » seul, qui dit qu'une action vient d'être faite, alors que « khoei » parle de souvenirs. Astuce pour retenir : « khoei », c'est la petite valise des souvenirs qu'on pose devant le verbe.","exampleRo":"Khoei pai Chiang-raai mái khráp?","lit":"avoir déjà · aller · Chiang Rai · [question] · [politesse]","say":{"Khoei":"เคย","khoei":"เคย","khoei pai Chiang-raai mái khráp":"เคยไปเชียงรายไหมครับ","khoei khráp":"เคยครับ","mâi":"ไม่","mâi khoei":"ไม่เคย","mâi khoei kin khâao-nǐao":"ไม่เคยกินข้าวเหนียว","láew":"แล้ว","phǒm khoei nâng rót-fai láew":"ผมเคยนั่งรถไฟแล้ว"}}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouver des amis","phrases":[{"fr":"Salut, ça va ?","tgt":"สวัสดี สบายดีไหม","ro":"Sà-wàt-dii, sà-baai-dii mái?","lit":"bonjour · à l'aise · bien · [question]"},{"fr":"Ça va bien, et toi ?","tgt":"สบายดี แล้วคุณล่ะ","ro":"Sà-baai-dii, láew khun lâ?","lit":"à l'aise · bien · et puis · toi · [et toi ?]"},{"fr":"Ça fait longtemps !","tgt":"ไม่ได้เจอกันนานเลย","ro":"Mâi dâi joe kan naan loei.","lit":"ne pas · avoir pu · se voir · ensemble · longtemps · [vraiment]"},{"fr":"Tu n'as pas du tout changé, dis donc.","tgt":"คุณไม่เปลี่ยนเลย","ro":"Khun mâi plìan loei.","lit":"tu · ne pas · changer · [du tout]"},{"fr":"Tu vas où comme ça ?","tgt":"ไปไหนครับ","ro":"Pai nǎi khráp?","lit":"aller · où · [politesse]"},{"fr":"Je vais voir des amis.","tgt":"ไปหาเพื่อนครับ","ro":"Pai hǎa phûean khráp.","lit":"aller · voir · ami · [politesse]"},{"fr":"Tu as déjà mangé ?","tgt":"กินข้าวหรือยัง","ro":"Kin khâao rǔe yang?","lit":"manger · riz · ou · pas encore"},{"fr":"Oui, j'ai déjà mangé, merci.","tgt":"กินแล้วครับ","ro":"Kin láew khráp.","lit":"manger · [accompli] · [politesse]"},{"fr":"Viens t'asseoir avec nous.","tgt":"มานั่งด้วยกันสิ","ro":"Maa nâng dûay-kan sì.","lit":"venir · s'asseoir · ensemble · [allez]"},{"fr":"Ça me fait plaisir de te revoir.","tgt":"ดีใจที่ได้เจอนะ","ro":"Dii-jai thîi dâi joe ná.","lit":"content · de · pouvoir · se voir · [douceur]"}]},{"title":"Se présenter : phǒm chûe","phrases":[{"fr":"Et toi, comment tu t'appelles ?","tgt":"คุณชื่ออะไรครับ","ro":"Khun chûe a-rai khráp?","lit":"tu · s'appeler · quoi · [politesse]"},{"fr":"Je m'appelle Julien.","tgt":"ผมชื่อจูเลียนครับ","ro":"Phǒm chûe Juu-lian khráp.","lit":"je (homme) · s'appeler · Julien · [politesse]"},{"fr":"Moi, je m'appelle Ploy.","tgt":"ฉันชื่อพลอยค่ะ","ro":"Chǎn chûe Phlawy khâ.","lit":"je (femme) · s'appeler · Ploy · [politesse]"},{"fr":"Mon surnom, c'est Nok.","tgt":"ชื่อเล่นผมคือนกครับ","ro":"Chûe-lên phǒm khue Nók khráp.","lit":"nom-jouer · je (homme) · c'est · Nok · [politesse]"},{"fr":"Tu as un surnom ?","tgt":"คุณมีชื่อเล่นไหมครับ","ro":"Khun mii chûe-lên mái khráp?","lit":"tu · avoir · nom-jouer · [question] · [politesse]"},{"fr":"Moi, je suis français, de Lyon.","tgt":"ผมเป็นคนฝรั่งเศส มาจากลียง","ro":"Phǒm pen khon fà-ràng-sèet, maa jàak Lii-yong.","lit":"je (homme) · être · personne · France · venir · de · Lyon"},{"fr":"J'habite à Bangkok depuis un an.","tgt":"ผมอยู่กรุงเทพมาหนึ่งปีแล้ว","ro":"Phǒm yùu Krung-thêep maa nùeng pii láew.","lit":"je (homme) · habiter · Bangkok · venir · un · an · [accompli]"},{"fr":"Elle, elle s'appelle Fon.","tgt":"เขาชื่อฝน","ro":"Khǎo chûe Fǒn.","lit":"elle · s'appeler · Fon"},{"fr":"Enchanté de te connaître.","tgt":"ยินดีที่ได้รู้จักครับ","ro":"Yin-dii thîi dâi rúu-jàk khráp.","lit":"ravi · de · pouvoir · connaître · [politesse]"},{"fr":"Comment s'appelle ton ami ?","tgt":"เพื่อนคุณชื่ออะไร","ro":"Phûean khun chûe a-rai?","lit":"ami · toi · s'appeler · quoi"}],"tip":{"title":"Se présenter : « phǒm chûe »","example":"Je m'appelle Julien. — <b>ผม</b><b>ชื่อ</b>จูเลียนครับ","body":"Pour te présenter en thaï, tu dis simplement « phǒm chûe », puis ton prénom. « Phǒm » veut dire « je » quand c'est un homme qui parle, et « chûe » veut dire à la fois « nom » et « s'appeler ». Mot à mot, « phǒm chûe Julien khráp » donne : je, s'appeler, Julien, politesse. Il n'y a aucun verbe à conjuguer, c'est bien plus simple qu'en français. Une femme dit « chǎn chûe » et termine par « khâ » au lieu de « khráp », par exemple « chǎn chûe Ploy khâ ». Pour demander le nom de quelqu'un, on remplace le prénom par « a-rai », qui veut dire « quoi » : « khun chûe a-rai ? », mot à mot tu t'appelles quoi. Retiens aussi « chûe-lên », le surnom, car presque tout le monde en Thaïlande en a un, comme « Nók » ou « Fǒn ». Astuce : « chûe » se dit avec un ton qui descend, comme un « ah bon » un peu déçu.","exampleRo":"Phǒm chûe Juu-lian khráp.","lit":"je (homme) · s'appeler · Julien · [politesse]","say":{"phǒm chûe":"ผมชื่อ","Phǒm":"ผม","chûe":"ชื่อ","phǒm chûe Julien khráp":"ผมชื่อจูเลียนครับ","chǎn chûe":"ฉันชื่อ","khâ":"ค่ะ","khráp":"ครับ","chǎn chûe Ploy khâ":"ฉันชื่อพลอยค่ะ","a-rai":"อะไร","khun chûe a-rai ?":"คุณชื่ออะไร","chûe-lên":"ชื่อเล่น","Nók":"นก","Fǒn":"ฝน"}}},{"title":"Où tu habites ?","phrases":[{"fr":"Tu habites où ?","tgt":"คุณอยู่ที่ไหน","ro":"Khun yùu thîi-nǎi?","lit":"tu · habiter · où"},{"fr":"J'habite près de Silom.","tgt":"ผมอยู่แถวสีลม","ro":"Phǒm yùu thǎew Sǐi-lom.","lit":"je (homme) · habiter · vers · Silom"},{"fr":"Et c'est loin d'ici ?","tgt":"ไกลจากที่นี่ไหม","ro":"Klai jàak thîi-nîi mái?","lit":"loin · de · ici · [question]"},{"fr":"Non, c'est vraiment tout près.","tgt":"ไม่ไกล ใกล้มาก","ro":"Mâi klai, klâi mâak.","lit":"ne pas · loin · proche · très"},{"fr":"Tu viens d'où, toi ?","tgt":"คุณมาจากไหน","ro":"Khun maa jàak nǎi?","lit":"tu · venir · de · où"},{"fr":"Je viens de Chiang Mai.","tgt":"ผมมาจากเชียงใหม่","ro":"Phǒm maa jàak Chiang-mài.","lit":"je (homme) · venir · de · Chiang Mai"},{"fr":"Mon appartement est petit.","tgt":"คอนโดผมเล็ก","ro":"Khawn-doo phǒm lék.","lit":"appartement · je (homme) · petit"},{"fr":"Il y a plein de restaurants dans le coin.","tgt":"แถวนี้มีร้านอาหารเยอะ","ro":"Thǎew níi mii ráan-aa-hǎan yóe.","lit":"coin · ce · il y a · restaurant · beaucoup"},{"fr":"Tu prends le métro aérien ?","tgt":"คุณนั่งรถไฟฟ้าไหม","ro":"Khun nâng rót-fai-fáa mái?","lit":"tu · s'asseoir · train électrique · [question]"},{"fr":"Oui, tous les jours.","tgt":"นั่งทุกวันครับ","ro":"Nâng thúk wan khráp.","lit":"s'asseoir · chaque · jour · [politesse]"}]},{"title":"« Châwp » : aimer","phrases":[{"fr":"Tu aimes la cuisine thaïe ?","tgt":"คุณชอบอาหารไทยไหม","ro":"Khun châwp aa-hǎan thai mái?","lit":"tu · aimer · nourriture · thaï · [question]"},{"fr":"Oui, j'aime beaucoup.","tgt":"ชอบมากครับ","ro":"Châwp mâak khráp.","lit":"aimer · beaucoup · [politesse]"},{"fr":"J'aime le som tam.","tgt":"ผมชอบส้มตำ","ro":"Phǒm châwp sôm-tam.","lit":"je (homme) · aimer · som tam"},{"fr":"Je n'aime pas la bière.","tgt":"ผมไม่ชอบเบียร์","ro":"Phǒm mâi châwp bia.","lit":"je (homme) · ne pas · aimer · bière"},{"fr":"J'aime chanter.","tgt":"ผมชอบร้องเพลง","ro":"Phǒm châwp ráwng-phleeng.","lit":"je (homme) · aimer · chanter-chanson"},{"fr":"Qu'est-ce que tu aimes faire ?","tgt":"คุณชอบทำอะไร","ro":"Khun châwp tham a-rai?","lit":"tu · aimer · faire · quoi"},{"fr":"J'aime lire le soir.","tgt":"ผมชอบอ่านหนังสือตอนเย็น","ro":"Phǒm châwp àan nǎng-sǔe tawn-yen.","lit":"je (homme) · aimer · lire · livre · le soir"},{"fr":"Ploy adore les chats.","tgt":"พลอยชอบแมวมาก","ro":"Phlawy châwp maew mâak.","lit":"Ploy · aimer · chat · beaucoup"},{"fr":"Tu aimes les chansons thaïes ?","tgt":"คุณชอบเพลงไทยไหม","ro":"Khun châwp phleeng thai mái?","lit":"tu · aimer · chanson · thaï · [question]"},{"fr":"Pas vraiment.","tgt":"ไม่ค่อยชอบ","ro":"Mâi khâwy châwp.","lit":"ne pas · guère · aimer"}],"tip":{"title":"« Châwp » : aimer","example":"J'aime le som tam. — ผม<b>ชอบ</b>ส้มตำ","body":"« Châwp » veut dire « aimer bien ». On le place juste devant ce qu'on aime : « phǒm châwp sôm-tam », mot à mot je, aimer, som tam. On peut aussi le mettre devant un verbe, sans aucun « de » ni infinitif : « phǒm châwp ráwng-phleeng », j'aime chanter. Pour dire qu'on n'aime pas, on ajoute « mâi » devant : « phǒm mâi châwp bia », je n'aime pas la bière. Pour poser la question, on met « mái » à la fin : « khun châwp aa-hǎan thai mái ? ». Attention à la musique : « mâi », le non, descend, alors que « mái », la question, monte en ton haut. Pour renforcer, on ajoute « mâak » après : « châwp mâak », j'aime beaucoup. Et pour refuser avec douceur, les Thaïs disent volontiers « mâi khâwy châwp », pas trop. Astuce : « châwp » se dit avec un ton descendant, comme un « chop ! » plein d'enthousiasme.","exampleRo":"Phǒm châwp sôm-tam.","lit":"je (homme) · aimer · som tam","say":{"Châwp":"ชอบ","phǒm châwp sôm-tam":"ผมชอบส้มตำ","phǒm châwp ráwng-phleeng":"ผมชอบร้องเพลง","mâi":"ไม่","phǒm mâi châwp bia":"ผมไม่ชอบเบียร์","mái":"ไหม","khun châwp aa-hǎan thai mái ?":"คุณชอบอาหารไทยไหม","mâak":"มาก","châwp mâak":"ชอบมาก","mâi khâwy châwp":"ไม่ค่อยชอบ","châwp":"ชอบ"}}},{"title":"Parler de son travail","phrases":[{"fr":"Tu fais quoi comme travail ?","tgt":"คุณทำงานอะไร","ro":"Khun tham-ngaan a-rai?","lit":"tu · travailler · quoi"},{"fr":"Je suis professeur de français.","tgt":"ผมเป็นครูสอนภาษาฝรั่งเศส","ro":"Phǒm pen khruu sǎwn phaa-sǎa fà-ràng-sèet.","lit":"je (homme) · être · professeur · enseigner · langue · France"},{"fr":"Je travaille dans un hôtel.","tgt":"ผมทำงานที่โรงแรม","ro":"Phǒm tham-ngaan thîi roong-raem.","lit":"je (homme) · travailler · à · hôtel"},{"fr":"Ploy est infirmière.","tgt":"พลอยเป็นพยาบาล","ro":"Phlawy pen phá-yaa-baan.","lit":"Ploy · être · infirmière"},{"fr":"Tu travailles où ?","tgt":"คุณทำงานที่ไหน","ro":"Khun tham-ngaan thîi-nǎi?","lit":"tu · travailler · où"},{"fr":"Mon bureau est à Sukhumvit.","tgt":"ออฟฟิศผมอยู่ที่สุขุมวิท","ro":"Áwp-fít phǒm yùu thîi Sù-khǔm-wít.","lit":"bureau · je (homme) · se trouver · à · Sukhumvit"},{"fr":"Je commence à neuf heures.","tgt":"ผมเริ่มงานเก้าโมง","ro":"Phǒm rôem ngaan kâo moong.","lit":"je (homme) · commencer · travail · neuf · heure"},{"fr":"Ton travail est fatigant ?","tgt":"งานเหนื่อยไหม","ro":"Ngaan nùeay mái?","lit":"travail · fatigué · [question]"},{"fr":"Un peu, mais c'est intéressant.","tgt":"นิดหน่อย แต่น่าสนใจ","ro":"Nít-nàwy, tàe nâa-sǒn-jai.","lit":"un peu · mais · intéressant"},{"fr":"Je finis tard le soir.","tgt":"ผมเลิกงานดึก","ro":"Phǒm lôek ngaan dùek.","lit":"je (homme) · finir · travail · tard"}]},{"title":"La famille : phâw, mâe, phîi, náwng","phrases":[{"fr":"Tu as des frères ou des sœurs ?","tgt":"คุณมีพี่น้องไหม","ro":"Khun mii phîi-náwng mái?","lit":"tu · avoir · aîné-cadet · [question]"},{"fr":"J'ai un grand frère.","tgt":"ผมมีพี่ชายหนึ่งคน","ro":"Phǒm mii phîi-chaai nùeng khon.","lit":"je (homme) · avoir · aîné-homme · un · [classificateur]"},{"fr":"Et aussi une petite sœur.","tgt":"แล้วก็มีน้องสาวหนึ่งคน","ro":"Láew kâw mii náwng-sǎao nùeng khon.","lit":"et puis · aussi · avoir · cadet-femme · un · [classificateur]"},{"fr":"Mon père est médecin.","tgt":"พ่อผมเป็นหมอ","ro":"Phâw phǒm pen mǎw.","lit":"père · je (homme) · être · médecin"},{"fr":"Ma mère est cuisinière.","tgt":"แม่ผมเป็นแม่ครัว","ro":"Mâe phǒm pen mâe-khrua.","lit":"mère · je (homme) · être · cuisinière"},{"fr":"Mes parents habitent en France.","tgt":"พ่อแม่ผมอยู่ที่ฝรั่งเศส","ro":"Phâw-mâe phǒm yùu thîi fà-ràng-sèet.","lit":"père-mère · je (homme) · habiter · à · France"},{"fr":"Ta grande sœur habite où ?","tgt":"พี่สาวคุณอยู่ที่ไหน","ro":"Phîi-sǎao khun yùu thîi-nǎi?","lit":"aîné-femme · toi · habiter · où"},{"fr":"Mon petit frère est étudiant.","tgt":"น้องชายผมเป็นนักศึกษา","ro":"Náwng-chaai phǒm pen nák-sùek-sǎa.","lit":"cadet-homme · je (homme) · être · étudiant"},{"fr":"Tu as des enfants ?","tgt":"คุณมีลูกไหม","ro":"Khun mii lûuk mái?","lit":"tu · avoir · enfant · [question]"},{"fr":"Oui, j'ai deux filles.","tgt":"มีลูกสาวสองคนครับ","ro":"Mii lûuk-sǎao sǎwng khon khráp.","lit":"avoir · enfant-femme · deux · [classificateur] · [politesse]"}],"tip":{"title":"La famille : « phâw, mâe, phîi, náwng »","example":"J'ai un grand frère. — ผมมี<b>พี่ชาย</b>หนึ่งคน","body":"Le père se dit « phâw » et la mère « mâe », les deux avec un ton qui descend. Ensemble, « phâw-mâe » veut dire les parents. Pour les frères et sœurs, le thaï ne regarde pas d'abord si c'est un garçon ou une fille, mais qui est le plus âgé : « phîi », c'est l'aîné, et « náwng », c'est le cadet. Si l'on veut préciser, on ajoute « chaai » pour un homme ou « sǎao » pour une femme. Ainsi « phîi-chaai » est le grand frère, mot à mot aîné homme, et « náwng-sǎao » la petite sœur, mot à mot cadet femme. Pour dire « mon père », on met simplement « phǒm » après : « phâw phǒm », le père de moi. Les enfants se disent « lûuk », et l'on a donc « lûuk-chaai » pour un fils et « lûuk-sǎao » pour une fille. Astuce : « phîi-náwng » tout court, aîné et cadet, veut dire frères et sœurs.","exampleRo":"Phǒm mii phîi-chaai nùeng khon.","lit":"je (homme) · avoir · aîné-homme · un · [classificateur]","say":{"phâw":"พ่อ","mâe":"แม่","phâw-mâe":"พ่อแม่","phîi":"พี่","náwng":"น้อง","chaai":"ชาย","sǎao":"สาว","phîi-chaai":"พี่ชาย","náwng-sǎao":"น้องสาว","phǒm":"ผม","phâw phǒm":"พ่อผม","lûuk":"ลูก","lûuk-chaai":"ลูกชาย","lûuk-sǎao":"ลูกสาว","phîi-náwng":"พี่น้อง","phâw, mâe, phîi, náwng":"พ่อ แม่ พี่ น้อง"}}},{"title":"Les collègues","phrases":[{"fr":"Voici mon collègue, il s'appelle Ton.","tgt":"นี่เพื่อนร่วมงานผม ชื่อต้น","ro":"Nîi phûean-rûam-ngaan phǒm, chûe Tôn.","lit":"voici · collègue · je (homme) · s'appeler · Ton"},{"fr":"On travaille ensemble.","tgt":"เราทำงานด้วยกัน","ro":"Rao tham-ngaan dûay-kan.","lit":"nous · travailler · ensemble"},{"fr":"Tes collègues sont sympas ?","tgt":"เพื่อนร่วมงานคุณใจดีไหม","ro":"Phûean-rûam-ngaan khun jai-dii mái?","lit":"collègue · toi · gentil · [question]"},{"fr":"Oui, ils sont très gentils.","tgt":"ใจดีมากครับ","ro":"Jai-dii mâak khráp.","lit":"gentil · très · [politesse]"},{"fr":"Mon chef est un peu sévère.","tgt":"หัวหน้าผมดุนิดหน่อย","ro":"Hǔa-nâa phǒm dù nít-nàwy.","lit":"chef · je (homme) · sévère · un peu"},{"fr":"À midi, on déjeune ensemble.","tgt":"ตอนเที่ยงเรากินข้าวด้วยกัน","ro":"Tawn-thîang rao kin khâao dûay-kan.","lit":"à midi · nous · manger · riz · ensemble"},{"fr":"Elle est nouvelle au bureau.","tgt":"เขาเป็นคนใหม่ที่ออฟฟิศ","ro":"Khǎo pen khon mài thîi áwp-fít.","lit":"elle · être · personne · nouveau · à · bureau"},{"fr":"Tu connais Ton ?","tgt":"คุณรู้จักต้นไหม","ro":"Khun rúu-jàk Tôn mái?","lit":"tu · connaître · Ton · [question]"},{"fr":"Oui, c'est mon ami.","tgt":"รู้จักครับ เขาเป็นเพื่อนผม","ro":"Rúu-jàk khráp, khǎo pen phûean phǒm.","lit":"connaître · [politesse] · il · être · ami · je (homme)"},{"fr":"Il est très drôle.","tgt":"เขาตลกมาก","ro":"Khǎo tà-lòk mâak.","lit":"il · drôle · très"}]},{"title":"« Kam-lang » : être en train de","phrases":[{"fr":"Tu fais quoi, là ?","tgt":"กำลังทำอะไรอยู่","ro":"Kam-lang tham a-rai yùu?","lit":"[en train de] · faire · quoi · [en cours]"},{"fr":"Je suis en train de manger.","tgt":"กำลังกินข้าวอยู่","ro":"Kam-lang kin khâao yùu.","lit":"[en train de] · manger · riz · [en cours]"},{"fr":"Je suis en train de travailler.","tgt":"ผมกำลังทำงานครับ","ro":"Phǒm kam-lang tham-ngaan khráp.","lit":"je (homme) · [en train de] · travailler · [politesse]"},{"fr":"Ploy est en train de chanter.","tgt":"พลอยกำลังร้องเพลง","ro":"Phlawy kam-lang ráwng-phleeng.","lit":"Ploy · [en train de] · chanter-chanson"},{"fr":"Je suis en chemin.","tgt":"ผมกำลังไปครับ","ro":"Phǒm kam-lang pai khráp.","lit":"je (homme) · [en train de] · aller · [politesse]"},{"fr":"Il est en train de dormir.","tgt":"เขากำลังนอนหลับ","ro":"Khǎo kam-lang nawn-làp.","lit":"il · [en train de] · dormir"},{"fr":"On est en train de regarder la boxe.","tgt":"เรากำลังดูมวยอยู่","ro":"Rao kam-lang duu muay yùu.","lit":"nous · [en train de] · regarder · boxe · [en cours]"},{"fr":"Tu es occupé ?","tgt":"ยุ่งไหม","ro":"Yûng mái?","lit":"occupé · [question]"},{"fr":"Oui, je suis en réunion.","tgt":"ครับ กำลังประชุมอยู่","ro":"Khráp, kam-lang prà-chum yùu.","lit":"oui · [en train de] · réunion · [en cours]"},{"fr":"Je te rappelle tout à l'heure.","tgt":"เดี๋ยวโทรกลับนะ","ro":"Dǐao thoo klàp ná.","lit":"tout à l'heure · téléphoner · retour · [douceur]"}],"tip":{"title":"« Kam-lang » : être en train de","example":"Je suis en train de manger. — <b>กำลัง</b>กินข้าว<b>อยู่</b>","body":"Le verbe thaï ne change jamais de forme, alors pour dire qu'une action se passe en ce moment, on ajoute un petit mot devant : « kam-lang ». Il se place juste avant le verbe, exactement comme notre « en train de ». Ainsi « phǒm kam-lang tham-ngaan » veut dire je suis en train de travailler, mot à mot je, en train de, travailler. Très souvent, on ajoute aussi « yùu » à la fin de la phrase, qui renforce l'idée que ça dure : « kam-lang kin khâao yùu », je suis en train de manger. Entre amis, on peut même enlever « phǒm » quand on sait qui parle. La question la plus utile au téléphone est « kam-lang tham a-rai yùu ? », tu fais quoi en ce moment. Et « kam-lang pai » veut dire j'arrive, je suis en route. Astuce : « kam-lang » a deux syllabes au ton moyen, bien à plat, comme un mot calme.","exampleRo":"Kam-lang kin khâao yùu.","lit":"[en train de] · manger · riz · [en cours]","say":{"Kam-lang":"กำลัง","kam-lang":"กำลัง","phǒm kam-lang tham-ngaan":"ผมกำลังทำงาน","yùu":"อยู่","kam-lang kin khâao yùu":"กำลังกินข้าวอยู่","phǒm":"ผม","kam-lang tham a-rai yùu ?":"กำลังทำอะไรอยู่","kam-lang pai":"กำลังไป"}}},{"title":"Le week-end","phrases":[{"fr":"Tu fais quoi ce week-end ?","tgt":"เสาร์อาทิตย์นี้ทำอะไร","ro":"Sǎo aa-thít níi tham a-rai?","lit":"samedi · dimanche · ce · faire · quoi"},{"fr":"Je vais au marché de Chatuchak.","tgt":"ผมจะไปตลาดจตุจักร","ro":"Phǒm jà pai tà-làat Jà-tù-jàk.","lit":"je (homme) · [futur] · aller · marché · Chatuchak"},{"fr":"On y va ensemble, tous les deux ?","tgt":"ไปด้วยกันไหม","ro":"Pai dûay-kan mái?","lit":"aller · ensemble · [question]"},{"fr":"Volontiers !","tgt":"ได้เลย","ro":"Dâi loei.","lit":"pouvoir · [tout à fait]"},{"fr":"Moi, le dimanche, je me repose.","tgt":"วันอาทิตย์ผมพักผ่อน","ro":"Wan aa-thít phǒm phák-phàwn.","lit":"jour · dimanche · je (homme) · se reposer"},{"fr":"On va au parc Lumphini ?","tgt":"ไปสวนลุมพินีไหม","ro":"Pai sǔan Lum-phí-nii mái?","lit":"aller · parc · Lumphini · [question]"},{"fr":"Il fait vraiment chaud aujourd'hui.","tgt":"วันนี้ร้อนมาก","ro":"Wan-níi ráwn mâak.","lit":"aujourd'hui · chaud · très"},{"fr":"Alors on va au cinéma.","tgt":"งั้นไปดูหนังกัน","ro":"Ngán pai duu nǎng kan.","lit":"alors · aller · regarder · film · ensemble"},{"fr":"Super idée !","tgt":"ดีเลย","ro":"Dii loei.","lit":"bien · [tout à fait]"},{"fr":"On se retrouve vers quelle heure ?","tgt":"เจอกันกี่โมง","ro":"Joe kan kìi moong?","lit":"se voir · ensemble · combien · heure"}]},{"title":"Comparer avec « kwàa »","phrases":[{"fr":"Bangkok est plus grand que Chiang Mai.","tgt":"กรุงเทพใหญ่กว่าเชียงใหม่","ro":"Krung-thêep yài kwàa Chiang-mài.","lit":"Bangkok · grand · plus que · Chiang Mai"},{"fr":"Chiang Mai est plus calme.","tgt":"เชียงใหม่เงียบกว่า","ro":"Chiang-mài ngîap kwàa.","lit":"Chiang Mai · calme · plus"},{"fr":"Ce restaurant-ci est meilleur.","tgt":"ร้านนี้อร่อยกว่า","ro":"Ráan níi à-ràwy kwàa.","lit":"restaurant · ce · délicieux · plus"},{"fr":"Mon grand frère est plus grand que moi.","tgt":"พี่ชายผมสูงกว่าผม","ro":"Phîi-chaai phǒm sǔung kwàa phǒm.","lit":"aîné-homme · je (homme) · haut · plus que · moi"},{"fr":"Le métro est plus rapide que le taxi.","tgt":"รถไฟฟ้าเร็วกว่าแท็กซี่","ro":"Rót-fai-fáa reo kwàa tháek-sîi.","lit":"train électrique · rapide · plus que · taxi"},{"fr":"Mais le taxi est plus cher.","tgt":"แต่แท็กซี่แพงกว่า","ro":"Tàe tháek-sîi phaeng kwàa.","lit":"mais · taxi · cher · plus"},{"fr":"Ce plat est plus épicé.","tgt":"จานนี้เผ็ดกว่า","ro":"Jaan níi phèt kwàa.","lit":"plat · ce · épicé · plus"},{"fr":"Lequel tu préfères ?","tgt":"คุณชอบอันไหนมากกว่า","ro":"Khun châwp an nǎi mâak kwàa?","lit":"tu · aimer · [classificateur] · lequel · beaucoup · plus"},{"fr":"Je préfère le riz gluant.","tgt":"ผมชอบข้าวเหนียวมากกว่า","ro":"Phǒm châwp khâao-nǐao mâak kwàa.","lit":"je (homme) · aimer · riz gluant · beaucoup · plus"},{"fr":"Tu parles thaï mieux que moi.","tgt":"คุณพูดไทยเก่งกว่าผม","ro":"Khun phûut thai kèng kwàa phǒm.","lit":"tu · parler · thaï · doué · plus que · moi"}],"tip":{"title":"Comparer avec « kwàa »","example":"Bangkok est plus grand que Chiang Mai. — กรุงเทพใหญ่<b>กว่า</b>เชียงใหม่","body":"Pour comparer, le thaï utilise un seul petit mot : « kwàa », qui veut dire « plus que ». On le place juste après l'adjectif, alors qu'en français « plus » vient avant. « Krung-thêep yài kwàa Chiang-mài » donne mot à mot : Bangkok, grand, plus que, Chiang Mai. Il n'y a pas besoin de verbe être, l'adjectif suffit. Si l'on ne dit pas avec quoi on compare, on s'arrête simplement après « kwàa » : « jaan níi phèt kwàa », ce plat est plus épicé. Pour dire qu'on préfère, on combine « châwp », aimer, avec « mâak kwàa », plus : « phǒm châwp khâao-nǐao mâak kwàa », je préfère le riz gluant. Et pour demander « lequel ? », on dit « an nǎi mâak kwàa ? ». Astuce : « kwàa » a un ton bas, comme un petit « coin » de canard grave.","exampleRo":"Krung-thêep yài kwàa Chiang-mài.","lit":"Bangkok · grand · plus que · Chiang Mai","say":{"kwàa":"กว่า","Krung-thêep yài kwàa Chiang-mài":"กรุงเทพใหญ่กว่าเชียงใหม่","jaan níi phèt kwàa":"จานนี้เผ็ดกว่า","châwp":"ชอบ","mâak kwàa":"มากกว่า","phǒm châwp khâao-nǐao mâak kwàa":"ผมชอบข้าวเหนียวมากกว่า","an nǎi mâak kwàa ?":"อันไหนมากกว่า"}}},{"title":"Une soirée karaoké","phrases":[{"fr":"On va au karaoké ce soir ?","tgt":"คืนนี้ไปคาราโอเกะกันไหม","ro":"Khuen-níi pai khaa-raa-oo-kè kan mái?","lit":"cette nuit · aller · karaoké · ensemble · [question]"},{"fr":"Je ne chante pas bien.","tgt":"ผมร้องเพลงไม่เก่ง","ro":"Phǒm ráwng-phleeng mâi kèng.","lit":"je (homme) · chanter-chanson · ne pas · doué"},{"fr":"Pas grave, on s'amuse !","tgt":"ไม่เป็นไร สนุกดี","ro":"Mâi pen rai, sà-nùk dii.","lit":"ne pas · être · rien · amusant · bien"},{"fr":"Tu vas chanter quelle chanson ?","tgt":"คุณจะร้องเพลงอะไร","ro":"Khun jà ráwng phleeng a-rai?","lit":"tu · [futur] · chanter · chanson · quoi"},{"fr":"Une chanson thaïe, bien sûr.","tgt":"เพลงไทยสิ","ro":"Phleeng thai sì.","lit":"chanson · thaï · [bien sûr]"},{"fr":"Vas-y, chante !","tgt":"ร้องเลย","ro":"Ráwng loei.","lit":"chanter · [vas-y]"},{"fr":"Tu chantes vraiment bien !","tgt":"ร้องเพราะมาก","ro":"Ráwng phráw mâak.","lit":"chanter · mélodieux · très"},{"fr":"Encore une chanson ?","tgt":"อีกเพลงไหม","ro":"Ìik phleeng mái?","lit":"encore · chanson · [question]"},{"fr":"On chante ensemble ?","tgt":"ร้องด้วยกันไหม","ro":"Ráwng dûay-kan mái?","lit":"chanter · ensemble · [question]"},{"fr":"On s'est bien amusés ce soir.","tgt":"คืนนี้สนุกมาก","ro":"Khuen-níi sà-nùk mâak.","lit":"cette nuit · amusant · très"}]},{"title":"« Phráw » : parce que","phrases":[{"fr":"Pourquoi tu apprends le thaï ?","tgt":"ทำไมคุณเรียนภาษาไทย","ro":"Tham-mai khun rian phaa-sǎa thai?","lit":"pourquoi · tu · apprendre · langue · thaï"},{"fr":"Parce que j'habite ici.","tgt":"เพราะผมอยู่ที่นี่","ro":"Phráw phǒm yùu thîi-nîi.","lit":"parce que · je (homme) · habiter · ici"},{"fr":"Et parce que j'aime la Thaïlande.","tgt":"แล้วก็เพราะผมชอบเมืองไทย","ro":"Láew kâw phráw phǒm châwp mueang-thai.","lit":"et puis · aussi · parce que · je (homme) · aimer · pays thaï"},{"fr":"Je suis fatigué parce que je travaille beaucoup.","tgt":"ผมเหนื่อยเพราะทำงานเยอะ","ro":"Phǒm nùeay phráw tham-ngaan yóe.","lit":"je (homme) · fatigué · parce que · travailler · beaucoup"},{"fr":"Pourquoi tu es en retard ?","tgt":"ทำไมมาสาย","ro":"Tham-mai maa sǎai?","lit":"pourquoi · venir · en retard"},{"fr":"Parce qu'il y avait des bouchons.","tgt":"เพราะรถติด","ro":"Phráw rót tìt.","lit":"parce que · voiture · coincé"},{"fr":"Je ne bois pas parce que je dois conduire.","tgt":"ผมไม่ดื่มเพราะต้องขับรถ","ro":"Phǒm mâi dùem phráw tâwng khàp rót.","lit":"je (homme) · ne pas · boire · parce que · devoir · conduire · voiture"},{"fr":"Pourquoi tu ris ?","tgt":"หัวเราะทำไม","ro":"Hǔa-ráw tham-mai?","lit":"rire · pourquoi"},{"fr":"Parce que c'est drôle.","tgt":"เพราะมันตลก","ro":"Phráw man tà-lòk.","lit":"parce que · ça · drôle"},{"fr":"Je reste à la maison parce qu'il pleut.","tgt":"ผมอยู่บ้านเพราะฝนตก","ro":"Phǒm yùu bâan phráw fǒn tòk.","lit":"je (homme) · rester · maison · parce que · pluie · tomber"}],"tip":{"title":"« Phráw » : parce que","example":"Parce que j'habite ici. — <b>เพราะ</b>ผมอยู่ที่นี่","body":"Pour donner une raison, on utilise « phráw », qui veut dire « parce que ». Il se place exactement comme en français, au début de la partie qui explique. « Phǒm nùeay phráw tham-ngaan yóe » donne mot à mot : je, fatigué, parce que, travailler, beaucoup. Pour répondre vite, on peut commencer directement par « phráw » : « phráw rót tìt », parce qu'il y a des bouchons, une phrase que tu entendras tous les jours à Bangkok. La question « pourquoi » se dit « tham-mai ». On peut la mettre au début, « tham-mai maa sǎai ? », pourquoi tu es en retard, ou à la fin, « hǔa-ráw tham-mai ? », pourquoi tu ris. Petite curiosité : le même mot « phráw » veut aussi dire mélodieux, quand on dit qu'une voix chante bien. Astuce : « phráw » a un ton haut et court, comme un « pro ! » lancé avec assurance.","exampleRo":"Phráw phǒm yùu thîi-nîi.","lit":"parce que · je (homme) · habiter · ici","say":{"Phráw":"เพราะ","phráw":"เพราะ","Phǒm nùeay phráw tham-ngaan yóe":"ผมเหนื่อยเพราะทำงานเยอะ","phráw rót tìt":"เพราะรถติด","tham-mai":"ทำไม","tham-mai maa sǎai ?":"ทำไมมาสาย","hǔa-ráw tham-mai ?":"หัวเราะทำไม"}}},{"title":"La boxe thaïe","phrases":[{"fr":"Tu t'entraînes à la boxe thaïe ?","tgt":"คุณฝึกมวยไทยไหม","ro":"Khun fùek muay-thai mái?","lit":"tu · s'entraîner · boxe thaïe · [question]"},{"fr":"Oui, deux fois par semaine.","tgt":"ครับ อาทิตย์ละสองครั้ง","ro":"Khráp, aa-thít lá sǎwng khráng.","lit":"oui · semaine · par · deux · fois"},{"fr":"La boxe thaïe, c'est bon pour la santé.","tgt":"มวยไทยดีต่อสุขภาพ","ro":"Muay-thai dii tàw sùk-khà-phâap.","lit":"boxe thaïe · bon · pour · santé"},{"fr":"Le cours a lieu le soir.","tgt":"เรียนตอนเย็น","ro":"Rian tawn-yen.","lit":"étudier · le soir"},{"fr":"C'est fatigant mais amusant.","tgt":"เหนื่อยแต่สนุก","ro":"Nùeay tàe sà-nùk.","lit":"fatigué · mais · amusant"},{"fr":"Mon entraîneur est très fort.","tgt":"ครูมวยของผมเก่งมาก","ro":"Khruu muay khǎwng phǒm kèng mâak.","lit":"professeur · boxe · [de] · je (homme) · doué · très"},{"fr":"Tu veux essayer ?","tgt":"อยากลองไหม","ro":"Yàak lawng mái?","lit":"vouloir · essayer · [question]"},{"fr":"J'ai un peu peur.","tgt":"กลัวนิดหน่อย","ro":"Klua nít-nàwy.","lit":"avoir peur · un peu"},{"fr":"On va voir un combat au stade Lumphini ?","tgt":"ไปดูมวยที่เวทีลุมพินีไหม","ro":"Pai duu muay thîi wee-thii Lum-phí-nii mái?","lit":"aller · regarder · boxe · à · ring · Lumphini · [question]"},{"fr":"Les boxeurs sont vraiment forts.","tgt":"นักมวยเก่งมาก","ro":"Nák-muay kèng mâak.","lit":"boxeur · doué · très"}]},{"title":"« Phîi » et « náwng » : appeler les gens selon leur âge","phrases":[{"fr":"Tu as quel âge ?","tgt":"คุณอายุเท่าไร","ro":"Khun aa-yú thâo-rai?","lit":"tu · âge · combien"},{"fr":"J'ai trente ans.","tgt":"ผมอายุสามสิบปี","ro":"Phǒm aa-yú sǎam-sìp pii.","lit":"je (homme) · âge · trente · an"},{"fr":"Alors tu es mon aîné.","tgt":"งั้นคุณเป็นพี่","ro":"Ngán khun pen phîi.","lit":"alors · tu · être · aîné"},{"fr":"Je peux t'appeler Phi Ton ?","tgt":"เรียกพี่ต้นได้ไหม","ro":"Rîak phîi Tôn dâi mái?","lit":"appeler · aîné · Ton · pouvoir · [question]"},{"fr":"Tu veux un café, Phi ?","tgt":"พี่ดื่มกาแฟไหม","ro":"Phîi dùem kaa-fae mái?","lit":"aîné · boire · café · [question]"},{"fr":"Nong, l'addition s'il te plaît !","tgt":"น้อง เช็กบิลด้วย","ro":"Náwng, chék-bin dûay.","lit":"cadet · addition · [s'il te plaît]"},{"fr":"Elle est plus jeune que moi.","tgt":"เขาอายุน้อยกว่าผม","ro":"Khǎo aa-yú náwy kwàa phǒm.","lit":"elle · âge · peu · plus que · moi"},{"fr":"Donc je l'appelle Nong.","tgt":"ผมเลยเรียกเขาว่าน้อง","ro":"Phǒm loei rîak khǎo wâa náwng.","lit":"je (homme) · donc · appeler · elle · que · cadet"},{"fr":"Phi Noi est très gentille.","tgt":"พี่น้อยใจดีมาก","ro":"Phîi Náwy jai-dii mâak.","lit":"aîné · Noi · gentil · très"},{"fr":"Merci beaucoup, Phi !","tgt":"ขอบคุณมากครับพี่","ro":"Khàwp-khun mâak khráp phîi.","lit":"merci · beaucoup · [politesse] · aîné"}],"tip":{"title":"« Phîi » et « náwng » : appeler les gens selon leur âge","example":"Nong, l'addition s'il te plaît ! — <b>น้อง</b> เช็กบิลด้วย","body":"En thaï, on appelle très souvent les gens selon leur âge par rapport à soi, même quand ils ne sont pas de la famille. Une personne un peu plus âgée devient « phîi », l'aîné, et une personne plus jeune devient « náwng », le cadet. On met ce mot devant le prénom : « phîi Tôn », « náwng Ploy ». On l'utilise aussi à la place de « tu » : « phîi dùem kaa-fae mái ? », mot à mot aîné, boire, café, question, c'est-à-dire tu veux un café. Au restaurant, on appelle le jeune serveur ou la jeune serveuse « náwng » : « náwng, chék-bin dûay », l'addition s'il te plaît. Voilà pourquoi les Thaïs demandent vite ton âge : « khun aa-yú thâo-rai ? ». Ce n'est pas indiscret, c'est pour savoir comment t'appeler. Astuce : dans le doute, dis « phîi », c'est toujours flatteur et respectueux.","exampleRo":"Náwng, chék-bin dûay.","lit":"cadet · addition · [s'il te plaît]","say":{"Phîi":"พี่","náwng":"น้อง","phîi":"พี่","phîi Tôn":"พี่ต้น","náwng Ploy":"น้องพลอย","phîi dùem kaa-fae mái ?":"พี่ดื่มกาแฟไหม","náwng, chék-bin dûay":"น้อง เช็กบิลด้วย","khun aa-yú thâo-rai ?":"คุณอายุเท่าไร"}}},{"title":"Une invitation","phrases":[{"fr":"Tu es libre samedi ?","tgt":"วันเสาร์ว่างไหม","ro":"Wan sǎo wâang mái?","lit":"jour · samedi · libre · [question]"},{"fr":"Oui, je suis libre.","tgt":"ว่างครับ","ro":"Wâang khráp.","lit":"libre · [politesse]"},{"fr":"Viens dîner à la maison.","tgt":"มากินข้าวที่บ้านผมสิ","ro":"Maa kin khâao thîi bâan phǒm sì.","lit":"venir · manger · riz · à · maison · je (homme) · [allez]"},{"fr":"Avec plaisir !","tgt":"ด้วยความยินดีครับ","ro":"Dûay khwaam-yin-dii khráp.","lit":"avec · plaisir · [politesse]"},{"fr":"J'invite aussi mes collègues.","tgt":"ผมชวนเพื่อนร่วมงานด้วย","ro":"Phǒm chuan phûean-rûam-ngaan dûay.","lit":"je (homme) · inviter · collègue · aussi"},{"fr":"Je dois apporter quelque chose ?","tgt":"ต้องเอาอะไรไปไหม","ro":"Tâwng ao a-rai pai mái?","lit":"devoir · prendre · quelque chose · aller · [question]"},{"fr":"Non, viens les mains vides.","tgt":"ไม่ต้อง มาตัวเปล่าได้เลย","ro":"Mâi tâwng, maa tua-plào dâi loei.","lit":"pas besoin · venir · corps vide · pouvoir · [tout à fait]"},{"fr":"Je viens à quelle heure ?","tgt":"มากี่โมงดี","ro":"Maa kìi moong dii?","lit":"venir · combien · heure · bien"},{"fr":"Vers six heures du soir.","tgt":"ประมาณหกโมงเย็น","ro":"Prà-maan hòk moong yen.","lit":"environ · six · heure · soir"},{"fr":"Merci de m'inviter.","tgt":"ขอบคุณที่ชวนนะ","ro":"Khàwp-khun thîi chuan ná.","lit":"merci · de · inviter · [douceur]"}]},{"title":"Les classificateurs : khon, tua, an","phrases":[{"fr":"J'ai acheté un petit cadeau.","tgt":"ผมซื้อของขวัญมาหนึ่งอัน","ro":"Phǒm súe khǎwng-khwǎn maa nùeng an.","lit":"je (homme) · acheter · cadeau · venir · un · [classificateur]"},{"fr":"Il y a combien de personnes ?","tgt":"มีกี่คน","ro":"Mii kìi khon?","lit":"il y a · combien · [classificateur]"},{"fr":"Il y a cinq personnes.","tgt":"มีห้าคน","ro":"Mii hâa khon.","lit":"il y a · cinq · [classificateur]"},{"fr":"J'ai acheté deux t-shirts.","tgt":"ผมซื้อเสื้อสองตัว","ro":"Phǒm súe sûea sǎwng tua.","lit":"je (homme) · acheter · vêtement · deux · [classificateur]"},{"fr":"Ce t-shirt est pour ton fils.","tgt":"เสื้อตัวนี้ให้ลูกชายคุณ","ro":"Sûea tua níi hâi lûuk-chaai khun.","lit":"vêtement · [classificateur] · ce · donner · enfant-homme · toi"},{"fr":"Elle a trois chats.","tgt":"เขามีแมวสามตัว","ro":"Khǎo mii maew sǎam tua.","lit":"elle · avoir · chat · trois · [classificateur]"},{"fr":"Je prends ce gâteau-là.","tgt":"ขอขนมอันนั้น","ro":"Khǎw khà-nǒm an nán.","lit":"demander · gâteau · [classificateur] · là"},{"fr":"Celui-ci, il coûte combien ?","tgt":"อันนี้เท่าไร","ro":"An níi thâo-rai?","lit":"[classificateur] · ce · combien"},{"fr":"Cent bahts pièce.","tgt":"อันละร้อยบาท","ro":"An lá ráwy bàat.","lit":"[classificateur] · par · cent · baht"},{"fr":"J'ai deux amis thaïs.","tgt":"ผมมีเพื่อนคนไทยสองคน","ro":"Phǒm mii phûean khon thai sǎwng khon.","lit":"je (homme) · avoir · ami · personne · thaï · deux · [classificateur]"}],"tip":{"title":"Les classificateurs : « khon, tua, an »","example":"Elle a trois chats. — เขามีแมวสาม<b>ตัว</b>","body":"En thaï, on ne dit pas « trois chats » directement : on dit le nom, puis le nombre, puis un petit mot qui indique la sorte de chose qu'on compte. C'est un peu comme en français quand on dit « trois tranches de pain » ou « deux paires de chaussures ». « Khǎo mii maew sǎam tua » donne mot à mot : elle, avoir, chat, trois, classificateur. Les trois classificateurs à connaître d'abord sont « khon » pour les personnes, « tua » pour les animaux et les vêtements, et « an » pour les petits objets, quand on ne sait pas lequel choisir. On les retrouve aussi avec « níi », ce, et « nán », ce-là : « sûea tua níi », ce t-shirt, ou « an nán », celui-là. Pour demander combien, on met « kìi » devant : « mii kìi khon ? », il y a combien de personnes. Astuce : au marché, « an níi thâo-rai ? » te servira tous les jours.","exampleRo":"Khǎo mii maew sǎam tua.","lit":"elle · avoir · chat · trois · [classificateur]","say":{"Khǎo mii maew sǎam tua":"เขามีแมวสามตัว","khon":"คน","tua":"ตัว","an":"อัน","níi":"นี้","nán":"นั้น","sûea tua níi":"เสื้อตัวนี้","an nán":"อันนั้น","kìi":"กี่","mii kìi khon ?":"มีกี่คน","an níi thâo-rai ?":"อันนี้เท่าไร","khon, tua, an":"คน ตัว อัน"}}},{"title":"À table entre amis","phrases":[{"fr":"Tu peux manger épicé ?","tgt":"กินเผ็ดได้ไหม","ro":"Kin phèt dâi mái?","lit":"manger · épicé · pouvoir · [question]"},{"fr":"Un peu seulement.","tgt":"ได้นิดหน่อย","ro":"Dâi nít-nàwy.","lit":"pouvoir · un peu"},{"fr":"Pas épicé pour moi, d'accord ?","tgt":"ไม่เผ็ดนะ","ro":"Mâi phèt ná.","lit":"ne pas · épicé · [douceur]"},{"fr":"Goûte donc ce curry vert.","tgt":"ลองชิมแกงเขียวหวานนี่สิ","ro":"Lawng chim kaeng-khǐao-wǎan nîi sì.","lit":"essayer · goûter · curry vert · ça · [allez]"},{"fr":"C'est délicieux !","tgt":"อร่อยมาก","ro":"À-ràwy mâak.","lit":"délicieux · très"},{"fr":"Qu'est-ce que tu ne manges pas ?","tgt":"คุณไม่กินอะไร","ro":"Khun mâi kin a-rai?","lit":"tu · ne pas · manger · quoi"},{"fr":"Je ne mange pas de crevettes.","tgt":"ผมไม่กินกุ้ง","ro":"Phǒm mâi kin kûng.","lit":"je (homme) · ne pas · manger · crevette"},{"fr":"On partage les plats, d'accord ?","tgt":"แบ่งกันกินนะ","ro":"Bàeng kan kin ná.","lit":"partager · ensemble · manger · [douceur]"},{"fr":"Tu reprends du riz ?","tgt":"เอาข้าวเพิ่มไหม","ro":"Ao khâao phôem mái?","lit":"vouloir · riz · ajouter · [question]"},{"fr":"Non merci, je n'ai plus faim.","tgt":"ไม่เป็นไรครับ อิ่มแล้ว","ro":"Mâi pen rai khráp, ìm láew.","lit":"ne pas · être · rien · [politesse] · rassasié · [accompli]"}]},{"title":"« Mâak » et « koen pai » : très et trop","phrases":[{"fr":"Cette chemise est très belle.","tgt":"เสื้อตัวนี้สวยมาก","ro":"Sûea tua níi sǔay mâak.","lit":"vêtement · [classificateur] · ce · beau · très"},{"fr":"C'est trop cher pour moi.","tgt":"แพงเกินไปสำหรับผม","ro":"Phaeng koen pai sǎm-ràp phǒm.","lit":"cher · dépasser · aller · pour · moi"},{"fr":"Ta maison est très jolie.","tgt":"บ้านคุณสวยมาก","ro":"Bâan khun sǔay mâak.","lit":"maison · toi · beau · très"},{"fr":"Tu parles très bien thaï.","tgt":"คุณพูดไทยเก่งมาก","ro":"Khun phûut thai kèng mâak.","lit":"tu · parler · thaï · doué · très"},{"fr":"Merci, c'est très gentil.","tgt":"ขอบคุณครับ ใจดีมาก","ro":"Khàwp-khun khráp, jai-dii mâak.","lit":"merci · [politesse] · gentil · très"},{"fr":"Ce plat est trop épicé.","tgt":"อาหารจานนี้เผ็ดเกินไป","ro":"Aa-hǎan jaan níi phèt koen pai.","lit":"nourriture · plat · ce · épicé · dépasser · aller"},{"fr":"La musique est trop forte.","tgt":"เพลงดังเกินไป","ro":"Phleeng dang koen pai.","lit":"musique · fort · dépasser · aller"},{"fr":"Il fait trop chaud dehors.","tgt":"ข้างนอกร้อนเกินไป","ro":"Khâang-nâwk ráwn koen pai.","lit":"dehors · chaud · dépasser · aller"},{"fr":"Je suis très content.","tgt":"ผมดีใจมาก","ro":"Phǒm dii-jai mâak.","lit":"je (homme) · content · très"},{"fr":"Tu travailles trop.","tgt":"คุณทำงานหนักเกินไป","ro":"Khun tham-ngaan nàk koen pai.","lit":"tu · travailler · lourd · dépasser · aller"}],"tip":{"title":"« Mâak » et « koen pai » : très et trop","example":"C'est trop cher pour moi. — แพง<b>เกินไป</b>สำหรับผม","body":"En français, « très » et « trop » se placent avant l'adjectif. En thaï, c'est l'inverse : ils viennent après. « Très » se dit « mâak », avec un ton qui descend : « sǔay mâak », très beau, ou « jai-dii mâak », très gentil. « Trop » se dit « koen pai », mot à mot dépasser, aller, comme si l'on allait au-delà de la limite. Ainsi « phaeng koen pai » donne : cher, dépasser, aller, c'est-à-dire trop cher. Attention à la différence : « mâak » est positif ou neutre, alors que « koen pai » exprime toujours un problème. Dire « phèt mâak », c'est très épicé, et peut-être tu aimes ça ; dire « phèt koen pai », c'est trop épicé, tu ne peux pas le manger. Astuce : pense à « koen pai » comme à une voiture qui dépasse la ligne d'arrivée et continue tout droit.","exampleRo":"Phaeng koen pai sǎm-ràp phǒm.","lit":"cher · dépasser · aller · pour · moi","say":{"Mâak":"มาก","koen pai":"เกินไป","mâak":"มาก","sǔay mâak":"สวยมาก","jai-dii mâak":"ใจดีมาก","phaeng koen pai":"แพงเกินไป","phèt mâak":"เผ็ดมาก","phèt koen pai":"เผ็ดเกินไป"}}},{"title":"Le sourire et la gentillesse","phrases":[{"fr":"Les Thaïs sourient souvent.","tgt":"คนไทยยิ้มเก่ง","ro":"Khon thai yím kèng.","lit":"personne · thaï · sourire · doué"},{"fr":"Ici, les gens parlent doucement.","tgt":"ที่นี่คนพูดเบาๆ","ro":"Thîi-nîi khon phûut bao bao.","lit":"ici · gens · parler · doux · doux"},{"fr":"Ce n'est rien, pas de souci.","tgt":"ไม่เป็นไร","ro":"Mâi pen rai.","lit":"ne pas · être · rien"},{"fr":"Elle sourit tout le temps.","tgt":"เขายิ้มตลอด","ro":"Khǎo yím tà-làwt.","lit":"elle · sourire · tout le temps"},{"fr":"Merci pour ta gentillesse.","tgt":"ขอบคุณที่ใจดีกับผม","ro":"Khàwp-khun thîi jai-dii kàp phǒm.","lit":"merci · de · gentil · avec · moi"},{"fr":"Je dois rentrer maintenant.","tgt":"ผมต้องกลับแล้ว","ro":"Phǒm tâwng klàp láew.","lit":"je (homme) · devoir · rentrer · [accompli]"},{"fr":"Rentre bien !","tgt":"กลับบ้านดีๆนะ","ro":"Klàp bâan dii dii ná.","lit":"rentrer · maison · bien · bien · [douceur]"},{"fr":"On se revoit très vite.","tgt":"เจอกันเร็วๆนี้นะ","ro":"Joe kan reo reo níi ná.","lit":"se voir · ensemble · vite · vite · ce · [douceur]"},{"fr":"Envoie-moi un message.","tgt":"ส่งข้อความมานะ","ro":"Sòng khâw-khwaam maa ná.","lit":"envoyer · message · venir · [douceur]"},{"fr":"Bonne nuit, à demain !","tgt":"ฝันดี พรุ่งนี้เจอกัน","ro":"Fǎn dii, phrûng-níi joe kan.","lit":"rêver · bien · demain · se voir · ensemble"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"J'aime vraiment parler thaï.","tgt":"ผมชอบพูดภาษาไทยมาก","ro":"Phǒm châwp phûut phaa-sǎa thai mâak.","lit":"je (homme) · aimer · parler · langue · thaï · beaucoup"},{"fr":"Maintenant, je sais me présenter.","tgt":"ตอนนี้ผมแนะนำตัวได้แล้ว","ro":"Tawn-níi phǒm náe-nam tua dâi láew.","lit":"maintenant · je (homme) · présenter · soi · pouvoir · [accompli]"},{"fr":"Parle un peu plus lentement, s'il te plaît.","tgt":"พูดช้าๆหน่อยนะ","ro":"Phûut cháa cháa nàwy ná.","lit":"parler · lent · lent · un peu · [douceur]"},{"fr":"Répète encore, vas-y !","tgt":"พูดอีกทีสิ","ro":"Phûut ìik thii sì.","lit":"parler · encore · fois · [allez]"},{"fr":"Et maintenant, on fait quoi ?","tgt":"แล้วจะทำอะไรต่อล่ะ","ro":"Láew jà tham a-rai tàw lâ?","lit":"et puis · [futur] · faire · quoi · ensuite · [alors ?]"},{"fr":"On continue à apprendre ensemble, d'accord ?","tgt":"เรียนต่อด้วยกันนะ","ro":"Rian tàw dûay-kan ná.","lit":"apprendre · continuer · ensemble · [douceur]"},{"fr":"Essaie de parler avec tes amis thaïs.","tgt":"ลองพูดกับเพื่อนคนไทยสิ","ro":"Lawng phûut kàp phûean khon thai sì.","lit":"essayer · parler · avec · ami · personne · thaï · [allez]"},{"fr":"Le thaï, ce n'est pas si difficile.","tgt":"ภาษาไทยไม่ยากนะ","ro":"Phaa-sǎa thai mâi yâak ná.","lit":"langue · thaï · ne pas · difficile · [douceur]"},{"fr":"Les tons sont encore difficiles pour moi.","tgt":"วรรณยุกต์ยังยากสำหรับผม","ro":"Wan-ná-yúk yang yâak sǎm-ràp phǒm.","lit":"ton · encore · difficile · pour · moi"},{"fr":"Bravo, continue comme ça !","tgt":"เก่งมาก สู้ๆนะ","ro":"Kèng mâak, sûu sûu ná.","lit":"doué · très · lutter · lutter · [douceur]"}],"tip":{"title":"« Ná », « sì », « lâ » : les petites particules de fin","example":"Répète encore, vas-y ! — พูดอีกที<b>สิ</b>","body":"Le thaï parlé adore les petits mots en fin de phrase. Ils ne changent pas le sens, mais ils donnent le ton, un peu comme nos « hein », « donc » ou « alors ». « Ná », au ton haut, adoucit la phrase et cherche l'accord de l'autre : « rian tàw dûay-kan ná », on continue ensemble, d'accord. « Sì », au ton bas, pousse gentiment à agir, comme « vas-y » ou « donc » : « phûut ìik thii sì », répète encore, vas-y, mot à mot parler, encore, fois, allez. « Lâ », au ton descendant, relance une question, comme « et toi alors ? » : « láew khun lâ ? ». Sans ces particules, une phrase thaïe peut sonner sèche ou trop directe. Entre amis, elles rendent la conversation chaleureuse et souriante. Astuce : si tu ne dois en retenir qu'une, garde « ná », elle rend presque toutes tes phrases plus aimables.","exampleRo":"Phûut ìik thii sì.","lit":"parler · encore · fois · [allez]","say":{"Ná":"นะ","sì":"สิ","lâ":"ล่ะ","rian tàw dûay-kan ná":"เรียนต่อด้วยกันนะ","Sì":"สิ","phûut ìik thii sì":"พูดอีกทีสิ","Lâ":"ล่ะ","láew khun lâ ?":"แล้วคุณล่ะ","ná":"นะ"}}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Louer un appartement à Chiang Mai","phrases":[{"fr":"Je cherche un logement à louer du côté de Nimman.","tgt":"ผมกำลังหาห้องเช่าแถวนิมมานครับ","ro":"Phǒm kam-lang hǎa hâwng châo thǎew Nim-maan khráp."},{"fr":"Le loyer est de combien par mois ?","tgt":"ค่าเช่าเดือนละเท่าไรครับ","ro":"Khâa châo duean lá thâo-rai khráp?"},{"fr":"Huit mille bahts, sans l'eau ni l'électricité.","tgt":"แปดพันบาทครับ ไม่รวมค่าน้ำค่าไฟ","ro":"Pàet phan bàat khráp, mâi ruam khâa náam khâa fai."},{"fr":"Est-ce que je peux voir la chambre aujourd'hui ?","tgt":"ขอดูห้องวันนี้ได้ไหมครับ","ro":"Khǎw duu hâwng wan-níi dâi mái khráp?"},{"fr":"Depuis le balcon, on voit même la montagne.","tgt":"จากระเบียงมองเห็นภูเขาด้วยครับ","ro":"Jàak rá-biang mawng hěn phuu-khǎo dûai khráp."},{"fr":"Il faut verser deux mois de caution.","tgt":"ต้องจ่ายเงินมัดจำสองเดือนครับ","ro":"Tâwng jàai ngoen mát-jam sǎwng duean khráp."},{"fr":"Le contrat dure au moins un an.","tgt":"สัญญาอย่างน้อยหนึ่งปีครับ","ro":"Sǎn-yaa yàang náwy nùeng pii khráp."},{"fr":"Y a-t-il une machine à laver dans l'immeuble ?","tgt":"ในตึกมีเครื่องซักผ้าไหมครับ","ro":"Nai tùek mii khrûeang sák-phâa mái khráp?"},{"fr":"Oui, au rez-de-chaussée, à côté du parking.","tgt":"มีครับ อยู่ชั้นล่าง ข้างที่จอดรถ","ro":"Mii khráp, yùu chán lâang, khâang thîi jàwt rót."},{"fr":"Je la prends, je peux emménager samedi ?","tgt":"ผมเอาห้องนี้ครับ ย้ายเข้าวันเสาร์ได้ไหมครับ","ro":"Phǒm ao hâwng níi khráp, yáai khâo wan sǎo dâi mái khráp?"}]},{"title":"Ouvrir un compte à la banque","phrases":[{"fr":"Demain, je vais ouvrir un compte à la banque.","tgt":"พรุ่งนี้ผมจะไปเปิดบัญชีที่ธนาคารครับ","ro":"Phrûng-níi phǒm jà pai pòet ban-chii thîi thá-naa-khaan khráp."},{"fr":"Quels documents faut-il apporter ?","tgt":"ต้องเอาเอกสารอะไรไปบ้างครับ","ro":"Tâwng ao èek-kà-sǎan à-rai pai bâang khráp?"},{"fr":"Votre passeport et votre contrat de location.","tgt":"หนังสือเดินทางกับสัญญาเช่าครับ","ro":"Nǎng-sǔe doen-thaang kàp sǎn-yaa châo khráp."},{"fr":"Vous recevrez votre carte d'ici une semaine.","tgt":"คุณจะได้บัตรภายในหนึ่งอาทิตย์ครับ","ro":"Khun jà dâi bàt phaai-nai nùeng aa-thít khráp."},{"fr":"Je vais faire venir de l'argent depuis la France.","tgt":"ผมจะโอนเงินมาจากฝรั่งเศสครับ","ro":"Phǒm jà oon ngoen maa jàak Fà-ràng-sèet khráp."},{"fr":"Est-ce qu'il y aura des frais ?","tgt":"จะมีค่าธรรมเนียมไหมครับ","ro":"Jà mii khâa tham-niam mái khráp?"},{"fr":"Oui, cent bahts par virement.","tgt":"มีครับ ครั้งละร้อยบาท","ro":"Mii khráp, khráng lá ráwy bàat."},{"fr":"Je vais aussi installer l'application sur mon portable.","tgt":"ผมจะลงแอปในมือถือด้วยครับ","ro":"Phǒm jà long áep nai mue-thǔe dûai khráp."},{"fr":"Quand est-ce que l'argent arrivera sur le compte ?","tgt":"เงินจะเข้าเมื่อไรครับ","ro":"Ngoen jà khâo mûea-rai khráp?"},{"fr":"Sans doute demain matin.","tgt":"น่าจะพรุ่งนี้เช้าครับ","ro":"Nâa-jà phrûng-níi cháo khráp."}],"tip":{"title":"« Jà » : le futur","example":"Demain, je vais ouvrir un compte à la banque. — พรุ่งนี้ผม<b>จะ</b>ไปเปิดบัญชีที่ธนาคารครับ","body":"En thaï, le verbe ne change jamais de forme : pour parler de l'avenir, on place simplement le petit mot « jà » juste devant le verbe. « Phǒm pai » veut dire « je vais » de façon générale, et « phǒm jà pai » veut dire « j'irai », ou « je vais y aller ». Dans l'exemple, on décompose : « phrûng-níi », demain, « phǒm », je, « jà », le futur, puis « pai pòet ban-chii », aller ouvrir un compte. Souvent, un mot de temps comme « phrûng-níi » suffit déjà, et « jà » ajoute l'idée d'un projet ou d'une intention. On l'entend aussi dans les questions : « jà mii khâa tham-niam mái ? », y aura-t-il des frais ? Pour retenir, pensez à « jà » comme au « je vais » du français : il annonce ce qui va arriver.","exampleRo":"Phrûng-níi phǒm jà pai pòet ban-chii thîi thá-naa-khaan khráp.","lit":"demain · je (homme) · [futur] · aller · ouvrir · compte · à · banque · [politesse]","say":{"Jà":"จะ","jà":"จะ","Phǒm pai":"ผมไป","phǒm jà pai":"ผมจะไป","phrûng-níi":"พรุ่งนี้","phǒm":"ผม","pai pòet ban-chii":"ไปเปิดบัญชี","jà mii khâa tham-niam mái ?":"จะมีค่าธรรมเนียมไหม"}}},{"title":"À la clinique","phrases":[{"fr":"Bonjour, j'ai de la fièvre depuis hier soir.","tgt":"สวัสดีครับ ผมเป็นไข้ตั้งแต่เมื่อคืน","ro":"Sà-wàt-dii khráp, phǒm pen khâi tâng-tàe mûea-khuen."},{"fr":"Vous avez mal à la gorge aussi ?","tgt":"เจ็บคอด้วยไหมครับ","ro":"Jèp khaw dûai mái khráp?"},{"fr":"Oui, un peu, et je tousse beaucoup.","tgt":"ครับ นิดหน่อย แล้วก็ไอเยอะมาก","ro":"Khráp, nít-nàwy, láew kâw ai yóe mâak."},{"fr":"Merci de remplir ce formulaire d'abord.","tgt":"กรุณากรอกแบบฟอร์มนี้ก่อนครับ","ro":"Kà-rú-naa kràwk bàep-fawm níi kàwn khráp."},{"fr":"Le médecin va vous examiner dans dix minutes.","tgt":"คุณหมอจะตรวจในอีกสิบนาทีครับ","ro":"Khun mǎw jà trùat nai ìik sìp naa-thii khráp."},{"fr":"Ouvrez la bouche, s'il vous plaît.","tgt":"อ้าปากหน่อยครับ","ro":"Âa pàak nàwy khráp."},{"fr":"C'est un simple rhume, rien de grave.","tgt":"เป็นหวัดธรรมดา ไม่ร้ายแรงครับ","ro":"Pen wàt tham-má-daa, mâi ráai-raeng khráp."},{"fr":"Reposez-vous bien et buvez beaucoup d'eau.","tgt":"พักผ่อนเยอะๆ และดื่มน้ำมากๆ นะครับ","ro":"Phák-phàwn yóe yóe lâe dùem náam mâak mâak ná khráp."},{"fr":"Combien coûte la consultation ?","tgt":"ค่าตรวจเท่าไรครับ","ro":"Khâa trùat thâo-rai khráp?"},{"fr":"Cinq cents bahts, médicaments compris.","tgt":"ห้าร้อยบาทครับ รวมค่ายาแล้ว","ro":"Hâa ráwy bàat khráp, ruam khâa yaa láew."}]},{"title":"À la pharmacie","phrases":[{"fr":"Vous avez une crème contre les piqûres de moustiques ?","tgt":"มียาทาแก้ยุงกัดไหมครับ","ro":"Mii yaa thaa kâe yung kàt mái khráp?"},{"fr":"Cette crème calme les démangeaisons très vite.","tgt":"ครีมนี้แก้คันได้เร็วมากครับ","ro":"Khriim níi kâe khan dâi reo mâak khráp."},{"fr":"Il faut en mettre combien de fois par jour ?","tgt":"ต้องทาวันละกี่ครั้งครับ","ro":"Tâwng thaa wan lá kìi khráng khráp?"},{"fr":"Trois fois par jour, après la douche.","tgt":"วันละสามครั้ง หลังอาบน้ำครับ","ro":"Wan lá sǎam khráng, lǎng àap-náam khráp."},{"fr":"Il me faut aussi quelque chose contre le mal de ventre.","tgt":"ผมต้องการยาแก้ปวดท้องด้วยครับ","ro":"Phǒm tâwng-kaan yaa kâe pùat tháwng dûai khráp."},{"fr":"Vous avez mangé quelque chose de trop épicé ?","tgt":"ทานอะไรเผ็ดๆ มาหรือเปล่าครับ","ro":"Thaan à-rai phèt phèt maa rǔe-plàao khráp?"},{"fr":"Oui, une salade de papaye très pimentée.","tgt":"ครับ ส้มตำเผ็ดมาก","ro":"Khráp, sôm-tam phèt mâak."},{"fr":"Prenez un comprimé avant chaque repas.","tgt":"ทานยาหนึ่งเม็ดก่อนอาหารทุกมื้อครับ","ro":"Thaan yaa nùeng mét kàwn aa-hǎan thúk múe khráp."},{"fr":"Si ça ne va pas mieux, allez voir un médecin.","tgt":"ถ้าไม่ดีขึ้น ควรไปหาหมอนะครับ","ro":"Thâa mâi dii khûen, khuan pai hǎa mǎw ná khráp."},{"fr":"Merci, je reviendrai si nécessaire.","tgt":"ขอบคุณครับ ถ้าจำเป็นจะกลับมาอีก","ro":"Khàwp-khun khráp, thâa jam-pen jà klàp maa ìik."}]},{"title":"Hier au travail","phrases":[{"fr":"Hier, je suis allé travailler à scooter.","tgt":"เมื่อวานผมขี่มอเตอร์ไซค์ไปทำงานครับ","ro":"Mûea-waan phǒm khìi maw-toe-sai pai tham-ngaan khráp."},{"fr":"En chemin, je suis allé acheter un café à mon endroit habituel.","tgt":"ระหว่างทางผมไปซื้อกาแฟที่ร้านประจำครับ","ro":"Rá-wàang thaang phǒm pai súe kaa-fae thîi ráan prà-jam khráp."},{"fr":"Une collègue a rapporté des gâteaux pour tout le monde.","tgt":"เพื่อนร่วมงานซื้อขนมมาฝากทุกคน","ro":"Phûean rûam ngaan súe khà-nǒm maa fàak thúk khon."},{"fr":"Le matin, j'ai préparé une réunion avec un client.","tgt":"ตอนเช้าผมเตรียมประชุมกับลูกค้าครับ","ro":"Tawn cháo phǒm triam prà-chum kàp lûuk-kháa khráp."},{"fr":"À midi, nous sommes allés manger une soupe de nouilles.","tgt":"ตอนเที่ยงพวกเราไปกินก๋วยเตี๋ยวกัน","ro":"Tawn thîang phûak-rao pai kin kǔai-tǐao kan."},{"fr":"Tu peux aller me chercher les documents sur mon bureau ?","tgt":"ช่วยไปเอาเอกสารบนโต๊ะผมมาหน่อยครับ","ro":"Chûai pai ao èek-kà-sǎan bon tó phǒm maa nàwy khráp."},{"fr":"L'après-midi, j'ai emporté l'ordinateur à réparer.","tgt":"ตอนบ่ายผมเอาคอมพิวเตอร์ไปซ่อม","ro":"Tawn bàai phǒm ao khawm-phiu-tôe pai sâwm."},{"fr":"J'ai fini tard, alors je suis rentré en taxi.","tgt":"ผมเลิกงานดึก เลยนั่งแท็กซี่กลับบ้าน","ro":"Phǒm lôek ngaan dùek, loei nâng tháek-sîi klàp bâan."},{"fr":"Mon chef est venu me remercier.","tgt":"หัวหน้าเดินมาขอบคุณผมครับ","ro":"Hǔa-nâa doen maa khàwp-khun phǒm khráp."},{"fr":"C'était une longue journée, mais tout s'est bien passé.","tgt":"เป็นวันที่ยาวมาก แต่ก็ผ่านไปด้วยดีครับ","ro":"Pen wan thîi yaao mâak, tàe kâw phàan pai dûai dii khráp."}],"tip":{"title":"Les verbes en série : « pai súe, ao maa »","example":"Tu peux aller me chercher les documents sur mon bureau ? — ช่วย<b>ไป</b><b>เอา</b>เอกสารบนโต๊ะผม<b>มา</b>หน่อยครับ","body":"Le thaï aime enchaîner plusieurs verbes à la suite, sans « et » ni « pour », dans l'ordre où les actions se passent. « Pai súe » signifie mot à mot « aller acheter », et « ao maa », « prendre venir », c'est-à-dire apporter ; à l'inverse, « ao pai », « prendre aller », veut dire emporter. Dans l'exemple, on entend : « chûai », aider, « pai », aller, « ao èek-kà-sǎan », prendre les documents, puis « maa », venir, autrement dit : va me les chercher et rapporte-les. On dit de même « khìi maw-toe-sai pai tham-ngaan », aller travailler à scooter, et « nâng tháek-sîi klàp bâan », rentrer en taxi. L'astuce : racontez la scène comme un petit film, une action après l'autre, et la phrase thaïe se construit toute seule.","exampleRo":"Chûai pai ao èek-kà-sǎan bon tó phǒm maa nàwy khráp.","lit":"aider · aller · prendre · documents · sur · table · je (homme) · venir · un peu · [politesse]","say":{"Pai súe":"ไปซื้อ","ao maa":"เอามา","ao pai":"เอาไป","chûai":"ช่วย","pai":"ไป","ao èek-kà-sǎan":"เอาเอกสาร","maa":"มา","khìi maw-toe-sai pai tham-ngaan":"ขี่มอเตอร์ไซค์ไปทำงาน","nâng tháek-sîi klàp bâan":"นั่งแท็กซี่กลับบ้าน","pai súe, ao maa":"ไปซื้อ เอามา"}}},{"title":"Faire réparer le scooter","phrases":[{"fr":"Mon scooter ne démarre plus depuis ce matin.","tgt":"มอเตอร์ไซค์ผมสตาร์ทไม่ติดตั้งแต่เช้าครับ","ro":"Maw-toe-sai phǒm sà-táat mâi tìt tâng-tàe cháo khráp."},{"fr":"Je vais le faire réparer au garage du coin.","tgt":"เดี๋ยวผมจะเอาไปให้ร้านแถวบ้านซ่อม","ro":"Dǐao phǒm jà ao pai hâi ráan thǎew bâan sâwm."},{"fr":"Vous pouvez me vérifier les freins aussi ?","tgt":"ช่วยเช็กเบรกให้ด้วยได้ไหมครับ","ro":"Chûai chék brèek hâi dûai dâi mái khráp?"},{"fr":"Le mécanicien m'a fait attendre une heure.","tgt":"ช่างให้ผมรอหนึ่งชั่วโมงครับ","ro":"Châang hâi phǒm raw nùeng chûa-moong khráp."},{"fr":"Il faut changer la batterie.","tgt":"ต้องเปลี่ยนแบตเตอรี่ครับ","ro":"Tâwng plìan bàet-toe-rîi khráp."},{"fr":"Mon voisin m'a prêté son casque.","tgt":"เพื่อนบ้านให้ผมยืมหมวกกันน็อก","ro":"Phûean-bâan hâi phǒm yuem mùak-kan-nók."},{"fr":"Je lui ai donné des mangues pour le remercier.","tgt":"ผมให้มะม่วงเขาเป็นการขอบคุณครับ","ro":"Phǒm hâi má-mûang kháo pen kaan khàwp-khun khráp."},{"fr":"Ça fait combien en tout ?","tgt":"ทั้งหมดเท่าไรครับ","ro":"Tháng-mòt thâo-rai khráp?"},{"fr":"Mille deux cents bahts, main-d'œuvre comprise.","tgt":"หนึ่งพันสองร้อยบาท รวมค่าแรงแล้วครับ","ro":"Nùeng phan sǎwng ráwy bàat, ruam khâa raeng láew khráp."},{"fr":"Je peux vous payer par virement ?","tgt":"ผมโอนเงินจ่ายได้ไหมครับ","ro":"Phǒm oon ngoen jàai dâi mái khráp?"}],"tip":{"title":"« Hâi » : donner, et faire faire","example":"Le mécanicien m'a fait attendre une heure. — ช่าง<b>ให้</b>ผมรอหนึ่งชั่วโมงครับ","body":"Le mot « hâi » est l'un des plus utiles du thaï. Seul, il veut dire donner : « phǒm hâi má-mûang kháo », je lui ai donné des mangues. Placé devant une personne suivie d'un verbe, il veut dire faire faire ou laisser faire : « châang hâi phǒm raw », mot à mot mécanicien, donner, moi, attendre, donc le mécanicien m'a fait attendre. Pour confier une réparation, on dit « ao pai hâi ráan sâwm », l'apporter et le faire réparer par le garage. En fin de phrase, « hâi » indique aussi qu'on rend un service à quelqu'un : « chûai chék brèek hâi dûai », vérifiez-moi les freins aussi. Retenez l'image d'un cadeau : avec « hâi », un objet ou une action passe d'une personne à une autre.","exampleRo":"Châang hâi phǒm raw nùeng chûa-moong khráp.","lit":"mécanicien · donner (faire) · je (homme) · attendre · un · heure · [politesse]","say":{"Hâi":"ให้","hâi":"ให้","phǒm hâi má-mûang kháo":"ผมให้มะม่วงเขา","châang hâi phǒm raw":"ช่างให้ผมรอ","ao pai hâi ráan sâwm":"เอาไปให้ร้านซ่อม","chûai chék brèek hâi dûai":"ช่วยเช็กเบรกให้ด้วย"}}},{"title":"Une coupure de courant","phrases":[{"fr":"Le courant est coupé dans toute la ruelle.","tgt":"ไฟดับทั้งซอยเลยครับ","ro":"Fai dàp tháng sawy loei khráp."},{"fr":"Ça arrive souvent quand il y a un orage.","tgt":"ช่วงพายุเข้าไฟดับบ่อยครับ","ro":"Chûang phaa-yú khâo fai dàp bàwy khráp."},{"fr":"Vous avez une lampe de poche ?","tgt":"มีไฟฉายไหมครับ","ro":"Mii fai-chǎai mái khráp?"},{"fr":"Elle est dans le tiroir de la cuisine.","tgt":"อยู่ในลิ้นชักในครัวครับ","ro":"Yùu nai lín-chák nai khrua khráp."},{"fr":"Sans la clim, la chambre chauffe très vite.","tgt":"ไม่มีแอร์ ห้องร้อนเร็วมากครับ","ro":"Mâi mii ae, hâwng ráwn reo mâak khráp."},{"fr":"J'ai peur que la nourriture du frigo s'abîme.","tgt":"กลัวของในตู้เย็นจะเสียครับ","ro":"Klua khǎwng nai tûu-yen jà sǐa khráp."},{"fr":"Je vais appeler la compagnie d'électricité pour me renseigner.","tgt":"ผมจะโทรถามการไฟฟ้าครับ","ro":"Phǒm jà thoo thǎam kaan-fai-fáa khráp."},{"fr":"Ils disent que le courant reviendra vers vingt heures.","tgt":"เขาบอกว่าไฟจะมาประมาณสองทุ่มครับ","ro":"Kháo bàwk wâa fai jà maa prà-maan sǎwng thûm khráp."},{"fr":"En attendant, allons dîner dehors.","tgt":"ระหว่างรอ ไปกินข้าวข้างนอกกันเถอะ","ro":"Rá-wàang raw, pai kin khâao khâang nâwk kan thòe."},{"fr":"Ah, l'électricité est revenue !","tgt":"อ้าว ไฟมาแล้วครับ","ro":"Âao, fai maa láew khráp!"}]},{"title":"Les voisins","phrases":[{"fr":"Bonjour, je viens d'emménager à côté.","tgt":"สวัสดีครับ ผมเพิ่งย้ายมาอยู่ห้องข้างๆ ครับ","ro":"Sà-wàt-dii khráp, phǒm phôeng yáai maa yùu hâwng khâang khâang khráp."},{"fr":"Bienvenue ! Je m'appelle Noi, vous venez d'où ?","tgt":"ยินดีต้อนรับค่ะ ฉันชื่อน้อย มาจากไหนคะ","ro":"Yin-dii tâwn-ráp khâ, chǎn chûe Náwy, maa jàak nǎi khá?"},{"fr":"Je suis français, je travaille ici depuis deux ans.","tgt":"ผมเป็นคนฝรั่งเศส ทำงานที่นี่มาสองปีแล้วครับ","ro":"Phǒm pen khon Fà-ràng-sèet, tham-ngaan thîi-nîi maa sǎwng pii láew khráp."},{"fr":"Si vous avez besoin d'aide, venez frapper chez moi.","tgt":"ถ้าต้องการให้ช่วยอะไร มาเคาะประตูได้เลยนะครับ","ro":"Thâa tâwng-kaan hâi chûai à-rai, maa kháw prà-tuu dâi loei ná khráp."},{"fr":"Le chien d'à côté aboie toute la nuit.","tgt":"หมาของห้องข้างๆ เห่าทั้งคืนเลยครับ","ro":"Mǎa khǎwng hâwng khâang khâang hào tháng khuen loei khráp."},{"fr":"Je vais aller leur en parler gentiment.","tgt":"ผมจะไปคุยกับเขาดีๆ ครับ","ro":"Phǒm jà pai khui kàp kháo dii dii khráp."},{"fr":"Excusez-moi, votre chien aboie un peu fort la nuit.","tgt":"ขอโทษครับ หมาของคุณเห่าเสียงดังตอนกลางคืนนิดหน่อยครับ","ro":"Khǎw-thôot khráp, mǎa khǎwng khun hào sǐang dang tawn klaang-khuen nít-nàwy khráp."},{"fr":"Désolé, je ne savais pas, je vais faire attention.","tgt":"ขอโทษครับ ผมไม่รู้เลย จะระวังนะครับ","ro":"Khǎw-thôot khráp, phǒm mâi rúu loei, jà rá-wang ná khráp."},{"fr":"Nos voisins nous apportent souvent des fruits de leur jardin.","tgt":"เพื่อนบ้านชอบเอาผลไม้จากสวนมาให้บ่อยๆ","ro":"Phûean-bâan châwp ao phǒn-lá-máai jàak sǔan maa hâi bàwy bàwy."},{"fr":"On a de la chance d'avoir des voisins aussi gentils.","tgt":"เราโชคดีที่มีเพื่อนบ้านใจดีแบบนี้ครับ","ro":"Rao chôok-dii thîi mii phûean-bâan jai-dii bàep níi khráp."}]},{"title":"La lessive","phrases":[{"fr":"Il n'y a pas de machine à laver dans ma chambre.","tgt":"ในห้องผมไม่มีเครื่องซักผ้าครับ","ro":"Nai hâwng phǒm mâi mii khrûeang sák-phâa khráp."},{"fr":"J'utilise les machines à pièces en bas de l'immeuble.","tgt":"ผมใช้เครื่องซักผ้าหยอดเหรียญข้างล่างตึกครับ","ro":"Phǒm chái khrûeang sák-phâa yàwt rǐan khâang lâang tùek khráp."},{"fr":"Une lessive coûte trente bahts.","tgt":"ซักครั้งละสามสิบบาทครับ","ro":"Sák khráng lá sǎam-sìp bàat khráp."},{"fr":"Tu as des pièces de dix bahts ?","tgt":"มีเหรียญสิบบาทไหม","ro":"Mii rǐan sìp bàat mái?"},{"fr":"Avec ce soleil, le linge sèche en deux heures.","tgt":"แดดแรงแบบนี้ ผ้าแห้งในสองชั่วโมงครับ","ro":"Dàet raeng bàep níi, phâa hâeng nai sǎwng chûa-moong khráp."},{"fr":"Mais à la saison des pluies, le linge sèche mal.","tgt":"แต่หน้าฝนผ้าไม่ค่อยแห้งเลยครับ","ro":"Tàe nâa fǒn phâa mâi khâwy hâeng loei khráp."},{"fr":"Parfois, je porte mon linge à la blanchisserie du coin.","tgt":"บางทีผมก็เอาผ้าไปส่งร้านซักรีดแถวบ้านครับ","ro":"Baang-thii phǒm kâw ao phâa pai sòng ráan sák-rîit thǎew bâan khráp."},{"fr":"Ils lavent et repassent tout pour le lendemain.","tgt":"เขาซักและรีดให้เสร็จภายในวันรุ่งขึ้นครับ","ro":"Kháo sák lâe rîit hâi sèt phaai-nai wan rûng-khûen khráp."},{"fr":"C'est seulement vingt bahts le kilo.","tgt":"กิโลละยี่สิบบาทเองครับ","ro":"Kì-loo lá yîi-sìp bàat eeng khráp."},{"fr":"Ce soir, je dois aller récupérer mes vêtements.","tgt":"เย็นนี้ผมต้องไปรับผ้าครับ","ro":"Yen níi phǒm tâwng pai ráp phâa khráp."}]},{"title":"Au marché du matin","phrases":[{"fr":"Le marché ouvre dès six heures du matin.","tgt":"ตลาดเปิดตั้งแต่หกโมงเช้าครับ","ro":"Tà-làat pòet tâng-tàe hòk moong cháo khráp."},{"fr":"Les mangues sont à combien le kilo ?","tgt":"มะม่วงกิโลละเท่าไรครับ","ro":"Má-mûang kì-loo lá thâo-rai khráp?"},{"fr":"Soixante bahts, elles sont mûres à point.","tgt":"หกสิบบาทครับ สุกกำลังดี","ro":"Hòk-sìp bàat khráp, sùk kam-lang dii."},{"fr":"Vous pouvez baisser un peu le prix ?","tgt":"ลดหน่อยได้ไหมครับ","ro":"Lót nàwy dâi mái khráp?"},{"fr":"Si vous en prenez deux kilos, ça fait cent bahts.","tgt":"ถ้าเอาสองกิโลก็ร้อยบาทครับ","ro":"Thâa ao sǎwng kì-loo kâw ráwy bàat khráp."},{"fr":"Je voudrais aussi un peu de basilic thaï.","tgt":"ขอใบโหระพานิดหน่อยด้วยครับ","ro":"Khǎw bai hǒo-rá-phaa nít-nàwy dûai khráp."},{"fr":"Ces légumes viennent des montagnes autour de la ville.","tgt":"ผักพวกนี้มาจากภูเขารอบเมืองครับ","ro":"Phàk phûak níi maa jàak phuu-khǎo râwp mueang khráp."},{"fr":"J'achète aussi du riz gluant pour le petit-déjeuner.","tgt":"ผมซื้อข้าวเหนียวไปกินเป็นมื้อเช้าด้วยครับ","ro":"Phǒm súe khâao-nǐao pai kin pen múe cháo dûai khráp."},{"fr":"Mettez tout dans le même sac, s'il vous plaît.","tgt":"ใส่ถุงเดียวกันเลยครับ","ro":"Sài thǔng diao kan loei khráp."},{"fr":"J'adore l'ambiance du marché le matin.","tgt":"ผมชอบบรรยากาศตลาดตอนเช้ามากครับ","ro":"Phǒm châwp ban-yaa-kàat tà-làat tawn cháo mâak khráp."}]},{"title":"Le week-end dernier","phrases":[{"fr":"Tu as fait quoi, le week-end dernier ?","tgt":"เสาร์อาทิตย์ที่แล้วทำอะไรบ้าง","ro":"Sǎo aa-thít thîi láew tham à-rai bâang?"},{"fr":"Je suis allé voir une cascade avec des amis.","tgt":"ผมไปเที่ยวน้ำตกกับเพื่อนๆ","ro":"Phǒm pai thîao nám-tòk kàp phûean phûean."},{"fr":"On est partis tôt, vers sept heures.","tgt":"เราออกเดินทางแต่เช้า ประมาณเจ็ดโมง","ro":"Rao àwk doen-thaang tàe cháo, prà-maan jèt moong."},{"fr":"Il n'y avait pas grand monde.","tgt":"คนไม่ค่อยเยอะ","ro":"Khon mâi khâwy yóe."},{"fr":"On s'est baignés dans l'eau fraîche.","tgt":"เราลงเล่นน้ำเย็นๆ กัน","ro":"Rao long lên náam yen yen kan."},{"fr":"Ensuite, on a mangé dans un restaurant au bord de la rivière.","tgt":"แล้วก็ไปกินข้าวร้านริมแม่น้ำ","ro":"Láew kâw pai kin khâao ráan rim mâe-náam."},{"fr":"Et toi, tu es sorti quelque part ?","tgt":"แล้วคุณล่ะ ได้ไปไหนไหม","ro":"Láew khun lâ, dâi pai nǎi mái?"},{"fr":"Non, je suis resté chez moi à me reposer.","tgt":"ไม่ได้ไปไหน อยู่บ้านพักผ่อน","ro":"Mâi dâi pai nǎi, yùu bâan phák-phàwn."},{"fr":"Dimanche, j'ai fait le ménage puis la cuisine.","tgt":"วันอาทิตย์ทำความสะอาดบ้านแล้วก็ทำกับข้าว","ro":"Wan aa-thít tham khwaam sà-àat bâan láew kâw tham kàp-khâao."},{"fr":"La prochaine fois, je viendrai avec vous.","tgt":"คราวหน้าผมจะไปด้วยนะ","ro":"Khraao nâa phǒm jà pai dûai ná."}]},{"title":"Un dîner entre amis","phrases":[{"fr":"Tu as déjà fait les courses pour ce soir ?","tgt":"ซื้อของสำหรับคืนนี้แล้วหรือยัง","ro":"Súe khǎwng sǎm-ràp khuen-níi láew rǔe yang?"},{"fr":"Oui, j'ai déjà tout acheté au marché.","tgt":"ซื้อแล้ว ซื้อมาจากตลาดครบแล้ว","ro":"Súe láew, súe maa jàak tà-làat khróp láew."},{"fr":"Les invités sont déjà arrivés ?","tgt":"แขกมาถึงแล้วหรือยัง","ro":"Khàek maa thǔeng láew rǔe yang?"},{"fr":"Pas encore, ils sont en chemin.","tgt":"ยังครับ กำลังเดินทางมา","ro":"Yang khráp, kam-lang doen-thaang maa."},{"fr":"Le riz n'est pas encore cuit.","tgt":"ข้าวยังไม่สุกเลย","ro":"Khâao yang mâi sùk loei."},{"fr":"Tu as déjà goûté le curry hang lay ?","tgt":"เคยกินแกงฮังเลหรือยัง","ro":"Khoei kin kaeng hang-lee rǔe yang?"},{"fr":"Pas encore, ce sera la première fois.","tgt":"ยังไม่เคย จะเป็นครั้งแรก","ro":"Yang mâi khoei, jà pen khráng râek."},{"fr":"Tout le monde a fini de manger ?","tgt":"ทุกคนกินเสร็จแล้วหรือยัง","ro":"Thúk khon kin sèt láew rǔe yang?"},{"fr":"Moi, j'ai déjà trop mangé.","tgt":"ผมกินเยอะเกินไปแล้ว","ro":"Phǒm kin yóe koen pai láew."},{"fr":"Il est déjà minuit, je dois rentrer.","tgt":"เที่ยงคืนแล้ว ผมต้องกลับแล้วนะ","ro":"Thîang-khuen láew, phǒm tâwng klàp láew ná."}],"tip":{"title":"« Láew » et « yang » : déjà et pas encore","example":"Tu as déjà fait les courses pour ce soir ? — ซื้อของสำหรับคืนนี้<b>แล้ว</b>หรือ<b>ยัง</b>","body":"« Láew », placé après le verbe, marque une action accomplie, comme notre « déjà » : « súe láew », c'est acheté. « Yang mâi », placé devant le verbe, veut dire pas encore : « khâao yang mâi sùk », le riz n'est pas encore cuit. La question la plus courante réunit les deux : on ajoute « láew rǔe yang » en fin de phrase, mot à mot « déjà, ou pas encore ? ». Dans l'exemple, on décompose : « súe », acheter, « khǎwng », des choses, « sǎm-ràp khuen-níi », pour ce soir, puis « láew rǔe yang ». Pour répondre, on reprend le verbe avec « láew », ou on dit simplement « yang », pas encore. Astuce : cette question s'entend partout en Thaïlande, même pour demander gentiment si vous avez déjà mangé.","exampleRo":"Súe khǎwng sǎm-ràp khuen-níi láew rǔe yang?","lit":"acheter · choses · pour · ce soir · [accompli] · ou · pas encore","say":{"Láew":"แล้ว","yang":"ยัง","súe láew":"ซื้อแล้ว","Yang mâi":"ยังไม่","khâao yang mâi sùk":"ข้าวยังไม่สุก","láew rǔe yang":"แล้วหรือยัง","súe":"ซื้อ","khǎwng":"ของ","sǎm-ràp khuen-níi":"สำหรับคืนนี้","láew":"แล้ว"}}},{"title":"La saison des pluies","phrases":[{"fr":"La saison des pluies commence en général en mai.","tgt":"หน้าฝนมักจะเริ่มเดือนพฤษภาคม","ro":"Nâa fǒn mák jà rôem duean phrúet-sà-phaa-khom."},{"fr":"Il pleut presque tous les après-midi.","tgt":"ฝนตกเกือบทุกบ่ายครับ","ro":"Fǒn tòk kùeap thúk bàai khráp."},{"fr":"Je garde toujours un imperméable sous la selle du scooter.","tgt":"ผมเก็บเสื้อกันฝนไว้ใต้เบาะมอเตอร์ไซค์ตลอด","ro":"Phǒm kèp sûea kan fǒn wái tâi bàw maw-toe-sai tà-làwt."},{"fr":"Après une grosse averse, certaines rues sont inondées.","tgt":"หลังฝนตกหนัก ถนนบางสายน้ำท่วม","ro":"Lǎng fǒn tòk nàk, thà-nǒn baang sǎai nám thûam."},{"fr":"Mieux vaut attendre que la pluie s'arrête.","tgt":"รอให้ฝนหยุดก่อนดีกว่าครับ","ro":"Raw hâi fǒn yùt kàwn dii kwàa khráp."},{"fr":"L'air se rafraîchit et tout devient vert.","tgt":"อากาศเย็นลง ต้นไม้เขียวไปหมด","ro":"Aa-kàat yen long, tôn-máai khǐao pai mòt."},{"fr":"En cette saison, il y a énormément de moustiques.","tgt":"ช่วงนี้ยุงเยอะมากครับ","ro":"Chûang níi yung yóe mâak khráp."},{"fr":"Les rizières autour de la ville sont magnifiques.","tgt":"นาข้าวรอบเมืองสวยมากครับ","ro":"Naa khâao râwp mueang sǔai mâak khráp."},{"fr":"Mes chaussures sont encore trempées.","tgt":"รองเท้าผมยังเปียกอยู่เลย","ro":"Rawng-tháao phǒm yang pìak yùu loei."},{"fr":"Moi, j'aime bien le bruit de la pluie la nuit.","tgt":"ผมชอบเสียงฝนตกตอนกลางคืนครับ","ro":"Phǒm châwp sǐang fǒn tòk tawn klaang-khuen khráp."}]},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais petit, j'habitais à la campagne.","tgt":"ตอนเด็กๆ ผมอยู่ชนบทครับ","ro":"Tawn dèk dèk phǒm yùu chon-ná-bòt khráp."},{"fr":"Mes grands-parents avaient une ferme.","tgt":"ปู่ย่าผมมีฟาร์ม","ro":"Pùu yâa phǒm mii faam."},{"fr":"J'allais à l'école à vélo.","tgt":"ผมขี่จักรยานไปโรงเรียน","ro":"Phǒm khìi jàk-krà-yaan pai roong-rian."},{"fr":"Le soir, on jouait au foot dans la rue.","tgt":"ตอนเย็นเราเล่นฟุตบอลกันบนถนน","ro":"Tawn yen rao lên fút-bawn kan bon thà-nǒn."},{"fr":"Ma mère était une excellente cuisinière.","tgt":"แม่ผมทำอาหารเก่งมาก","ro":"Mâe phǒm tham aa-hǎan kèng mâak."},{"fr":"Vous étiez un enfant sage ?","tgt":"ตอนเด็กคุณเป็นเด็กดีไหมครับ","ro":"Tawn dèk khun pen dèk dii mái khráp?"},{"fr":"Pas vraiment, j'étais plutôt turbulent.","tgt":"ไม่ค่อยครับ ผมค่อนข้างซน","ro":"Mâi khâwy khráp, phǒm khâwn-khâang son."},{"fr":"Autrefois, je détestais les légumes.","tgt":"เมื่อก่อนผมไม่ชอบกินผักเลย","ro":"Mûea-kàwn phǒm mâi châwp kin phàk loei."},{"fr":"Maintenant, je mange de tout.","tgt":"ตอนนี้กินได้ทุกอย่างแล้วครับ","ro":"Tawn-níi kin dâi thúk yàang láew khráp."},{"fr":"Quand j'y repense, j'aimerais redevenir enfant.","tgt":"คิดถึงเรื่องพวกนี้แล้วก็อยากกลับไปเป็นเด็กอีก","ro":"Khít thǔeng rûeang phûak níi láew kâw yàak klàp pai pen dèk ìik."}]},{"title":"Un dimanche tranquille","phrases":[{"fr":"Le dimanche, je me réveille sans réveil.","tgt":"วันอาทิตย์ผมตื่นเองไม่ต้องตั้งนาฬิกาปลุก","ro":"Wan aa-thít phǒm tùen eeng mâi tâwng tâng naa-lí-kaa plùk."},{"fr":"Je bois mon café tranquillement sur le balcon.","tgt":"ผมนั่งดื่มกาแฟที่ระเบียง","ro":"Phǒm nâng dùem kaa-fae thîi rá-biang."},{"fr":"Ensuite, je vais courir autour des douves de la vieille ville.","tgt":"จากนั้นก็ไปวิ่งรอบคูเมือง","ro":"Jàak nán kâw pai wîng râwp khuu mueang."},{"fr":"À cette heure-là, il fait encore frais.","tgt":"ตอนนั้นอากาศยังเย็นอยู่","ro":"Tawn nán aa-kàat yang yen yùu."},{"fr":"L'après-midi, je fais une sieste.","tgt":"ตอนบ่ายผมนอนกลางวัน","ro":"Tawn bàai phǒm nawn klaang-wan."},{"fr":"Le soir, il y a le marché de rue du dimanche.","tgt":"ตอนเย็นมีถนนคนเดินวันอาทิตย์","ro":"Tawn yen mii thà-nǒn khon doen wan aa-thít."},{"fr":"On y trouve de l'artisanat et plein de choses à manger.","tgt":"มีงานฝีมือแล้วก็ของกินเยอะแยะ","ro":"Mii ngaan fǐi-mue láew kâw khǎwng kin yóe-yáe."},{"fr":"J'aime y acheter du porc grillé.","tgt":"ผมชอบซื้อหมูปิ้งที่นั่น","ro":"Phǒm châwp súe mǔu pîng thîi-nân."},{"fr":"Il y a tellement de monde qu'on avance à peine.","tgt":"คนเยอะจนเดินแทบไม่ได้","ro":"Khon yóe jon doen thâep mâi dâi."},{"fr":"C'est ma façon préférée de finir la semaine.","tgt":"นี่เป็นวิธีปิดท้ายสัปดาห์ที่ผมชอบที่สุด","ro":"Nîi pen wí-thii pìt tháai sàp-daa thîi phǒm châwp thîi-sùt."}]},{"title":"La clim en panne","phrases":[{"fr":"La clim fait un drôle de bruit.","tgt":"แอร์มีเสียงแปลกๆ ครับ","ro":"Ae mii sǐang plàek plàek khráp."},{"fr":"Et elle ne refroidit plus du tout.","tgt":"แล้วก็ไม่เย็นเลยครับ","ro":"Láew kâw mâi yen loei khráp."},{"fr":"J'ai appelé le propriétaire ce matin.","tgt":"เมื่อเช้าผมโทรหาเจ้าของห้องแล้ว","ro":"Mûea-cháo phǒm thoo hǎa jâo-khǎwng hâwng láew."},{"fr":"Il va envoyer un technicien cet après-midi.","tgt":"เขาจะส่งช่างมาตอนบ่ายนี้","ro":"Kháo jà sòng châang maa tawn bàai níi."},{"fr":"Il faut nettoyer les filtres tous les trois mois.","tgt":"ต้องล้างแผ่นกรองทุกสามเดือนครับ","ro":"Tâwng láang phàen krawng thúk sǎam duean khráp."},{"fr":"Il manque aussi un peu de gaz réfrigérant.","tgt":"น้ำยาแอร์ก็ขาดนิดหน่อยครับ","ro":"Nám-yaa ae kâw khàat nít-nàwy khráp."},{"fr":"La réparation va prendre longtemps ?","tgt":"ซ่อมนานไหมครับ","ro":"Sâwm naan mái khráp?"},{"fr":"Une heure environ, pas plus.","tgt":"ประมาณชั่วโมงเดียว ไม่เกินนั้นครับ","ro":"Prà-maan chûa-moong diao, mâi koen nán khráp."},{"fr":"C'est le propriétaire qui paie la réparation.","tgt":"เจ้าของห้องเป็นคนจ่ายค่าซ่อม","ro":"Jâo-khǎwng hâwng pen khon jàai khâa sâwm."},{"fr":"Enfin, la chambre est de nouveau fraîche.","tgt":"ในที่สุดห้องก็เย็นอีกครั้ง","ro":"Nai thîi-sùt hâwng kâw yen ìik khráng."}]},{"title":"À la poste","phrases":[{"fr":"Je voudrais envoyer ce colis en France.","tgt":"ผมอยากส่งพัสดุนี้ไปฝรั่งเศสครับ","ro":"Phǒm yàak sòng phát-sà-dù níi pai Fà-ràng-sèet khráp."},{"fr":"Qu'est-ce qu'il y a dedans ?","tgt":"ข้างในมีอะไรบ้างครับ","ro":"Khâang nai mii à-rai bâang khráp?"},{"fr":"Des vêtements et du café de la région.","tgt":"มีเสื้อผ้ากับกาแฟของที่นี่ครับ","ro":"Mii sûea-phâa kàp kaa-fae khǎwng thîi-nîi khráp."},{"fr":"Par avion ou par bateau ?","tgt":"ส่งทางอากาศหรือทางเรือครับ","ro":"Sòng thaang aa-kàat rǔe thaang ruea khráp?"},{"fr":"Par avion, c'est plus rapide.","tgt":"ทางอากาศครับ เร็วกว่า","ro":"Thaang aa-kàat khráp, reo kwàa."},{"fr":"Il arrivera dans combien de jours ?","tgt":"กี่วันถึงครับ","ro":"Kìi wan thǔeng khráp?"},{"fr":"Une dizaine de jours environ.","tgt":"ประมาณสิบวันครับ","ro":"Prà-maan sìp wan khráp."},{"fr":"Notez l'adresse sur ce formulaire, s'il vous plaît.","tgt":"กรอกที่อยู่ในใบนี้ด้วยครับ","ro":"Kràwk thîi-yùu nai bai níi dûai khráp."},{"fr":"Je voudrais aussi une enveloppe et des timbres.","tgt":"ขอซองจดหมายกับแสตมป์ด้วยครับ","ro":"Khǎw sawng jòt-mǎai kàp sà-taem dûai khráp."},{"fr":"Ma famille sera contente de recevoir ce colis.","tgt":"ครอบครัวผมคงดีใจที่ได้รับพัสดุนี้","ro":"Khrâwp-khrua phǒm khong dii-jai thîi dâi ráp phát-sà-dù níi."}]},{"title":"Organiser un anniversaire","phrases":[{"fr":"Samedi, c'est l'anniversaire de Fon, ma collègue.","tgt":"วันเสาร์เป็นวันเกิดของฝน เพื่อนร่วมงานผม","ro":"Wan sǎo pen wan-kòet khǎwng Fǒn, phûean rûam ngaan phǒm."},{"fr":"On va lui préparer une surprise.","tgt":"เราจะเตรียมเซอร์ไพรส์ให้เธอ","ro":"Rao jà triam soe-phrái hâi thoe."},{"fr":"Qui va acheter le gâteau ?","tgt":"ใครจะเป็นคนซื้อเค้ก","ro":"Khrai jà pen khon súe khéek?"},{"fr":"Moi ! Je connais une bonne pâtisserie à Nimman.","tgt":"ผมเอง รู้จักร้านเค้กอร่อยแถวนิมมาน","ro":"Phǒm eeng, rúu-jàk ráan khéek à-ràwy thǎew Nim-maan."},{"fr":"On se retrouve au restaurant à dix-neuf heures.","tgt":"เจอกันที่ร้านอาหารตอนหนึ่งทุ่ม","ro":"Joe kan thîi ráan aa-hǎan tawn nùeng thûm."},{"fr":"Il faut réserver une grande table.","tgt":"ต้องจองโต๊ะใหญ่","ro":"Tâwng jawng tó yài."},{"fr":"Chacun met deux cents bahts pour le cadeau.","tgt":"ทุกคนลงเงินคนละสองร้อยบาทสำหรับของขวัญ","ro":"Thúk khon long ngoen khon lá sǎwng ráwy bàat sǎm-ràp khǎwng-khwǎn."},{"fr":"Joyeux anniversaire, Fon !","tgt":"สุขสันต์วันเกิดนะฝน","ro":"Sùk-sǎn wan-kòet ná Fǒn!"},{"fr":"Merci à tous, je suis vraiment touchée.","tgt":"ขอบคุณทุกคนมากนะคะ ฉันซึ้งใจจริงๆ","ro":"Khàwp-khun thúk khon mâak ná khá, chǎn sûeng-jai jing jing."},{"fr":"On s'est vraiment bien amusés ce soir.","tgt":"คืนนี้สนุกมากเลย","ro":"Khuen níi sà-nùk mâak loei."}]},{"title":"Le règlement de la résidence","phrases":[{"fr":"Le gardien m'a expliqué le règlement de la résidence.","tgt":"พี่ยามอธิบายกฎของคอนโดให้ผมฟัง","ro":"Phîi yaam à-thí-baai kòt khǎwng khawn-doo hâi phǒm fang."},{"fr":"Ne fumez pas dans les couloirs.","tgt":"อย่าสูบบุหรี่ที่ทางเดินนะครับ","ro":"Yàa sùup bù-rìi thîi thaang-doen ná khráp."},{"fr":"Ne garez pas votre scooter devant l'entrée.","tgt":"อย่าจอดมอเตอร์ไซค์หน้าทางเข้านะครับ","ro":"Yàa jàwt maw-toe-sai nâa thaang khâo ná khráp."},{"fr":"Et ne faites pas de bruit après vingt-deux heures.","tgt":"แล้วก็อย่าส่งเสียงดังหลังสี่ทุ่มนะครับ","ro":"Láew kâw yàa sòng sǐang dang lǎng sìi thûm ná khráp."},{"fr":"Les animaux sont-ils acceptés ?","tgt":"เลี้ยงสัตว์ได้ไหมครับ","ro":"Líang sàt dâi mái khráp?"},{"fr":"Non, c'est interdit dans tout l'immeuble.","tgt":"ไม่ได้ครับ ห้ามทั้งตึก","ro":"Mâi dâi khráp, hâam tháng tùek."},{"fr":"N'oublie pas ta carte magnétique, sinon tu restes dehors.","tgt":"อย่าลืมพกคีย์การ์ดนะ ไม่งั้นเข้าตึกไม่ได้","ro":"Yàa luem phók khii-káat ná, mâi-ngán khâo tùek mâi dâi."},{"fr":"Ne laissez pas les sacs poubelle devant votre porte.","tgt":"อย่าวางถุงขยะไว้หน้าห้องนะครับ","ro":"Yàa waang thǔng khà-yà wái nâa hâwng ná khráp."},{"fr":"Il faut les descendre au local à poubelles.","tgt":"ต้องเอาไปทิ้งที่ห้องขยะข้างล่างครับ","ro":"Tâwng ao pai thíng thîi hâwng khà-yà khâang lâang khráp."},{"fr":"Ne vous inquiétez pas, je respecterai toutes les règles.","tgt":"อย่าห่วงเลยครับ ผมจะทำตามกฎทุกข้อ","ro":"Yàa hùang loei khráp, phǒm jà tham taam kòt thúk khâw."}],"tip":{"title":"« Yàa » : l'interdiction","example":"Ne fumez pas dans les couloirs. — <b>อย่า</b>สูบบุหรี่ที่ทางเดินนะครับ","body":"Pour demander à quelqu'un de ne pas faire quelque chose, on place « yàa » tout au début de la phrase, juste devant le verbe. « Yàa sùup bù-rìi », c'est ne fumez pas, mot à mot ne pas, fumer, cigarette. On adoucit presque toujours la phrase avec « ná » à la fin, suivi de « khráp » ou « khâ », pour rester aimable. Deux formules reviennent sans cesse : « yàa luem », n'oublie pas, et « yàa hùang », ne t'inquiète pas. Sur les panneaux et dans les règlements, on entend plutôt « hâam », interdit, qui sonne plus officiel. Retenez : « yàa » pour conseiller ou demander gentiment, « hâam » pour la règle stricte.","exampleRo":"Yàa sùup bù-rìi thîi thaang-doen ná khráp.","lit":"ne pas (interdiction) · fumer · cigarette · à · couloir · [douceur] · [politesse]","say":{"Yàa":"อย่า","yàa":"อย่า","Yàa sùup bù-rìi":"อย่าสูบบุหรี่","ná":"นะ","khráp":"ครับ","khâ":"ค่ะ","yàa luem":"อย่าลืม","yàa hùang":"อย่าห่วง","hâam":"ห้าม"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Dans ce module, j'ai appris à parler de ma vie de tous les jours.","tgt":"ในบทนี้ผมได้เรียนพูดเรื่องชีวิตประจำวัน","ro":"Nai bòt níi phǒm dâi rian phûut rûeang chii-wít prà-jam wan."},{"fr":"Maintenant, je sais parler du futur avec « jà ».","tgt":"ตอนนี้ผมใช้คำว่า จะ พูดถึงอนาคตได้แล้ว","ro":"Tawn-níi phǒm chái kham wâa \"jà\" phûut thǔeng à-naa-khót dâi láew."},{"fr":"Je peux dire ce que j'ai déjà fait et ce qui reste à faire.","tgt":"ผมบอกได้ว่าอะไรทำแล้ว อะไรยังไม่ได้ทำ","ro":"Phǒm bàwk dâi wâa à-rai tham láew, à-rai yang mâi dâi tham."},{"fr":"Je sais expliquer mes symptômes au médecin.","tgt":"ผมอธิบายอาการให้หมอฟังได้","ro":"Phǒm à-thí-baai aa-kaan hâi mǎw fang dâi."},{"fr":"Je peux faire réparer mon scooter sans aide.","tgt":"ผมเอามอเตอร์ไซค์ไปให้ช่างซ่อมเองได้","ro":"Phǒm ao maw-toe-sai pai hâi châang sâwm eeng dâi."},{"fr":"Le thaï me semble moins difficile qu'au début.","tgt":"ภาษาไทยดูไม่ยากเท่าตอนแรก","ro":"Phaa-sǎa thai duu mâi yâak thâo tawn râek."},{"fr":"Les tons demandent encore beaucoup d'entraînement.","tgt":"วรรณยุกต์ยังต้องฝึกอีกเยอะ","ro":"Wan-ná-yúk yang tâwng fùek ìik yóe."},{"fr":"Je discute avec mes voisins tous les jours.","tgt":"ผมคุยกับเพื่อนบ้านทุกวัน","ro":"Phǒm khui kàp phûean-bâan thúk wan."},{"fr":"Ils me corrigent avec beaucoup de patience.","tgt":"เขาช่วยแก้ให้ผมอย่างใจเย็น","ro":"Kháo chûai kâe hâi phǒm yàang jai-yen."},{"fr":"Je suis prêt pour le module suivant !","tgt":"ผมพร้อมสำหรับบทต่อไปแล้ว","ro":"Phǒm phráwm sǎm-ràp bòt tàw pai láew!"}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Phuket","phrases":[{"fr":"Notre avion vient d'atterrir à Phuket.","tgt":"เครื่องบินของเราเพิ่งลงที่ภูเก็ต","ro":"Khrûeang-bin khǎwng rao phôeng long thîi Phuu-kèt."},{"fr":"Il fait beaucoup plus chaud qu'à Bangkok.","tgt":"ที่นี่ร้อนกว่ากรุงเทพมาก","ro":"Thîi-nîi ráwn kwàa Krung-thêep mâak."},{"fr":"Comment va-t-on jusqu'à notre hôtel ?","tgt":"เราจะไปโรงแรมยังไงดี","ro":"Rao jà pai roong-raem yang-ngai dii?"},{"fr":"Il y a un minibus qui part toutes les heures.","tgt":"มีรถตู้ออกทุกชั่วโมง","ro":"Mii rót-tûu àwk thúk chûa-moong."},{"fr":"Le trajet dure environ une heure.","tgt":"ใช้เวลาประมาณหนึ่งชั่วโมง","ro":"Chái wee-laa prà-maan nùeng chûa-moong."},{"fr":"On a réservé une chambre près de la plage de Kata.","tgt":"เราจองห้องใกล้หาดกะตะไว้","ro":"Rao jawng hâwng klâi hàat Kà-tà wái."},{"fr":"Je voudrais changer un peu d'argent ici.","tgt":"ผมอยากแลกเงินที่นี่นิดหน่อยครับ","ro":"Phǒm yàak lâek ngoen thîi-nîi nít-nàwy khráp."},{"fr":"La mer est juste de l'autre côté de la route.","tgt":"ทะเลอยู่ฝั่งตรงข้ามถนนนี่เอง","ro":"Thá-lee yùu fàng trong-khâam thà-nǒn nîi eeng."},{"fr":"Allons d'abord nous reposer un peu.","tgt":"ไปพักผ่อนก่อนสักหน่อยเถอะ","ro":"Pai phák-phàwn kàwn sàk nàwy thòe."},{"fr":"Nos vacances dans le sud commencent enfin.","tgt":"ในที่สุดวันหยุดของเราที่ภาคใต้ก็เริ่มแล้ว","ro":"Nai thîi-sùt wan-yùt khǎwng rao thîi phâak-tâi kâw rôem láew."}]},{"title":"Une journée à la plage de Kata","phrases":[{"fr":"Le sable est blanc et très fin.","tgt":"ทรายขาวและละเอียดมาก","ro":"Saai khǎao láe lá-ìat mâak."},{"fr":"On loue deux transats pour la journée.","tgt":"เราเช่าเก้าอี้ชายหาดสองตัวทั้งวัน","ro":"Rao châo kâo-îi chaai-hàat sǎwng tua tháng wan."},{"fr":"Combien coûte un parasol ?","tgt":"ร่มกันแดดคันละเท่าไรครับ","ro":"Rôm kan-dàet khan lá thâo-rai khráp?"},{"fr":"Cent bahts pour toute la journée.","tgt":"ทั้งวันหนึ่งร้อยบาทครับ","ro":"Tháng wan nùeng rói bàat khráp."},{"fr":"N'oublie pas de mettre de la crème solaire.","tgt":"อย่าลืมทาครีมกันแดดนะ","ro":"Yàa luem thaa khriim kan-dàet ná."},{"fr":"Le soleil tape vraiment fort à midi.","tgt":"ตอนเที่ยงแดดแรงมากจริงๆ","ro":"Tawn thîang dàet raeng mâak jing-jing."},{"fr":"L'eau est chaude comme dans une baignoire.","tgt":"น้ำทะเลอุ่นเหมือนน้ำในอ่างอาบน้ำ","ro":"Nám thá-lee ùn mǔean náam nai àang àap-náam."},{"fr":"Fais attention, il y a un drapeau rouge.","tgt":"ระวังนะ มีธงแดงปักอยู่","ro":"Rá-wang ná, mii thong daeng pàk yùu."},{"fr":"Les courants sont dangereux aujourd'hui.","tgt":"วันนี้กระแสน้ำอันตราย","ro":"Wan-níi krà-sǎe náam an-tà-raai."},{"fr":"On regardera le coucher de soleil depuis la plage.","tgt":"เราจะดูพระอาทิตย์ตกจากชายหาด","ro":"Rao jà duu phrá-aa-thít tòk jàak chaai-hàat."}]},{"title":"Le ferry pour Ko Phi Phi","phrases":[{"fr":"Le ferry pour Ko Phi Phi part à quelle heure ?","tgt":"เรือไปเกาะพีพีออกกี่โมงครับ","ro":"Ruea pai Kàw Phii-phii àwk kìi moong khráp?"},{"fr":"S'il y a de la place, on prend celui de neuf heures.","tgt":"ถ้ามีที่ เราก็ขึ้นลำเก้าโมง","ro":"Thâa mii thîi, rao kâw khûen lam kâo moong."},{"fr":"Si la mer est agitée, on prendra des cachets contre le mal de mer.","tgt":"ถ้าคลื่นแรง เราก็จะกินยาแก้เมาเรือ","ro":"Thâa khlûen raeng, rao kâw jà kin yaa kâe mao ruea."},{"fr":"Si tu as le mal de mer, regarde l'horizon.","tgt":"ถ้าเมาเรือ ก็มองไปที่ขอบฟ้านะ","ro":"Thâa mao ruea, kâw mawng pai thîi khàwp-fáa ná."},{"fr":"Le billet coûte six cents bahts par personne.","tgt":"ตั๋วราคาคนละหกร้อยบาท","ro":"Tǔa raa-khaa khon lá hòk rói bàat."},{"fr":"Si on achète l'aller-retour, c'est moins cher.","tgt":"ถ้าซื้อไปกลับ ก็ถูกกว่า","ro":"Thâa súe pai-klàp, kâw thùuk kwàa."},{"fr":"On peut mettre nos sacs sur le pont.","tgt":"เราวางกระเป๋าไว้บนดาดฟ้าเรือได้","ro":"Rao waang krà-pǎo wái bon dàat-fáa ruea dâai."},{"fr":"Si tu as froid, il y a des places à l'intérieur.","tgt":"ถ้าหนาว ก็มีที่นั่งข้างในนะ","ro":"Thâa nǎao, kâw mii thîi-nâng khâang-nai ná."},{"fr":"La traversée dure à peu près deux heures.","tgt":"ใช้เวลาข้ามทะเลประมาณสองชั่วโมง","ro":"Chái wee-laa khâam thá-lee prà-maan sǎwng chûa-moong."},{"fr":"Si on arrive tôt, la plage sera encore calme.","tgt":"ถ้าไปถึงเช้า ชายหาดก็จะยังเงียบอยู่","ro":"Thâa pai thǔeng cháo, chaai-hàat kâw jà yang ngîap yùu."}],"tip":{"title":"« Thâa... kâw... » : si... alors...","example":"S'il y a de la place, on prend celui de neuf heures. — <b>ถ้า</b>มีที่ เรา<b>ก็</b>ขึ้นลำเก้าโมง","body":"Pour dire « si », on commence la phrase par « thâa », avec un ton descendant, puis on place « kâw » juste avant le verbe de la deuxième partie, comme un petit « alors ». Dans « thâa mii thîi, rao kâw khûen lam kâo moong », on a mot à mot : si, avoir place, nous, alors, monter, le bateau de neuf heures. Contrairement au français, rien ne change dans les verbes : pas de conditionnel, pas d'imparfait à choisir. Écoutez aussi « thâa nǎao, kâw mii thîi-nâng khâang-nai », s'il fait froid, il y a des places dedans, et « thâa súe pai-klàp, kâw thùuk kwàa », si on achète l'aller-retour, c'est moins cher. Retenez l'image d'un pont : « thâa » ouvre la condition, « kâw » fait passer à la conséquence.","exampleRo":"Thâa mii thîi, rao kâw khûen lam kâo moong.","lit":"si · avoir · place · nous · alors · monter · [classificateur] · neuf heures","say":{"Thâa... kâw...":"ถ้า ก็","thâa":"ถ้า","kâw":"ก็","thâa mii thîi, rao kâw khûen lam kâo moong":"ถ้ามีที่ เราก็ขึ้นลำเก้าโมง","thâa nǎao, kâw mii thîi-nâng khâang-nai":"ถ้าหนาว ก็มีที่นั่งข้างใน","thâa súe pai-klàp, kâw thùuk kwàa":"ถ้าซื้อไปกลับ ก็ถูกกว่า"}}},{"title":"Ko Phi Phi et la baie de Maya","phrases":[{"fr":"Ko Phi Phi est encore plus belle qu'en photo.","tgt":"เกาะพีพีสวยกว่าในรูปอีก","ro":"Kàw Phii-phii sǔai kwàa nai rûup ìik."},{"fr":"L'eau est si claire qu'on voit le fond.","tgt":"น้ำใสจนมองเห็นพื้นทราย","ro":"Náam sǎi jon mawng hěn phúen saai."},{"fr":"On prend un bateau à longue queue pour la baie de Maya.","tgt":"เรานั่งเรือหางยาวไปอ่าวมาหยา","ro":"Rao nâng ruea hǎang-yaao pai Àao Maa-yǎa."},{"fr":"On n'a plus le droit de se baigner dans cette baie.","tgt":"ตอนนี้ห้ามว่ายน้ำในอ่าวนี้แล้ว","ro":"Tawn-níi hâam wâai-náam nai àao níi láew."},{"fr":"Ils protègent les coraux et les requins.","tgt":"เขาอนุรักษ์ปะการังกับฉลาม","ro":"Khǎo à-nú-rák pà-kaa-rang kàp chà-lǎam."},{"fr":"Il y a trop de touristes à midi.","tgt":"ตอนเที่ยงนักท่องเที่ยวเยอะเกินไป","ro":"Tawn thîang nák-thâwng-thîao yóe koen pai."},{"fr":"Montons au point de vue avant le coucher du soleil.","tgt":"ขึ้นไปจุดชมวิวก่อนพระอาทิตย์ตกกันเถอะ","ro":"Khûen pai jùt chom wiu kàwn phrá-aa-thít tòk kan thòe."},{"fr":"Emporte de l'eau, la montée est fatigante.","tgt":"เอาน้ำไปด้วยนะ ทางขึ้นเหนื่อยมาก","ro":"Ao náam pai dûai ná, thaang khûen nùeai mâak."},{"fr":"D'en haut, on voit les deux baies.","tgt":"จากข้างบนมองเห็นอ่าวทั้งสองฝั่ง","ro":"Jàak khâang-bon mawng hěn àao tháng sǎwng fàng."},{"fr":"Je n'oublierai jamais cette vue.","tgt":"ผมจะไม่มีวันลืมวิวนี้","ro":"Phǒm jà mâi mii wan luem wiu níi."}]},{"title":"Louer un scooter à Ko Samui","phrases":[{"fr":"Je voudrais louer un scooter pour trois jours.","tgt":"ผมอยากเช่ามอเตอร์ไซค์สามวันครับ","ro":"Phǒm yàak châo maw-toe-sai sǎam wan khráp."},{"fr":"C'est deux cent cinquante bahts par jour.","tgt":"วันละสองร้อยห้าสิบบาทครับ","ro":"Wan lá sǎwng rói hâa sìp bàat khráp."},{"fr":"Je laisse une caution de mille bahts.","tgt":"ผมวางมัดจำหนึ่งพันบาท","ro":"Phǒm waang mát-jam nùeng phan bàat."},{"fr":"Le loueur est sur le point de fermer.","tgt":"ร้านเช่ากำลังจะปิด","ro":"Ráan châo kam-lang jà pìt."},{"fr":"Je suis sur le point de partir, où est le casque ?","tgt":"ผมกำลังจะออกไปแล้ว หมวกกันน็อกอยู่ไหนครับ","ro":"Phǒm kam-lang jà àwk pai láew, mùak-kan-nók yùu nǎi khráp?"},{"fr":"On est sur le point de tomber en panne d'essence.","tgt":"น้ำมันกำลังจะหมด","ro":"Nám-man kam-lang jà mòt."},{"fr":"Il y a une station-service juste devant.","tgt":"มีปั๊มน้ำมันอยู่ข้างหน้านี่เอง","ro":"Mii pám nám-man yùu khâang-nâa nîi eeng."},{"fr":"Il va pleuvoir d'un instant à l'autre, rentrons vite.","tgt":"ฝนกำลังจะตก รีบกลับกันเถอะ","ro":"Fǒn kam-lang jà tòk, rîip klàp kan thòe."},{"fr":"On est sur le point d'arriver à la cascade de Na Muang.","tgt":"เรากำลังจะถึงน้ำตกหน้าเมืองแล้ว","ro":"Rao kam-lang jà thǔeng nám-tòk Nâa Mueang láew."},{"fr":"Roule doucement, la route est glissante.","tgt":"ขับช้าๆ นะ ถนนลื่น","ro":"Khàp cháa-cháa ná, thà-nǒn lûen."}],"tip":{"title":"« Kam-lang jà » : être sur le point de","example":"Il va pleuvoir d'un instant à l'autre, rentrons vite. — ฝน<b>กำลังจะ</b>ตก รีบกลับกันเถอะ","body":"Vous connaissez déjà « jà », qui annonce le futur, et « kam-lang », qui veut dire « en train de ». En les collant, « kam-lang jà » devant un verbe signifie que l'action va arriver dans un instant, comme « être sur le point de ». Décomposons « fǒn kam-lang jà tòk » : pluie, en train de, futur, tomber, autrement dit il va pleuvoir d'une minute à l'autre. De même, « ráan châo kam-lang jà pìt », le loueur va fermer, et « rao kam-lang jà thǔeng », on est presque arrivés. On ajoute souvent « láew » à la fin pour insister, comme dans « phǒm kam-lang jà àwk pai láew », je pars, là. Pour retenir, pensez au compte à rebours : « kam-lang jà », c'est le moment juste avant le zéro.","exampleRo":"Fǒn kam-lang jà tòk, rîip klàp kan thòe.","lit":"pluie · en train de · [futur] · tomber · se dépêcher · rentrer · ensemble · [incitation]","say":{"Kam-lang jà":"กำลังจะ","jà":"จะ","kam-lang":"กำลัง","kam-lang jà":"กำลังจะ","fǒn kam-lang jà tòk":"ฝนกำลังจะตก","ráan châo kam-lang jà pìt":"ร้านเช่ากำลังจะปิด","rao kam-lang jà thǔeng":"เรากำลังจะถึง","láew":"แล้ว","phǒm kam-lang jà àwk pai láew":"ผมกำลังจะออกไปแล้ว"}}},{"title":"Sur les routes de Ko Samui","phrases":[{"fr":"On fait le tour de l'île en une journée.","tgt":"เราขับรอบเกาะในหนึ่งวัน","ro":"Rao khàp râwp kàw nai nùeng wan."},{"fr":"La route côtière est magnifique.","tgt":"ถนนเลียบชายฝั่งสวยมาก","ro":"Thà-nǒn lîap chaai-fàng sǔai mâak."},{"fr":"Arrêtons-nous pour boire une noix de coco.","tgt":"แวะกินน้ำมะพร้าวกันเถอะ","ro":"Wáe kin nám-má-phráao kan thòe."},{"fr":"Il y a des cocotiers partout sur l'île.","tgt":"บนเกาะมีต้นมะพร้าวเต็มไปหมด","ro":"Bon kàw mii tôn má-phráao tem pai mòt."},{"fr":"Cette montée est vraiment raide.","tgt":"ทางขึ้นเขานี้ชันมากจริงๆ","ro":"Thaang khûen khǎo níi chan mâak jing-jing."},{"fr":"Attention aux chiens sur la route.","tgt":"ระวังหมาบนถนนด้วยนะ","ro":"Rá-wang mǎa bon thà-nǒn dûai ná."},{"fr":"On s'est perdus, demandons notre chemin.","tgt":"เราหลงทางแล้ว ถามทางกันเถอะ","ro":"Rao lǒng thaang láew, thǎam thaang kan thòe."},{"fr":"Excusez-moi, la plage de Lamai, c'est par où ?","tgt":"ขอโทษครับ หาดละไมไปทางไหนครับ","ro":"Khǎw-thôot khráp, hàat Lá-mai pai thaang nǎi khráp?"},{"fr":"Tout droit, puis à gauche au feu.","tgt":"ตรงไป แล้วเลี้ยวซ้ายที่ไฟแดง","ro":"Trong pai, láew líao sáai thîi fai-daeng."},{"fr":"Le scooter, c'est le meilleur moyen de découvrir l'île.","tgt":"ขี่มอเตอร์ไซค์เป็นวิธีที่ดีที่สุดในการเที่ยวเกาะ","ro":"Khìi maw-toe-sai pen wí-thii thîi dii thîi-sùt nai kaan thîao kàw."}]},{"title":"Krabi et les falaises de Railay","phrases":[{"fr":"Railay n'est accessible qu'en bateau.","tgt":"ไปไร่เลย์ได้ทางเรือเท่านั้น","ro":"Pai Râi-lee dâai thaang ruea thâo-nán."},{"fr":"Le bateau part de la plage d'Ao Nang.","tgt":"เรือออกจากหาดอ่าวนาง","ro":"Ruea àwk jàak hàat Àao Naang."},{"fr":"En descendant du bateau, on a de l'eau jusqu'aux genoux.","tgt":"ลงจากเรือแล้วน้ำสูงถึงเข่า","ro":"Long jàak ruea láew náam sǔung thǔeng khào."},{"fr":"Ces falaises de calcaire sont immenses.","tgt":"หน้าผาหินปูนพวกนี้ใหญ่มาก","ro":"Nâa-phǎa hǐn-puun phûak-níi yài mâak."},{"fr":"Beaucoup de gens viennent ici pour l'escalade.","tgt":"หลายคนมาที่นี่เพื่อปีนผา","ro":"Lǎai khon maa thîi-nîi phûea piin phǎa."},{"fr":"Je n'ai jamais grimpé de ma vie.","tgt":"ผมไม่เคยปีนผามาก่อนเลย","ro":"Phǒm mâi khoei piin phǎa maa kàwn loei."},{"fr":"Il y a un cours pour débutants le matin.","tgt":"ตอนเช้ามีคอร์สสำหรับมือใหม่","ro":"Tawn cháo mii khâwt sǎm-ràp mue-mài."},{"fr":"Le moniteur vérifie la corde deux fois.","tgt":"ครูฝึกเช็กเชือกสองรอบ","ro":"Khruu-fùek chék chûeak sǎwng râwp."},{"fr":"Les singes volent la nourriture des touristes.","tgt":"ลิงชอบขโมยอาหารนักท่องเที่ยว","ro":"Ling châwp khà-mooi aa-hǎan nák-thâwng-thîao."},{"fr":"Le soir, la plage devient toute rose.","tgt":"ตอนเย็นชายหาดกลายเป็นสีชมพู","ro":"Tawn yen chaai-hàat klaai pen sǐi chom-phuu."}]},{"title":"Un baptême de plongée à Ko Tao","phrases":[{"fr":"Ko Tao est célèbre pour la plongée.","tgt":"เกาะเต่ามีชื่อเรื่องการดำน้ำ","ro":"Kàw Tào mii chûe rûeang kaan dam-náam."},{"fr":"Il faut d'abord remplir ce formulaire.","tgt":"ต้องกรอกแบบฟอร์มนี้ก่อนครับ","ro":"Tâwng kràwk bàep-fawm níi kàwn khráp."},{"fr":"Vous devez savoir nager un peu.","tgt":"คุณต้องว่ายน้ำเป็นนิดหน่อย","ro":"Khun tâwng wâai-náam pen nít-nàwy."},{"fr":"Est-ce que je dois avoir un certificat médical ?","tgt":"ผมต้องมีใบรับรองแพทย์ไหมครับ","ro":"Phǒm tâwng mii bai ráp-rawng phâet mái khráp?"},{"fr":"Non, mais il faut nous dire si vous avez de l'asthme.","tgt":"ไม่ต้องครับ แต่ต้องบอกถ้าเป็นหอบหืด","ro":"Mâi tâwng khráp, tàe tâwng bàwk thâa pen hàwp-hùet."},{"fr":"On doit toujours plonger à deux.","tgt":"ต้องดำน้ำเป็นคู่เสมอ","ro":"Tâwng dam-náam pen khûu sà-mǒe."},{"fr":"Il faut respirer tout le temps.","tgt":"ต้องหายใจตลอดเวลา","ro":"Tâwng hǎai-jai tà-làwt wee-laa."},{"fr":"Je dois apprendre à vider l'eau de mon masque.","tgt":"ผมต้องฝึกเอาน้ำออกจากหน้ากาก","ro":"Phǒm tâwng fùek ao náam àwk jàak nâa-kàak."},{"fr":"On descend jusqu'à douze mètres.","tgt":"เราจะดำลงไปถึงสิบสองเมตร","ro":"Rao jà dam long pai thǔeng sìp-sǎwng méet."},{"fr":"Pas besoin de stresser, le moniteur reste à côté.","tgt":"ไม่ต้องเครียดนะ ครูอยู่ข้างๆ ตลอด","ro":"Mâi tâwng khrîat ná, khruu yùu khâang-khâang tà-làwt."}],"tip":{"title":"« Tâwng » : devoir, il faut","example":"On doit toujours plonger à deux. — <b>ต้อง</b>ดำน้ำเป็นคู่เสมอ","body":"« Tâwng », au ton descendant, se place simplement devant le verbe pour exprimer l'obligation : c'est à la fois « devoir » et « il faut ». Il ne change jamais, que ce soit je dois, tu dois ou on doit, et on peut même l'employer sans sujet quand la règle vaut pour tout le monde. Dans « tâwng dam-náam pen khûu sà-mǒe », on a : devoir, plonger, comme une paire, toujours. Attention au négatif : « mâi tâwng » ne veut pas dire « il ne faut pas », mais « pas besoin », comme dans « mâi tâwng khrîat », pas besoin de stresser. Pour une vraie interdiction, on dit plutôt « hâam », interdit, ou « yàa », ne fais pas. Astuce : « tâwng » sonne comme un coup de gong, celui de la règle à respecter.","exampleRo":"Tâwng dam-náam pen khûu sà-mǒe.","lit":"devoir · plonger · être · paire · toujours","say":{"Tâwng":"ต้อง","tâwng dam-náam pen khûu sà-mǒe":"ต้องดำน้ำเป็นคู่เสมอ","mâi tâwng":"ไม่ต้อง","mâi tâwng khrîat":"ไม่ต้องเครียด","hâam":"ห้าม","yàa":"อย่า","tâwng":"ต้อง"}}},{"title":"Sous l'eau à Ko Tao","phrases":[{"fr":"J'ai vu une tortue sous l'eau !","tgt":"ผมเห็นเต่าทะเลใต้น้ำด้วย","ro":"Phǒm hěn tào thá-lee tâi náam dûai!"},{"fr":"Les coraux sont de toutes les couleurs.","tgt":"ปะการังมีหลายสีมาก","ro":"Pà-kaa-rang mii lǎai sǐi mâak."},{"fr":"Un banc de poissons est passé juste devant nous.","tgt":"ฝูงปลาว่ายผ่านหน้าเราไป","ro":"Fǔung plaa wâai phàan nâa rao pai."},{"fr":"Il y avait un petit requin près du rocher.","tgt":"มีฉลามตัวเล็กอยู่ใกล้ก้อนหิน","ro":"Mii chà-lǎam tua lék yùu klâi kâwn hǐn."},{"fr":"Ne touche pas aux coraux, ils sont fragiles.","tgt":"อย่าจับปะการังนะ มันเปราะบาง","ro":"Yàa jàp pà-kaa-rang ná, man pràw-baang."},{"fr":"Mes oreilles me font un peu mal.","tgt":"หูผมเจ็บนิดหน่อย","ro":"Hǔu phǒm jèp nít-nàwy."},{"fr":"Pince-toi le nez et souffle doucement.","tgt":"บีบจมูกแล้วเป่าเบาๆ","ro":"Bìip jà-mùuk láew pào bao-bao."},{"fr":"Le moniteur nous fait signe de remonter.","tgt":"ครูส่งสัญญาณให้ขึ้นแล้ว","ro":"Khruu sòng sǎn-yaan hâi khûen láew."},{"fr":"J'aimerais passer mon brevet de plongée ici.","tgt":"ผมอยากเรียนเอาใบอนุญาตดำน้ำที่นี่","ro":"Phǒm yàak rian ao bai à-nú-yâat dam-náam thîi-nîi."},{"fr":"C'était l'expérience la plus incroyable du voyage.","tgt":"เป็นประสบการณ์ที่สุดยอดที่สุดของทริปนี้","ro":"Pen prà-sòp-kaan thîi sùt-yâwt thîi-sùt khǎwng tríp níi."}]},{"title":"Une nuit en bungalow","phrases":[{"fr":"Notre bungalow est au bord de la plage.","tgt":"บังกะโลของเราอยู่ริมหาด","ro":"Bang-kà-loo khǎwng rao yùu rim hàat."},{"fr":"Il y a une moustiquaire au-dessus du lit.","tgt":"มีมุ้งอยู่เหนือเตียง","ro":"Mii múng yùu nǔea tiang."},{"fr":"Le ventilateur fait un bruit bizarre.","tgt":"พัดลมเสียงแปลกๆ","ro":"Phát-lom sǐang plàek-plàek."},{"fr":"Est-ce que l'électricité est coupée la nuit ?","tgt":"กลางคืนไฟดับไหมครับ","ro":"Klaang-khuen fai dàp mái khráp?"},{"fr":"Oui, de minuit à six heures du matin.","tgt":"ครับ ตั้งแต่เที่ยงคืนถึงหกโมงเช้า","ro":"Khráp, tâng-tàe thîang-khuen thǔeng hòk moong cháo."},{"fr":"On entend les vagues toute la nuit.","tgt":"ได้ยินเสียงคลื่นทั้งคืน","ro":"Dâi-yin sǐang khlûen tháng khuen."},{"fr":"Il y a un gecko au plafond.","tgt":"มีตุ๊กแกอยู่บนเพดาน","ro":"Mii túk-kae yùu bon phee-daan."},{"fr":"Ne t'inquiète pas, il mange les moustiques.","tgt":"ไม่ต้องห่วง มันกินยุง","ro":"Mâi tâwng hùang, man kin yung."},{"fr":"L'eau de la douche est un peu froide.","tgt":"น้ำฝักบัวเย็นไปหน่อย","ro":"Náam fàk-bua yen pai nàwy."},{"fr":"Le matin, le petit-déjeuner est servi sur la terrasse.","tgt":"ตอนเช้ามีอาหารเช้าที่ระเบียง","ro":"Tawn cháo mii aa-hǎan cháo thîi rá-biang."}]},{"title":"Le marché de nuit de Krabi","phrases":[{"fr":"Le marché de nuit ouvre à six heures du soir.","tgt":"ตลาดกลางคืนเปิดหกโมงเย็น","ro":"Tà-làat klaang-khuen pòet hòk moong yen."},{"fr":"Ça sent bon le poisson grillé.","tgt":"กลิ่นปลาย่างหอมมาก","ro":"Klìn plaa yâang hǎwm mâak."},{"fr":"Je voudrais goûter le curry du sud.","tgt":"ผมอยากลองแกงปักษ์ใต้","ro":"Phǒm yàak lawng kaeng pàk-tâi."},{"fr":"Attention, c'est très épicé !","tgt":"ระวังนะ เผ็ดมาก","ro":"Rá-wang ná, phèt mâak!"},{"fr":"Pas trop pimenté pour moi, s'il vous plaît.","tgt":"ไม่เอาเผ็ดมากนะครับ","ro":"Mâi ao phèt mâak ná khráp."},{"fr":"Ces crevettes ont été pêchées ce matin.","tgt":"กุ้งพวกนี้เพิ่งจับมาเมื่อเช้า","ro":"Kûng phûak-níi phôeng jàp maa mûea-cháo."},{"fr":"Deux jus de mangue mixés, s'il vous plaît.","tgt":"เอาน้ำมะม่วงปั่นสองแก้วครับ","ro":"Ao nám má-mûang pàn sǎwng kâew khráp."},{"fr":"Vous pouvez faire un petit prix ?","tgt":"ลดหน่อยได้ไหมครับ","ro":"Lót nàwy dâai mái khráp?"},{"fr":"Trois t-shirts pour cinq cents bahts, ça vous va ?","tgt":"สามตัวห้าร้อยบาทได้ไหมครับ","ro":"Sǎam tua hâa rói bàat dâai mái khráp?"},{"fr":"Un groupe joue de la musique au bout du marché.","tgt":"มีวงดนตรีเล่นอยู่สุดตลาด","ro":"Mii wong don-trii lên yùu sùt tà-làat."}]},{"title":"Arrivée au parc de Khao Sok","phrases":[{"fr":"Quand on est arrivés à Khao Sok, il pleuvait.","tgt":"เมื่อเรามาถึงเขาสก ฝนกำลังตก","ro":"Mûea rao maa thǔeng Khǎo Sòk, fǒn kam-lang tòk."},{"fr":"Quand le bus s'arrête, on descend tout de suite.","tgt":"เมื่อรถจอด เราก็ลงเลย","ro":"Mûea rót jàwt, rao kâw long loei."},{"fr":"Cette forêt est l'une des plus anciennes du monde.","tgt":"ป่าที่นี่เป็นป่าที่เก่าแก่ที่สุดแห่งหนึ่งของโลก","ro":"Pàa thîi-nîi pen pàa thîi kào-kàe thîi-sùt hàeng nùeng khǎwng lôok."},{"fr":"L'entrée du parc coûte trois cents bahts.","tgt":"ค่าเข้าอุทยานสามร้อยบาท","ro":"Khâa khâo ùt-thá-yaan sǎam rói bàat."},{"fr":"Quand tu as acheté le billet, garde-le bien.","tgt":"เมื่อซื้อตั๋วแล้ว เก็บไว้ดีๆ นะ","ro":"Mûea súe tǔa láew, kèp wái dii-dii ná."},{"fr":"On dort dans une cabane dans les arbres.","tgt":"เรานอนในบ้านต้นไม้","ro":"Rao nawn nai bâan tôn-mái."},{"fr":"Quand la nuit tombe, la forêt devient très bruyante.","tgt":"เมื่อถึงกลางคืน ป่าจะเสียงดังมาก","ro":"Mûea thǔeng klaang-khuen, pàa jà sǐang dang mâak."},{"fr":"Ce sont des grillons et des grenouilles.","tgt":"เป็นเสียงจิ้งหรีดกับกบ","ro":"Pen sǐang jîng-rìit kàp kòp."},{"fr":"Quand j'étais petit, j'avais peur de la forêt.","tgt":"เมื่อผมยังเด็ก ผมกลัวป่ามาก","ro":"Mûea phǒm yang dèk, phǒm klua pàa mâak."},{"fr":"Le guide passera nous chercher à sept heures.","tgt":"ไกด์จะมารับเราตอนเจ็ดโมง","ro":"Kái jà maa ráp rao tawn jèt moong."}],"tip":{"title":"« Mûea » : quand","example":"Quand le bus s'arrête, on descend tout de suite. — <b>เมื่อ</b>รถจอด เราก็ลงเลย","body":"Pour situer une action dans le temps, on ouvre la phrase avec « mûea », au ton descendant, qui veut dire « quand » ou « lorsque ». Comme avec « thâa », on peut ajouter « kâw » dans la deuxième partie pour bien lier les deux idées. Dans « mûea rót jàwt, rao kâw long loei », on a : quand, véhicule, s'arrêter, nous, alors, descendre, tout de suite. Le thaï ne marque pas le passé dans le verbe, donc « mûea rao maa thǔeng Khǎo Sòk » peut vouloir dire quand nous sommes arrivés ou quand nous arrivons : c'est le contexte qui décide. Dans la conversation, on entend aussi « tawn », plus familier, mais « mûea » reste très courant. Astuce : la question « mûea-rai ? », quand ?, contient le même mot.","exampleRo":"Mûea rót jàwt, rao kâw long loei.","lit":"quand · véhicule · s'arrêter · nous · alors · descendre · tout de suite","say":{"Mûea":"เมื่อ","mûea":"เมื่อ","thâa":"ถ้า","kâw":"ก็","mûea rót jàwt, rao kâw long loei":"เมื่อรถจอด เราก็ลงเลย","mûea rao maa thǔeng Khǎo Sòk":"เมื่อเรามาถึงเขาสก","tawn":"ตอน","mûea-rai ?":"เมื่อไร"}}},{"title":"Randonnée dans la jungle","phrases":[{"fr":"Le sentier est boueux après la pluie.","tgt":"หลังฝนตกทางเดินเป็นโคลน","ro":"Lǎng fǒn tòk thaang-doen pen khloon."},{"fr":"Mets des chaussettes anti-sangsues.","tgt":"ใส่ถุงเท้ากันทากด้วยนะ","ro":"Sài thǔng-tháo kan thâak dûai ná."},{"fr":"Il y a une sangsue sur ma jambe !","tgt":"มีทากติดขาผม","ro":"Mii thâak tìt khǎa phǒm!"},{"fr":"Le guide nous montre une fleur géante.","tgt":"ไกด์ชี้ให้ดูดอกไม้ยักษ์","ro":"Kái chíi hâi duu dàwk-mái yák."},{"fr":"Elle sent très mauvais, comme la viande pourrie.","tgt":"มันเหม็นมาก เหมือนเนื้อเน่า","ro":"Man měn mâak, mǔean núea nâo."},{"fr":"On marche encore une heure jusqu'à la cascade.","tgt":"เดินอีกหนึ่งชั่วโมงถึงน้ำตก","ro":"Doen ìik nùeng chûa-moong thǔeng nám-tòk."},{"fr":"Faisons une pause, j'ai très soif.","tgt":"พักก่อนเถอะ ผมหิวน้ำมาก","ro":"Phák kàwn thòe, phǒm hǐu náam mâak."},{"fr":"Regarde, il y a des calaos dans cet arbre.","tgt":"ดูสิ มีนกเงือกอยู่บนต้นไม้นั้น","ro":"Duu sì, mii nók-ngûeak yùu bon tôn-mái nán."},{"fr":"On peut se baigner sous la cascade.","tgt":"เล่นน้ำใต้น้ำตกได้","ro":"Lên náam tâi nám-tòk dâai."},{"fr":"Mes jambes sont épuisées, mais je suis heureux.","tgt":"ขาผมล้ามาก แต่ผมมีความสุข","ro":"Khǎa phǒm láa mâak, tàe phǒm mii khwaam-sùk."}]},{"title":"Une nuit sur le lac de Chiao Lan","phrases":[{"fr":"Le lac de Chiao Lan est d'un vert magnifique.","tgt":"ทะเลสาบเชี่ยวหลานสีเขียวสวยมาก","ro":"Thá-lee-sàap Chîao Lǎan sǐi khǐao sǔai mâak."},{"fr":"Cette nuit, on dort dans une maison flottante.","tgt":"คืนนี้เรานอนที่บ้านแพ","ro":"Khuen-níi rao nawn thîi bâan-phae."},{"fr":"Le bateau traverse le lac pendant une heure.","tgt":"เรือแล่นข้ามทะเลสาบหนึ่งชั่วโมง","ro":"Ruea lâen khâam thá-lee-sàap nùeng chûa-moong."},{"fr":"Les montagnes sortent de l'eau comme des tours.","tgt":"ภูเขาโผล่ขึ้นมาจากน้ำเหมือนหอคอย","ro":"Phuu-khǎo phlòo khûen maa jàak náam mǔean hǎw-khoi."},{"fr":"On peut faire du kayak avant le dîner.","tgt":"พายเรือคายัคก่อนกินข้าวเย็นได้","ro":"Phaai ruea khaa-yák kàwn kin khâao yen dâai."},{"fr":"Il n'y a pas de réseau ici.","tgt":"ที่นี่ไม่มีสัญญาณ","ro":"Thîi-nîi mâi mii sǎn-yaan."},{"fr":"Tant mieux, on va vraiment se reposer.","tgt":"ดีเลย จะได้พักผ่อนจริงๆ","ro":"Dii loei, jà dâi phák-phàwn jing-jing."},{"fr":"À l'aube, il y a de la brume sur le lac.","tgt":"ตอนเช้ามืดมีหมอกบนทะเลสาบ","ro":"Tawn cháo-mûet mii màwk bon thá-lee-sàap."},{"fr":"On a vu des singes sauter dans les arbres.","tgt":"เราเห็นลิงกระโดดอยู่บนต้นไม้","ro":"Rao hěn ling krà-dòot yùu bon tôn-mái."},{"fr":"Ici, c'est si calme qu'on croirait rêver.","tgt":"ที่นี่เงียบสงบจนเหมือนฝัน","ro":"Thîi-nîi ngîap sà-ngòp jon mǔean fǎn."}]},{"title":"La mousson arrive","phrases":[{"fr":"La saison des pluies commence dans le sud.","tgt":"หน้าฝนเริ่มแล้วที่ภาคใต้","ro":"Nâa fǒn rôem láew thîi phâak-tâi."},{"fr":"Il pleut presque chaque après-midi.","tgt":"ฝนตกเกือบทุกบ่าย","ro":"Fǒn tòk kùeap thúk bàai."},{"fr":"Les averses sont fortes mais courtes.","tgt":"ฝนตกหนักแต่ไม่นาน","ro":"Fǒn tòk nàk tàe mâi naan."},{"fr":"Il faut toujours avoir un imperméable sur soi.","tgt":"ต้องพกเสื้อกันฝนไว้ตลอด","ro":"Tâwng phók sûea-kan-fǒn wái tà-làwt."},{"fr":"Le vent souffle très fort sur la côte.","tgt":"ลมแรงมากที่ชายฝั่ง","ro":"Lom raeng mâak thîi chaai-fàng."},{"fr":"Les bateaux ne sortent pas quand il y a une tempête.","tgt":"เวลามีพายุ เรือไม่ออก","ro":"Wee-laa mii phaa-yú, ruea mâi àwk."},{"fr":"Les hôtels sont beaucoup moins chers en ce moment.","tgt":"ช่วงนี้โรงแรมถูกกว่าเยอะ","ro":"Chûang-níi roong-raem thùuk kwàa yóe."},{"fr":"Et il y a beaucoup moins de touristes.","tgt":"แล้วนักท่องเที่ยวก็น้อยกว่ามาก","ro":"Láew nák-thâwng-thîao kâw náwy kwàa mâak."},{"fr":"Regardons la météo avant de partir.","tgt":"ดูพยากรณ์อากาศก่อนออกเดินทางกันเถอะ","ro":"Duu phá-yaa-kawn aa-kàat kàwn àwk doen-thaang kan thòe."},{"fr":"Après la pluie, tout est si vert.","tgt":"หลังฝนตก ทุกอย่างเขียวไปหมด","ro":"Lǎng fǒn tòk, thúk yàang khǐao pai mòt."}]},{"title":"Un ferry annulé","phrases":[{"fr":"Le ferry pour Ko Tao est annulé à cause des vagues.","tgt":"เรือไปเกาะเต่ายกเลิกเพราะคลื่นแรง","ro":"Ruea pai Kàw Tào yók-lôek phráw khlûen raeng."},{"fr":"On voulait partir ce matin, mais la mer est trop forte.","tgt":"เราอยากออกเดินทางเช้านี้ แต่คลื่นลมแรงเกินไป","ro":"Rao yàak àwk doen-thaang cháo níi, tàe khlûen lom raeng koen pai."},{"fr":"Même s'il fait beau, les bateaux restent au port.","tgt":"ถึงฟ้าจะใส เรือก็ยังจอดอยู่ที่ท่า","ro":"Thǔeng fáa jà sǎi, ruea kâw yang jàwt yùu thîi thâa."},{"fr":"C'est agaçant, mais c'est plus sûr.","tgt":"น่าหงุดหงิด แต่ปลอดภัยกว่า","ro":"Nâa ngùt-ngìt, tàe plàwt-phai kwàa."},{"fr":"Le prochain bateau part demain, mais il est presque complet.","tgt":"เรือลำต่อไปออกพรุ่งนี้ แต่ที่นั่งเกือบเต็มแล้ว","ro":"Ruea lam tàw pai àwk phrûng-níi, tàe thîi-nâng kùeap tem láew."},{"fr":"Même si c'est cher, on doit dormir ici ce soir.","tgt":"ถึงจะแพง เราก็ต้องพักที่นี่คืนนี้","ro":"Thǔeng jà phaeng, rao kâw tâwng phák thîi-nîi khuen-níi."},{"fr":"Le guichet rembourse les billets, mais seulement à moitié.","tgt":"ที่ขายตั๋วคืนเงินให้ แต่แค่ครึ่งเดียว","ro":"Thîi khǎai tǔa khuen ngoen hâi, tàe khâe khrûeng diao."},{"fr":"Même avec un jour de retard, on ne rate rien d'important.","tgt":"ถึงเราจะช้าไปหนึ่งวัน เราก็ไม่พลาดอะไรสำคัญ","ro":"Thǔeng rao jà cháa pai nùeng wan, rao kâw mâi phlâat à-rai sǎm-khan."},{"fr":"J'appelle le centre de plongée pour décaler la réservation.","tgt":"ผมจะโทรไปที่ร้านดำน้ำเพื่อเลื่อนการจอง","ro":"Phǒm jà thoo pai thîi ráan dam-náam phûea lûean kaan jawng."},{"fr":"Même sous la pluie, cette île reste belle.","tgt":"ถึงฝนจะตก เกาะนี้ก็ยังสวย","ro":"Thǔeng fǒn jà tòk, kàw níi kâw yang sǔai."}],"tip":{"title":"« Tàe » et « thǔeng... kâw... » : mais et bien que","example":"Même s'il fait beau, les bateaux restent au port. — <b>ถึง</b>ฟ้าจะใส เรือ<b>ก็</b>ยังจอดอยู่ที่ท่า","body":"« Tàe », au ton bas, est le « mais » de tous les jours : on le place entre deux idées, exactement comme en français, par exemple « nâa ngùt-ngìt, tàe plàwt-phai kwàa », c'est agaçant, mais c'est plus sûr. Pour dire « même si » ou « bien que », on ouvre la phrase par « thǔeng », au ton montant, on met souvent « jà » devant le verbe, puis « kâw » dans la deuxième partie, souvent suivi de « yang », encore. Décomposons « thǔeng fáa jà sǎi, ruea kâw yang jàwt yùu thîi thâa » : même si, ciel, clair, bateau, quand même, encore, stationner au quai. On retrouve le même moule dans « thǔeng jà phaeng, rao kâw tâwng phák thîi-nîi », même si c'est cher, on doit dormir ici. Astuce : c'est la petite sœur de « thâa... kâw... », il suffit de remplacer « si » par « même si ».","exampleRo":"Thǔeng fáa jà sǎi, ruea kâw yang jàwt yùu thîi thâa.","lit":"même si · ciel · [futur] · clair · bateau · alors · encore · stationner · [en cours] · à · quai","say":{"Tàe":"แต่","thǔeng... kâw...":"ถึง ก็","nâa ngùt-ngìt, tàe plàwt-phai kwàa":"น่าหงุดหงิด แต่ปลอดภัยกว่า","thǔeng":"ถึง","jà":"จะ","kâw":"ก็","yang":"ยัง","thǔeng fáa jà sǎi, ruea kâw yang jàwt yùu thîi thâa":"ถึงฟ้าจะใส เรือก็ยังจอดอยู่ที่ท่า","thǔeng jà phaeng, rao kâw tâwng phák thîi-nîi":"ถึงจะแพง เราก็ต้องพักที่นี่","thâa... kâw...":"ถ้า ก็"}}},{"title":"Un petit accident de scooter","phrases":[{"fr":"Mon ami est tombé de son scooter.","tgt":"เพื่อนผมล้มจากมอเตอร์ไซค์","ro":"Phûean phǒm lóm jàak maw-toe-sai."},{"fr":"Heureusement, ce n'est pas grave.","tgt":"โชคดีที่ไม่เป็นอะไรมาก","ro":"Chôok dii thîi mâi pen à-rai mâak."},{"fr":"Il a une grosse égratignure au genou.","tgt":"เขามีแผลถลอกใหญ่ที่เข่า","ro":"Khǎo mii phlǎe thà-làwk yài thîi khào."},{"fr":"Où est la pharmacie la plus proche ?","tgt":"ร้านขายยาที่ใกล้ที่สุดอยู่ที่ไหนครับ","ro":"Ráan khǎai yaa thîi klâi thîi-sùt yùu thîi-nǎi khráp?"},{"fr":"Il faut bien nettoyer la plaie.","tgt":"ต้องล้างแผลให้สะอาด","ro":"Tâwng láang phlǎe hâi sà-àat."},{"fr":"Avec cette chaleur, la plaie s'infecte vite.","tgt":"อากาศร้อนแบบนี้ แผลติดเชื้อง่าย","ro":"Aa-kàat ráwn bàep níi, phlǎe tìt chúea ngâai."},{"fr":"Le rétroviseur du scooter est cassé.","tgt":"กระจกมอเตอร์ไซค์แตก","ro":"Krà-jòk maw-toe-sai tàek."},{"fr":"Combien le loueur va-t-il nous faire payer ?","tgt":"ร้านเช่าจะคิดเงินเราเท่าไร","ro":"Ráan châo jà khít ngoen rao thâo-rai?"},{"fr":"Il demande huit cents bahts pour la réparation.","tgt":"เขาขอแปดร้อยบาทค่าซ่อม","ro":"Khǎo khǎw pàet rói bàat khâa sâwm."},{"fr":"Désormais, on met toujours un casque.","tgt":"ต่อไปนี้เราจะใส่หมวกกันน็อกทุกครั้ง","ro":"Tàw pai níi rao jà sài mùak-kan-nók thúk khráng."}]},{"title":"Un sac oublié sur le bateau","phrases":[{"fr":"J'ai oublié mon sac dans le bateau.","tgt":"ผมลืมกระเป๋าไว้บนเรือ","ro":"Phǒm luem krà-pǎo wái bon ruea."},{"fr":"Mon téléphone et mes lunettes sont dedans.","tgt":"โทรศัพท์กับแว่นตาผมอยู่ในนั้น","ro":"Thoo-rá-sàp kàp wâen-taa phǒm yùu nai nán."},{"fr":"Le bateau est déjà reparti pour Krabi.","tgt":"เรือกลับไปกระบี่แล้ว","ro":"Ruea klàp pai Krà-bìi láew."},{"fr":"Pouvez-vous appeler le capitaine, s'il vous plaît ?","tgt":"ช่วยโทรหากัปตันเรือให้หน่อยได้ไหมครับ","ro":"Chûai thoo hǎa kàp-tan ruea hâi nàwy dâai mái khráp?"},{"fr":"C'est un sac à dos bleu avec une poche rouge.","tgt":"เป็นเป้สีน้ำเงินมีกระเป๋าสีแดง","ro":"Pen pêe sǐi nám-ngoen mii krà-pǎo sǐi daeng."},{"fr":"L'équipage l'a trouvé sous un siège.","tgt":"ลูกเรือเจอมันใต้ที่นั่ง","ro":"Lûuk-ruea joe man tâi thîi-nâng."},{"fr":"Ils le rapportent avec le bateau de demain.","tgt":"เขาจะเอากลับมากับเรือพรุ่งนี้","ro":"Khǎo jà ao klàp maa kàp ruea phrûng-níi."},{"fr":"Je viendrai le chercher au port à dix heures.","tgt":"ผมจะไปรับที่ท่าเรือตอนสิบโมง","ro":"Phǒm jà pai ráp thîi thâa-ruea tawn sìp moong."},{"fr":"Merci beaucoup, vous m'avez bien aidé.","tgt":"ขอบคุณมากครับ ช่วยผมได้เยอะเลย","ro":"Khàwp-khun mâak khráp, chûai phǒm dâi yóe loei."},{"fr":"La prochaine fois, je vérifierai avant de descendre.","tgt":"คราวหน้าผมจะเช็กก่อนลงจากเรือ","ro":"Khraao nâa phǒm jà chék kàwn long jàak ruea."}]},{"title":"Derniers jours à Ko Samui","phrases":[{"fr":"Il ne nous reste que deux jours sur l'île.","tgt":"เราเหลือเวลาอยู่บนเกาะแค่สองวัน","ro":"Rao lǔea wee-laa yùu bon kàw khâe sǎwng wan."},{"fr":"Je veux me faire masser sur la plage.","tgt":"ผมอยากนวดที่ชายหาด","ro":"Phǒm yàak nûat thîi chaai-hàat."},{"fr":"Un massage d'une heure coûte quatre cents bahts.","tgt":"นวดหนึ่งชั่วโมงสี่ร้อยบาท","ro":"Nûat nùeng chûa-moong sìi rói bàat."},{"fr":"Moins fort, s'il vous plaît.","tgt":"เบาหน่อยครับ","ro":"Bao nàwy khráp."},{"fr":"On achète de l'huile de coco pour la famille.","tgt":"เราซื้อน้ำมันมะพร้าวไปฝากครอบครัว","ro":"Rao súe nám-man má-phráao pai fàak khrâwp-khrua."},{"fr":"Il faut encore réserver le bus pour l'aéroport.","tgt":"ยังต้องจองรถไปสนามบินอีก","ro":"Yang tâwng jawng rót pai sà-nǎam-bin ìik."},{"fr":"Notre vol part de Ko Samui jeudi.","tgt":"เที่ยวบินของเราออกจากเกาะสมุยวันพฤหัส","ro":"Thîao-bin khǎwng rao àwk jàak Kàw Sà-mǔi wan Phá-rúe-hàt."},{"fr":"Allons nager une dernière fois avant la nuit.","tgt":"ไปว่ายน้ำครั้งสุดท้ายก่อนมืดกันเถอะ","ro":"Pai wâai-náam khráng sùt-tháai kàwn mûet kan thòe."},{"fr":"Ma peau a bien bronzé.","tgt":"ผิวผมคล้ำขึ้นเยอะเลย","ro":"Phǐu phǒm khlám khûen yóe loei."},{"fr":"Le sud de la Thaïlande va beaucoup me manquer.","tgt":"ผมจะคิดถึงภาคใต้ของไทยมาก","ro":"Phǒm jà khít-thǔeng phâak-tâi khǎwng Thai mâak."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait voyager d'île en île.","tgt":"บทนี้พาเราเที่ยวจากเกาะหนึ่งไปอีกเกาะหนึ่ง","ro":"Bòt níi phaa rao thîao jàak kàw nùeng pai ìik kàw nùeng."},{"fr":"Maintenant, je sais acheter un billet de bateau en thaï.","tgt":"ตอนนี้ผมซื้อตั๋วเรือเป็นภาษาไทยได้แล้ว","ro":"Tawn-níi phǒm súe tǔa ruea pen phaa-sǎa Thai dâai láew."},{"fr":"Je peux louer un scooter sans problème.","tgt":"ผมเช่ามอเตอร์ไซค์ได้โดยไม่มีปัญหา","ro":"Phǒm châo maw-toe-sai dâai dooi mâi mii pan-hǎa."},{"fr":"Les phrases avec « si » m'aident à faire face aux imprévus.","tgt":"ประโยคที่มีคำว่าถ้าช่วยให้ผมรับมือกับเรื่องไม่คาดคิด","ro":"Prà-yòok thîi mii kham wâa thâa chûai hâi phǒm ráp-mue kàp rûeang mâi khâat-khít."},{"fr":"Je sais aussi dire ce que je dois faire.","tgt":"ผมพูดได้ด้วยว่าผมต้องทำอะไร","ro":"Phǒm phûut dâai dûai wâa phǒm tâwng tham à-rai."},{"fr":"Les imprévus me font moins peur qu'avant.","tgt":"เรื่องไม่คาดคิดทำให้ผมกลัวน้อยกว่าเมื่อก่อน","ro":"Rûeang mâi khâat-khít tham hâi phǒm klua náwy kwàa mûea-kàwn."},{"fr":"Mon thaï devient plus naturel chaque jour.","tgt":"ภาษาไทยของผมเป็นธรรมชาติขึ้นทุกวัน","ro":"Phaa-sǎa Thai khǎwng phǒm pen tham-má-châat khûen thúk wan."},{"fr":"Même si je fais encore des erreurs, je continue.","tgt":"ถึงผมจะยังพูดผิดอยู่ ผมก็จะพูดต่อไป","ro":"Thǔeng phǒm jà yang phûut phìt yùu, phǒm kâw jà phûut tàw pai."},{"fr":"Le prochain module parlera de la vie sociale.","tgt":"บทต่อไปจะเป็นเรื่องการเข้าสังคม","ro":"Bòt tàw pai jà pen rûeang kaan khâo sǎng-khom."},{"fr":"Bravo pour tout ce chemin parcouru !","tgt":"เก่งมากที่มาได้ไกลขนาดนี้","ro":"Kèng mâak thîi maa dâai klai khà-nàat níi!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouvailles à Hua Hin","phrases":[{"fr":"Tôn ! Ça fait une éternité qu'on ne s'est pas vus !","tgt":"ต้น ไม่ได้เจอกันตั้งนานเลย","ro":"Tôn, mâi dâi joe kan tâng naan loei!"},{"fr":"Tu n'as pas changé du tout.","tgt":"นายไม่เปลี่ยนไปเลยนะ","ro":"Naai mâi plìan pai loei ná."},{"fr":"Tu habites toujours à Hua Hin ?","tgt":"ยังอยู่หัวหินเหรอ","ro":"Yang yùu Hǔa-hǐn rǒe?"},{"fr":"Non, je me suis installé à Bangkok l'an dernier.","tgt":"เปล่า ย้ายไปอยู่กรุงเทพตั้งแต่ปีที่แล้ว","ro":"Plào, yáai pai yùu Krung-thêep tâng-tàe pii thîi láew."},{"fr":"Je suis revenu ici pour les vacances.","tgt":"กลับมาเที่ยวที่นี่ช่วงวันหยุด","ro":"Klàp maa thîao thîi-nîi chûang wan-yùt."},{"fr":"On va boire un café au bord de la mer ?","tgt":"ไปนั่งกินกาแฟริมทะเลกันไหม","ro":"Pai nâng kin kaa-fae rim thá-lee kan mái?"},{"fr":"Bonne idée, j'ai plein de choses à te raconter.","tgt":"ดีเลย มีเรื่องจะเล่าให้ฟังเยอะเลย","ro":"Dii loei, mii rûeang jà lâo hâi fang yóe loei."},{"fr":"Et ta petite sœur, comment elle va ?","tgt":"น้องสาวนายเป็นไงบ้าง","ro":"Náwng-sǎao naai pen ngai bâang?"},{"fr":"Elle va bien, elle travaille dans un hôtel maintenant.","tgt":"สบายดี ตอนนี้ทำงานอยู่ที่โรงแรม","ro":"Sà-baai-dii, tawn-níi tham-ngaan yùu thîi roong-raem."},{"fr":"Ça me fait vraiment plaisir de te retrouver.","tgt":"ดีใจจริงๆที่ได้เจอนายอีก","ro":"Dii-jai jing-jing thîi dâi joe naai ìik."}]},{"title":"Entre amis, on parle simplement","phrases":[{"fr":"Salut, quoi de neuf ?","tgt":"ว่าไง มีอะไรใหม่ๆบ้าง","ro":"Wâa ngai, mii à-rai mài-mài bâang?"},{"fr":"Rien de spécial, et toi alors ?","tgt":"ไม่มีอะไรหรอก แล้วแกล่ะ","ro":"Mâi mii à-rai ràwk, láew kae lâ?"},{"fr":"On va manger ensemble ce soir ?","tgt":"เย็นนี้ไปกินข้าวกันป่ะ","ro":"Yen-níi pai kin khâao kan pà?"},{"fr":"Ok, je t'attends devant le centre commercial.","tgt":"โอเค เดี๋ยวรอหน้าห้างนะ","ro":"Oo-khee, dǐao raw nâa hâang ná."},{"fr":"Encore en retard, comme d'hab !","tgt":"มาสายอีกแล้ว เหมือนเดิมเลย","ro":"Maa sǎai ìik láew, mǔean doem loei!"},{"fr":"Désolé, il y avait trop de bouchons.","tgt":"โทษที รถติดมาก","ro":"Thôot-thii, rót tìt mâak."},{"fr":"Toi, tu exagères toujours !","tgt":"แกนี่ชอบพูดเกินจริงตลอด","ro":"Kae nîi châwp phûut koen jing tà-làwt!"},{"fr":"Allez, on commande, je meurs de faim.","tgt":"เอาเลย สั่งกันเถอะ หิวจะตายแล้ว","ro":"Ao loei, sàng kan thòe, hǐu jà taai láew."},{"fr":"Aujourd'hui, c'est moi qui régale.","tgt":"วันนี้เราเลี้ยงเอง","ro":"Wan-níi rao líang eeng."},{"fr":"Sérieux ? Trop sympa !","tgt":"จริงดิ ใจดีสุดๆ","ro":"Jing dì? Jai-dii sùt-sùt!"}],"tip":{"title":"Le registre familier entre amis","example":"On va manger ensemble ce soir ? — เย็นนี้ไปกินข้าวกัน<b>ป่ะ</b>","body":"Entre amis, les Thaïs laissent tomber les particules de politesse « khráp » et « khâ » : les garder avec un copain sonnerait presque distant. On remplace aussi « phǒm » par « rao », qui veut dire « nous » mais sert de « je » familier, et on appelle l'autre « naai » ou « kae », un peu comme notre tutoiement. Pour poser une question, « mái » devient souvent « pà » en fin de phrase : « yen-níi pai kin khâao kan pà », mot à mot « ce soir, aller manger riz ensemble, hein », c'est-à-dire « on va manger ensemble ce soir ? ». De même, « jing rǒe » devient « jing dì » pour dire « sérieux ? », et « khàwp-khun » devient « khàwp-jai », merci entre copains. Astuce : avec un ami de ton âge, parle comme lui ; avec un aîné ou un inconnu, remets aussitôt le « khráp ».","exampleRo":"Yen-níi pai kin khâao kan pà?","lit":"ce soir · aller · manger · riz · ensemble · [question familière]","say":{"khráp":"ครับ","khâ":"ค่ะ","phǒm":"ผม","rao":"เรา","naai":"นาย","kae":"แก","mái":"ไหม","pà":"ป่ะ","yen-níi pai kin khâao kan pà":"เย็นนี้ไปกินข้าวกันป่ะ","jing rǒe":"จริงเหรอ","jing dì":"จริงดิ","khàwp-khun":"ขอบคุณ","khàwp-jai":"ขอบใจ"}}},{"title":"Parler de séries","phrases":[{"fr":"Tu regardes quelle série en ce moment ?","tgt":"ช่วงนี้ดูซีรีส์เรื่องอะไรอยู่","ro":"Chûang-níi duu sii-rîi rûeang à-rai yùu?"},{"fr":"Une série thaïe sur une bande d'étudiants.","tgt":"ซีรีส์ไทยเกี่ยวกับกลุ่มนักศึกษา","ro":"Sii-rîi thai kìao-kàp klùm nák-sùek-sǎa."},{"fr":"Elle a combien d'épisodes ?","tgt":"มีกี่ตอน","ro":"Mii kìi tawn?"},{"fr":"Seize, j'en ai déjà vu la moitié.","tgt":"สิบหกตอน ดูไปครึ่งนึงแล้ว","ro":"Sìp-hòk tawn, duu pai khrûeng nueng láew."},{"fr":"Le héros joue vraiment bien.","tgt":"พระเอกเล่นดีมาก","ro":"Phrá-èek lên dii mâak."},{"fr":"Le dernier épisode m'a fait pleurer.","tgt":"ตอนล่าสุดทำเอาร้องไห้เลย","ro":"Tawn lâa-sùt tham ao ráwng-hâi loei."},{"fr":"Ne me raconte pas la fin !","tgt":"อย่าเพิ่งเล่าตอนจบนะ","ro":"Yàa phôeng lâo tawn-jòp ná!"},{"fr":"Je regarde un épisode chaque soir avant de dormir.","tgt":"ดูคืนละตอนก่อนนอน","ro":"Duu khuen lá tawn kàwn nawn."},{"fr":"Hier, j'ai regardé jusqu'à deux heures du matin.","tgt":"เมื่อคืนดูถึงตีสองเลย","ro":"Mûea-khuen duu thǔeng tii sǎwng loei."},{"fr":"Tu as une série à me conseiller ?","tgt":"มีซีรีส์อะไรแนะนำบ้าง","ro":"Mii sii-rîi à-rai náe-nam bâang?"}]},{"title":"Préparer Songkran","phrases":[{"fr":"Songkran arrive dans une semaine !","tgt":"อีกอาทิตย์เดียวก็สงกรานต์แล้ว","ro":"Ìik aa-thít diao kâw Sǒng-kraan láew!"},{"fr":"Tu fais quoi pour le nouvel an thaï ?","tgt":"ปีใหม่ไทยจะทำอะไร","ro":"Pii-mài thai jà tham à-rai?"},{"fr":"Je rentre chez mes parents à Hua Hin.","tgt":"จะกลับไปบ้านพ่อแม่ที่หัวหิน","ro":"Jà klàp pai bâan phâw-mâe thîi Hǔa-hǐn."},{"fr":"Il faut acheter des pistolets à eau.","tgt":"ต้องซื้อปืนฉีดน้ำ","ro":"Tâwng súe puen-chìit-náam."},{"fr":"J'en veux un grand, pas un petit !","tgt":"เอาอันใหญ่นะ ไม่เอาอันเล็ก","ro":"Ao an yài ná, mâi ao an lék!"},{"fr":"N'oublie pas une pochette étanche pour ton téléphone.","tgt":"อย่าลืมซองกันน้ำใส่โทรศัพท์นะ","ro":"Yàa luem sawng kan náam sài thoo-rá-sàp ná."},{"fr":"Et des vêtements qui sèchent vite.","tgt":"แล้วก็เสื้อผ้าที่แห้งเร็ว","ro":"Láew-kâw sûea-phâa thîi hâeng reo."},{"fr":"Les billets de car sont presque tous partis.","tgt":"ตั๋วรถทัวร์ใกล้จะหมดแล้ว","ro":"Tǔa rót-thua klâi jà mòt láew."},{"fr":"On devrait réserver dès aujourd'hui.","tgt":"เราควรจองวันนี้เลย","ro":"Rao khuan jawng wan-níi loei."},{"fr":"Ce Songkran, je serai en famille pour la première fois depuis des années.","tgt":"สงกรานต์นี้จะได้อยู่กับครอบครัวครั้งแรกในรอบหลายปี","ro":"Sǒng-kraan níi jà dâi yùu kàp khrâwp-khrua khráng râek nai râwp lǎai pii."}]},{"title":"Des projets pas encore sûrs","phrases":[{"fr":"Ce week-end, j'irai peut-être à la plage.","tgt":"เสาร์อาทิตย์นี้อาจจะไปทะเล","ro":"Sǎo-aa-thít níi àat jà pai thá-lee."},{"fr":"Il va peut-être pleuvoir demain.","tgt":"พรุ่งนี้ฝนอาจจะตก","ro":"Phrûng-níi fǒn àat jà tòk."},{"fr":"Nók viendra peut-être avec nous.","tgt":"นกอาจจะมากับเราด้วย","ro":"Nók àat jà maa kàp rao dûai."},{"fr":"Je ne suis pas sûr, je finis peut-être tard.","tgt":"ไม่แน่ใจ อาจจะเลิกงานดึก","ro":"Mâi nâe-jai, àat jà lôek ngaan dùek."},{"fr":"Peut-être, ça dépend de la météo.","tgt":"อาจจะ ขึ้นอยู่กับอากาศ","ro":"Àat jà, khûen yùu kàp aa-kàat."},{"fr":"On pourrait peut-être louer un scooter.","tgt":"เราอาจจะเช่ามอเตอร์ไซค์กัน","ro":"Rao àat jà châo maw-toe-sai kan."},{"fr":"Je ne sais pas encore, je te dis ça demain.","tgt":"ยังไม่รู้เลย พรุ่งนี้บอกนะ","ro":"Yang mâi rúu loei, phrûng-níi bàwk ná."},{"fr":"Le restaurant est peut-être fermé le lundi.","tgt":"ร้านอาจจะปิดวันจันทร์","ro":"Ráan àat jà pìt wan jan."},{"fr":"Il est peut-être déjà parti, qui sait.","tgt":"เขาอาจจะไปแล้วก็ได้","ro":"Khǎo àat jà pai láew kâw dâi."},{"fr":"Peut-être que oui, peut-être que non.","tgt":"อาจจะใช่ อาจจะไม่ใช่","ro":"Àat jà châi, àat jà mâi châi."}],"tip":{"title":"« Àat jà » : peut-être","example":"Il va peut-être pleuvoir demain. — พรุ่งนี้ฝน<b>อาจจะ</b>ตก","body":"« Àat jà » veut dire « peut-être » et se place juste devant le verbe, exactement là où l'on mettrait le futur « jà ». « Phrûng-níi fǒn àat jà tòk », mot à mot « demain, pluie, peut-être, tomber », signifie « il va peut-être pleuvoir demain ». On dit aussi « rao àat jà pai » pour « on ira peut-être », et « àat jà mâi châi » pour « ce n'est peut-être pas ça ». Pour ajouter encore du doute, on termine la phrase par « kâw dâi », comme dans « khǎo àat jà pai láew kâw dâi », « il est peut-être déjà parti, qui sait ». Astuce : vois « àat jà » comme un futur qui hésite, le « jà » du futur précédé d'un petit « àat » prudent.","exampleRo":"Phrûng-níi fǒn àat jà tòk.","lit":"demain · pluie · [peut-être] · tomber","say":{"Àat jà":"อาจจะ","jà":"จะ","Phrûng-níi fǒn àat jà tòk":"พรุ่งนี้ฝนอาจจะตก","rao àat jà pai":"เราอาจจะไป","àat jà mâi châi":"อาจจะไม่ใช่","kâw dâi":"ก็ได้","khǎo àat jà pai láew kâw dâi":"เขาอาจจะไปแล้วก็ได้","àat jà":"อาจจะ","àat":"อาจ"}}},{"title":"La bataille d'eau de Songkran","phrases":[{"fr":"Regarde, la rue est noire de monde !","tgt":"ดูสิ คนเต็มถนนเลย","ro":"Duu sì, khon tem thà-nǒn loei!"},{"fr":"Attention, il arrive avec un seau d'eau !","tgt":"ระวัง เขาถือถังน้ำมาแล้ว","ro":"Rá-wang, khǎo thǔe thǎng náam maa láew!"},{"fr":"Trop tard, je suis trempé de la tête aux pieds !","tgt":"ไม่ทันแล้ว เปียกหมดเลย","ro":"Mâi than láew, pìak mòt loei!"},{"fr":"L'eau est glacée, ils ont mis des glaçons !","tgt":"น้ำเย็นเจี๊ยบ ใส่น้ำแข็งด้วย","ro":"Náam yen jíap, sài náam-khǎeng dûai!"},{"fr":"Vas-y, arrose-le !","tgt":"เอาเลย สาดเขาเลย","ro":"Ao loei, sàat khǎo loei!"},{"fr":"Une dame m'a mis de la poudre blanche sur la joue.","tgt":"ป้าคนนึงเอาดินสอพองมาทาแก้มเรา","ro":"Pâa khon nueng ao din-sǎw-phawng maa thaa kâem rao."},{"fr":"C'est la tradition, ça porte chance.","tgt":"เป็นประเพณี ถือว่าโชคดี","ro":"Pen prà-phee-nii, thǔe wâa chôok dii."},{"fr":"Avec cette chaleur, être mouillé, ça fait du bien.","tgt":"ร้อนขนาดนี้ เปียกแล้วสบายดี","ro":"Ráwn khà-nàat níi, pìak láew sà-baai dii."},{"fr":"Heureusement, mon téléphone est resté au sec.","tgt":"โชคดีที่โทรศัพท์ไม่เปียก","ro":"Chôok dii thîi thoo-rá-sàp mâi pìak."},{"fr":"On continue de jouer jusqu'au soir !","tgt":"เล่นต่อจนถึงเย็นเลย","ro":"Lên tàw jon thǔeng yen loei!"}]},{"title":"Un anniversaire surprise","phrases":[{"fr":"Samedi, c'est l'anniversaire de Plaa.","tgt":"วันเสาร์นี้วันเกิดปลา","ro":"Wan sǎo níi wan-kòet Plaa."},{"fr":"Et si on lui organisait une fête en secret ?","tgt":"เราแอบจัดงานให้เขาดีไหม","ro":"Rao àep jàt ngaan hâi khǎo dii mái?"},{"fr":"Elle va avoir trente ans.","tgt":"เขาจะอายุสามสิบแล้ว","ro":"Khǎo jà aa-yú sǎam-sìp láew."},{"fr":"Je m'occupe du gâteau.","tgt":"เดี๋ยวเราจัดการเรื่องเค้กเอง","ro":"Dǐao rao jàt-kaan rûeang khéek eeng."},{"fr":"Elle adore les gâteaux à la noix de coco.","tgt":"เขาชอบเค้กมะพร้าวมาก","ro":"Khǎo châwp khéek má-phráao mâak."},{"fr":"Qui l'amène au restaurant sans qu'elle se doute de rien ?","tgt":"ใครจะพาเขามาร้านโดยไม่ให้รู้ตัว","ro":"Khrai jà phaa khǎo maa ráan dooi mâi hâi rúu-tua?"},{"fr":"Silence, la voilà !","tgt":"เงียบๆ เขามาแล้ว","ro":"Ngîap-ngîap, khǎo maa láew!"},{"fr":"Joyeux anniversaire, Plaa !","tgt":"สุขสันต์วันเกิดนะปลา","ro":"Sùk-sǎn wan-kòet ná Plaa!"},{"fr":"Allez, souffle les bougies !","tgt":"เป่าเทียนเลย","ro":"Pào thian loei!"},{"fr":"Je ne me doutais vraiment de rien, merci !","tgt":"ไม่รู้ตัวเลยจริงๆ ขอบใจนะ","ro":"Mâi rúu-tua loei jing-jing, khàwp-jai ná!"}]},{"title":"Donner son avis","phrases":[{"fr":"Franchement, tu en penses quoi ?","tgt":"พูดตรงๆ นายว่าเป็นไง","ro":"Phûut trong-trong, naai wâa pen ngai?"},{"fr":"Je trouve que c'est un peu trop cher.","tgt":"เราว่าแพงไปหน่อย","ro":"Rao wâa phaeng pai nòi."},{"fr":"Là, je ne suis pas d'accord avec toi.","tgt":"เราไม่เห็นด้วยกับนาย","ro":"Rao mâi hěn dûai kàp naai."},{"fr":"Pour moi, c'est le meilleur restaurant du quartier.","tgt":"สำหรับเรา ร้านนี้อร่อยที่สุดแถวนี้","ro":"Sǎm-ràp rao, ráan níi à-ròi thîi-sùt thǎew níi."},{"fr":"C'est vrai, je n'y avais pas pensé.","tgt":"จริงด้วย ไม่ได้คิดถึงเรื่องนี้เลย","ro":"Jing dûai, mâi dâi khít thǔeng rûeang níi loei."},{"fr":"Ça dépend des goûts de chacun.","tgt":"แล้วแต่คนชอบ","ro":"Láew-tàe khon châwp."},{"fr":"Moi, je préfère la mer à la montagne.","tgt":"เราชอบทะเลมากกว่าภูเขา","ro":"Rao châwp thá-lee mâak kwàa phuu-khǎo."},{"fr":"Pas mal, mais on a vu mieux.","tgt":"ก็ไม่เลว แต่มีที่ดีกว่านี้","ro":"Kâw mâi leo, tàe mii thîi dii kwàa níi."},{"fr":"Je n'ai pas vraiment d'avis là-dessus.","tgt":"เรื่องนี้ไม่ค่อยมีความเห็นเท่าไหร่","ro":"Rûeang níi mâi khâwy mii khwaam-hěn thâo-rài."},{"fr":"On ne pense pas pareil, ce n'est pas grave.","tgt":"คิดไม่เหมือนกันก็ไม่เป็นไร","ro":"Khít mâi mǔean kan kâw mâi pen rai."}]},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Petit, j'habitais près de la plage de Hua Hin.","tgt":"ตอนเด็กๆเราอยู่ใกล้หาดหัวหิน","ro":"Tawn dèk-dèk rao yùu klâi hàat Hǔa-hǐn."},{"fr":"Tous les soirs, on jouait au foot sur le sable.","tgt":"ทุกเย็นเราเตะบอลกันบนทราย","ro":"Thúk yen rao tè bawn kan bon saai."},{"fr":"Tu te souviens de notre maîtresse d'école ?","tgt":"จำครูประจำชั้นของเราได้ไหม","ro":"Jam khruu prà-jam-chán khǎwng rao dâi mái?"},{"fr":"Elle était sévère mais très gentille.","tgt":"ครูดุแต่ใจดีมาก","ro":"Khruu dù tàe jai-dii mâak."},{"fr":"Un jour, j'ai grimpé tout en haut d'un cocotier.","tgt":"เราเคยปีนขึ้นไปถึงยอดต้นมะพร้าว","ro":"Rao khoei piin khûen pai thǔeng yâwt tôn má-phráao."},{"fr":"Ma mère était furieuse !","tgt":"แม่โกรธมากเลย","ro":"Mâe kròot mâak loei!"},{"fr":"On adorait acheter des glaces au vendeur ambulant.","tgt":"เราชอบซื้อไอติมจากรถขายไอติม","ro":"Rao châwp súe ai-tim jàak rót khǎai ai-tim."},{"fr":"Qu'est-ce qu'on était heureux à l'époque.","tgt":"ตอนนั้นมีความสุขจัง","ro":"Tawn-nán mii khwaam-sùk jang."},{"fr":"Ça me rappelle tellement de souvenirs.","tgt":"ทำให้นึกถึงความหลังเยอะเลย","ro":"Tham hâi núek thǔeng khwaam-lǎng yóe loei."},{"fr":"Un jour, il faudrait qu'on y retourne ensemble.","tgt":"สักวันเราน่าจะกลับไปที่นั่นด้วยกัน","ro":"Sàk wan rao nâa jà klàp pai thîi-nân dûai-kan."}]},{"title":"Au marché de nuit de Hua Hin","phrases":[{"fr":"On se retrouve au marché de nuit à vingt heures ?","tgt":"เจอกันที่ตลาดโต้รุ่งตอนสองทุ่มไหม","ro":"Joe kan thîi tà-làat tôo-rûng tawn sǎwng thûm mái?"},{"fr":"Il y a tellement de choses à manger ici !","tgt":"ที่นี่มีของกินเยอะมาก","ro":"Thîi-nîi mii khǎwng-kin yóe mâak!"},{"fr":"Commandons plusieurs plats à partager, c'est plus sympa.","tgt":"สั่งหลายอย่างมาแบ่งกันกินดีกว่า สนุกดี","ro":"Sàng lǎai yàang maa bàeng kan kin dii kwàa, sà-nùk dii."},{"fr":"Goûte ces fruits de mer grillés.","tgt":"ลองชิมอาหารทะเลย่างนี่สิ","ro":"Lawng chim aa-hǎan thá-lee yâang nîi sì."},{"fr":"Pour moi, pas trop pimenté, hein.","tgt":"ของเราไม่เอาเผ็ดมากนะ","ro":"Khǎwng rao mâi ao phèt mâak ná."},{"fr":"Ce stand de riz gluant à la mangue est très connu.","tgt":"ร้านข้าวเหนียวมะม่วงร้านนี้ดังมาก","ro":"Ráan khâao-nǐao má-mûang ráan níi dang mâak."},{"fr":"On fait la queue, ça vaut vraiment le coup.","tgt":"ต่อแถวกันเถอะ คุ้มอยู่แล้ว","ro":"Tàw thǎew kan thòe, khúm yùu láew."},{"fr":"Je te dois combien ?","tgt":"เราต้องให้นายเท่าไหร่","ro":"Rao tâwng hâi naai thâo-rài?"},{"fr":"Cent vingt bahts chacun.","tgt":"คนละร้อยยี่สิบบาท","ro":"Khon lá rói yîi-sìp bàat."},{"fr":"Après, on va se balader sur la plage ?","tgt":"เดี๋ยวไปเดินเล่นชายหาดกันต่อไหม","ro":"Dǐao pai doen lên chaai-hàat kan tàw mái?"}]},{"title":"Préparer Loy Krathong","phrases":[{"fr":"Loy Krathong tombe en général en novembre, à la pleine lune.","tgt":"ลอยกระทงมักจะตรงกับคืนพระจันทร์เต็มดวงในเดือนพฤศจิกายน","ro":"Loi-krà-thong mák jà trong kàp khuen phrá-jan tem duang nai duean phrúet-sà-jì-kaa-yon."},{"fr":"Cette année, on fabrique nos krathongs nous-mêmes ?","tgt":"ปีนี้เราทำกระทงเองกันไหม","ro":"Pii níi rao tham krà-thong eeng kan mái?"},{"fr":"Il faut des feuilles de bananier et des fleurs.","tgt":"ต้องใช้ใบตองกับดอกไม้","ro":"Tâwng chái bai-tawng kàp dàwk-mái."},{"fr":"Pour la base, on peut prendre un morceau de tronc de bananier.","tgt":"ใช้หยวกกล้วยทำฐานก็ได้","ro":"Chái yùak klûai tham thǎan kâw dâi."},{"fr":"C'est mieux que le polystyrène, ça ne salit pas la rivière.","tgt":"ดีกว่าโฟม ไม่ทำให้แม่น้ำสกปรก","ro":"Dii kwàa foom, mâi tham hâi mâe-náam sòk-kà-pròk."},{"fr":"Ma grand-mère est très douée pour plier les feuilles.","tgt":"ยายพับใบตองเก่งมาก","ro":"Yaai pháp bai-tawng kèng mâak."},{"fr":"Elle va nous montrer comment on fait.","tgt":"เดี๋ยวยายจะสอนวิธีทำให้","ro":"Dǐao yaai jà sǎwn wí-thii tham hâi."},{"fr":"Le mien est un peu de travers, non ?","tgt":"ของเราเบี้ยวนิดนึงป่ะ","ro":"Khǎwng rao bîao nít nueng pà?"},{"fr":"Mais non, il est super joli !","tgt":"ไม่หรอก สวยออก","ro":"Mâi ràwk, sǔai àwk!"},{"fr":"On plante une bougie au milieu et c'est fini.","tgt":"ปักเทียนตรงกลางก็เสร็จแล้ว","ro":"Pàk thian trong klaang kâw sèt láew."}]},{"title":"Les nouvelles qui circulent","phrases":[{"fr":"J'ai entendu dire que Tôn allait se marier.","tgt":"ได้ยินว่าต้นจะแต่งงาน","ro":"Dâi-yin wâa Tôn jà tàeng-ngaan."},{"fr":"Ah bon ? Avec qui ?","tgt":"จริงเหรอ กับใคร","ro":"Jing rǒe? Kàp khrai?"},{"fr":"Il paraît que c'est une fille de Hua Hin.","tgt":"ได้ยินว่าเป็นสาวหัวหิน","ro":"Dâi-yin wâa pen sǎao Hǔa-hǐn."},{"fr":"Qui t'a raconté ça ?","tgt":"ใครบอก","ro":"Khrai bàwk?"},{"fr":"J'ai entendu dire qu'un nouveau café avait ouvert près du port.","tgt":"ได้ยินว่ามีร้านกาแฟเปิดใหม่ใกล้ท่าเรือ","ro":"Dâi-yin wâa mii ráan kaa-fae pòet mài klâi thâa-ruea."},{"fr":"On m'a dit que leur café glacé était excellent.","tgt":"ได้ยินมาว่ากาแฟเย็นที่นั่นอร่อยมาก","ro":"Dâi-yin maa wâa kaa-fae yen thîi-nân à-ròi mâak."},{"fr":"J'ai entendu dire qu'il y aurait des feux d'artifice ce soir.","tgt":"ได้ยินว่าคืนนี้จะมีพลุ","ro":"Dâi-yin wâa khuen-níi jà mii phlú."},{"fr":"Ce n'est qu'une rumeur, je ne sais pas si c'est vrai.","tgt":"เป็นแค่ข่าวลือ ไม่รู้ว่าจริงหรือเปล่า","ro":"Pen khâe khàao-lue, mâi rúu wâa jing rǔe plào."},{"fr":"Moi aussi, j'ai entendu la même chose.","tgt":"เราก็ได้ยินมาเหมือนกัน","ro":"Rao kâw dâi-yin maa mǔean-kan."},{"fr":"On le saura bien assez tôt.","tgt":"เดี๋ยวก็รู้","ro":"Dǐao kâw rúu."}],"tip":{"title":"« Dâi-yin wâa » : j'ai entendu dire que","example":"J'ai entendu dire que Tôn allait se marier. — <b>ได้ยินว่า</b>ต้นจะแต่งงาน","body":"« Dâi-yin wâa » signifie mot à mot « entendre que » : c'est notre « j'ai entendu dire que » ou « il paraît que ». On le pose en tête de phrase, puis on enchaîne la nouvelle sans rien changer : « dâi-yin wâa Tôn jà tàeng-ngaan », mot à mot « entendu que, Tôn, futur, se marier », donc « il paraît que Tôn va se marier ». Pas besoin de dire « je » : le contexte suffit, comme souvent en thaï. En ajoutant « maa », « dâi-yin maa wâa », on souligne que l'information vient de quelqu'un d'autre, et « rao kâw dâi-yin maa » veut dire « moi aussi, on me l'a dit ». Astuce : « wâa » est le même petit mot que dans « khít wâa », « je pense que » ; il ouvre la porte à tout ce qu'on rapporte.","exampleRo":"Dâi-yin wâa Tôn jà tàeng-ngaan.","lit":"avoir entendu · que · Tôn · [futur] · se marier","say":{"Dâi-yin wâa":"ได้ยินว่า","dâi-yin wâa Tôn jà tàeng-ngaan":"ได้ยินว่าต้นจะแต่งงาน","maa":"มา","dâi-yin maa wâa":"ได้ยินมาว่า","rao kâw dâi-yin maa":"เราก็ได้ยินมา","wâa":"ว่า","khít wâa":"คิดว่า"}}},{"title":"La soirée de Loy Krathong","phrases":[{"fr":"Il y a un monde fou au bord du fleuve.","tgt":"ริมแม่น้ำคนเยอะมาก","ro":"Rim mâe-náam khon yóe mâak."},{"fr":"Tiens-moi la main, sinon on va se perdre.","tgt":"จับมือไว้นะ เดี๋ยวหลงกัน","ro":"Jàp mue wái ná, dǐao lǒng kan."},{"fr":"Allume la bougie, j'ai un briquet.","tgt":"จุดเทียนเลย เรามีไฟแช็ก","ro":"Jùt thian loei, rao mii fai-cháek."},{"fr":"Pose-le doucement sur l'eau.","tgt":"วางลงน้ำเบาๆนะ","ro":"Waang long náam bao-bao ná."},{"fr":"Regarde, il part avec le courant.","tgt":"ดูสิ ลอยไปตามน้ำแล้ว","ro":"Duu sì, loi pai taam náam láew."},{"fr":"Les lumières sur le fleuve sont magnifiques.","tgt":"แสงไฟบนแม่น้ำสวยมาก","ro":"Sǎeng fai bon mâe-náam sǔai mâak."},{"fr":"Là-bas, des lanternes montent dans le ciel.","tgt":"ตรงโน้นมีโคมลอยขึ้นฟ้า","ro":"Trong nóon mii khoom-loi khûen fáa."},{"fr":"On dirait des milliers d'étoiles.","tgt":"เหมือนดาวเป็นพันๆดวงเลย","ro":"Mǔean daao pen phan-phan duang loei."},{"fr":"Prends une photo de nous deux.","tgt":"ถ่ายรูปเราสองคนหน่อย","ro":"Thàai rûup rao sǎwng khon nòi."},{"fr":"Pour moi, c'est la plus belle fête de l'année.","tgt":"สำหรับเรา นี่เป็นเทศกาลที่สวยที่สุดของปี","ro":"Sǎm-ràp rao, nîi pen thêet-sà-kaan thîi sǔai thîi-sùt khǎwng pii."}]},{"title":"Tout faire en même temps","phrases":[{"fr":"Il mange en regardant la télé.","tgt":"เขากินข้าวไปด้วยดูทีวีไปด้วย","ro":"Khǎo kin khâao pai dûai duu thii-wii pai dûai."},{"fr":"Je chante en conduisant.","tgt":"เราร้องเพลงไปด้วยขับรถไปด้วย","ro":"Rao ráwng phleeng pai dûai khàp rót pai dûai."},{"fr":"Ne parle pas en mangeant !","tgt":"อย่ากินไปด้วยพูดไปด้วย","ro":"Yàa kin pai dûai phûut pai dûai!"},{"fr":"Nók travaille en écoutant de la musique.","tgt":"นกทำงานไปด้วยฟังเพลงไปด้วย","ro":"Nók tham-ngaan pai dûai fang phleeng pai dûai."},{"fr":"On a bavardé en se promenant sur la plage.","tgt":"เราเดินเล่นชายหาดไปด้วยคุยกันไปด้วย","ro":"Rao doen lên chaai-hàat pai dûai khui kan pai dûai."},{"fr":"Elle raconte l'histoire en riant.","tgt":"เขาเล่าไปด้วยหัวเราะไปด้วย","ro":"Khǎo lâo pai dûai hǔa-ró pai dûai."},{"fr":"Faire deux choses à la fois, ce n'est pas facile.","tgt":"ทำสองอย่างพร้อมกันไม่ง่ายเลย","ro":"Tham sǎwng yàang phráwm kan mâi ngâai loei."},{"fr":"Je révise mon vocabulaire dans le bus.","tgt":"เรานั่งรถเมล์ไปด้วยท่องศัพท์ไปด้วย","ro":"Rao nâng rót-mee pai dûai thâwng sàp pai dûai."},{"fr":"Il pleurait et riait en même temps.","tgt":"เขาร้องไห้ไปด้วยหัวเราะไปด้วย","ro":"Khǎo ráwng-hâi pai dûai hǔa-ró pai dûai."},{"fr":"Attention, ne conduis pas en téléphonant.","tgt":"ระวังนะ อย่าขับรถไปด้วยคุยโทรศัพท์ไปด้วย","ro":"Rá-wang ná, yàa khàp rót pai dûai khui thoo-rá-sàp pai dûai."}],"tip":{"title":"« Pai dûai... pai dûai » : faire deux choses à la fois","example":"Il mange en regardant la télé. — เขากินข้าว<b>ไปด้วย</b>ดูทีวี<b>ไปด้วย</b>","body":"Pour dire qu'on fait deux choses à la fois, on place « pai dûai » après chacun des deux verbes : premier verbe, « pai dûai », second verbe, « pai dûai ». « Khǎo kin khâao pai dûai duu thii-wii pai dûai » se décompose en « il, manger riz, en même temps, regarder télé, en même temps » : il mange en regardant la télé. Là où le français utilise le gérondif « en regardant », le thaï met les deux actions à égalité, comme les deux plateaux d'une balance. Autres exemples : « ráwng phleeng pai dûai khàp rót pai dûai », chanter en conduisant, et « yàa kin pai dûai phûut pai dûai », ne parle pas en mangeant. Astuce : retiens-le comme une petite comptine à deux temps, « ... pai dûai, ... pai dûai ».","exampleRo":"Khǎo kin khâao pai dûai duu thii-wii pai dûai.","lit":"il · manger · riz · [en même temps] · regarder · télé · [en même temps]","say":{"Pai dûai... pai dûai":"ไปด้วย ไปด้วย","pai dûai":"ไปด้วย","Khǎo kin khâao pai dûai duu thii-wii pai dûai":"เขากินข้าวไปด้วยดูทีวีไปด้วย","ráwng phleeng pai dûai khàp rót pai dûai":"ร้องเพลงไปด้วยขับรถไปด้วย","yàa kin pai dûai phûut pai dûai":"อย่ากินไปด้วยพูดไปด้วย","... pai dûai, ... pai dûai":"ไปด้วย ไปด้วย"}}},{"title":"Un week-end à Bangkok","phrases":[{"fr":"On prend le train pour Bangkok vendredi soir ?","tgt":"คืนวันศุกร์นั่งรถไฟไปกรุงเทพกันไหม","ro":"Khuen wan sùk nâng rót-fai pai Krung-thêep kan mái?"},{"fr":"On peut dormir chez mon cousin.","tgt":"ไปนอนบ้านลูกพี่ลูกน้องเราได้","ro":"Pai nawn bâan lûuk-phîi-lûuk-náwng rao dâi."},{"fr":"Samedi, on va au marché de Chatuchak.","tgt":"วันเสาร์ไปตลาดจตุจักรกัน","ro":"Wan sǎo pai tà-làat Jà-tù-jàk kan."},{"fr":"Là-bas, il fait une chaleur à mourir.","tgt":"ที่นั่นร้อนจะแย่","ro":"Thîi-nân ráwn jà yâe."},{"fr":"Le soir, on boit un verre sur un toit-terrasse.","tgt":"ตอนเย็นไปนั่งดื่มบนดาดฟ้ากัน","ro":"Tawn yen pai nâng dùem bon dàat-fáa kan."},{"fr":"La vue sur la ville est incroyable.","tgt":"วิวเมืองสวยสุดยอด","ro":"Wiu mueang sǔai sùt-yâwt."},{"fr":"Dimanche matin, grasse matinée pour tout le monde.","tgt":"เช้าวันอาทิตย์นอนตื่นสายกัน","ro":"Cháo wan aa-thít nawn tùen sǎai kan."},{"fr":"Ensuite, on ira manger des nouilles à Yaowarat.","tgt":"แล้วค่อยไปกินก๋วยเตี๋ยวที่เยาวราช","ro":"Láew khâwy pai kin kǔai-tǐao thîi Yao-wá-râat."},{"fr":"On rentre en car dimanche soir.","tgt":"คืนวันอาทิตย์นั่งรถทัวร์กลับ","ro":"Khuen wan aa-thít nâng rót-thua klàp."},{"fr":"Bangkok, c'est épuisant mais génial.","tgt":"กรุงเทพเหนื่อยแต่สนุกมาก","ro":"Krung-thêep nùeai tàe sà-nùk mâak."}]},{"title":"Soirée karaoké","phrases":[{"fr":"Ce soir, on va chanter au karaoké !","tgt":"คืนนี้ไปร้องคาราโอเกะกัน","ro":"Khuen-níi pai ráwng khaa-raa-oo-kè kan!"},{"fr":"Je préviens, je chante faux.","tgt":"บอกก่อนนะ เราร้องเพลงไม่เพราะเลย","ro":"Bàwk kàwn ná, rao ráwng phleeng mâi phráw loei."},{"fr":"Pas grave, c'est juste pour s'amuser.","tgt":"ไม่เป็นไรหรอก ร้องเอาสนุก","ro":"Mâi pen rai ràwk, ráwng ao sà-nùk."},{"fr":"Choisis une chanson, n'importe laquelle.","tgt":"เลือกเพลงมาสักเพลง อะไรก็ได้","ro":"Lûeak phleeng maa sàk phleeng, à-rai kâw dâi."},{"fr":"J'adore cette chanson, on l'entend partout.","tgt":"เพลงนี้ชอบมาก ได้ยินทุกที่เลย","ro":"Phleeng níi châwp mâak, dâi-yin thúk thîi loei."},{"fr":"Monte le son, on n'entend rien !","tgt":"เปิดเสียงดังๆหน่อย ไม่ได้ยินเลย","ro":"Pòet sǐang dang-dang nòi, mâi dâi-yin loei!"},{"fr":"À toi, tu chantes la suivante.","tgt":"ตาแกแล้ว ร้องเพลงต่อไปเลย","ro":"Taa kae láew, ráwng phleeng tàw pai loei."},{"fr":"En fait, tu as une très jolie voix !","tgt":"ที่แท้เสียงแกเพราะมากเลยนะ","ro":"Thîi-tháe sǐang kae phráw mâak loei ná!"},{"fr":"Le refrain, on le chante tous ensemble !","tgt":"ท่อนฮุคร้องพร้อมกันเลย","ro":"Thâwn húk ráwng phráwm kan loei!"},{"fr":"J'ai tellement crié que j'ai la voix cassée.","tgt":"ตะโกนจนเสียงแหบเลย","ro":"Tà-koon jon sǐang hàep loei."}]},{"title":"Une petite dispute","phrases":[{"fr":"Pourquoi tu ne m'as pas répondu hier ?","tgt":"ทำไมเมื่อวานไม่ตอบ","ro":"Tham-mai mûea-waan mâi tàwp?"},{"fr":"Je t'ai attendu pendant une heure entière.","tgt":"เรารอนายตั้งชั่วโมงนึง","ro":"Rao raw naai tâng chûa-moong nueng."},{"fr":"Mon téléphone n'avait plus de batterie.","tgt":"โทรศัพท์แบตหมด","ro":"Thoo-rá-sàp bàet mòt."},{"fr":"Tu aurais pu emprunter celui de quelqu'un pour m'appeler.","tgt":"ยืมของคนอื่นโทรมาก็ได้นี่","ro":"Yuem khǎwng khon ùen thoo maa kâw dâi nîi."},{"fr":"Oui, c'est ma faute, j'aurais dû te prévenir.","tgt":"ใช่ เราผิดเอง น่าจะบอกก่อน","ro":"Châi, rao phìt eeng, nâa jà bàwk kàwn."},{"fr":"Ne te fâche pas, s'il te plaît.","tgt":"อย่าโกรธเลยนะ","ro":"Yàa kròot loei ná."},{"fr":"Je ne suis pas fâché, j'étais juste inquiet.","tgt":"ไม่ได้โกรธ แค่เป็นห่วง","ro":"Mâi dâi kròot, khâe pen hùang."},{"fr":"Pardon, ce soir c'est moi qui t'offre le dîner.","tgt":"ขอโทษนะ เย็นนี้เราเลี้ยงข้าวเอง","ro":"Khǎw-thôot ná, yen-níi rao líang khâao eeng."},{"fr":"Bon, d'accord, on n'en parle plus.","tgt":"ก็ได้ ลืมๆไปเถอะ","ro":"Kâw dâi, luem-luem pai thòe."},{"fr":"Entre vrais amis, on ne reste pas fâchés longtemps.","tgt":"เพื่อนกันโกรธกันไม่นานหรอก","ro":"Phûean kan kròot kan mâi naan ràwk."}]},{"title":"Ne pas déranger les autres","phrases":[{"fr":"Je suis gêné, je ne veux pas te déranger.","tgt":"เกรงใจ ไม่อยากรบกวน","ro":"Kreeng-jai, mâi yàak róp-kuan."},{"fr":"Ne fais pas de manières, sers-toi !","tgt":"ไม่ต้องเกรงใจ ตักเลย","ro":"Mâi tâwng kreeng-jai, tàk loei!"},{"fr":"Ça me gêne, tu m'as déjà tellement aidé.","tgt":"เกรงใจจัง นายช่วยเรามาเยอะแล้ว","ro":"Kreeng-jai jang, naai chûai rao maa yóe láew."},{"fr":"Les Thaïs refusent rarement de façon directe.","tgt":"คนไทยไม่ค่อยปฏิเสธตรงๆ","ro":"Khon thai mâi khâwy pà-tì-sèet trong-trong."},{"fr":"On dit plutôt : laisse-moi d'abord y réfléchir.","tgt":"มักจะพูดว่าขอคิดดูก่อน","ro":"Mák jà phûut wâa khǎw khít duu kàwn."},{"fr":"Avec les aînés, il faut remettre le « khráp ».","tgt":"กับผู้ใหญ่ต้องพูดครับด้วย","ro":"Kàp phûu-yài tâwng phûut khráp dûai."},{"fr":"Pardon, monsieur, je ne voulais pas vous déranger.","tgt":"ขอโทษครับคุณลุง ไม่ได้ตั้งใจรบกวน","ro":"Khǎw-thôot khráp khun lung, mâi dâi tâng-jai róp-kuan."},{"fr":"Merci beaucoup de m'avoir prévenu.","tgt":"ขอบคุณมากที่บอกนะครับ","ro":"Khàwp-khun mâak thîi bàwk ná khráp."},{"fr":"Il n'a pas voulu prendre l'argent, par discrétion.","tgt":"เขาไม่รับเงินเพราะเกรงใจ","ro":"Khǎo mâi ráp ngoen phráw kreeng-jai."},{"fr":"Entre amis, pas besoin d'être aussi gêné.","tgt":"เพื่อนกัน ไม่ต้องเกรงใจขนาดนั้น","ro":"Phûean kan, mâi tâwng kreeng-jai khà-nàat nán."}],"tip":{"title":"La politesse et le « kreeng-jai »","example":"Ne fais pas de manières, sers-toi ! — ไม่ต้อง<b>เกรงใจ</b> ตักเลย","body":"Le « kreeng-jai » est une notion clé de la vie en Thaïlande : c'est la crainte de déranger, de gêner ou d'imposer quoi que ce soit aux autres. Mot à mot, « kreeng » veut dire « craindre » et « jai » « le cœur » : on ménage le cœur de l'autre. On l'entend partout : « kreeng-jai jang », « je suis vraiment gêné », quand quelqu'un vous rend service, et la réponse chaleureuse « mâi tâwng kreeng-jai », « pas besoin de te gêner », pour inviter à se servir. C'est aussi pour cela qu'on évite un « non » trop sec et qu'on préfère « khǎw khít duu kàwn », « laisse-moi d'abord y réfléchir ». Astuce : si un ami thaï hésite à accepter, insiste gentiment avec « mâi tâwng kreeng-jai ».","exampleRo":"Mâi tâwng kreeng-jai, tàk loei!","lit":"pas besoin · avoir du kreeng-jai · se servir · [vas-y]","say":{"kreeng-jai":"เกรงใจ","kreeng":"เกรง","jai":"ใจ","kreeng-jai jang":"เกรงใจจัง","mâi tâwng kreeng-jai":"ไม่ต้องเกรงใจ","khǎw khít duu kàwn":"ขอคิดดูก่อน"}}},{"title":"Garder le contact","phrases":[{"fr":"Déjà la fin des vacances, ça passe trop vite.","tgt":"หมดวันหยุดแล้ว เร็วจัง","ro":"Mòt wan-yùt láew, reo jang."},{"fr":"Je rentre à Bangkok demain matin.","tgt":"พรุ่งนี้เช้ากลับกรุงเทพแล้ว","ro":"Phrûng-níi cháo klàp Krung-thêep láew."},{"fr":"Garde mon numéro, on s'enverra des messages.","tgt":"เก็บเบอร์เราไว้นะ แล้วส่งข้อความหากัน","ro":"Kèp boe rao wái ná, láew sòng khâw-khwaam hǎa kan."},{"fr":"Si tu passes à Bangkok, viens me voir.","tgt":"ถ้ามากรุงเทพก็แวะมาหาบ้างนะ","ro":"Thâa maa Krung-thêep kâw wáe maa hǎa bâang ná."},{"fr":"Promis, je t'appellerai.","tgt":"สัญญาเลย จะโทรหา","ro":"Sǎn-yaa loei, jà thoo hǎa."},{"fr":"Tu vas me manquer, tu sais.","tgt":"จะคิดถึงนะ","ro":"Jà khít-thǔeng ná."},{"fr":"Toi aussi, prends bien soin de toi.","tgt":"เหมือนกัน ดูแลตัวเองด้วยนะ","ro":"Mǔean-kan, duu-lae tua-eeng dûai ná."},{"fr":"On se retrouve pour Loy Krathong ?","tgt":"ลอยกระทงมาเจอกันอีกไหม","ro":"Loi-krà-thong maa joe kan ìik mái?"},{"fr":"Dis bonjour à tes parents de ma part.","tgt":"ฝากสวัสดีพ่อแม่ด้วยนะ","ro":"Fàak sà-wàt-dii phâw-mâe dûai ná."},{"fr":"Bon retour, et écris-moi quand tu es arrivé.","tgt":"เดินทางปลอดภัยนะ ถึงแล้วส่งข้อความมาบอกด้วย","ro":"Doen-thaang plàwt-phai ná, thǔeng láew sòng khâw-khwaam maa bàwk dûai."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a appris à parler entre amis.","tgt":"บทนี้สอนให้เราคุยกับเพื่อนได้","ro":"Bòt níi sǎwn hâi rao khui kàp phûean dâi."},{"fr":"On sait maintenant quand laisser tomber le « khráp ».","tgt":"ตอนนี้รู้แล้วว่าเมื่อไหร่ไม่ต้องพูดครับ","ro":"Tawn-níi rúu láew wâa mûea-rài mâi tâwng phûut khráp."},{"fr":"On connaît mieux Songkran et Loy Krathong maintenant.","tgt":"เรารู้จักสงกรานต์กับลอยกระทงดีขึ้นแล้ว","ro":"Rao rúu-jàk Sǒng-kraan kàp Loi-krà-thong dii khûen láew."},{"fr":"On sait donner son avis et raconter ses souvenirs.","tgt":"เราแสดงความเห็นและเล่าความหลังได้แล้ว","ro":"Rao sà-daeng khwaam-hěn láe lâo khwaam-lǎng dâi láew."},{"fr":"On dit déjà « àat jà » et « dâi-yin wâa » sans hésiter.","tgt":"คำว่าอาจจะกับได้ยินว่าเริ่มพูดได้คล่องแล้ว","ro":"Kham wâa àat jà kàp dâi-yin wâa rôem phûut dâi khlâwng láew."},{"fr":"Et on comprend mieux le « kreeng-jai ».","tgt":"แล้วก็เข้าใจเรื่องเกรงใจมากขึ้น","ro":"Láew-kâw khâo-jai rûeang kreeng-jai mâak khûen."},{"fr":"Voilà, le niveau deux est terminé.","tgt":"ระดับสองจบแล้ว","ro":"Rá-dàp sǎwng jòp láew."},{"fr":"Le niveau trois nous attend, avec un thaï plus soutenu.","tgt":"ระดับสามรออยู่ ภาษาไทยจะสุภาพขึ้นอีก","ro":"Rá-dàp sǎam raw yùu, phaa-sǎa thai jà sù-phâap khûen ìik."},{"fr":"Bravo d'avoir persévéré jusqu'ici.","tgt":"เก่งมากที่พยายามมาตลอด","ro":"Kèng mâak thîi phá-yaa-yaam maa tà-làwt."},{"fr":"Repose-toi bien, et à très vite pour la suite.","tgt":"พักผ่อนให้เต็มที่ แล้วเจอกันบทต่อไปนะ","ro":"Phák-phàwn hâi tem-thîi, láew joe kan bòt tàw pai ná."}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée en Thaïlande, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une journée difficile au bureau","phrases":[{"fr":"Mon rapport a été critiqué par le directeur.","tgt":"รายงานของผมถูกผู้อำนวยการวิจารณ์ครับ","ro":"Raai-ngaan khǎwng phǒm thùuk phûu-am-nuay-kaan wí-jaan khráp."},{"fr":"Je me suis fait gronder par mon chef devant tout le monde.","tgt":"ผมถูกหัวหน้าดุต่อหน้าทุกคนครับ","ro":"Phǒm thùuk hǔa-nâa dù tàw-nâa thúk khon khráp."},{"fr":"Mon portefeuille a été volé dans le métro aérien.","tgt":"กระเป๋าสตางค์ของผมถูกขโมยบนรถไฟฟ้าครับ","ro":"Krà-pǎo sà-taang khǎwng phǒm thùuk khà-mooi bon rót-fai-fáa khráp."},{"fr":"La réunion a été annulée à la dernière minute.","tgt":"การประชุมถูกยกเลิกกะทันหันครับ","ro":"Kaan-prà-chum thùuk yók-lôek kà-than-hǎn khráp."},{"fr":"J'ai été invité à présenter le projet demain matin.","tgt":"ผมได้รับเชิญให้นำเสนอโครงการพรุ่งนี้เช้าครับ","ro":"Phǒm dâi-ráp choen hâi nam-sà-nǒe khroong-kaan phrûng-níi cháao khráp."},{"fr":"Ma demande de congé a encore été refusée.","tgt":"คำขอลาพักร้อนของผมถูกปฏิเสธอีกแล้วครับ","ro":"Kham-khǎw laa-phák-ráwn khǎwng phǒm thùuk pà-tì-sèet ìik láew khráp."},{"fr":"Mon collègue s'est fait licencier la semaine dernière.","tgt":"เพื่อนร่วมงานของผมถูกไล่ออกเมื่ออาทิตย์ที่แล้วครับ","ro":"Phûean-rûam-ngaan khǎwng phǒm thùuk lâi àwk mûea aa-thít thîi-láew khráp."},{"fr":"Le dossier a été envoyé au mauvais service.","tgt":"เอกสารถูกส่งไปผิดแผนกครับ","ro":"Èek-kà-sǎan thùuk sòng pai phìt phà-nàek khráp."},{"fr":"On m'a ordonné de refaire tout le travail.","tgt":"ผมถูกสั่งให้ทำงานใหม่ทั้งหมดครับ","ro":"Phǒm thùuk sàng hâi tham-ngaan mài tháng-mòt khráp."},{"fr":"Heureusement, tout a fini par s'arranger.","tgt":"แต่โชคดีที่สุดท้ายทุกอย่างก็จบลงด้วยดีครับ","ro":"Tàe chôok-dii thîi sùt-tháai thúk-yàang kâw jòp long dûay dii khráp."}],"tip":{"title":"Le passif avec « thùuk »","example":"Je me suis fait gronder par mon chef devant tout le monde. — ผม<b>ถูก</b>หัวหน้าดุต่อหน้าทุกคนครับ","body":"Pour dire qu'on a subi quelque chose, le thaï place « thùuk » devant celui qui agit, puis le verbe. Dans « phǒm thùuk hǔa-nâa dù », mot à mot « je, subir, chef, gronder », on comprend « je me suis fait gronder par le chef ». Ce passif sert surtout pour les choses désagréables : « thùuk khà-mooi », se faire voler, ou « thùuk lâi àwk », se faire licencier. Pour une bonne nouvelle, on dit plutôt « dâi-ráp », recevoir : « dâi-ráp choen », être invité. À l'oral, on entend aussi « doon », plus familier, qui veut dire la même chose. Astuce : imaginez « thùuk » comme quelque chose qui vous tombe dessus.","exampleRo":"Phǒm thùuk hǔa-nâa dù tàw-nâa thúk khon khráp.","lit":"je · [passif] · chef · gronder · devant · tous · personne · [politesse]","say":{"thùuk":"ถูก","phǒm thùuk hǔa-nâa dù":"ผมถูกหัวหน้าดุ","thùuk khà-mooi":"ถูกขโมย","thùuk lâi àwk":"ถูกไล่ออก","dâi-ráp":"ได้รับ","dâi-ráp choen":"ได้รับเชิญ","doon":"โดน"}}},{"title":"Hiérarchie et kreng-jai","phrases":[{"fr":"En Thaïlande, au travail, on respecte beaucoup les plus anciens.","tgt":"ในที่ทำงานที่เมืองไทย คนเคารพผู้อาวุโสมากครับ","ro":"Nai thîi-tham-ngaan thîi mueang-thai khon khao-róp phûu aa-wú-sǒo mâak khráp."},{"fr":"Je n'ose pas contredire mon chef pendant la réunion.","tgt":"ผมไม่กล้าเถียงหัวหน้าในที่ประชุมครับ","ro":"Phǒm mâi klâa thǐang hǔa-nâa nai thîi-prà-chum khráp."},{"fr":"Le kreng-jai, c'est ne pas vouloir déranger les autres.","tgt":"เกรงใจคือการไม่อยากรบกวนคนอื่นครับ","ro":"Kreeng-jai khue kaan mâi yàak róp-kuan khon ùen khráp."},{"fr":"Elle ne dit jamais non directement, par kreng-jai.","tgt":"เธอไม่เคยปฏิเสธตรงๆเพราะเกรงใจครับ","ro":"Thoe mâi khoei pà-tì-sèet trong-trong phráw kreeng-jai khráp."},{"fr":"Il vaut mieux poser ses questions après la réunion.","tgt":"ถามคำถามหลังประชุมจะดีกว่าครับ","ro":"Thǎam kham-thǎam lǎng prà-chum jà dii kwàa khráp."},{"fr":"J'appelle mon chef « grand frère » parce qu'il est plus âgé.","tgt":"ผมเรียกหัวหน้าว่าพี่เพราะเขาอายุมากกว่าครับ","ro":"Phǒm rîak hǔa-nâa wâa phîi phráw khǎo aa-yú mâak kwàa khráp."},{"fr":"Quand on mange ensemble, c'est souvent l'aîné qui paie.","tgt":"เวลากินข้าวด้วยกัน ผู้ใหญ่มักจะเป็นคนจ่ายครับ","ro":"Wee-laa kin khâao dûay-kan phûu-yài mák jà pen khon jàai khráp."},{"fr":"Je ne veux pas qu'il perde la face devant son équipe.","tgt":"ผมไม่อยากให้เขาเสียหน้าต่อหน้าลูกน้องครับ","ro":"Phǒm mâi yàak hâi khǎo sǐa-nâa tàw-nâa lûuk-náwng khráp."},{"fr":"Sourire d'abord aide souvent à éviter les problèmes.","tgt":"ยิ้มไว้ก่อนมักจะช่วยเลี่ยงปัญหาได้ครับ","ro":"Yím wái kàwn mák jà chûay lîang pan-hǎa dâi khráp."},{"fr":"Avec le temps, j'ai appris à deviner ce que les gens pensent.","tgt":"พออยู่นานๆผมก็เริ่มอ่านใจคนออกครับ","ro":"Phaw yùu naan-naan phǒm kâw rôem àan jai khon àwk khráp."}]},{"title":"Déléguer au bureau","phrases":[{"fr":"J'ai fait imprimer le contrat par ma secrétaire.","tgt":"ผมให้เลขาพิมพ์สัญญาครับ","ro":"Phǒm hâi lee-khǎa phim sǎn-yaa khráp."},{"fr":"Le chef nous a fait rester jusqu'à vingt heures.","tgt":"หัวหน้าให้พวกเราอยู่ถึงสองทุ่มครับ","ro":"Hǔa-nâa hâi phûak-rao yùu thǔeng sǎwng thûm khráp."},{"fr":"Pourriez-vous faire vérifier ce document par le service juridique ?","tgt":"ช่วยให้ฝ่ายกฎหมายตรวจเอกสารนี้หน่อยได้ไหมครับ","ro":"Chûay hâi fàai kòt-mǎai trùat èek-kà-sǎan níi nàwy dâi mái khráp?"},{"fr":"Ce week-end, je vais faire réparer la climatisation.","tgt":"เสาร์อาทิตย์นี้ผมจะให้ช่างมาซ่อมแอร์ครับ","ro":"Sǎo aa-thít níi phǒm jà hâi châang maa sâwm ae khráp."},{"fr":"Le propriétaire nous a fait payer deux mois d'avance.","tgt":"เจ้าของห้องให้เราจ่ายล่วงหน้าสองเดือนครับ","ro":"Jâo-khǎwng hâwng hâi rao jàai lûang-nâa sǎwng duean khráp."},{"fr":"Le directeur a fait supprimer toutes les dépenses inutiles.","tgt":"ผู้อำนวยการให้ตัดค่าใช้จ่ายที่ไม่จำเป็นออกทั้งหมดครับ","ro":"Phûu-am-nuay-kaan hâi tàt khâa-chái-jàai thîi mâi jam-pen àwk tháng-mòt khráp."},{"fr":"Ne me faites pas attendre trop longtemps, s'il vous plaît.","tgt":"อย่าให้ผมรอนานนะครับ","ro":"Yàa hâi phǒm raw naan ná khráp."},{"fr":"Mon chef me laisse travailler de chez moi le vendredi.","tgt":"หัวหน้าให้ผมทำงานที่บ้านทุกวันศุกร์ครับ","ro":"Hǔa-nâa hâi phǒm tham-ngaan thîi bâan thúk wan-sùk khráp."},{"fr":"J'ai fait traduire le contrat en français.","tgt":"ผมให้คนแปลสัญญาเป็นภาษาฝรั่งเศสครับ","ro":"Phǒm hâi khon plae sǎn-yaa pen phaa-sǎa fà-ràng-sèet khráp."},{"fr":"Il faut faire signer ce formulaire par le directeur.","tgt":"ต้องให้ผู้อำนวยการเซ็นแบบฟอร์มนี้ครับ","ro":"Tâwng hâi phûu-am-nuay-kaan sen bàep-fawm níi khráp."}],"tip":{"title":"Faire faire avec « hâi »","example":"J'ai fait imprimer le contrat par ma secrétaire. — ผม<b>ให้</b>เลขาพิมพ์สัญญาครับ","body":"Le verbe « hâi », donner, sert aussi à faire faire quelque chose à quelqu'un. L'ordre est simple : celui qui décide, puis « hâi », puis celui qui agit, puis l'action. « Phǒm hâi lee-khǎa phim sǎn-yaa », mot à mot « je, faire, secrétaire, imprimer, contrat », veut dire « j'ai fait imprimer le contrat par ma secrétaire ». Selon la situation, « hâi » signifie demander, laisser ou obliger : « hǔa-nâa hâi phǒm tham-ngaan thîi bâan », le chef me laisse travailler chez moi. À la forme négative, on dit « yàa hâi phǒm raw », ne me faites pas attendre. Astuce : retenez l'image de quelqu'un qui « donne » une action à faire à un autre.","exampleRo":"Phǒm hâi lee-khǎa phim sǎn-yaa khráp.","lit":"je · faire · secrétaire · imprimer · contrat · [politesse]","say":{"hâi":"ให้","Phǒm hâi lee-khǎa phim sǎn-yaa":"ผมให้เลขาพิมพ์สัญญา","hǔa-nâa hâi phǒm tham-ngaan thîi bâan":"หัวหน้าให้ผมทำงานที่บ้าน","yàa hâi phǒm raw":"อย่าให้ผมรอ"}}},{"title":"Les embouteillages de Bangkok","phrases":[{"fr":"Sur Sukhumvit, ça bouchonne énormément à cette heure-ci.","tgt":"ถนนสุขุมวิทรถติดหนักมากเวลานี้ครับ","ro":"Thà-nǒn sù-khǔm-wít rót tìt nàk mâak wee-laa níi khráp."},{"fr":"Je pars de chez moi dès six heures pour fuir les bouchons.","tgt":"ผมออกจากบ้านตั้งแต่หกโมงเช้าเพื่อหนีรถติดครับ","ro":"Phǒm àwk jàak bâan tâng-tàe hòk moong cháao phûea nǐi rót tìt khráp."},{"fr":"Quand il pleut, les bouchons sont deux fois pires.","tgt":"เวลาฝนตก รถจะติดหนักกว่าเดิมสองเท่าครับ","ro":"Wee-laa fǒn tòk rót jà tìt nàk kwàa doem sǎwng thâo khráp."},{"fr":"Aux heures de pointe, le métro aérien est plus rapide que le taxi.","tgt":"ช่วงชั่วโมงเร่งด่วน รถไฟฟ้าเร็วกว่าแท็กซี่ครับ","ro":"Chûang chûa-moong rêng-dùan rót-fai-fáa reo kwàa tháek-sîi khráp."},{"fr":"Je prends souvent un moto-taxi pour aller jusqu'au bureau.","tgt":"ผมมักจะต่อวินมอเตอร์ไซค์ไปที่ทำงานครับ","ro":"Phǒm mák jà tàw win maw-toe-sai pai thîi-tham-ngaan khráp."},{"fr":"Il m'a fallu une heure et demie pour faire cinq kilomètres.","tgt":"ผมใช้เวลาชั่วโมงครึ่งกว่าจะไปได้ห้ากิโลครับ","ro":"Phǒm chái wee-laa chûa-moong khrûeng kwàa jà pai dâi hâa kì-loo khráp."},{"fr":"Mon collègue est encore en retard à cause de la circulation.","tgt":"เพื่อนร่วมงานมาสายอีกแล้วเพราะรถติดครับ","ro":"Phûean-rûam-ngaan maa sǎai ìik láew phráw rót tìt khráp."},{"fr":"On devrait décaler la réunion à dix heures.","tgt":"เราน่าจะเลื่อนประชุมไปเป็นสิบโมงครับ","ro":"Rao nâa jà lûean prà-chum pai pen sìp moong khráp."},{"fr":"Pendant le trajet, j'écoute la radio.","tgt":"ระหว่างทางผมฟังวิทยุไปด้วยครับ","ro":"Rá-wàang thaang phǒm fang wít-thá-yú pai dûay khráp."},{"fr":"À Bangkok, il faut toujours prévoir du temps en plus.","tgt":"อยู่กรุงเทพต้องเผื่อเวลาไว้เสมอครับ","ro":"Yùu krung-thêep tâwng phùea wee-laa wái sà-mǒe khráp."}]},{"title":"Négocier un contrat","phrases":[{"fr":"Si vous signez aujourd'hui, nous vous faisons dix pour cent de remise.","tgt":"ถ้าคุณเซ็นวันนี้ เราจะลดให้สิบเปอร์เซ็นต์ครับ","ro":"Thâa khun sen wan-níi rao jà lót hâi sìp poe-sen khráp."},{"fr":"Si le prix baisse un peu, on peut en discuter.","tgt":"ถ้าราคาลดลงอีกนิด เราก็คุยกันได้ครับ","ro":"Thâa raa-khaa lót long ìik nít rao kâw khui kan dâi khráp."},{"fr":"Si j'étais vous, je relirais chaque clause attentivement.","tgt":"ถ้าผมเป็นคุณ ผมจะอ่านทุกข้อให้ละเอียดครับ","ro":"Thâa phǒm pen khun phǒm jà àan thúk khâw hâi lá-ìat khráp."},{"fr":"Que se passe-t-il si le projet prend du retard ?","tgt":"ถ้าโครงการล่าช้า จะเกิดอะไรขึ้นครับ","ro":"Thâa khroong-kaan lâa-cháa jà kòet à-rai khûen khráp?"},{"fr":"Si vous payez d'avance, la livraison est gratuite.","tgt":"ถ้าจ่ายล่วงหน้า ไม่มีค่าส่งครับ","ro":"Thâa jàai lûang-nâa mâi mii khâa sòng khráp."},{"fr":"Nous avons besoin de deux semaines de plus.","tgt":"เราต้องการเวลาเพิ่มอีกสองอาทิตย์ครับ","ro":"Rao tâwng-kaan wee-laa phôem ìik sǎwng aa-thít khráp."},{"fr":"Si vous n'êtes pas d'accord, dites-le-moi franchement.","tgt":"ถ้าคุณไม่เห็นด้วย บอกผมตรงๆได้เลยครับ","ro":"Thâa khun mâi hěn dûay bàwk phǒm trong-trong dâi loei khráp."},{"fr":"Voici notre dernière offre.","tgt":"นี่คือข้อเสนอสุดท้ายของเราครับ","ro":"Nîi khue khâw-sà-nǒe sùt-tháai khǎwng rao khráp."},{"fr":"Si tout va bien, nous signerons la semaine prochaine.","tgt":"ถ้าทุกอย่างเรียบร้อย เราจะเซ็นสัญญากันอาทิตย์หน้าครับ","ro":"Thâa thúk-yàang rîap-ráwy rao jà sen sǎn-yaa kan aa-thít nâa khráp."},{"fr":"Ne vous inquiétez pas, nous trouverons sûrement un accord.","tgt":"ไม่ต้องห่วงครับ เราหาทางตกลงกันได้แน่นอน","ro":"Mâi tâwng hùang khráp, rao hǎa thaang tòk-long kan dâi nâe-nawn."}],"tip":{"title":"Les hypothèses avec « thâa »","example":"Si le prix baisse un peu, on peut en discuter. — <b>ถ้า</b>ราคาลดลงอีกนิด เรา<b>ก็</b>คุยกันได้ครับ","body":"Pour poser une condition, on commence par « thâa », si, et on annonce la suite avec « kâw », alors, ou avec « jà », la marque du futur. « Thâa raa-khaa lót long ìik nít, rao kâw khui kan dâi » se décompose en « si, prix, baisser, encore un peu, nous, alors, discuter, pouvoir ». Le verbe ne change jamais : « si j'étais vous » se dit simplement « thâa phǒm pen khun », mot à mot « si je suis vous ». C'est le contexte qui dit si l'hypothèse est réelle ou imaginaire. En négociation, « thâa » suivi de « kâw » sonne souple et ouvert, ce qui plaît beaucoup. Astuce : « thâa » ouvre la porte, « kâw » la referme.","exampleRo":"Thâa raa-khaa lót long ìik nít rao kâw khui kan dâi khráp.","lit":"si · prix · baisser · descendre · encore · un peu · nous · alors · discuter · ensemble · pouvoir · [politesse]","say":{"thâa":"ถ้า","kâw":"ก็","jà":"จะ","Thâa raa-khaa lót long ìik nít, rao kâw khui kan dâi":"ถ้าราคาลดลงอีกนิด เราก็คุยกันได้","thâa phǒm pen khun":"ถ้าผมเป็นคุณ"}}},{"title":"La réunion d'équipe","phrases":[{"fr":"La réunion commence à quatorze heures précises.","tgt":"ประชุมเริ่มบ่ายสองโมงตรงครับ","ro":"Prà-chum rôem bàai sǎwng moong trong khráp."},{"fr":"Qui va prendre les notes aujourd'hui ?","tgt":"วันนี้ใครจะจดบันทึกการประชุมครับ","ro":"Wan-níi khrai jà jòt ban-thúek kaan-prà-chum khráp?"},{"fr":"Je voudrais ajouter un point à l'ordre du jour.","tgt":"ผมขอเพิ่มอีกหนึ่งวาระครับ","ro":"Phǒm khǎw phôem ìik nùeng waa-rá khráp."},{"fr":"Pouvez-vous partager votre écran ?","tgt":"ช่วยแชร์หน้าจอหน่อยได้ไหมครับ","ro":"Chûay chae nâa-jaw nàwy dâi mái khráp?"},{"fr":"Les ventes ont augmenté de quinze pour cent ce trimestre.","tgt":"ยอดขายไตรมาสนี้เพิ่มขึ้นสิบห้าเปอร์เซ็นต์ครับ","ro":"Yâwt-khǎai trai-mâat níi phôem khûen sìp-hâa poe-sen khráp."},{"fr":"Je ne suis pas sûr d'avoir bien compris.","tgt":"ผมไม่แน่ใจว่าเข้าใจถูกหรือเปล่าครับ","ro":"Phǒm mâi nâe-jai wâa khâo-jai thùuk rǔe-plàao khráp."},{"fr":"On en reparlera la semaine prochaine.","tgt":"เรื่องนี้ไว้คุยกันต่ออาทิตย์หน้านะครับ","ro":"Rûeang níi wái khui kan tàw aa-thít nâa ná khráp."},{"fr":"Chacun doit envoyer son bilan avant vendredi.","tgt":"ทุกคนต้องส่งสรุปงานก่อนวันศุกร์ครับ","ro":"Thúk khon tâwng sòng sà-rùp ngaan kàwn wan-sùk khráp."},{"fr":"Personne n'a osé poser de question.","tgt":"ไม่มีใครกล้าถามอะไรเลยครับ","ro":"Mâi mii khrai klâa thǎam à-rai loei khráp."},{"fr":"Merci à tous, la séance est levée.","tgt":"ขอบคุณทุกคนครับ ขอปิดการประชุมเพียงเท่านี้","ro":"Khàwp-khun thúk khon khráp, khǎw pìt kaan-prà-chum phiang thâo-níi."}]},{"title":"Choisir une assurance santé","phrases":[{"fr":"Mon entreprise ne fournit que l'assurance de base.","tgt":"บริษัทให้แค่ประกันพื้นฐานครับ","ro":"Baw-rí-sàt hâi khâe prà-kan phúen-thǎan khráp."},{"fr":"Je cherche une assurance qui couvre les hôpitaux privés.","tgt":"ผมกำลังหาประกันที่จ่ายค่าโรงพยาบาลเอกชนได้ครับ","ro":"Phǒm kam-lang hǎa prà-kan thîi jàai khâa roong-phá-yaa-baan èek-kà-chon dâi khráp."},{"fr":"Combien coûte la prime par an ?","tgt":"เบี้ยประกันต่อปีเท่าไหร่ครับ","ro":"Bîa prà-kan tàw pii thâo-rài khráp?"},{"fr":"Est-ce que les soins dentaires sont inclus ?","tgt":"รวมค่าทำฟันด้วยไหมครับ","ro":"Ruam khâa tham fan dûay mái khráp?"},{"fr":"Les maladies déjà présentes ne sont pas couvertes.","tgt":"โรคที่เป็นอยู่ก่อนแล้วประกันไม่คุ้มครองครับ","ro":"Rôok thîi pen yùu kàwn láew prà-kan mâi khúm-khrawng khráp."},{"fr":"Il y a une franchise de cinq mille bahts.","tgt":"มีค่าเสียหายส่วนแรกห้าพันบาทครับ","ro":"Mii khâa-sǐa-hǎai sùan râek hâa phan bàat khráp."},{"fr":"Il faut attendre trente jours avant d'être couvert.","tgt":"ต้องรอสามสิบวันก่อนประกันจะเริ่มคุ้มครองครับ","ro":"Tâwng raw sǎam-sìp wan kàwn prà-kan jà rôem khúm-khrawng khráp."},{"fr":"Pouvez-vous m'envoyer les conditions du contrat par courriel ?","tgt":"ช่วยส่งเงื่อนไขกรมธรรม์มาทางอีเมลได้ไหมครับ","ro":"Chûay sòng ngûean-khǎi krom-má-than maa thaang ii-meo dâi mái khráp?"},{"fr":"Je préfère payer un peu plus cher pour être tranquille.","tgt":"ผมยอมจ่ายแพงขึ้นนิดหน่อยเพื่อความสบายใจครับ","ro":"Phǒm yawm jàai phaeng khûen nít-nàwy phûea khwaam sà-baai-jai khráp."},{"fr":"Je vais comparer trois compagnies avant de décider.","tgt":"ผมจะเปรียบเทียบสามเจ้าก่อนตัดสินใจครับ","ro":"Phǒm jà prìap-thîap sǎam jâo kàwn tàt-sǐn-jai khráp."}]},{"title":"Le déménagement","phrases":[{"fr":"Même le canapé n'a pas pu passer la porte.","tgt":"แม้แต่โซฟาก็เข้าประตูไม่ได้ครับ","ro":"Mâe-tàe soo-faa kâw khâo prà-tuu mâi dâi khráp."},{"fr":"Même mes voisins sont venus m'aider à porter les cartons.","tgt":"แม้แต่เพื่อนบ้านก็มาช่วยผมขนกล่องครับ","ro":"Mâe-tàe phûean-bâan kâw maa chûay phǒm khǒn klàwng khráp."},{"fr":"J'ai engagé des déménageurs pour samedi.","tgt":"ผมจ้างบริษัทขนของไว้วันเสาร์ครับ","ro":"Phǒm jâang baw-rí-sàt khǒn khǎwng wái wan-sǎo khráp."},{"fr":"Le nouveau condo est plus proche du métro aérien.","tgt":"คอนโดใหม่ใกล้รถไฟฟ้ากว่าเดิมครับ","ro":"Khawn-doo mài klâi rót-fai-fáa kwàa doem khráp."},{"fr":"Aujourd'hui, je n'ai même pas eu le temps de manger.","tgt":"วันนี้ผมไม่มีเวลาแม้แต่จะกินข้าวครับ","ro":"Wan-níi phǒm mâi mii wee-laa mâe-tàe jà kin khâao khráp."},{"fr":"Même un enfant pourrait monter cette armoire.","tgt":"แม้แต่เด็กก็ประกอบตู้นี้ได้ครับ","ro":"Mâe-tàe dèk kâw prà-kàwp tûu níi dâi khráp."},{"fr":"Il faut prévenir le propriétaire un mois à l'avance.","tgt":"ต้องบอกเจ้าของห้องล่วงหน้าหนึ่งเดือนครับ","ro":"Tâwng bàwk jâo-khǎwng hâwng lûang-nâa nùeng duean khráp."},{"fr":"Le gardien ne connaît même pas encore mon nom.","tgt":"ยามยังไม่รู้แม้แต่ชื่อผมเลยครับ","ro":"Yaam yang mâi rúu mâe-tàe chûe phǒm loei khráp."},{"fr":"J'ai récupéré ma caution sans aucun problème.","tgt":"ผมได้เงินประกันคืนโดยไม่มีปัญหาครับ","ro":"Phǒm dâi ngoen prà-kan khuen dooi mâi mii pan-hǎa khráp."},{"fr":"Au bout d'une semaine, tout était enfin rangé.","tgt":"ผ่านไปหนึ่งอาทิตย์ ทุกอย่างก็เข้าที่สักทีครับ","ro":"Phàan pai nùeng aa-thít thúk-yàang kâw khâo thîi sàk-thii khráp."}],"tip":{"title":"« Mâe-tàe » : même","example":"Même le canapé n'a pas pu passer la porte. — <b>แม้แต่</b>โซฟา<b>ก็</b>เข้าประตูไม่ได้ครับ","body":"Pour insister comme avec notre « même », on place « mâe-tàe » juste devant le mot visé, puis on ajoute souvent « kâw » avant le verbe. « Mâe-tàe soo-faa kâw khâo prà-tuu mâi dâi » se décompose en « même, canapé, aussi, entrer, porte, ne pas pouvoir ». Dans une phrase négative, « mâe-tàe » vient après le verbe : « mâi rúu mâe-tàe chûe », il ne connaît même pas le nom. On dit aussi « mâi mii wee-laa mâe-tàe jà kin khâao », pas même le temps de manger. Astuce : « mâe-tàe » se pose toujours devant ce qui vous surprend.","exampleRo":"Mâe-tàe soo-faa kâw khâo prà-tuu mâi dâi khráp.","lit":"même · canapé · aussi · entrer · porte · ne pas · pouvoir · [politesse]","say":{"Mâe-tàe":"แม้แต่","mâe-tàe":"แม้แต่","kâw":"ก็","Mâe-tàe soo-faa kâw khâo prà-tuu mâi dâi":"แม้แต่โซฟาก็เข้าประตูไม่ได้","mâi rúu mâe-tàe chûe":"ไม่รู้แม้แต่ชื่อ","mâi mii wee-laa mâe-tàe jà kin khâao":"ไม่มีเวลาแม้แต่จะกินข้าว"}}},{"title":"Le télétravail","phrases":[{"fr":"Je travaille de chez moi trois jours par semaine.","tgt":"ผมทำงานที่บ้านอาทิตย์ละสามวันครับ","ro":"Phǒm tham-ngaan thîi bâan aa-thít lá sǎam wan khráp."},{"fr":"La connexion a coupé en pleine réunion.","tgt":"อินเทอร์เน็ตหลุดกลางประชุมเลยครับ","ro":"In-thoe-nét lùt klaang prà-chum loei khráp."},{"fr":"Votre micro est coupé, on ne vous entend pas.","tgt":"ไมค์ของคุณปิดอยู่ เราไม่ได้ยินเสียงครับ","ro":"Mai khǎwng khun pìt yùu rao mâi dâi-yin sǐang khráp."},{"fr":"J'ai installé un petit coin bureau dans ma chambre.","tgt":"ผมจัดมุมทำงานเล็กๆไว้ในห้องนอนครับ","ro":"Phǒm jàt mum tham-ngaan lék-lék wái nai hâwng-nawn khráp."},{"fr":"Sans trajet, je gagne deux heures par jour.","tgt":"ไม่ต้องเดินทาง ผมประหยัดเวลาได้วันละสองชั่วโมงครับ","ro":"Mâi tâwng doen-thaang phǒm prà-yàt wee-laa dâi wan lá sǎwng chûa-moong khráp."},{"fr":"Le plus difficile, c'est de s'arrêter le soir.","tgt":"ที่ยากที่สุดคือการเลิกงานตอนเย็นครับ","ro":"Thîi yâak thîi-sùt khue kaan lôek ngaan tawn yen khráp."},{"fr":"Mes collègues me manquent un peu.","tgt":"ผมคิดถึงเพื่อนร่วมงานนิดหน่อยครับ","ro":"Phǒm khít-thǔeng phûean-rûam-ngaan nít-nàwy khráp."},{"fr":"Nous allons au bureau le jeudi pour nous voir.","tgt":"เราเข้าออฟฟิศวันพฤหัสเพื่อเจอกันครับ","ro":"Rao khâo áwp-fít wan phá-rúe-hàt phûea joe kan khráp."},{"fr":"Sans la climatisation, il fait trop chaud pour travailler.","tgt":"ไม่เปิดแอร์นี่ร้อนจนทำงานไม่ไหวเลยครับ","ro":"Mâi pòet ae nîi ráwn jon tham-ngaan mâi wǎi loei khráp."},{"fr":"Parfois, je vais travailler dans un café du quartier.","tgt":"บางทีผมก็ไปนั่งทำงานที่ร้านกาแฟแถวบ้านครับ","ro":"Baang-thii phǒm kâw pai nâng tham-ngaan thîi ráan kaa-fae thǎeo bâan khráp."}]},{"title":"Ouvrir un compte en banque","phrases":[{"fr":"Je voudrais ouvrir un compte d'épargne.","tgt":"ผมอยากเปิดบัญชีออมทรัพย์ครับ","ro":"Phǒm yàak pòet ban-chii awm-sáp khráp."},{"fr":"Quels documents dois-je apporter ?","tgt":"ต้องใช้เอกสารอะไรบ้างครับ","ro":"Tâwng chái èek-kà-sǎan à-rai bâang khráp?"},{"fr":"Il faut une attestation de résidence.","tgt":"ต้องมีหนังสือรับรองที่อยู่ครับ","ro":"Tâwng mii nǎng-sǔe ráp-rawng thîi-yùu khráp."},{"fr":"Le passeport et le permis de travail, est-ce suffisant ?","tgt":"พาสปอร์ตกับใบอนุญาตทำงานพอไหมครับ","ro":"Pháat-sà-pàwt kàp bai à-nú-yâat tham-ngaan phaw mái khráp?"},{"fr":"Je voudrais aussi une carte de débit.","tgt":"ผมขอบัตรเดบิตด้วยครับ","ro":"Phǒm khǎw bàt dee-bìt dûay khráp."},{"fr":"Comment activer l'application de la banque sur mon téléphone ?","tgt":"เปิดใช้แอปธนาคารในมือถือยังไงครับ","ro":"Pòet chái áep thá-naa-khaan nai mue-thǔe yang-ngai khráp?"},{"fr":"Après un virement, combien de jours faut-il attendre ?","tgt":"โอนเงินแล้วกี่วันถึงจะเข้าครับ","ro":"Oon ngoen láew kìi wan thǔeng jà khâo khráp?"},{"fr":"Mon salaire est versé le vingt-cinq de chaque mois.","tgt":"เงินเดือนผมเข้าทุกวันที่ยี่สิบห้าครับ","ro":"Ngoen-duean phǒm khâo thúk wan-thîi yîi-sìp-hâa khráp."},{"fr":"Les frais de virement sont assez élevés.","tgt":"ค่าธรรมเนียมการโอนค่อนข้างแพงครับ","ro":"Khâa-tham-niam kaan oon khâwn-khâang phaeng khráp."},{"fr":"On fait longtemps la queue, même pour une petite question.","tgt":"แม้แต่จะถามเรื่องเล็กๆก็ต้องรอคิวนานครับ","ro":"Mâe-tàe jà thǎam rûeang lék-lék kâw tâwng raw khiu naan khráp."}]},{"title":"Renouveler son permis de travail","phrases":[{"fr":"Mon permis de travail expire le mois prochain.","tgt":"ใบอนุญาตทำงานของผมจะหมดอายุเดือนหน้าครับ","ro":"Bai à-nú-yâat tham-ngaan khǎwng phǒm jà mòt aa-yú duean nâa khráp."},{"fr":"C'est le service du personnel qui s'occupe du dossier.","tgt":"ฝ่ายบุคคลเป็นคนดูแลเรื่องเอกสารครับ","ro":"Fàai bùk-khon pen khon duu-lae rûeang èek-kà-sǎan khráp."},{"fr":"Il faut un certificat médical récent.","tgt":"ต้องมีใบรับรองแพทย์ฉบับใหม่ครับ","ro":"Tâwng mii bai ráp-rawng phâet chà-bàp mài khráp."},{"fr":"J'ai dû faire la queue toute la matinée.","tgt":"ผมต้องรอคิวทั้งเช้าเลยครับ","ro":"Phǒm tâwng raw khiu tháng cháao loei khráp."},{"fr":"Il manque une copie signée de mon passeport.","tgt":"ขาดสำเนาพาสปอร์ตที่เซ็นรับรองแล้วหนึ่งใบครับ","ro":"Khàat sǎm-nao pháat-sà-pàwt thîi sen ráp-rawng láew nùeng bai khráp."},{"fr":"Chaque page doit être signée à la main.","tgt":"ทุกหน้าต้องเซ็นด้วยมือครับ","ro":"Thúk nâa tâwng sen dûay mue khráp."},{"fr":"Le guichet ferme à quinze heures trente.","tgt":"เคาน์เตอร์ปิดบ่ายสามโมงครึ่งครับ","ro":"Khao-tôe pìt bàai sǎam moong khrûeng khráp."},{"fr":"Veuillez revenir la semaine prochaine avec les pièces manquantes.","tgt":"กรุณากลับมาใหม่อาทิตย์หน้าพร้อมเอกสารที่ขาดครับ","ro":"Kà-rú-naa klàp maa mài aa-thít nâa phráwm èek-kà-sǎan thîi khàat khráp."},{"fr":"Est-ce que je peux faire la démarche en ligne ?","tgt":"ผมทำเรื่องทางออนไลน์ได้ไหมครับ","ro":"Phǒm tham rûeang thaang awn-lai dâi mái khráp?"},{"fr":"Finalement, j'ai obtenu le renouvellement pour un an.","tgt":"ในที่สุดผมก็ได้ต่ออายุอีกหนึ่งปีครับ","ro":"Nai thîi-sùt phǒm kâw dâi tàw aa-yú ìik nùeng pii khráp."}]},{"title":"Le thaï formel du bureau","phrases":[{"fr":"Je me permets de vous informer que la réunion est reportée.","tgt":"ขอเรียนให้ทราบว่าการประชุมเลื่อนออกไปครับ","ro":"Khǎw rian hâi sâap wâa kaan-prà-chum lûean àwk pai khráp."},{"fr":"Permettez-moi de prendre la parole un instant.","tgt":"ขออนุญาตพูดสักครู่นะครับ","ro":"Khǎw à-nú-yâat phûut sàk khrûu ná khráp."},{"fr":"Veuillez trouver ci-joint le rapport mensuel.","tgt":"ขอส่งรายงานรายเดือนมาพร้อมนี้ครับ","ro":"Khǎw sòng raai-ngaan raai-duean maa phráwm níi khráp."},{"fr":"Nous allons procéder immédiatement.","tgt":"เราจะดำเนินการทันทีครับ","ro":"Rao jà dam-noen-kaan than-thii khráp."},{"fr":"Monsieur le directeur pourrait-il me recevoir ?","tgt":"ท่านผู้อำนวยการสะดวกให้เข้าพบไหมครับ","ro":"Thân phûu-am-nuay-kaan sà-dùak hâi khâo phóp mái khráp?"},{"fr":"J'ai bien reçu votre courriel, je vous remercie.","tgt":"ได้รับอีเมลเรียบร้อยแล้วครับ ขอบคุณครับ","ro":"Dâi-ráp ii-meo rîap-ráwy láew khráp, khàwp-khun khráp."},{"fr":"Veuillez confirmer votre présence avant vendredi.","tgt":"กรุณายืนยันการเข้าร่วมก่อนวันศุกร์ครับ","ro":"Kà-rú-naa yuen-yan kaan khâo-rûam kàwn wan-sùk khráp."},{"fr":"Nous vous prions d'excuser la gêne occasionnée.","tgt":"ขออภัยในความไม่สะดวกครับ","ro":"Khǎw à-phai nai khwaam mâi sà-dùak khráp."},{"fr":"Pourriez-vous préciser ce point, je vous prie ?","tgt":"รบกวนช่วยอธิบายประเด็นนี้เพิ่มเติมได้ไหมครับ","ro":"Róp-kuan chûay à-thí-baai prà-den níi phôem-toem dâi mái khráp?"},{"fr":"Pour toute question, n'hésitez pas à me contacter.","tgt":"หากมีข้อสงสัยประการใด ติดต่อผมได้ตลอดครับ","ro":"Hàak mii khâw-sǒng-sǎi prà-kaan dai tìt-tàw phǒm dâi tà-làwt khráp."}],"tip":{"title":"Le thaï formel du bureau","example":"Je me permets de vous informer que la réunion est reportée. — <b>ขอเรียนให้ทราบ</b>ว่าการประชุมเลื่อนออกไปครับ","body":"Au bureau, surtout avec un supérieur ou dans un courriel, le thaï change de vocabulaire plutôt que de grammaire. On remplace « bàwk », dire, par « rian », et « rúu », savoir, par « sâap » : « khǎw rian hâi sâap », mot à mot « demander, informer, faire, savoir », équivaut à « je me permets de vous informer ». « Tham », faire, devient « dam-noen-kaan », procéder, et « thâa », si, devient « hàak ». Pour demander poliment, on commence par « kà-rú-naa », veuillez, ou par « róp-kuan », littéralement « je vous dérange ». Devant le titre d'un directeur, on ajoute « thân » par respect. Astuce : apprenez ces formules d'un bloc et dites-les lentement, avec un « khráp » bien posé.","exampleRo":"Khǎw rian hâi sâap wâa kaan-prà-chum lûean àwk pai khráp.","lit":"demander · informer · faire · savoir · que · réunion · reporter · sortir · aller · [politesse]","say":{"bàwk":"บอก","rian":"เรียน","rúu":"รู้","sâap":"ทราบ","khǎw rian hâi sâap":"ขอเรียนให้ทราบ","Tham":"ทำ","dam-noen-kaan":"ดำเนินการ","thâa":"ถ้า","hàak":"หาก","kà-rú-naa":"กรุณา","róp-kuan":"รบกวน","thân":"ท่าน","khráp":"ครับ"}}},{"title":"Chercher un appartement","phrases":[{"fr":"Je cherche un condo à louer près de la station Asok.","tgt":"ผมกำลังหาคอนโดให้เช่าใกล้สถานีอโศกครับ","ro":"Phǒm kam-lang hǎa khawn-doo hâi châo klâi sà-thǎa-nii à-sòok khráp."},{"fr":"Le loyer est de vingt mille bahts par mois.","tgt":"ค่าเช่าเดือนละสองหมื่นบาทครับ","ro":"Khâa châo duean lá sǎwng mùen bàat khráp."},{"fr":"Les charges communes sont-elles comprises ?","tgt":"รวมค่าส่วนกลางแล้วหรือยังครับ","ro":"Ruam khâa sùan-klaang láew rǔe yang khráp?"},{"fr":"Il faut payer deux mois de caution.","tgt":"ต้องจ่ายเงินประกันสองเดือนครับ","ro":"Tâwng jàai ngoen prà-kan sǎwng duean khráp."},{"fr":"L'appartement est-il entièrement meublé ?","tgt":"ห้องมีเฟอร์นิเจอร์ครบไหมครับ","ro":"Hâwng mii foe-ní-joe khróp mái khráp?"},{"fr":"Je préfère un étage élevé, parce que c'est plus calme.","tgt":"ผมชอบชั้นสูงๆ เพราะเงียบกว่าครับ","ro":"Phǒm châwp chán sǔung-sǔung phráw ngîap kwàa khráp."},{"fr":"Le bail est d'un an minimum.","tgt":"สัญญาเช่าขั้นต่ำหนึ่งปีครับ","ro":"Sǎn-yaa châo khân-tàm nùeng pii khráp."},{"fr":"Peut-on visiter samedi après-midi ?","tgt":"ขอดูห้องวันเสาร์ตอนบ่ายได้ไหมครับ","ro":"Khǎw duu hâwng wan-sǎo tawn bàai dâi mái khráp?"},{"fr":"L'eau et l'électricité se paient à part.","tgt":"ค่าน้ำค่าไฟแยกจ่ายต่างหากครับ","ro":"Khâa náam khâa fai yâek jàai tàang-hàak khráp."},{"fr":"Ce quartier me plaît beaucoup, je prends cet appartement.","tgt":"ผมชอบย่านนี้มาก เอาห้องนี้เลยครับ","ro":"Phǒm châwp yâan níi mâak ao hâwng níi loei khráp."}]},{"title":"Une fuite d'eau dans le condo","phrases":[{"fr":"De l'eau coule du plafond de la salle de bain.","tgt":"เพดานห้องน้ำมีน้ำรั่วครับ","ro":"Phee-daan hâwng-náam mii náam rûa khráp."},{"fr":"J'ai déjà appelé le service technique de l'immeuble.","tgt":"ผมโทรหาฝ่ายช่างของคอนโดแล้วครับ","ro":"Phǒm thoo hǎa fàai châang khǎwng khawn-doo láew khráp."},{"fr":"Le technicien passera demain entre neuf et onze heures.","tgt":"ช่างจะมาพรุ่งนี้ระหว่างเก้าโมงถึงสิบเอ็ดโมงครับ","ro":"Châang jà maa phrûng-níi rá-wàang kâo moong thǔeng sìp-èt moong khráp."},{"fr":"Le voisin du dessus n'était pas du tout au courant.","tgt":"เพื่อนบ้านชั้นบนไม่รู้เรื่องเลยครับ","ro":"Phûean-bâan chán bon mâi rúu rûeang loei khráp."},{"fr":"Mon ordinateur a été endommagé par l'eau.","tgt":"คอมของผมโดนน้ำเสียหายครับ","ro":"Khawm khǎwng phǒm doon náam sǐa-hǎai khráp."},{"fr":"Qui va payer les réparations ?","tgt":"ใครจะเป็นคนจ่ายค่าซ่อมครับ","ro":"Khrai jà pen khon jàai khâa sâwm khráp?"},{"fr":"Prenez des photos avant de nettoyer.","tgt":"ถ่ายรูปไว้ก่อนทำความสะอาดนะครับ","ro":"Thàai rûup wái kàwn tham khwaam-sà-àat ná khráp."},{"fr":"Le syndic a promis de s'en occuper.","tgt":"นิติบุคคลรับปากว่าจะจัดการให้ครับ","ro":"Ní-tì-bùk-khon ráp-pàak wâa jà jàt-kaan hâi khráp."},{"fr":"Si ça recommence, je déménage pour de bon.","tgt":"ถ้าเป็นอีก ผมย้ายออกแน่ครับ","ro":"Thâa pen ìik phǒm yáai àwk nâe khráp."},{"fr":"Finalement, la réparation n'a pris qu'une heure.","tgt":"สุดท้ายซ่อมแค่ชั่วโมงเดียวก็เสร็จครับ","ro":"Sùt-tháai sâwm khâe chûa-moong diao kâw sèt khráp."}]},{"title":"La fête de fin d'année au bureau","phrases":[{"fr":"La fête de fin d'année de l'entreprise se tient dans un hôtel.","tgt":"งานเลี้ยงปีใหม่ของบริษัทจัดที่โรงแรมครับ","ro":"Ngaan-líang pii-mài khǎwng baw-rí-sàt jàt thîi roong-raem khráp."},{"fr":"Chaque service doit préparer un spectacle.","tgt":"ทุกแผนกต้องเตรียมการแสดงครับ","ro":"Thúk phà-nàek tâwng triam kaan sà-daeng khráp."},{"fr":"Il y a un tirage au sort avec beaucoup de lots.","tgt":"มีจับฉลากของรางวัลเยอะมากครับ","ro":"Mii jàp-chà-làak khǎwng-raang-wan yóe mâak khráp."},{"fr":"Tout le monde doit venir habillé en blanc.","tgt":"ทุกคนต้องแต่งชุดสีขาวมาครับ","ro":"Thúk khon tâwng tàeng chút sǐi khǎao maa khráp."},{"fr":"J'ai gagné un bon d'achat de trois mille bahts.","tgt":"ผมได้บัตรกำนัลสามพันบาทครับ","ro":"Phǒm dâi bàt kam-nan sǎam phan bàat khráp."},{"fr":"Le directeur a fait un discours très court.","tgt":"ผู้อำนวยการกล่าวสุนทรพจน์สั้นๆครับ","ro":"Phûu-am-nuay-kaan klàao sǔn-thaw-rá-phót sân-sân khráp."},{"fr":"Tout le monde s'est bien amusé au karaoké.","tgt":"ทุกคนร้องคาราโอเกะกันสนุกมากครับ","ro":"Thúk khon ráwng khaa-raa-oo-kè kan sà-nùk mâak khráp."},{"fr":"C'est l'occasion de discuter avec les autres services.","tgt":"เป็นโอกาสได้คุยกับคนแผนกอื่นครับ","ro":"Pen oo-kàat dâi khui kàp khon phà-nàek ùen khráp."},{"fr":"Mon chef m'a servi à boire, j'étais très gêné.","tgt":"หัวหน้ารินเครื่องดื่มให้ผม ผมเกรงใจมากครับ","ro":"Hǔa-nâa rin khrûeang-dùem hâi phǒm phǒm kreeng-jai mâak khráp."},{"fr":"La soirée s'est terminée vers minuit.","tgt":"งานเลิกประมาณเที่ยงคืนครับ","ro":"Ngaan lôek prà-maan thîang-khuen khráp."}]},{"title":"Chez le médecin","phrases":[{"fr":"J'ai de la fièvre depuis hier soir.","tgt":"ผมมีไข้ตั้งแต่เมื่อคืนครับ","ro":"Phǒm mii khâi tâng-tàe mûea-khuen khráp."},{"fr":"Je voudrais un rendez-vous avec un médecin généraliste.","tgt":"ผมขอนัดหมอทั่วไปครับ","ro":"Phǒm khǎw nát mǎw thûa-pai khráp."},{"fr":"Avez-vous votre carte d'assurance ?","tgt":"มีบัตรประกันไหมครับ","ro":"Mii bàt prà-kan mái khráp?"},{"fr":"Le médecin m'a prescrit des antibiotiques.","tgt":"หมอสั่งยาฆ่าเชื้อให้ผมครับ","ro":"Mǎw sàng yaa khâa-chúea hâi phǒm khráp."},{"fr":"Prenez ce médicament après les repas, trois fois par jour.","tgt":"ทานยานี้หลังอาหาร วันละสามครั้งนะครับ","ro":"Thaan yaa níi lǎng aa-hǎan wan lá sǎam khráng ná khráp."},{"fr":"J'ai besoin d'un certificat d'arrêt maladie pour deux jours.","tgt":"ผมขอใบรับรองแพทย์ลาป่วยสองวันครับ","ro":"Phǒm khǎw bai ráp-rawng phâet laa pùay sǎwng wan khráp."},{"fr":"L'assurance a tout pris en charge directement.","tgt":"ประกันจ่ายให้ทั้งหมดเลยครับ","ro":"Prà-kan jàai hâi tháng-mòt loei khráp."},{"fr":"Évitez les plats épicés pendant quelques jours.","tgt":"งดอาหารเผ็ดสักสองสามวันนะครับ","ro":"Ngót aa-hǎan phèt sàk sǎwng sǎam wan ná khráp."},{"fr":"Si ça ne va pas mieux, revenez me voir.","tgt":"ถ้าอาการไม่ดีขึ้น กลับมาหาหมออีกนะครับ","ro":"Thâa aa-kaan mâi dii khûen klàp maa hǎa mǎw ìik ná khráp."},{"fr":"Je me sens déjà beaucoup mieux.","tgt":"ผมรู้สึกดีขึ้นเยอะแล้วครับ","ro":"Phǒm rúu-sùek dii khûen yóe láew khráp."}]},{"title":"La vie en condo","phrases":[{"fr":"La piscine est ouverte de six heures à vingt et une heures.","tgt":"สระว่ายน้ำเปิดหกโมงเช้าถึงสามทุ่มครับ","ro":"Sà wâai-náam pòet hòk moong cháao thǔeng sǎam thûm khráp."},{"fr":"Le bureau de la copropriété garde nos colis.","tgt":"นิติจะเก็บพัสดุไว้ให้ครับ","ro":"Ní-tì jà kèp phát-sà-dù wái hâi khráp."},{"fr":"Il est interdit de faire sécher le linge sur le balcon.","tgt":"ห้ามตากผ้าที่ระเบียงครับ","ro":"Hâam tàak phâa thîi rá-biang khráp."},{"fr":"Les animaux sont interdits dans ce condo.","tgt":"คอนโดนี้ห้ามเลี้ยงสัตว์ครับ","ro":"Khawn-doo níi hâam líang sàt khráp."},{"fr":"Mon voisin fait du bruit tard le soir.","tgt":"เพื่อนบ้านผมเสียงดังตอนดึกๆครับ","ro":"Phûean-bâan phǒm sǐang dang tawn dùek-dùek khráp."},{"fr":"Je n'ose pas aller me plaindre directement.","tgt":"ผมไม่กล้าไปต่อว่าเขาตรงๆครับ","ro":"Phǒm mâi klâa pai tàw-wâa khǎo trong-trong khráp."},{"fr":"Les charges communes augmentent l'an prochain.","tgt":"ค่าส่วนกลางจะขึ้นปีหน้าครับ","ro":"Khâa sùan-klaang jà khûen pii nâa khráp."},{"fr":"La salle de sport est pleine tous les soirs.","tgt":"ฟิตเนสคนเต็มทุกเย็นครับ","ro":"Fít-nét khon tem thúk yen khráp."},{"fr":"Les gardiens d'ici sont gentils et très serviables.","tgt":"ยามที่นี่ใจดีและช่วยเหลือดีมากครับ","ro":"Yaam thîi-nîi jai-dii láe chûay-lǔea dii mâak khráp."},{"fr":"Il y a une assemblée des copropriétaires dimanche.","tgt":"วันอาทิตย์มีประชุมเจ้าของร่วมครับ","ro":"Wan aa-thít mii prà-chum jâo-khǎwng rûam khráp."}]},{"title":"Un entretien d'embauche","phrases":[{"fr":"Pourriez-vous vous présenter brièvement ?","tgt":"ช่วยแนะนำตัวสั้นๆหน่อยครับ","ro":"Chûay náe-nam tua sân-sân nàwy khráp."},{"fr":"J'ai cinq ans d'expérience dans le marketing.","tgt":"ผมมีประสบการณ์ด้านการตลาดห้าปีครับ","ro":"Phǒm mii prà-sòp-kaan dâan kaan-tà-làat hâa pii khráp."},{"fr":"Pourquoi voulez-vous quitter votre poste actuel ?","tgt":"ทำไมถึงอยากลาออกจากงานปัจจุบันครับ","ro":"Tham-mai thǔeng yàak laa-àwk jàak ngaan pàt-jù-ban khráp?"},{"fr":"Je cherche un poste avec plus de responsabilités.","tgt":"ผมอยากได้งานที่รับผิดชอบมากขึ้นครับ","ro":"Phǒm yàak dâi ngaan thîi ráp-phìt-châwp mâak khûen khráp."},{"fr":"Quel salaire espérez-vous ?","tgt":"คาดหวังเงินเดือนเท่าไหร่ครับ","ro":"Khâat-wǎng ngoen-duean thâo-rài khráp?"},{"fr":"Je peux commencer dès le mois prochain.","tgt":"ผมเริ่มงานได้ตั้งแต่เดือนหน้าครับ","ro":"Phǒm rôem ngaan dâi tâng-tàe duean nâa khráp."},{"fr":"Quels sont les avantages pour les employés ?","tgt":"มีสวัสดิการอะไรบ้างครับ","ro":"Mii sà-wàt-dì-kaan à-rai bâang khráp?"},{"fr":"La période d'essai dure trois mois.","tgt":"ทดลองงานสามเดือนครับ","ro":"Thót-lawng ngaan sǎam duean khráp."},{"fr":"Nous vous recontacterons d'ici une semaine.","tgt":"เราจะติดต่อกลับภายในหนึ่งอาทิตย์ครับ","ro":"Rao jà tìt-tàw klàp phaai-nai nùeng aa-thít khráp."},{"fr":"Je crois que l'entretien s'est bien passé.","tgt":"ผมคิดว่าสัมภาษณ์ผ่านไปได้ด้วยดีครับ","ro":"Phǒm khít wâa sǎm-phâat phàan pai dâi dûay dii khráp."}]},{"title":"Trouver son équilibre","phrases":[{"fr":"Je ne lis pas mes courriels de travail les jours de congé.","tgt":"ผมไม่อ่านอีเมลงานในวันหยุดครับ","ro":"Phǒm mâi àan ii-meo ngaan nai wan-yùt khráp."},{"fr":"Le dimanche, je vais courir au parc Lumphini.","tgt":"วันอาทิตย์ผมไปวิ่งที่สวนลุมพินีครับ","ro":"Wan aa-thít phǒm pai wîng thîi sǔan lum-phí-nii khráp."},{"fr":"À trop travailler, tout le monde finit épuisé.","tgt":"ทำงานหนักเกินไป สุดท้ายทุกคนก็หมดไฟครับ","ro":"Tham-ngaan nàk koen pai sùt-tháai thúk khon kâw mòt fai khráp."},{"fr":"J'ai pris trois jours de congé pour me reposer.","tgt":"ผมลาพักร้อนสามวันเพื่อพักผ่อนครับ","ro":"Phǒm laa-phák-ráwn sǎam wan phûea phák-phàwn khráp."},{"fr":"Mon médecin m'a conseillé de dormir davantage.","tgt":"หมอแนะนำให้ผมนอนมากขึ้นครับ","ro":"Mǎw náe-nam hâi phǒm nawn mâak khûen khráp."},{"fr":"Je cuisine moi-même le soir, ça me détend.","tgt":"ตอนเย็นผมทำกับข้าวเอง รู้สึกผ่อนคลายดีครับ","ro":"Tawn yen phǒm tham kàp-khâao eeng rúu-sùek phàwn-khlaai dii khráp."},{"fr":"Le travail compte, mais la santé passe avant tout.","tgt":"งานสำคัญก็จริง แต่สุขภาพต้องมาก่อนครับ","ro":"Ngaan sǎm-khan kâw jing tàe sùk-khà-phâap tâwng maa kàwn khráp."},{"fr":"Ici, on aime dire qu'il ne faut pas trop se stresser.","tgt":"ที่นี่คนชอบพูดว่าอย่าเครียดมากครับ","ro":"Thîi-nîi khon châwp phûut wâa yàa khrîat mâak khráp."},{"fr":"J'aime m'asseoir pour regarder la vue sur la ville.","tgt":"ผมชอบนั่งดูวิวเมืองครับ","ro":"Phǒm châwp nâng duu wiu mueang khráp."},{"fr":"J'ai enfin trouvé mon rythme de vie à Bangkok.","tgt":"ในที่สุดผมก็เจอจังหวะชีวิตที่กรุงเทพแล้วครับ","ro":"Nai thîi-sùt phǒm kâw joe jang-wà chii-wít thîi krung-thêep láew khráp."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait découvrir la vie professionnelle à Bangkok.","tgt":"บทเรียนชุดนี้พาเราไปรู้จักชีวิตการทำงานที่กรุงเทพครับ","ro":"Bòt-rian chút níi phaa rao pai rúu-jàk chii-wít kaan tham-ngaan thîi krung-thêep khráp."},{"fr":"On sait maintenant parler poliment en réunion.","tgt":"ตอนนี้เราพูดในที่ประชุมอย่างสุภาพได้แล้วครับ","ro":"Tawn-níi rao phûut nai thîi-prà-chum yàang sù-phâap dâi láew khráp."},{"fr":"Nous savons maintenant utiliser le mot « thùuk ».","tgt":"เรารู้จักใช้คำว่าถูกแล้วครับ","ro":"Rao rúu-jàk chái kham wâa thùuk láew khráp."},{"fr":"On sait aussi confier des tâches aux autres avec « hâi ».","tgt":"เราใช้คำว่าให้เพื่อสั่งงานคนอื่นได้ด้วยครับ","ro":"Rao chái kham wâa hâi phûea sàng ngaan khon ùen dâi dûay khráp."},{"fr":"Le kreng-jai nous aide à mieux comprendre nos collègues.","tgt":"ความเกรงใจช่วยให้เราเข้าใจเพื่อนร่วมงานมากขึ้นครับ","ro":"Khwaam kreeng-jai chûay hâi rao khâo-jai phûean-rûam-ngaan mâak khûen khráp."},{"fr":"Le thaï formel ne nous fait plus aussi peur.","tgt":"ภาษาไทยแบบทางการไม่น่ากลัวเหมือนเดิมแล้วครับ","ro":"Phaa-sǎa thai bàep thaang-kaan mâi nâa-klua mǔean doem láew khráp."},{"fr":"Même les démarches semblent plus simples maintenant.","tgt":"แม้แต่การทำเอกสารก็ดูง่ายขึ้นครับ","ro":"Mâe-tàe kaan tham èek-kà-sǎan kâw duu ngâai khûen khráp."},{"fr":"Le prochain module nous emmènera en voyage.","tgt":"บทต่อไปเราจะออกเดินทางท่องเที่ยวกันครับ","ro":"Bòt tàw pai rao jà àwk doen-thaang thâwng-thîao kan khráp."},{"fr":"Faisons une petite pause avant de continuer.","tgt":"พักกันสักหน่อยก่อนไปต่อนะครับ","ro":"Phák kan sàk nàwy kàwn pai tàw ná khráp."},{"fr":"Bravo à vous, et à très bientôt !","tgt":"เก่งมากครับ แล้วเจอกันใหม่เร็วๆนี้","ro":"Kèng mâak khráp, láew joe kan mài reo-reo níi."}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Khon Kaen, au cœur de l'Isan","phrases":[{"fr":"Nous voici enfin à Khon Kaen, au cœur de l'Isan.","tgt":"ในที่สุดเราก็มาถึงขอนแก่น ใจกลางภาคอีสาน","ro":"Nai thîi-sùt rao kâw maa thǔeng khǎwn-kàen, jai-klaang phâak ii-sǎan."},{"fr":"Les touristes étrangers ne viennent pas beaucoup dans cette région.","tgt":"นักท่องเที่ยวต่างชาติมาภาคนี้ไม่ค่อยเยอะ","ro":"Nák-thâwng-thîao tàang-châat maa phâak níi mâi khâwy yóe."},{"fr":"Les gens de l'Isan sont réputés pour leur gentillesse.","tgt":"คนอีสานขึ้นชื่อเรื่องความใจดี","ro":"Khon ii-sǎan khûen-chûe rûeang khwaam-jai-dii."},{"fr":"La ville est plus moderne que ce que j'imaginais.","tgt":"เมืองนี้ทันสมัยกว่าที่ผมคิดไว้","ro":"Mueang níi than-sà-mǎi kwàa thîi phǒm khít wái."},{"fr":"On a loué une voiture pour faire le tour de la province.","tgt":"เราเช่ารถมาขับเที่ยวรอบๆจังหวัด","ro":"Rao châo rót maa khàp thîao râwp râwp jang-wàt."},{"fr":"Les routes de l'Isan sont longues et toutes droites.","tgt":"ถนนในภาคอีสานยาวและตรง","ro":"Thà-nǒn nai phâak ii-sǎan yaao láe trong."},{"fr":"Le long de la route, on ne voit que des rizières.","tgt":"ระหว่างทางเราเห็นแต่นาข้าว","ro":"Rá-wàang thaang rao hěn tàe naa-khâao."},{"fr":"Le paysage change beaucoup selon la saison.","tgt":"ทิวทัศน์เปลี่ยนไปมากตามฤดูกาล","ro":"Thiu-thát plìan pai mâak taam rúe-duu-kaan."},{"fr":"Le soir, on cherche un endroit simple pour dormir.","tgt":"ตอนเย็นเราหาที่พักง่ายๆ","ro":"Tawn-yen rao hǎa thîi-phák ngâai ngâai."},{"fr":"Ce voyage commence vraiment très bien.","tgt":"ทริปนี้เริ่มต้นได้ดีมากจริงๆ","ro":"Tríp níi rôem-tôn dâi dii mâak jing jing."}]},{"title":"Un guide qui connaît bien la région","phrases":[{"fr":"Le guide qui nous accompagne est né à Khon Kaen.","tgt":"ไกด์ที่พาเราเที่ยวเกิดที่ขอนแก่น","ro":"Kái thîi phaa rao thîao kòet thîi khǎwn-kàen."},{"fr":"C'est la personne qui connaît le mieux la région.","tgt":"เขาเป็นคนที่รู้จักภาคนี้ดีที่สุด","ro":"Khǎo pen khon thîi rúu-jàk phâak níi dii thîi-sùt."},{"fr":"Il nous emmène dans des villages que peu de touristes connaissent.","tgt":"เขาพาเราไปหมู่บ้านที่นักท่องเที่ยวไม่ค่อยรู้จัก","ro":"Khǎo phaa rao pai mùu-bâan thîi nák-thâwng-thîao mâi khâwy rúu-jàk."},{"fr":"Le plat qu'il nous a fait goûter était très épicé.","tgt":"อาหารที่เขาให้เราชิมเผ็ดมาก","ro":"Aa-hǎan thîi khǎo hâi rao chim phèt mâak."},{"fr":"L'histoire qu'il raconte sur ce village est passionnante.","tgt":"เรื่องที่เขาเล่าเกี่ยวกับหมู่บ้านนี้น่าสนใจมาก","ro":"Rûeang thîi khǎo lâo kìao-kàp mùu-bâan níi nâa-sǒn-jai mâak."},{"fr":"La femme qui tisse la soie est sa tante.","tgt":"ผู้หญิงที่ทอผ้าไหมเป็นป้าของเขา","ro":"Phûu-yǐng thîi thaw phâa-mǎi pen pâa khǎwng khǎo."},{"fr":"Elle vend au marché les tissus qu'elle tisse elle-même.","tgt":"เธอเอาผ้าที่ทอเองไปขายที่ตลาด","ro":"Thoe ao phâa thîi thaw eeng pai khǎai thîi tà-làat."},{"fr":"J'aimerais acheter l'écharpe que vous m'avez montrée tout à l'heure.","tgt":"ผมอยากซื้อผ้าพันคอที่คุณให้ผมดูเมื่อกี้ครับ","ro":"Phǒm yàak súe phâa-phan-khaw thîi khun hâi phǒm duu mûea-kíi khráp."},{"fr":"Les gens que nous rencontrons ici nous accueillent chaleureusement.","tgt":"คนที่เราเจอที่นี่ต้อนรับเราอย่างอบอุ่น","ro":"Khon thîi rao joe thîi-nîi tâwn-ráp rao yàang òp-ùn."},{"fr":"C'est exactement le genre de voyage que je cherchais depuis longtemps.","tgt":"นี่คือการเที่ยวแบบที่ผมตามหามานาน","ro":"Nîi khue kaan-thîao bàep thîi phǒm taam-hǎa maa naan."}],"tip":{"title":"Les relatives avec « thîi »","example":"Le guide qui nous accompagne est né à Khon Kaen. — ไกด์<b>ที่</b>พาเราเที่ยวเกิดที่ขอนแก่น","body":"En thaï, pour dire « le guide qui nous accompagne », on place simplement « thîi » juste après le nom, puis on ajoute la description : « kái thîi phaa rao thîao », mot à mot « guide qui emmène nous visiter ». Contrairement au français, il n'y a aucune différence entre « qui », « que » ou « où » : un seul petit mot, « thîi », fait tout le travail. Par exemple, « aa-hǎan thîi khǎo tham » veut dire « le plat qu'il prépare », et « mùu-bâan thîi rao pai » veut dire « le village où nous allons ». Attention, le même mot « thîi » signifie aussi « à » devant un lieu, comme dans « kòet thîi khǎwn-kàen », né à Khon Kaen. Pour retenir, voyez « thîi » comme un crochet qui accroche une description derrière le nom, toujours avec son ton descendant.","exampleRo":"Kái thîi phaa rao thîao kòet thîi khǎwn-kàen.","lit":"guide · [qui] · emmener · nous · visiter · naître · à · Khon Kaen","say":{"thîi":"ที่","kái thîi phaa rao thîao":"ไกด์ที่พาเราเที่ยว","aa-hǎan thîi khǎo tham":"อาหารที่เขาทำ","mùu-bâan thîi rao pai":"หมู่บ้านที่เราไป","kòet thîi khǎwn-kàen":"เกิดที่ขอนแก่น"}}},{"title":"Le lac aux lotus rouges d'Udon Thani","phrases":[{"fr":"On se lève dès cinq heures du matin pour aller voir le lac aux lotus rouges.","tgt":"เราตื่นตั้งแต่ตีห้าไปดูทะเลบัวแดง","ro":"Rao tùen tâng-tàe tii hâa pai duu thá-lee-bua-daeng."},{"fr":"Les fleurs ne s'ouvrent qu'au petit matin.","tgt":"ดอกบัวบานแค่ตอนเช้าตรู่","ro":"Dàwk-bua baan khâe tawn-cháao-trùu."},{"fr":"La meilleure période, c'est de décembre à février.","tgt":"ช่วงที่ดีที่สุดคือเดือนธันวาคมถึงกุมภาพันธ์","ro":"Chûang thîi dii thîi-sùt khue duean than-waa-khom thǔeng kum-phaa-phan."},{"fr":"On fait le tour du lac en petit bateau.","tgt":"เรานั่งเรือลำเล็กชมรอบทะเลสาบ","ro":"Rao nâng ruea lam lék chom râwp thá-lee-sàap."},{"fr":"Partout où l'on regarde, on ne voit que des fleurs roses sur l'eau.","tgt":"มองไปทางไหนก็เห็นแต่ดอกบัวสีชมพูบนน้ำ","ro":"Mawng pai thaang nǎi kâw hěn tàe dàwk-bua sǐi chom-phuu bon náam."},{"fr":"Le batelier coupe le moteur et le silence s'installe.","tgt":"คนขับเรือดับเครื่อง แล้วทุกอย่างก็เงียบสงบ","ro":"Khon khàp ruea dàp khrûeang, láew thúk-yàang kâw ngîap-sà-ngòp."},{"fr":"Il est interdit de cueillir les fleurs de lotus.","tgt":"ห้ามเด็ดดอกบัว","ro":"Hâam dèt dàwk-bua."},{"fr":"La lumière du matin rend le lac encore plus beau.","tgt":"แสงตอนเช้าทำให้ทะเลสาบสวยยิ่งขึ้น","ro":"Sǎeng tawn-cháao tham-hâi thá-lee-sàap sǔai yîng khûen."},{"fr":"Il vaut mieux venir avant que la chaleur n'arrive.","tgt":"มาก่อนอากาศร้อนจะดีกว่า","ro":"Maa kàwn aa-kàat ráwn jà dii kwàa."},{"fr":"C'est l'un des plus beaux spectacles naturels du pays.","tgt":"นี่เป็นหนึ่งในภาพธรรมชาติที่สวยที่สุดของประเทศ","ro":"Nîi pen nùeng nai phâap tham-má-châat thîi sǔai thîi-sùt khǎwng prà-thêet."}]},{"title":"Préparer une randonnée à Khao Yai","phrases":[{"fr":"Nous partons tôt pour éviter la chaleur.","tgt":"เราออกเดินทางแต่เช้าเพื่อหลบอากาศร้อน","ro":"Rao àwk doen-thaang tàe cháao phûea lòp aa-kàat ráwn."},{"fr":"Nous prenons un guide pour ne pas nous perdre dans la forêt.","tgt":"เราจ้างไกด์เพื่อจะได้ไม่หลงป่า","ro":"Rao jâang kái phûea jà dâi mâi lǒng pàa."},{"fr":"Il faut acheter un billet pour entrer dans le parc national.","tgt":"ต้องซื้อตั๋วเพื่อเข้าอุทยานแห่งชาติ","ro":"Tâwng súe tǔa phûea khâo ùt-thá-yaan hàeng-châat."},{"fr":"Je porte des guêtres anti-sangsues pour qu'elles ne s'accrochent pas à mes jambes.","tgt":"ผมใส่ถุงกันทากเพื่อไม่ให้ทากเกาะขา","ro":"Phǒm sài thǔng-kan-thâak phûea mâi hâi thâak kàw khǎa."},{"fr":"Nous emportons beaucoup d'eau pour en avoir assez toute la journée.","tgt":"เราพกน้ำไปเยอะเพื่อให้พอตลอดวัน","ro":"Rao phók náam pai yóe phûea hâi phaw tà-làwt wan."},{"fr":"Le guide se lève avant l'aube pour vérifier la météo.","tgt":"ไกด์ตื่นแต่เช้ามืดเพื่อเช็กสภาพอากาศ","ro":"Kái tùen tàe cháao-mûet phûea chék sà-phâap aa-kàat."},{"fr":"On parle à voix basse pour ne pas effrayer les animaux.","tgt":"เราพูดเบาๆเพื่อไม่ให้สัตว์ตกใจ","ro":"Rao phûut bao bao phûea mâi hâi sàt tòk-jai."},{"fr":"Ce sentier a été aménagé pour protéger la forêt.","tgt":"เส้นทางนี้ถูกสร้างขึ้นเพื่อปกป้องป่า","ro":"Sên-thaang níi thùuk sâang khûen phûea pòk-pâwng pàa."},{"fr":"Je fais du sport depuis un mois pour être prêt physiquement.","tgt":"ผมออกกำลังกายมาหนึ่งเดือนแล้วเพื่อให้ร่างกายพร้อม","ro":"Phǒm àwk-kam-lang-kaai maa nùeng duean láew phûea hâi râang-kaai phráwm."},{"fr":"Nous sommes venus ici pour voir des calaos en liberté.","tgt":"เรามาที่นี่เพื่อดูนกเงือกในธรรมชาติ","ro":"Rao maa thîi-nîi phûea duu nók-ngûeak nai tham-má-châat."}],"tip":{"title":"« Phûea » : pour, afin de","example":"Nous partons tôt pour éviter la chaleur. — เราออกเดินทางแต่เช้า<b>เพื่อ</b>หลบอากาศร้อน","body":"« Phûea » se place devant un verbe pour dire « pour » ou « afin de », exactement comme en français : « rao àwk doen-thaang tàe cháao phûea lòp aa-kàat ráwn », mot à mot « nous partons dès le matin pour éviter temps chaud ». Le verbe qui suit ne change jamais de forme, il suffit de l'accoler. Pour dire « pour ne pas », on ajoute « mâi hâi », littéralement « ne pas laisser » : « phûea mâi hâi sàt tòk-jai », pour ne pas effrayer les animaux. Vous entendrez aussi « phûea jà dâi », pour pouvoir, comme dans « phûea jà dâi mâi lǒng pàa », pour ne pas se perdre dans la forêt. À l'oral, soignez le ton descendant de « phûea », qui part haut et retombe, comme une petite affirmation décidée.","exampleRo":"Rao àwk doen-thaang tàe cháao phûea lòp aa-kàat ráwn.","lit":"nous · sortir · voyager · dès · matin · [pour] · éviter · temps · chaud","say":{"Phûea":"เพื่อ","rao àwk doen-thaang tàe cháao phûea lòp aa-kàat ráwn":"เราออกเดินทางแต่เช้าเพื่อหลบอากาศร้อน","mâi hâi":"ไม่ให้","phûea mâi hâi sàt tòk-jai":"เพื่อไม่ให้สัตว์ตกใจ","phûea jà dâi":"เพื่อจะได้","phûea jà dâi mâi lǒng pàa":"เพื่อจะได้ไม่หลงป่า","phûea":"เพื่อ"}}},{"title":"Observer les animaux à Khao Yai","phrases":[{"fr":"Le guide a repéré un groupe de gibbons dans les arbres.","tgt":"ไกด์เห็นชะนีฝูงหนึ่งอยู่บนต้นไม้","ro":"Kái hěn chá-nii fǔung nùeng yùu bon tôn-mái."},{"fr":"On les entend chanter avant même de les voir.","tgt":"เราได้ยินเสียงร้องของมันก่อนจะเห็นตัวเสียอีก","ro":"Rao dâi-yin sǐang ráwng khǎwng man kàwn jà hěn tua sǐa ìik."},{"fr":"Ce soir, nous ferons un safari de nuit en voiture.","tgt":"คืนนี้เราจะนั่งรถส่องสัตว์ตอนกลางคืน","ro":"Khuen níi rao jà nâng rót sàwng sàt tawn klaang-khuen."},{"fr":"Dans le faisceau de la lampe, on aperçoit les yeux d'un cerf.","tgt":"พอส่องไฟ เราก็เห็นตาของกวาง","ro":"Phaw sàwng fai, rao kâw hěn taa khǎwng kwaang."},{"fr":"Parfois, des éléphants sauvages traversent la route.","tgt":"บางครั้งช้างป่าก็เดินข้ามถนน","ro":"Baang khráng cháang-pàa kâw doen khâam thà-nǒn."},{"fr":"Dans ce cas, il faut s'arrêter et garder ses distances.","tgt":"ถ้าเจอแบบนั้นต้องหยุดรถและอยู่ห่างๆ","ro":"Thâa joe bàep nán tâwng yùt rót láe yùu hàang hàang."},{"fr":"Il est strictement interdit de nourrir les singes.","tgt":"ห้ามให้อาหารลิงเด็ดขาด","ro":"Hâam hâi aa-hǎan ling dèt-khàat."},{"fr":"Les singes qui volent la nourriture des touristes deviennent agressifs.","tgt":"ลิงที่ขโมยอาหารนักท่องเที่ยวจะดุขึ้น","ro":"Ling thîi khà-mooi aa-hǎan nák-thâwng-thîao jà dù khûen."},{"fr":"On a eu la chance de voir un calao passer au-dessus de nous.","tgt":"เราโชคดีที่ได้เห็นนกเงือกบินผ่านหัว","ro":"Rao chôok-dii thîi dâi hěn nók-ngûeak bin phàan hǔa."},{"fr":"Cette forêt abrite des centaines d'espèces d'animaux.","tgt":"ป่านี้เป็นที่อยู่ของสัตว์หลายร้อยชนิด","ro":"Pàa níi pen thîi-yùu khǎwng sàt lǎai ráwy chá-nít."}]},{"title":"Un sanctuaire éthique pour éléphants","phrases":[{"fr":"Ce sanctuaire accueille des éléphants qui ont été exploités autrefois.","tgt":"ศูนย์นี้รับดูแลช้างที่เคยถูกใช้งานมาก่อน","ro":"Sǔun níi ráp duu-lae cháang thîi khoei thùuk chái-ngaan maa kàwn."},{"fr":"Ici, personne ne monte sur le dos des éléphants.","tgt":"ที่นี่ไม่มีการขี่ช้าง","ro":"Thîi-nîi mâi mii kaan khìi cháang."},{"fr":"On les regarde de loin pendant qu'ils se baignent.","tgt":"เราดูพวกมันอาบน้ำอยู่ห่างๆ","ro":"Rao duu phûak man àap-náam yùu hàang hàang."},{"fr":"Les cornacs nous racontent l'histoire de chaque éléphant.","tgt":"ควาญช้างเล่าประวัติของช้างแต่ละตัวให้เราฟัง","ro":"Khwaan-cháang lâo prà-wàt khǎwng cháang tàe-lá tua hâi rao fang."},{"fr":"Cette femelle a été sauvée il y a dix ans.","tgt":"ช้างพังตัวนี้ถูกช่วยออกมาเมื่อสิบปีก่อน","ro":"Cháang-phang tua níi thùuk chûai àwk maa mûea sìp pii kàwn."},{"fr":"Elle avait été blessée en travaillant dans la forêt.","tgt":"มันเคยบาดเจ็บตอนทำงานในป่า","ro":"Man khoei bàat-jèp tawn tham-ngaan nai pàa."},{"fr":"On aide à préparer leur repas : des bananes et de la canne à sucre.","tgt":"เราช่วยเตรียมอาหารให้ช้าง มีกล้วยกับอ้อย","ro":"Rao chûai triam aa-hǎan hâi cháang, mii klûai kàp âwy."},{"fr":"Un éléphant adulte mange plus de cent kilos par jour.","tgt":"ช้างโตตัวหนึ่งกินอาหารวันละมากกว่าร้อยกิโล","ro":"Cháang too tua nùeng kin aa-hǎan wan lá mâak kwàa ráwy kì-loo."},{"fr":"Avant de choisir un camp d'éléphants, renseignez-vous bien.","tgt":"ก่อนเลือกปางช้าง ควรหาข้อมูลให้ดีก่อน","ro":"Kàwn lûeak paang-cháang, khuan hǎa khâw-muun hâi dii kàwn."},{"fr":"Voir ces éléphants vivre librement m'a beaucoup ému.","tgt":"การได้เห็นช้างใช้ชีวิตอย่างอิสระทำให้ผมซึ้งใจมาก","ro":"Kaan dâi hěn cháang chái-chii-wít yàang ìt-sà-rà tham-hâi phǒm sûeng-jai mâak."}]},{"title":"Organiser son séjour à Pai","phrases":[{"fr":"J'ai réservé un bungalow à Pai il y a deux semaines.","tgt":"ผมจองบังกะโลที่ปายไว้ตั้งแต่สองอาทิตย์ก่อน","ro":"Phǒm jawng bang-kà-loo thîi paai wái tâng-tàe sǎwng aa-thít kàwn."},{"fr":"Quand il y a beaucoup de touristes, il faut tout réserver à l'avance.","tgt":"ช่วงที่นักท่องเที่ยวเยอะ ต้องจองทุกอย่างไว้ล่วงหน้า","ro":"Chûang thîi nák-thâwng-thîao yóe, tâwng jawng thúk-yàang wái lûang-nâa."},{"fr":"Pourriez-vous me garder cette chambre jusqu'à demain ?","tgt":"ช่วยเก็บห้องนี้ไว้ให้ผมถึงพรุ่งนี้ได้ไหมครับ","ro":"Chûai kèp hâwng níi wái hâi phǒm thǔeng phrûng-níi dâi mái khráp?"},{"fr":"J'ai noté l'adresse dans mon téléphone.","tgt":"ผมจดที่อยู่ไว้ในโทรศัพท์แล้ว","ro":"Phǒm jòt thîi-yùu wái nai thoo-rá-sàp láew."},{"fr":"Laissez vos bagages ici, vous viendrez les reprendre plus tard.","tgt":"วางกระเป๋าไว้ตรงนี้ก่อน เดี๋ยวค่อยมาเอา","ro":"Waang krà-pǎo wái trong-níi kàwn, dǐao khâwy maa ao."},{"fr":"Gardez un peu d'argent liquide : il n'y a pas de distributeur dans la montagne.","tgt":"เก็บเงินสดไว้บ้างนะครับ บนเขาไม่มีตู้เอทีเอ็ม","ro":"Kèp ngoen-sòt wái bâang ná khráp, bon khǎo mâi mii tûu ee-thii-em."},{"fr":"J'ai acheté le billet de bus du retour à l'avance.","tgt":"ผมซื้อตั๋วรถขากลับไว้ล่วงหน้าแล้ว","ro":"Phǒm súe tǔa rót khǎa-klàp wái lûang-nâa láew."},{"fr":"La propriétaire nous a préparé du café pour le matin.","tgt":"เจ้าของที่พักชงกาแฟไว้ให้เราตอนเช้า","ro":"Jâo-khǎwng thîi-phák chong kaa-fae wái hâi rao tawn-cháao."},{"fr":"Gardez votre ticket, on vous le demandera à la sortie.","tgt":"เก็บตั๋วไว้นะครับ ตอนออกเขาจะขอดู","ro":"Kèp tǔa wái ná khráp, tawn àwk khǎo jà khǎw duu."},{"fr":"J'ai pris des photos pour garder un souvenir de cet endroit.","tgt":"ผมถ่ายรูปเก็บไว้เป็นที่ระลึก","ro":"Phǒm thàai rûup kèp wái pen thîi-rá-lúek."}],"tip":{"title":"« Wái » : faire à l'avance, garder","example":"Pourriez-vous me garder cette chambre jusqu'à demain ? — ช่วยเก็บห้องนี้<b>ไว้</b>ให้ผมถึงพรุ่งนี้ได้ไหมครับ","body":"Le petit mot « wái », au ton haut, se met après le verbe et son complément pour dire qu'on fait une chose à l'avance, ou qu'on la garde pour plus tard. « Jawng wái » veut dire réserver d'avance, et « kèp wái » veut dire mettre de côté. Dans « chûai kèp hâwng níi wái hâi phǒm », mot à mot « aider garder chambre cette de côté pour moi », on demande poliment qu'on nous garde la chambre. Le français n'a pas d'équivalent exact : c'est un peu notre « de côté » ou « en prévision ». Autres exemples : « jòt wái », noter pour ne pas oublier, et « súe tǔa wái lûang-nâa », acheter le billet à l'avance. Pour retenir, imaginez « wái » comme un tiroir où l'on range une action pour plus tard.","exampleRo":"Chûai kèp hâwng níi wái hâi phǒm thǔeng phrûng-níi dâi mái khráp?","lit":"aider · garder · chambre · cette · [de côté] · pour · moi · jusqu'à · demain · pouvoir · [question] · [politesse]","say":{"Wái":"ไว้","wái":"ไว้","Jawng wái":"จองไว้","kèp wái":"เก็บไว้","chûai kèp hâwng níi wái hâi phǒm":"ช่วยเก็บห้องนี้ไว้ให้ผม","jòt wái":"จดไว้","súe tǔa wái lûang-nâa":"ซื้อตั๋วไว้ล่วงหน้า"}}},{"title":"Les ruines de Sukhothai à vélo","phrases":[{"fr":"Sukhothai est une ancienne capitale vieille de plus de sept siècles.","tgt":"สุโขทัยเป็นเมืองหลวงเก่าที่มีอายุกว่าเจ็ดร้อยปี","ro":"Sù-khǒo-thai pen mueang-lǔang kào thîi mii aa-yú kwàa jèt ráwy pii."},{"fr":"Ce parc historique est classé comme héritage mondial de l’humanité.","tgt":"อุทยานประวัติศาสตร์แห่งนี้เป็นมรดกโลก","ro":"Ùt-thá-yaan prà-wàt-tì-sàat hàeng níi pen maw-rá-dòk lôok."},{"fr":"Le meilleur moyen de le visiter, c'est à vélo.","tgt":"วิธีที่ดีที่สุดในการเที่ยวที่นี่คือปั่นจักรยาน","ro":"Wí-thii thîi dii thîi-sùt nai kaan thîao thîi-nîi khue pàn jàk-krà-yaan."},{"fr":"On loue des vélos à l'entrée pour trente bahts.","tgt":"เราเช่าจักรยานที่ทางเข้าในราคาสามสิบบาท","ro":"Rao châo jàk-krà-yaan thîi thaang-khâo nai raa-khaa sǎam-sìp bàat."},{"fr":"Les ruines sont entourées de bassins et de grands arbres.","tgt":"โบราณสถานล้อมรอบด้วยสระน้ำและต้นไม้ใหญ่","ro":"Boo-raan-sà-thǎan láwm râwp dûai sà-náam láe tôn-mái yài."},{"fr":"Certaines colonnes ont été restaurées il y a peu de temps.","tgt":"เสาบางต้นเพิ่งถูกบูรณะไม่นานมานี้","ro":"Sǎo baang tôn phôeng thùuk buu-rá-ná mâi naan maa níi."},{"fr":"En fin d'après-midi, il fait un peu moins chaud.","tgt":"ช่วงบ่ายแก่ๆอากาศจะไม่ร้อนเท่าไหร่","ro":"Chûang bàai kàe kàe aa-kàat jà mâi ráwn thâo-rài."},{"fr":"Au coucher du soleil, les vieilles pierres prennent une couleur dorée.","tgt":"ตอนพระอาทิตย์ตก ก้อนหินเก่าๆกลายเป็นสีทอง","ro":"Tawn phrá-aa-thít tòk, kâwn-hǐn kào kào klaai pen sǐi thawng."},{"fr":"Un panneau explique comment la ville était organisée.","tgt":"ป้ายอธิบายว่าเมืองนี้เคยมีผังเมืองอย่างไร","ro":"Pâai à-thí-baai wâa mueang níi khoei mii phǎng-mueang yàang-rai."},{"fr":"On est restés ici toute la journée sans voir le temps passer.","tgt":"เราอยู่ที่นี่ทั้งวันจนลืมเวลา","ro":"Rao yùu thîi-nîi tháng wan jon luem wee-laa."}]},{"title":"Un bus de nuit vers le Nord","phrases":[{"fr":"Nous prenons le bus de nuit de Bangkok à Chiang Mai.","tgt":"เรานั่งรถทัวร์กลางคืนจากกรุงเทพฯไปเชียงใหม่","ro":"Rao nâng rót-thua klaang-khuen jàak krung-thêep pai chiang-mài."},{"fr":"Le trajet dure une dizaine d'heures.","tgt":"การเดินทางใช้เวลาประมาณสิบชั่วโมง","ro":"Kaan doen-thaang chái wee-laa prà-maan sìp chûa-moong."},{"fr":"Les sièges s'inclinent presque comme un lit.","tgt":"เบาะเอนได้เกือบเหมือนเตียง","ro":"Bàw een dâi kùeap mǔean tiang."},{"fr":"Une employée distribue de l'eau et des couvertures.","tgt":"พนักงานบนรถแจกน้ำกับผ้าห่ม","ro":"Phá-nák-ngaan bon rót jàek náam kàp phâa-hòm."},{"fr":"La climatisation est tellement forte qu'on a froid.","tgt":"แอร์แรงจนหนาว","ro":"Ae raeng jon nǎao."},{"fr":"Le bus s'arrête au milieu de la nuit pour que les passagers puissent manger.","tgt":"รถจอดกลางดึกให้ผู้โดยสารลงไปกินข้าว","ro":"Rót jàwt klaang dùek hâi phûu-dooi-sǎan long pai kin khâao."},{"fr":"Le repas est compris dans le prix du billet.","tgt":"ค่าอาหารรวมอยู่ในค่าตั๋วแล้ว","ro":"Khâa aa-hǎan ruam yùu nai khâa tǔa láew."},{"fr":"Je n'ai presque pas dormi à cause des virages.","tgt":"ผมแทบไม่ได้นอนเพราะทางโค้งเยอะ","ro":"Phǒm thâep mâi dâi nawn phráw thaang khóong yóe."},{"fr":"À Chiang Mai, on prend un minibus pour Pai.","tgt":"ที่เชียงใหม่เราต่อรถตู้ไปปาย","ro":"Thîi chiang-mài rao tàw rót-tûu pai paai."},{"fr":"Cette route compte plus de sept cents virages.","tgt":"ถนนเส้นนี้มีโค้งมากกว่าเจ็ดร้อยโค้ง","ro":"Thà-nǒn sên níi mii khóong mâak kwàa jèt ráwy khóong."}]},{"title":"Les montagnes de Pai","phrases":[{"fr":"Pai est une petite ville entourée de montagnes.","tgt":"ปายเป็นเมืองเล็กๆที่มีภูเขาล้อมรอบ","ro":"Paai pen mueang lék lék thîi mii phuu-khǎo láwm râwp."},{"fr":"Le matin, la vallée disparaît sous la brume.","tgt":"ตอนเช้าหุบเขาจมอยู่ในหมอก","ro":"Tawn-cháao hùp-khǎo jom yùu nai màwk."},{"fr":"On monte au point de vue pour admirer la mer de nuages.","tgt":"เราขึ้นไปจุดชมวิวเพื่อดูทะเลหมอก","ro":"Rao khûen pai jùt-chom-wiu phûea duu thá-lee-màwk."},{"fr":"Avant le lever du soleil, il fait plus froid qu'on ne le pense.","tgt":"ก่อนพระอาทิตย์ขึ้นอากาศหนาวกว่าที่คิด","ro":"Kàwn phrá-aa-thít khûen aa-kàat nǎao kwàa thîi khít."},{"fr":"Beaucoup de voyageurs louent un scooter pour se promener.","tgt":"นักท่องเที่ยวหลายคนเช่ามอเตอร์ไซค์ขับเที่ยว","ro":"Nák-thâwng-thîao lǎai khon châo maw-toe-sai khàp thîao."},{"fr":"Les routes de montagne sont à la fois raides et étroites.","tgt":"ถนนบนเขาทั้งชันและแคบ","ro":"Thà-nǒn bon khǎo tháng chan láe khâep."},{"fr":"Le canyon de Kong Lan est magnifique au coucher du soleil.","tgt":"กองแลนสวยมากตอนพระอาทิตย์ตก","ro":"Kawng-laen sǔai mâak tawn phrá-aa-thít tòk."},{"fr":"On se détend dans les sources d'eau chaude.","tgt":"เราแช่น้ำพุร้อนให้สบายตัว","ro":"Rao châe náam-phú-ráwn hâi sà-baai tua."},{"fr":"Le soir, la grande rue se transforme en marché.","tgt":"ตอนเย็นถนนสายหลักกลายเป็นตลาด","ro":"Tawn-yen thà-nǒn sǎai làk klaai pen tà-làat."},{"fr":"Je comprends pourquoi tant de gens restent ici plus longtemps que prévu.","tgt":"ผมเข้าใจแล้วว่าทำไมหลายคนถึงอยู่ที่นี่นานกว่าที่ตั้งใจไว้","ro":"Phǒm khâo-jai láew wâa tham-mai lǎai khon thǔeng yùu thîi-nîi naan kwàa thîi tâng-jai wái."}]},{"title":"Goûter la cuisine de l'Isan","phrases":[{"fr":"La cuisine de l'Isan est réputée pour être très pimentée.","tgt":"อาหารอีสานขึ้นชื่อว่าเผ็ดมาก","ro":"Aa-hǎan ii-sǎan khûen-chûe wâa phèt mâak."},{"fr":"Le riz gluant se mange avec les doigts.","tgt":"ข้าวเหนียวต้องกินด้วยมือ","ro":"Khâao-nǐao tâwng kin dûai mue."},{"fr":"On en fait une petite boule qu'on trempe dans la sauce.","tgt":"ปั้นเป็นก้อนเล็กๆแล้วจิ้มน้ำจิ้ม","ro":"Pân pen kâwn lék lék láew jîm náam-jîm."},{"fr":"La salade de papaye se pile dans un mortier.","tgt":"ส้มตำต้องตำในครก","ro":"Sôm-tam tâwng tam nai khrók."},{"fr":"Je la voudrais un peu moins épicée, s'il vous plaît.","tgt":"ขอเผ็ดน้อยหน่อยครับ","ro":"Khǎw phèt náwy nàwy khráp."},{"fr":"Le poulet grillé d'ici est célèbre dans tout le pays.","tgt":"ไก่ย่างของที่นี่มีชื่อเสียงไปทั่วประเทศ","ro":"Kài-yâang khǎwng thîi-nîi mii chûe-sǐang pai thûa prà-thêet."},{"fr":"Le laap est une salade de viande hachée aux herbes.","tgt":"ลาบคือยำเนื้อสับใส่สมุนไพร","ro":"Lâap khue yam núea sàp sài sà-mǔn-phrai."},{"fr":"On boit de l'eau fraîche pour calmer le feu du piment.","tgt":"เราดื่มน้ำเย็นเพื่อดับความเผ็ด","ro":"Rao dùem náam yen phûea dàp khwaam-phèt."},{"fr":"Les plats sont posés au milieu de la table pour être partagés.","tgt":"อาหารวางไว้กลางโต๊ะให้ทุกคนกินด้วยกัน","ro":"Aa-hǎan waang wái klaang tó hâi thúk khon kin dûai-kan."},{"fr":"C'est sans doute le repas le plus épicé de ma vie.","tgt":"นี่คงเป็นมื้อที่เผ็ดที่สุดในชีวิตผม","ro":"Nîi khong pen múe thîi phèt thîi-sùt nai chii-wít phǒm."}]},{"title":"Prévoir la météo avant une excursion","phrases":[{"fr":"Normalement, il devrait faire beau demain.","tgt":"พรุ่งนี้อากาศน่าจะดี","ro":"Phrûng-níi aa-kàat nâa jà dii."},{"fr":"Il devrait pleuvoir dans l'après-midi.","tgt":"ช่วงบ่ายน่าจะมีฝนตก","ro":"Chûang bàai nâa jà mii fǒn tòk."},{"fr":"Le guide devrait arriver vers sept heures.","tgt":"ไกด์น่าจะมาถึงประมาณเจ็ดโมง","ro":"Kái nâa jà maa thǔeng prà-maan jèt moong."},{"fr":"Après la pluie, le sentier doit être glissant.","tgt":"หลังฝนตก ทางเดินน่าจะลื่น","ro":"Lǎng fǒn tòk, thaang-doen nâa jà lûen."},{"fr":"Il nous faudra sans doute trois heures de marche.","tgt":"น่าจะใช้เวลาเดินประมาณสามชั่วโมง","ro":"Nâa jà chái wee-laa doen prà-maan sǎam chûa-moong."},{"fr":"Nous devrions atteindre le sommet avant midi.","tgt":"เราน่าจะถึงยอดเขาก่อนเที่ยง","ro":"Rao nâa jà thǔeng yâwt-khǎo kàwn thîang."},{"fr":"Vous devriez emporter un imperméable, au cas où.","tgt":"คุณน่าจะเอาเสื้อกันฝนไปด้วยเผื่อไว้","ro":"Khun nâa jà ao sûea-kan-fǒn pai dûai phùea wái."},{"fr":"Un mardi, il ne devrait pas y avoir trop de monde.","tgt":"วันอังคารคนน่าจะไม่เยอะ","ro":"Wan ang-khaan khon nâa jà mâi yóe."},{"fr":"Ce chemin-ci devrait être plus rapide.","tgt":"ทางนี้น่าจะเร็วกว่า","ro":"Thaang níi nâa jà reo kwàa."},{"fr":"Ce restaurant doit être bon : il est plein de gens du coin.","tgt":"ร้านนี้น่าจะอร่อย คนท้องถิ่นเต็มร้านเลย","ro":"Ráan níi nâa jà à-ràwy, khon tháwng-thìn tem ráan loei."}],"tip":{"title":"« Nâa jà » : normalement, ça devrait","example":"Normalement, il devrait faire beau demain. — พรุ่งนี้อากาศ<b>น่าจะ</b>ดี","body":"« Nâa jà » se place devant le verbe ou l'adjectif pour exprimer une supposition raisonnable : normalement, ça devrait, sans doute. « Phrûng-níi aa-kàat nâa jà dii » se décompose ainsi : demain, temps, ça devrait, bon, donc « demain, il devrait faire beau ». C'est plus prudent que le simple « jà » du futur : on ne promet rien, on estime. On l'emploie sans cesse pour la météo, les horaires ou les distances : « kái nâa jà maa thǔeng jèt moong », le guide devrait arriver à sept heures, ou « nâa jà à-ràwy », ça doit être bon. Avec « khun », vous, il devient un conseil tout en douceur : « khun nâa jà ao sûea-kan-fǒn pai », vous devriez prendre un imperméable. Astuce : retenez « nâa jà » comme le « sûrement » qu'on dit en haussant les épaules.","exampleRo":"Phrûng-níi aa-kàat nâa jà dii.","lit":"demain · temps · [devrait] · bon","say":{"Nâa jà":"น่าจะ","Phrûng-níi aa-kàat nâa jà dii":"พรุ่งนี้อากาศน่าจะดี","jà":"จะ","kái nâa jà maa thǔeng jèt moong":"ไกด์น่าจะมาถึงเจ็ดโมง","nâa jà à-ràwy":"น่าจะอร่อย","khun":"คุณ","khun nâa jà ao sûea-kan-fǒn pai":"คุณน่าจะเอาเสื้อกันฝนไป","nâa jà":"น่าจะ"}}},{"title":"Un marché de nuit à Khon Kaen","phrases":[{"fr":"Le marché de nuit ouvre dès six heures du soir.","tgt":"ตลาดกลางคืนเปิดตั้งแต่หกโมงเย็น","ro":"Tà-làat klaang-khuen pòet tâng-tàe hòk moong yen."},{"fr":"Les stands de nourriture s'alignent tout le long de la rue.","tgt":"ร้านอาหารแผงลอยเรียงยาวตลอดถนน","ro":"Ráan aa-hǎan phǎeng-lawy riang yaao tà-làwt thà-nǒn."},{"fr":"Ceux qui osent peuvent goûter des insectes frits.","tgt":"ใครกล้าก็ลองชิมแมลงทอดได้","ro":"Khrai klâa kâw lawng chim má-laeng thâwt dâi."},{"fr":"Combien coûte ce sac en soie, s'il vous plaît ?","tgt":"กระเป๋าผ้าไหมใบนี้ราคาเท่าไหร่ครับ","ro":"Krà-pǎo phâa-mǎi bai níi raa-khaa thâo-rài khráp?"},{"fr":"Si j'en prends deux, vous pouvez me faire un prix ?","tgt":"ถ้าซื้อสองใบ ลดให้หน่อยได้ไหมครับ","ro":"Thâa súe sǎwng bai, lót hâi nàwy dâi mái khráp?"},{"fr":"Ici, on marchande avec le sourire, sans insister.","tgt":"ที่นี่ต่อราคากันแบบสุภาพ ไม่ตื๊อ","ro":"Thîi-nîi tàw raa-khaa kan bàep sù-phâap, mâi túe."},{"fr":"Un groupe de jeunes joue de la musique traditionnelle.","tgt":"วัยรุ่นกลุ่มหนึ่งเล่นดนตรีพื้นบ้าน","ro":"Wai-rûn klùm nùeng lên don-trii phúen-bâan."},{"fr":"Le son de l'orgue à bouche est typique de l'Isan.","tgt":"เสียงแคนเป็นเอกลักษณ์ของอีสาน","ro":"Sǐang khaen pen èek-kà-lák khǎwng ii-sǎan."},{"fr":"Tout le monde s'assoit sur des nattes pour manger.","tgt":"ทุกคนนั่งกินบนเสื่อ","ro":"Thúk khon nâng kin bon sùea."},{"fr":"J'ai trop mangé, mais je ne regrette rien.","tgt":"ผมกินเยอะเกินไป แต่ไม่เสียใจเลย","ro":"Phǒm kin yóe koen pai, tàe mâi sǐa-jai loei."}]},{"title":"Une panne de scooter près de Pai","phrases":[{"fr":"Mon scooter est tombé en panne en pleine montagne.","tgt":"มอเตอร์ไซค์ผมเสียกลางภูเขา","ro":"Maw-toe-sai phǒm sǐa klaang phuu-khǎo."},{"fr":"Le moteur ne veut plus démarrer.","tgt":"เครื่องสตาร์ทไม่ติด","ro":"Khrûeang sà-táat mâi tìt."},{"fr":"Ici, il n'y a pas de réseau téléphonique.","tgt":"ตรงนี้ไม่มีสัญญาณโทรศัพท์","ro":"Trong-níi mâi mii sǎn-yaan thoo-rá-sàp."},{"fr":"Un villageois s'est arrêté pour nous aider.","tgt":"ชาวบ้านคนหนึ่งจอดรถลงมาช่วยเรา","ro":"Chaao-bâan khon nùeng jàwt rót long maa chûai rao."},{"fr":"Il pense que le problème vient de la bougie.","tgt":"เขาคิดว่าน่าจะเป็นที่หัวเทียน","ro":"Khǎo khít wâa nâa jà pen thîi hǔa-thian."},{"fr":"Le garage le plus proche est à cinq kilomètres.","tgt":"อู่ที่ใกล้ที่สุดอยู่ห่างไปห้ากิโล","ro":"Ùu thîi klâi thîi-sùt yùu hàang pai hâa kì-loo."},{"fr":"Il a proposé de remorquer le scooter jusqu'au village.","tgt":"เขาเสนอว่าจะลากรถไปถึงหมู่บ้าน","ro":"Khǎo sà-nǒe wâa jà lâak rót pai thǔeng mùu-bâan."},{"fr":"Le mécanicien l'a réparé en une demi-heure.","tgt":"ช่างซ่อมเสร็จภายในครึ่งชั่วโมง","ro":"Châang sâwm sèt phaai-nai khrûeng chûa-moong."},{"fr":"Il ne m'a demandé que cent bahts pour la réparation.","tgt":"เขาคิดค่าซ่อมแค่ร้อยบาท","ro":"Khǎo khít khâa-sâwm khâe ráwy bàat."},{"fr":"Je n'oublierai jamais la générosité de ces gens.","tgt":"ผมจะไม่มีวันลืมน้ำใจของคนเหล่านี้","ro":"Phǒm jà mâi mii wan luem nám-jai khǎwng khon lào-níi."}]},{"title":"Voyager de manière responsable","phrases":[{"fr":"Je préfère loger chez des gens du coin.","tgt":"ผมชอบพักที่พักของคนท้องถิ่นมากกว่า","ro":"Phǒm châwp phák thîi-phák khǎwng khon tháwng-thìn mâak kwàa."},{"fr":"Comme ça, l'argent reste dans la communauté.","tgt":"แบบนี้เงินก็จะอยู่ในชุมชน","ro":"Bàep níi ngoen kâw jà yùu nai chum-chon."},{"fr":"J'emporte toujours ma propre gourde.","tgt":"ผมพกขวดน้ำของตัวเองไปด้วยเสมอ","ro":"Phǒm phók khùat-náam khǎwng tua-eeng pai dûai sà-mǒe."},{"fr":"On refuse les sacs en plastique quand ce n'est pas nécessaire.","tgt":"เราไม่รับถุงพลาสติกถ้าไม่จำเป็น","ro":"Rao mâi ráp thǔng phláat-sà-tìk thâa mâi jam-pen."},{"fr":"Il ne faut rien laisser derrière soi dans la nature.","tgt":"ไม่ควรทิ้งอะไรไว้ในธรรมชาติ","ro":"Mâi khuan thíng à-rai wái nai tham-má-châat."},{"fr":"Les déchets doivent être rapportés en ville.","tgt":"ขยะต้องเอากลับมาทิ้งในเมือง","ro":"Khà-yà tâwng ao klàp maa thíng nai mueang."},{"fr":"Il vaut mieux éviter les spectacles avec des animaux.","tgt":"ควรหลีกเลี่ยงการแสดงที่ใช้สัตว์","ro":"Khuan lìik-lîang kaan sà-daeng thîi chái sàt."},{"fr":"Demandez toujours la permission avant de photographier quelqu'un.","tgt":"ก่อนถ่ายรูปใคร ควรขออนุญาตก่อนเสมอ","ro":"Kàwn thàai rûup khrai, khuan khǎw à-nú-yâat kàwn sà-mǒe."},{"fr":"Respecter les coutumes locales, c'est aussi voyager de façon responsable.","tgt":"การเคารพประเพณีท้องถิ่นก็เป็นการเที่ยวอย่างรับผิดชอบ","ro":"Kaan khao-róp prà-phee-nii tháwng-thìn kâw pen kaan thîao yàang ráp-phìt-châwp."},{"fr":"Voyager lentement permet de mieux comprendre un pays.","tgt":"การเที่ยวช้าๆทำให้เข้าใจประเทศนั้นได้ลึกซึ้งขึ้น","ro":"Kaan thîao cháa cháa tham-hâi khâo-jai prà-thêet nán dâi lúek-súeng khûen."}]},{"title":"Un séjour chez l'habitant en Isan","phrases":[{"fr":"Nous logeons chez une famille de riziculteurs.","tgt":"เราพักอยู่กับครอบครัวชาวนา","ro":"Rao phák yùu kàp khrâwp-khrua chaao-naa."},{"fr":"Leur maison est construite sur pilotis.","tgt":"บ้านของเขาเป็นบ้านใต้ถุนสูง","ro":"Bâan khǎwng khǎo pen bâan tâi-thǔn sǔung."},{"fr":"Sous la maison, la grand-mère tisse à l'ombre.","tgt":"ใต้ถุนบ้าน คุณยายนั่งทอผ้าอยู่ในที่ร่ม","ro":"Tâi-thǔn bâan, khun-yaai nâng thaw phâa yùu nai thîi rôm."},{"fr":"Le matin, j'aide à nourrir les buffles.","tgt":"ตอนเช้าผมช่วยให้อาหารควาย","ro":"Tawn-cháao phǒm chûai hâi aa-hǎan khwaai."},{"fr":"Ils m'ont appris à repiquer le riz.","tgt":"เขาสอนผมดำนา","ro":"Khǎo sǎwn phǒm dam-naa."},{"fr":"C'est un travail bien plus dur qu'il n'y paraît.","tgt":"งานนี้หนักกว่าที่เห็นเยอะเลย","ro":"Ngaan níi nàk kwàa thîi hěn yóe loei."},{"fr":"Le soir, toute la famille mange ensemble par terre.","tgt":"ตอนเย็นทั้งครอบครัวนั่งกินข้าวด้วยกันบนพื้น","ro":"Tawn-yen tháng khrâwp-khrua nâng kin khâao dûai-kan bon phúen."},{"fr":"Les enfants m'apprennent de nouveaux mots chaque jour.","tgt":"เด็กๆสอนคำศัพท์ใหม่ๆให้ผมทุกวัน","ro":"Dèk dèk sǎwn kham-sàp mài mài hâi phǒm thúk wan."},{"fr":"On dort sous une moustiquaire.","tgt":"เรานอนในมุ้ง","ro":"Rao nawn nai múng."},{"fr":"Partir sera difficile, on s'est attachés à eux.","tgt":"คงจะลาจากยาก เพราะเราผูกพันกับพวกเขาแล้ว","ro":"Khong jà laa-jàak yâak, phráw rao phùuk-phan kàp phûak-khǎo láew."}]},{"title":"Une cascade à Khao Yai","phrases":[{"fr":"La cascade de Haew Suwat est la plus célèbre du parc.","tgt":"น้ำตกเหวสุวัตเป็นน้ำตกที่ดังที่สุดในอุทยาน","ro":"Náam-tòk hěo-sù-wát pen náam-tòk thîi dang thîi-sùt nai ùt-thá-yaan."},{"fr":"On y descend par un escalier en pierre.","tgt":"ทางลงไปเป็นบันไดหิน","ro":"Thaang long pai pen ban-dai hǐn."},{"fr":"À la saison des pluies, le débit est impressionnant.","tgt":"หน้าฝนน้ำตกไหลแรงมาก","ro":"Nâa-fǒn náam-tòk lǎi raeng mâak."},{"fr":"La baignade est interdite à cause du courant.","tgt":"ห้ามลงเล่นน้ำเพราะกระแสน้ำแรง","ro":"Hâam long lên náam phráw krà-sǎe-náam raeng."},{"fr":"Le bruit de l'eau couvre nos voix.","tgt":"เสียงน้ำดังจนกลบเสียงพูดของเรา","ro":"Sǐang náam dang jon klòp sǐang phûut khǎwng rao."},{"fr":"Les rochers sont couverts de mousse et très glissants.","tgt":"ก้อนหินมีตะไคร่ขึ้นเต็มและลื่นมาก","ro":"Kâwn-hǐn mii tà-khrâi khûen tem láe lûen mâak."},{"fr":"On fait une pause pour déjeuner au bord de l'eau.","tgt":"เราพักกินข้าวกลางวันริมน้ำ","ro":"Rao phák kin khâao-klaang-wan rim náam."},{"fr":"Des papillons de toutes les couleurs volent autour de nous.","tgt":"ผีเสื้อหลากสีบินอยู่รอบตัวเรา","ro":"Phǐi-sûea lâak sǐi bin yùu râwp tua rao."},{"fr":"Le chemin du retour grimpe beaucoup.","tgt":"ทางกลับเป็นทางขึ้นเขาชันมาก","ro":"Thaang klàp pen thaang khûen khǎo chan mâak."},{"fr":"Fatigués mais heureux, on rentre avant la nuit.","tgt":"ถึงจะเหนื่อยแต่ก็มีความสุข เรากลับก่อนมืด","ro":"Thǔeng jà nùeai tàe kâw mii khwaam-sùk, rao klàp kàwn mûet."}]},{"title":"Une tempête surprend notre randonnée","phrases":[{"fr":"Le ciel devient de plus en plus sombre.","tgt":"ท้องฟ้ามืดมากขึ้นเรื่อยๆ","ro":"Tháwng-fáa mûet mâak khûen rûeai rûeai."},{"fr":"Le vent souffle de plus en plus fort.","tgt":"ลมพัดแรงขึ้นเรื่อยๆ","ro":"Lom phát raeng khûen rûeai rûeai."},{"fr":"La pluie tombe de plus en plus dru.","tgt":"ฝนตกหนักขึ้นเรื่อยๆ","ro":"Fǒn tòk nàk khûen rûeai rûeai."},{"fr":"Le guide nous dit de nous abriter sous un gros rocher.","tgt":"ไกด์บอกให้เราหลบใต้ก้อนหินใหญ่","ro":"Kái bàwk hâi rao lòp tâi kâwn-hǐn yài."},{"fr":"Le tonnerre gronde de plus en plus près.","tgt":"ฟ้าร้องใกล้เข้ามาเรื่อยๆ","ro":"Fáa-ráwng klâi khâo maa rûeai rûeai."},{"fr":"Le sentier se transforme en ruisseau.","tgt":"ทางเดินกลายเป็นลำธาร","ro":"Thaang-doen klaai pen lam-thaan."},{"fr":"Nos vêtements sont trempés, alors on a de plus en plus froid.","tgt":"เสื้อผ้าเปียกโชก เราเลยหนาวมากขึ้นเรื่อยๆ","ro":"Sûea-phâa pìak chôok, rao loei nǎao mâak khûen rûeai rûeai."},{"fr":"À cette période de l'année, les tempêtes sont de plus en plus fréquentes.","tgt":"ช่วงนี้ของปีมีพายุมากขึ้นเรื่อยๆ","ro":"Chûang níi khǎwng pii mii phaa-yú mâak khûen rûeai rûeai."},{"fr":"Au bout d'une heure, l'orage finit par s'éloigner.","tgt":"ผ่านไปหนึ่งชั่วโมง พายุก็ค่อยๆผ่านไป","ro":"Phàan pai nùeng chûa-moong, phaa-yú kâw khâwy khâwy phàan pai."},{"fr":"Le calme de notre guide m'impressionne de plus en plus.","tgt":"ผมทึ่งในความใจเย็นของไกด์มากขึ้นเรื่อยๆ","ro":"Phǒm thûeng nai khwaam-jai-yen khǎwng kái mâak khûen rûeai rûeai."}],"tip":{"title":"« Mâak khûen rûeai rûeai » : de plus en plus","example":"Le ciel devient de plus en plus sombre. — ท้องฟ้ามืด<b>มากขึ้นเรื่อยๆ</b>","body":"Pour dire « de plus en plus », le thaï place après l'adjectif ou le verbe le mot « khûen », qui veut dire monter, puis « rûeai rûeai », qui veut dire sans arrêt. « Tháwng-fáa mûet mâak khûen rûeai rûeai » donne mot à mot : ciel, sombre, beaucoup, monter, sans arrêt, c'est-à-dire « le ciel devient de plus en plus sombre ». On peut garder « mâak », beaucoup, pour insister, ou le laisser tomber : « raeng khûen rûeai rûeai », de plus en plus fort, ou « dii khûen rûeai rûeai », de mieux en mieux. Quand une chose se rapproche, on remplace « khûen » par « khâo maa » : « klâi khâo maa rûeai rûeai », de plus en plus près. Pour retenir, imaginez un escalier sans fin : « khûen » pour la montée, et « rûeai rûeai » pour les marches qui continuent.","exampleRo":"Tháwng-fáa mûet mâak khûen rûeai rûeai.","lit":"ciel · sombre · beaucoup · monter · [sans cesse]","say":{"Mâak khûen rûeai rûeai":"มากขึ้นเรื่อยๆ","khûen":"ขึ้น","rûeai rûeai":"เรื่อยๆ","Tháwng-fáa mûet mâak khûen rûeai rûeai":"ท้องฟ้ามืดมากขึ้นเรื่อยๆ","mâak":"มาก","raeng khûen rûeai rûeai":"แรงขึ้นเรื่อยๆ","dii khûen rûeai rûeai":"ดีขึ้นเรื่อยๆ","khâo maa":"เข้ามา","klâi khâo maa rûeai rûeai":"ใกล้เข้ามาเรื่อยๆ"}}},{"title":"Revenir à Sukhothai des années plus tard","phrases":[{"fr":"Je reviens à Sukhothai quinze ans après mon premier séjour.","tgt":"ผมกลับมาสุโขทัยอีกครั้งหลังจากมาครั้งแรกเมื่อสิบห้าปีก่อน","ro":"Phǒm klàp maa sù-khǒo-thai ìik khráng lǎng-jàak maa khráng râek mûea sìp-hâa pii kàwn."},{"fr":"À l'époque, je voyageais seul avec un petit sac.","tgt":"ตอนนั้นผมเที่ยวคนเดียวกับกระเป๋าใบเล็กๆ","ro":"Tawn-nán phǒm thîao khon diao kàp krà-pǎo bai lék lék."},{"fr":"Cette fois, je suis venu avec ma femme et mes enfants.","tgt":"ครั้งนี้ผมพาภรรยากับลูกๆมาด้วย","ro":"Khráng níi phǒm phaa phan-rá-yaa kàp lûuk lûuk maa dûai."},{"fr":"La maison d'hôtes où j'avais dormi est toujours ouverte.","tgt":"เกสต์เฮาส์ที่ผมเคยพักยังเปิดอยู่","ro":"Kèet-háo thîi phǒm khoei phák yang pòet yùu."},{"fr":"La propriétaire m'a reconnu tout de suite.","tgt":"เจ้าของจำผมได้ทันที","ro":"Jâo-khǎwng jam phǒm dâi than-thii."},{"fr":"Le village a beaucoup changé, mais les ruines sont restées les mêmes.","tgt":"หมู่บ้านเปลี่ยนไปมาก แต่โบราณสถานยังเหมือนเดิม","ro":"Mùu-bâan plìan pai mâak, tàe boo-raan-sà-thǎan yang mǔean doem."},{"fr":"Je montre à mes enfants l'endroit où j'avais pris ma photo préférée.","tgt":"ผมพาลูกไปดูจุดที่ผมเคยถ่ายรูปที่ชอบที่สุด","ro":"Phǒm phaa lûuk pai duu jùt thîi phǒm khoei thàai rûup thîi châwp thîi-sùt."},{"fr":"Ils sont moins émerveillés que moi.","tgt":"พวกเขาไม่ได้ตื่นเต้นเท่าผม","ro":"Phûak-khǎo mâi dâi tùen-tên thâo phǒm."},{"fr":"Revenir dans un lieu qu'on aime montre combien le temps a passé.","tgt":"การกลับมาที่ที่เรารักทำให้เห็นว่าเวลาผ่านไปนานแค่ไหน","ro":"Kaan klàp maa thîi thîi rao rák tham-hâi hěn wâa wee-laa phàan pai naan khâe-nǎi."},{"fr":"Je suis sûr que je reviendrai encore.","tgt":"ผมแน่ใจว่าจะกลับมาอีก","ro":"Phǒm nâe-jai wâa jà klàp maa ìik."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Nous arrivons à la fin de ce module sur le voyage.","tgt":"เรามาถึงตอนท้ายของบทเรียนชุดการเดินทางแล้ว","ro":"Rao maa thǔeng tawn-tháai khǎwng bòt-rian chút kaan doen-thaang láew."},{"fr":"J'ai appris à raconter un voyage en thaï.","tgt":"ผมได้เรียนรู้วิธีเล่าเรื่องการเดินทางเป็นภาษาไทย","ro":"Phǒm dâi rian-rúu wí-thii lâo rûeang kaan doen-thaang pen phaa-sǎa thai."},{"fr":"Je peux maintenant décrire les lieux que j'ai visités.","tgt":"ตอนนี้ผมบรรยายสถานที่ที่ผมเคยไปได้แล้ว","ro":"Tawn-níi phǒm ban-yaai sà-thǎan-thîi thîi phǒm khoei pai dâi láew."},{"fr":"Dire des phrases longues est moins difficile qu'avant.","tgt":"การพูดประโยคยาวๆไม่ยากเท่าเมื่อก่อนแล้ว","ro":"Kaan phûut prà-yòok yaao yaao mâi yâak thâo mûea-kàwn láew."},{"fr":"Je sais expliquer dans quel but je fais les choses.","tgt":"ผมอธิบายได้ว่าทำอะไรไปเพื่ออะไร","ro":"Phǒm à-thí-baai dâi wâa tham à-rai pai phûea à-rai."},{"fr":"Je parle de la météo avec plus d'assurance.","tgt":"ผมพูดเรื่องสภาพอากาศได้มั่นใจขึ้น","ro":"Phǒm phûut rûeang sà-phâap aa-kàat dâi mân-jai khûen."},{"fr":"Mon thaï s'améliore de jour en jour.","tgt":"ภาษาไทยของผมดีขึ้นเรื่อยๆ","ro":"Phaa-sǎa thai khǎwng phǒm dii khûen rûeai rûeai."},{"fr":"Il me reste encore beaucoup de mots à apprendre.","tgt":"ยังมีคำศัพท์อีกเยอะที่ผมต้องเรียน","ro":"Yang mii kham-sàp ìik yóe thîi phǒm tâwng rian."},{"fr":"Mais je peux déjà voyager tout en discutant avec les gens.","tgt":"แต่ตอนนี้ผมก็เที่ยวไปคุยกับคนไปได้แล้ว","ro":"Tàe tawn-níi phǒm kâw thîao pai khui kàp khon pai dâi láew."},{"fr":"Ensuite, on va s'entraîner à bavarder avec les gens.","tgt":"ต่อไปเราจะไปฝึกคุยกับผู้คนกัน","ro":"Tàw pai rao jà pai fùek khui kàp phûu-khon kan."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Sà-nùk et sà-baai, l'art de vivre thaï","phrases":[{"fr":"Pour les Thaïs, le travail doit aussi être amusant.","tgt":"สำหรับคนไทย งานก็ต้องสนุกด้วย","ro":"Sǎm-ràp khon thai, ngaan kâw tâwng sà-nùk dûai."},{"fr":"Si ce n'est pas amusant, on n'a pas envie de le faire.","tgt":"ถ้าไม่สนุก ก็ไม่อยากทำ","ro":"Thâa mâi sà-nùk, kâw mâi yàak tham."},{"fr":"Je me sens vraiment bien ici, je n'ai aucun souci.","tgt":"ผมรู้สึกสบายมากที่นี่ ไม่มีเรื่องอะไรต้องกังวลเลยครับ","ro":"Phǒm rúu-sùek sà-baai mâak thîi-nîi, mâi mii rûeang à-rai tâwng kang-won loei khráp."},{"fr":"Hier soir, on s'est vraiment bien amusés avec les collègues.","tgt":"เมื่อคืนไปเที่ยวกับเพื่อนร่วมงานสนุกมากเลยครับ","ro":"Mûea-khuen pai thîao kàp phûean rûam ngaan sà-nùk mâak loei khráp."},{"fr":"Les Thaïs aiment faire les choses tranquillement, sans se presser.","tgt":"คนไทยชอบทำอะไรสบายๆ ไม่รีบร้อน","ro":"Khon thai châwp tham à-rai sà-baai sà-baai, mâi rîip-ráwn."},{"fr":"Prendre la vie à la cool, c'est un peu la philosophie du pays.","tgt":"ใช้ชีวิตสบายๆ เป็นเหมือนปรัชญาของคนที่นี่","ro":"Chái chii-wít sà-baai sà-baai pen mǔean prát-yaa khǎwng khon thîi-nîi."},{"fr":"Tu es à l'aise dans ton nouveau travail ?","tgt":"งานใหม่สบายไหม","ro":"Ngaan mài sà-baai mái?"},{"fr":"Le travail est un peu fatigant, mais l'ambiance est sympa.","tgt":"งานเหนื่อยหน่อย แต่บรรยากาศสนุกดีครับ","ro":"Ngaan nùeai nàwy, tàe ban-yaa-kàat sà-nùk dii khráp."},{"fr":"Pour moi, une belle vie, c'est s'amuser et se sentir bien.","tgt":"สำหรับผม ชีวิตที่ดีคือได้สนุกและได้สบาย","ro":"Sǎm-ràp phǒm, chii-wít thîi dii khue dâai sà-nùk láe dâai sà-baai."},{"fr":"Ne réfléchis pas trop, du moment qu'on s'amuse, ça suffit.","tgt":"อย่าคิดมากเลย ขอให้สนุกก็พอ","ro":"Yàa khít mâak loei, khǎw hâi sà-nùk kâw phaw."}],"tip":{"title":"« Sà-nùk » et « sà-baai » : deux mots-clés de la vie thaïe","example":"Si ce n'est pas amusant, on n'a pas envie de le faire. — ถ้าไม่<b>สนุก</b> ก็ไม่อยากทำ","body":"Deux petits mots résument une bonne partie de l'état d'esprit thaï. « Sà-nùk », avec deux tons bas, veut dire amusant, agréable à faire : un travail, un repas ou une sortie doivent être « sà-nùk » pour valoir la peine. « Sà-baai », ton bas puis ton moyen, veut dire être à l'aise, se sentir bien ; on le retrouve dans « sà-baai dii mái », ça va bien ?, et dans « sà-baai jai », avoir l'esprit tranquille. Décomposons « thâa mâi sà-nùk, kâw mâi yàak tham » : si, pas, amusant, alors, pas, vouloir, faire, sans aucun verbe conjugué. En doublant le mot, « sà-baai sà-baai », on obtient une nuance détendue, tranquille, à la cool. Pour retenir : « sà-nùk », c'est le plaisir de faire, et « sà-baai », le plaisir d'être.","exampleRo":"Thâa mâi sà-nùk, kâw mâi yàak tham.","lit":"si · ne pas · amusant · alors · ne pas · vouloir · faire","say":{"Sà-nùk":"สนุก","sà-baai":"สบาย","sà-nùk":"สนุก","Sà-baai":"สบาย","sà-baai dii mái":"สบายดีไหม","sà-baai jai":"สบายใจ","thâa mâi sà-nùk, kâw mâi yàak tham":"ถ้าไม่สนุก ก็ไม่อยากทำ","sà-baai sà-baai":"สบายๆ"}}},{"title":"Le travail et l'équilibre de vie","phrases":[{"fr":"À Bangkok, beaucoup de gens travaillent jusque tard le soir.","tgt":"ที่กรุงเทพ หลายคนทำงานจนดึก","ro":"Thîi krung-thêep, lǎai khon tham-ngaan jon dùek."},{"fr":"Je rentre souvent chez moi après huit heures du soir.","tgt":"ผมกลับถึงบ้านหลังสองทุ่มบ่อยๆครับ","ro":"Phǒm klàp thǔeng bâan lǎng sǎwng thûm bàwy bàwy khráp."},{"fr":"Les embouteillages me font perdre deux heures par jour.","tgt":"รถติดทำให้ผมเสียเวลาวันละสองชั่วโมง","ro":"Rót tìt tham hâi phǒm sǐa wee-laa wan lá sǎwng chûa-moong."},{"fr":"Mon chef m'envoie des messages même le week-end.","tgt":"เจ้านายส่งข้อความมาหาผมแม้แต่วันเสาร์อาทิตย์","ro":"Jâo-naai sòng khâw-khwaam maa hǎa phǒm máe-tàe wan sǎo aa-thít."},{"fr":"Gagner de l'argent est important, mais la santé l'est encore plus.","tgt":"หาเงินก็สำคัญ แต่สุขภาพสำคัญกว่า","ro":"Hǎa ngoen kâw sǎm-khan, tàe sùk-khà-phâap sǎm-khan kwàa."},{"fr":"J'ai décidé de ne plus répondre aux mails après le travail.","tgt":"ผมตัดสินใจว่าจะไม่ตอบอีเมลหลังเลิกงานแล้ว","ro":"Phǒm tàt-sǐn-jai wâa jà mâi tàwp ii-meen lǎng lôek ngaan láew."},{"fr":"Le dimanche, j'éteins mon téléphone toute la journée.","tgt":"วันอาทิตย์ผมปิดโทรศัพท์ทั้งวัน","ro":"Wan aa-thít phǒm pìt thoo-rá-sàp tháng wan."},{"fr":"Mes collègues thaïs déjeunent ensemble tous les jours.","tgt":"เพื่อนร่วมงานคนไทยกินข้าวกลางวันด้วยกันทุกวัน","ro":"Phûean rûam ngaan khon thai kin khâao klaang-wan dûai kan thúk wan."},{"fr":"Cette pause rend la journée de travail plus agréable.","tgt":"การพักแบบนี้ทำให้วันทำงานสบายขึ้น","ro":"Kaan phák bàep níi tham hâi wan tham-ngaan sà-baai khûen."},{"fr":"Trouver le bon équilibre demande du temps.","tgt":"การหาความสมดุลที่ดีต้องใช้เวลา","ro":"Kaan hǎa khwaam sǒm-dun thîi dii tâwng chái wee-laa."}]},{"title":"Les petites phrases de tous les jours","phrases":[{"fr":"La dame d'à côté me demande toujours si j'ai mangé.","tgt":"ป้าข้างบ้านถามผมเสมอว่ากินข้าวรึยัง","ro":"Pâa khâang bâan thǎam phǒm sà-mǒe wâa kin khâao rúe yang."},{"fr":"Tu as déjà mangé ? Oui, merci, c'est fait.","tgt":"กินข้าวรึยัง กินแล้วครับ ขอบคุณครับ","ro":"Kin khâao rúe yang? Kin láew khráp, khàwp-khun khráp."},{"fr":"En fait, cette question sert simplement à dire bonjour.","tgt":"จริงๆแล้วคำถามนี้ก็แค่เป็นการทักทาย","ro":"Jing jing láew, kham-thǎam níi kâw khâe pen kaan thák-thaai."},{"fr":"Ce n'est pas grave, ne t'inquiète pas pour ça.","tgt":"ไม่เป็นไร ไม่ต้องห่วงเรื่องนั้นหรอก","ro":"Mâi pen rai, mâi tâwng hùang rûeang nán ràwk."},{"fr":"Les Thaïs disent « ce n'est rien » dans presque toutes les situations.","tgt":"คนไทยพูดว่าไม่เป็นไรแทบทุกสถานการณ์","ro":"Khon thai phûut wâa mâi pen rai thâep thúk sà-thǎa-ná-kaan."},{"fr":"Calme-toi, on va trouver une solution ensemble.","tgt":"ใจเย็นๆ เดี๋ยวเราช่วยกันหาทางออก","ro":"Jai yen yen, dǐao rao chûai kan hǎa thaang-àwk."},{"fr":"Le serveur s'est trompé de plat, mais ce n'est pas grave.","tgt":"พนักงานเอาอาหารมาผิด แต่ไม่เป็นไรครับ","ro":"Phá-nák-ngaan ao aa-hǎan maa phìt, tàe mâi pen rai khráp."},{"fr":"Dans les bouchons, il faut vraiment garder son calme.","tgt":"เวลารถติด ต้องใจเย็นๆจริงๆ","ro":"Wee-laa rót tìt, tâwng jai yen yen jing jing."},{"fr":"Quand on te demande où tu vas, c'est aussi une façon de saluer.","tgt":"เวลามีคนถามว่าไปไหน ก็เป็นการทักทายเหมือนกัน","ro":"Wee-laa mii khon thǎam wâa pai nǎi, kâw pen kaan thák-thaai mǔean kan."},{"fr":"De rien, ça me fait plaisir de t'aider.","tgt":"ไม่เป็นไรครับ ผมยินดีช่วย","ro":"Mâi pen rai khráp, phǒm yin-dii chûai."}],"tip":{"title":"Les expressions du quotidien : « kin khâao rúe yang, mâi pen rai, jai yen yen »","example":"Calme-toi, on va trouver une solution ensemble. — <b>ใจเย็นๆ</b> เดี๋ยวเราช่วยกันหาทางออก","body":"Trois formules reviennent sans cesse dans la bouche des Thaïs. « Kin khâao rúe yang », mot à mot manger, riz, ou, pas encore, signifie as-tu mangé ?, mais c'est surtout une façon chaleureuse de dire bonjour ; on répond simplement « kin láew », j'ai mangé. « Mâi pen rai », ne pas, être, quoi, veut dire ce n'est rien, pas de souci ou de rien, et sert à apaiser toutes les petites tensions. « Jai yen yen », cœur frais, frais, veut dire calme-toi, car pour les Thaïs un cœur frais est un cœur patient, tandis qu'un cœur chaud, « jai ráwn », est impatient. Retenez l'image : ici, la sagesse est fraîche et la colère est chaude.","exampleRo":"Jai yen yen, dǐao rao chûai kan hǎa thaang-àwk.","lit":"cœur · frais · frais · [bientôt] · nous · s'entraider · chercher · chemin · sortie","say":{"Kin khâao rúe yang":"กินข้าวหรือยัง","kin láew":"กินแล้ว","Mâi pen rai":"ไม่เป็นไร","Jai yen yen":"ใจเย็นๆ","jai ráwn":"ใจร้อน","kin khâao rúe yang, mâi pen rai, jai yen yen":"กินข้าวหรือยัง ไม่เป็นไร ใจเย็นๆ"}}},{"title":"Ville ou campagne ?","phrases":[{"fr":"Tu préfères vivre à Bangkok ou en province ?","tgt":"คุณชอบอยู่กรุงเทพหรือต่างจังหวัดมากกว่ากัน","ro":"Khun châwp yùu krung-thêep rǔe tàang-jang-wàt mâak kwàa kan?"},{"fr":"En ville, on trouve plus d'occasions de travailler.","tgt":"ในเมืองมีโอกาสทำงานมากกว่า","ro":"Nai mueang mii oo-kàat tham-ngaan mâak kwàa."},{"fr":"Mais la vie y coûte de plus en plus cher.","tgt":"แต่ค่าครองชีพก็แพงขึ้นเรื่อยๆ","ro":"Tàe khâa khrawng-chîip kâw phaeng khûen rûeai rûeai."},{"fr":"Mes amis de Chiang Mai vivent beaucoup plus tranquillement.","tgt":"เพื่อนที่เชียงใหม่ใช้ชีวิตสบายกว่ามาก","ro":"Phûean thîi chiang-mài chái chii-wít sà-baai kwàa mâak."},{"fr":"En province, tout le monde se connaît.","tgt":"ที่ต่างจังหวัด ทุกคนรู้จักกันหมด","ro":"Thîi tàang-jang-wàt, thúk khon rúu-jàk kan mòt."},{"fr":"Beaucoup de jeunes quittent leur village pour travailler à Bangkok.","tgt":"วัยรุ่นหลายคนออกจากหมู่บ้านมาทำงานที่กรุงเทพ","ro":"Wai-rûn lǎai khon àwk jàak mùu-bâan maa tham-ngaan thîi krung-thêep."},{"fr":"Pendant les fêtes, ils rentrent tous dans leur région natale.","tgt":"ช่วงเทศกาล พวกเขากลับบ้านเกิดกันหมด","ro":"Chûang thêet-sà-kaan, phûak khǎo klàp bâan-kòet kan mòt."},{"fr":"À ce moment-là, Bangkok devient étonnamment calme.","tgt":"ตอนนั้นกรุงเทพเงียบผิดปกติ","ro":"Tawn nán krung-thêep ngîap phìt pòk-kà-tì."},{"fr":"Un jour, j'aimerais avoir une petite maison à la campagne.","tgt":"สักวันผมอยากมีบ้านหลังเล็กๆที่ต่างจังหวัด","ro":"Sák wan phǒm yàak mii bâan lǎng lék lék thîi tàang-jang-wàt."},{"fr":"Chaque mode de vie a ses avantages et ses inconvénients.","tgt":"ชีวิตแต่ละแบบก็มีข้อดีข้อเสีย","ro":"Chii-wít tàe-lá bàep kâw mii khâw-dii khâw-sǐa."}]},{"title":"Tradition et modernité","phrases":[{"fr":"On dirait que Bangkok change chaque année.","tgt":"ดูเหมือนกรุงเทพจะเปลี่ยนไปทุกปี","ro":"Duu mǔean krung-thêep jà plìan pai thúk pii."},{"fr":"On dirait que les jeunes passent la journée sur leur téléphone.","tgt":"ดูเหมือนวัยรุ่นจะอยู่กับโทรศัพท์ทั้งวัน","ro":"Duu mǔean wai-rûn jà yùu kàp thoo-rá-sàp tháng wan."},{"fr":"Pourtant, ils saluent encore les aînés en joignant les mains.","tgt":"แต่พวกเขาก็ยังไหว้ผู้ใหญ่อยู่","ro":"Tàe phûak khǎo kâw yang wâi phûu-yài yùu."},{"fr":"On dirait que les vieilles traditions résistent plutôt bien.","tgt":"ดูเหมือนประเพณีเก่าๆยังอยู่ได้ดี","ro":"Duu mǔean prà-phee-nii kào kào yang yùu dâai dii."},{"fr":"Aujourd'hui, les marchés flottants ressemblent plutôt à des attractions pour touristes.","tgt":"ตลาดน้ำตอนนี้ดูเหมือนสถานที่ท่องเที่ยวมากกว่า","ro":"Tà-làat náam tawn-níi duu mǔean sà-thǎan-thîi thâwng-thîao mâak kwàa."},{"fr":"Ma grand-mère achète encore ses légumes au marché du matin.","tgt":"ยายผมยังซื้อผักที่ตลาดเช้าอยู่","ro":"Yaai phǒm yang súe phàk thîi tà-làat cháao yùu."},{"fr":"Mon neveu, lui, commande tout en ligne.","tgt":"ส่วนหลานผมสั่งทุกอย่างทางออนไลน์","ro":"Sùan lǎan phǒm sàng thúk yàang thaang awn-lai."},{"fr":"On dirait que ces deux mondes vivent ensemble sans problème.","tgt":"ดูเหมือนสองโลกนี้อยู่ด้วยกันได้โดยไม่มีปัญหา","ro":"Duu mǔean sǎwng lôok níi yùu dûai kan dâai dooi mâi mii pan-hǎa."},{"fr":"Les gratte-ciel se dressent à côté des vieilles maisons en bois.","tgt":"ตึกสูงตั้งอยู่ข้างบ้านไม้หลังเก่า","ro":"Tùek sǔung tâng yùu khâang bâan máai lǎng kào."},{"fr":"C'est justement ce mélange qui rend la Thaïlande si fascinante.","tgt":"ความผสมผสานแบบนี้แหละที่ทำให้เมืองไทยน่าสนใจมาก","ro":"Khwaam phà-sǒm-phà-sǎan bàep níi làe thîi tham hâi mueang thai nâa-sǒn-jai mâak."}],"tip":{"title":"« Duu mǔean » : on dirait que","example":"On dirait que Bangkok change chaque année. — <b>ดูเหมือน</b>กรุงเทพจะเปลี่ยนไปทุกปี","body":"Pour donner une impression sans l'affirmer, on place « duu mǔean » en tête de phrase : « duu », regarder ou sembler, et « mǔean », comme, donc mot à mot cela regarde comme. Dans « duu mǔean krung-thêep jà plìan pai thúk pii », on dit on dirait que Bangkok change chaque année ; le petit « jà » adoucit encore l'affirmation. De la même façon, « duu mǔean fǒn jà tòk » veut dire on dirait qu'il va pleuvoir. Devant un simple adjectif, « duu » suffit : « khǎo duu nùeai », il a l'air fatigué. Attention au ton montant de « mǔean », qui remonte comme une question en français. Pour retenir, pensez à « duu », je regarde, et « mǔean », ça ressemble.","exampleRo":"Duu mǔean krung-thêep jà plìan pai thúk pii.","lit":"regarder · comme · Bangkok · [futur] · changer · aller · chaque · année","say":{"Duu mǔean":"ดูเหมือน","duu mǔean":"ดูเหมือน","duu":"ดู","mǔean":"เหมือน","duu mǔean krung-thêep jà plìan pai thúk pii":"ดูเหมือนกรุงเทพจะเปลี่ยนไปทุกปี","jà":"จะ","duu mǔean fǒn jà tòk":"ดูเหมือนฝนจะตก","khǎo duu nùeai":"เขาดูเหนื่อย"}}},{"title":"Parler de cuisine","phrases":[{"fr":"Les Thaïs parlent de nourriture presque toute la journée.","tgt":"คนไทยคุยเรื่องอาหารแทบทั้งวัน","ro":"Khon thai khui rûeang aa-hǎan thâep tháng wan."},{"fr":"La cuisine thaïe doit être à la fois acide, sucrée, salée et pimentée.","tgt":"อาหารไทยต้องมีทั้งเปรี้ยว หวาน เค็ม เผ็ด","ro":"Aa-hǎan thai tâwng mii tháng prîao, wǎan, khem, phèt."},{"fr":"Une collègue m'a appris à préparer la salade de papaye verte.","tgt":"เพื่อนร่วมงานสอนผมทำส้มตำ","ro":"Phûean rûam ngaan sǎwn phǒm tham sôm-tam."},{"fr":"Le secret, c'est de bien piler l'ail et le piment.","tgt":"เคล็ดลับคือต้องตำกระเทียมกับพริกให้ละเอียด","ro":"Khlét-láp khue tâwng tam krà-thiam kàp phrík hâi lá-ìat."},{"fr":"Au début, je ne supportais pas du tout le piment.","tgt":"ตอนแรกผมกินเผ็ดไม่ได้เลย","ro":"Tawn râek phǒm kin phèt mâi dâai loei."},{"fr":"Maintenant, je commande même mes plats très épicés.","tgt":"ตอนนี้ผมสั่งเผ็ดมากด้วยซ้ำ","ro":"Tawn-níi phǒm sàng phèt mâak dûai-sám."},{"fr":"Dans l'Isan, on mange le riz gluant avec les doigts.","tgt":"ที่อีสานคนกินข้าวเหนียวด้วยมือ","ro":"Thîi ii-sǎan khon kin khâao-nǐao dûai mue."},{"fr":"La cuisine de rue est souvent meilleure que celle des restaurants chics.","tgt":"อาหารริมทางมักอร่อยกว่าร้านหรูๆ","ro":"Aa-hǎan rim thaang mák à-ròi kwàa ráan rǔu rǔu."},{"fr":"Partager les plats au milieu de la table, c'est très chaleureux.","tgt":"การแบ่งกันกินกับข้าวกลางโต๊ะเป็นอะไรที่อบอุ่นมาก","ro":"Kaan bàeng kan kin kàp-khâao klaang tó pen à-rai thîi òp-ùn mâak."},{"fr":"Je rêve d'ouvrir un jour un petit restaurant thaï en France.","tgt":"ผมฝันว่าสักวันจะเปิดร้านอาหารไทยเล็กๆที่ฝรั่งเศส","ro":"Phǒm fǎn wâa sák wan jà pòet ráan aa-hǎan thai lék lék thîi fà-ràng-sèet."}]},{"title":"Le massage thaï, un vrai loisir","phrases":[{"fr":"Ici, se faire masser n'est pas un luxe, c'est un loisir.","tgt":"ที่นี่การนวดไม่ใช่ของหรูหรา แต่เป็นงานอดิเรก","ro":"Thîi-nîi kaan nûat mâi châi khǎwng rǔu-rǎa, tàe pen ngaan à-dì-rèek."},{"fr":"Je vais me faire masser une fois par semaine.","tgt":"ผมไปนวดอาทิตย์ละครั้งครับ","ro":"Phǒm pai nûat aa-thít lá khráng khráp."},{"fr":"Une heure de massage coûte environ trois cents bahts.","tgt":"นวดหนึ่งชั่วโมงราคาประมาณสามร้อยบาท","ro":"Nûat nùeng chûa-moong raa-khaa prà-maan sǎam ráwy bàat."},{"fr":"Le massage thaï est bien plus énergique qu'on ne le pense.","tgt":"นวดแผนไทยแรงกว่าที่คิดไว้เยอะ","ro":"Nûat phǎen thai raeng kwàa thîi khít wái yóe."},{"fr":"La masseuse m'a demandé si ça me faisait mal.","tgt":"หมอนวดถามผมว่าเจ็บไหม","ro":"Mǎw nûat thǎam phǒm wâa jèp mái."},{"fr":"Pas trop fort, s'il vous plaît, j'ai mal au dos.","tgt":"เบาๆหน่อยนะครับ ผมปวดหลัง","ro":"Bao bao nàwy ná khráp, phǒm pùat lǎng."},{"fr":"Après une séance, je me sens complètement détendu.","tgt":"นวดเสร็จแล้วผมรู้สึกผ่อนคลายมาก","ro":"Nûat sèt láew phǒm rúu-sùek phàwn-khlaai mâak."},{"fr":"Les masseurs étudient des mois avant de devenir vraiment bons.","tgt":"หมอนวดต้องเรียนหลายเดือนกว่าจะเก่ง","ro":"Mǎw nûat tâwng rian lǎai duean kwàa jà kèng."},{"fr":"Parfois, avec un ami, on se fait masser les pieds après le marché.","tgt":"บางทีผมกับเพื่อนไปนวดเท้ากันหลังเดินตลาด","ro":"Baang-thii phǒm kàp phûean pai nûat tháao kan lǎng doen tà-làat."},{"fr":"C'est ma façon préférée de terminer une longue semaine.","tgt":"นี่คือวิธีปิดท้ายสัปดาห์ที่ผมชอบที่สุด","ro":"Nîi khue wí-thii pìt-tháai sàp-daa thîi phǒm châwp thîi-sùt."}]},{"title":"Les obligations du quotidien","phrases":[{"fr":"Demain, je suis obligé de me lever à cinq heures.","tgt":"พรุ่งนี้ผมจำเป็นต้องตื่นตีห้าครับ","ro":"Phrûng-níi phǒm jam-pen tâwng tùen tii hâa khráp."},{"fr":"Je ne peux pas venir ce soir, je suis obligé de finir mon travail.","tgt":"ผมไปคืนนี้ไม่ได้ เพราะจำเป็นต้องทำงานให้เสร็จ","ro":"Phǒm pai khuen-níi mâi dâai, phráw jam-pen tâwng tham-ngaan hâi sèt."},{"fr":"Est-ce que je suis vraiment obligé de porter un costume ?","tgt":"ผมจำเป็นต้องใส่สูทไหมครับ","ro":"Phǒm jam-pen tâwng sài sùut mái khráp?"},{"fr":"Non, ce n'est pas nécessaire, une chemise suffit.","tgt":"ไม่จำเป็นหรอก ใส่เสื้อเชิ้ตก็พอ","ro":"Mâi jam-pen ràwk, sài sûea-chóet kâw phaw."},{"fr":"Dans la vie, on est parfois obligé de faire des choix difficiles.","tgt":"ในชีวิต บางครั้งเราจำเป็นต้องเลือกเรื่องยากๆ","ro":"Nai chii-wít, baang khráng rao jam-pen tâwng lûeak rûeang yâak yâak."},{"fr":"Ma petite sœur a dû quitter Chiang Mai pour son travail.","tgt":"น้องสาวผมจำเป็นต้องย้ายออกจากเชียงใหม่เพราะงาน","ro":"Náwng-sǎao phǒm jam-pen tâwng yáai àwk jàak chiang-mài phráw ngaan."},{"fr":"Tu n'es pas obligé de tout comprendre tout de suite.","tgt":"ไม่จำเป็นต้องเข้าใจทุกอย่างทันทีหรอก","ro":"Mâi jam-pen tâwng khâo-jai thúk yàang than-thii ràwk."},{"fr":"Parfois, il faut savoir dire non poliment.","tgt":"บางครั้งก็ต้องรู้จักปฏิเสธอย่างสุภาพ","ro":"Baang khráng kâw tâwng rúu-jàk pà-tì-sèet yàang sù-phâap."},{"fr":"Est-il nécessaire de réserver à l'avance ?","tgt":"จำเป็นต้องจองล่วงหน้าไหมครับ","ro":"Jam-pen tâwng jawng lûang-nâa mái khráp?"},{"fr":"Ce n'est pas obligatoire, mais c'est mieux de réserver.","tgt":"ไม่จำเป็นครับ แต่จองไว้ก่อนก็ดีกว่า","ro":"Mâi jam-pen khráp, tàe jawng wái kàwn kâw dii kwàa."}],"tip":{"title":"« Jam-pen tâwng » : être obligé de","example":"Demain, je suis obligé de me lever à cinq heures. — พรุ่งนี้ผม<b>จำเป็นต้อง</b>ตื่นตีห้าครับ","body":"Vous connaissez déjà « tâwng », devoir, placé devant le verbe. En ajoutant « jam-pen », nécessaire, on obtient « jam-pen tâwng », être obligé de, une obligation plus forte et plus formelle, imposée par les circonstances. Décomposons « phrûng-níi phǒm jam-pen tâwng tùen tii hâa khráp » : demain, je, nécessaire, devoir, se réveiller, cinq heures du matin, politesse. À la forme négative, on dit « mâi jam-pen tâwng », pas besoin de, ou simplement « mâi jam-pen », ce n'est pas nécessaire, une réponse très utile et très polie. Pour poser la question, on ajoute « mái » à la fin : « jam-pen tâwng jawng mái », faut-il réserver ? Astuce : « jam-pen » annonce la contrainte, et « tâwng » introduit l'action à faire.","exampleRo":"Phrûng-níi phǒm jam-pen tâwng tùen tii hâa khráp.","lit":"demain · je (homme) · nécessaire · devoir · se réveiller · cinq heures du matin · [politesse]","say":{"Jam-pen tâwng":"จำเป็นต้อง","tâwng":"ต้อง","jam-pen":"จำเป็น","jam-pen tâwng":"จำเป็นต้อง","phrûng-níi phǒm jam-pen tâwng tùen tii hâa khráp":"พรุ่งนี้ผมจำเป็นต้องตื่นตีห้าครับ","mâi jam-pen tâwng":"ไม่จำเป็นต้อง","mâi jam-pen":"ไม่จำเป็น","mái":"ไหม","jam-pen tâwng jawng mái":"จำเป็นต้องจองไหม"}}},{"title":"Jai yen : garder son calme","phrases":[{"fr":"Les Thaïs apprécient les gens qui restent calmes.","tgt":"คนไทยชอบคนที่ใจเย็น","ro":"Khon thai châwp khon thîi jai yen."},{"fr":"S'énerver devant les autres, c'est perdre la face.","tgt":"การโมโหต่อหน้าคนอื่นทำให้เสียหน้า","ro":"Kaan moo-hǒo tàw nâa khon ùen tham hâi sǐa nâa."},{"fr":"Quand je suis pressé, je deviens vite impatient.","tgt":"เวลาผมรีบ ผมจะใจร้อนง่าย","ro":"Wee-laa phǒm rîip, phǒm jà jai ráwn ngâai."},{"fr":"Un ami m'a dit de respirer profondément et de sourire.","tgt":"เพื่อนบอกให้ผมหายใจลึกๆแล้วยิ้ม","ro":"Phûean bàwk hâi phǒm hǎai-jai lúek lúek láew yím."},{"fr":"Un sourire règle beaucoup de petits conflits.","tgt":"รอยยิ้มช่วยแก้ปัญหาเล็กๆได้หลายเรื่อง","ro":"Rawy-yím chûai kâe pan-hǎa lék lék dâai lǎai rûeang."},{"fr":"Hier, un chauffeur de taxi s'est perdu pendant une demi-heure.","tgt":"เมื่อวานคนขับแท็กซี่หลงทางครึ่งชั่วโมง","ro":"Mûea-waan khon khàp tháek-sîi lǒng thaang khrûeng chûa-moong."},{"fr":"Avant, je me serais fâché, mais cette fois je suis resté zen.","tgt":"เมื่อก่อนผมคงโกรธ แต่ครั้งนี้ผมใจเย็นได้","ro":"Mûea-kàwn phǒm khong kròot, tàe khráng níi phǒm jai yen dâai."},{"fr":"Rester calme ne veut pas dire tout accepter.","tgt":"การใจเย็นไม่ได้แปลว่าต้องยอมทุกอย่าง","ro":"Kaan jai yen mâi dâai plae wâa tâwng yawm thúk yàang."},{"fr":"On peut exprimer son désaccord avec douceur.","tgt":"เราบอกว่าไม่เห็นด้วยแบบนุ่มนวลได้","ro":"Rao bàwk wâa mâi hěn dûai bàep nûm-nuan dâai."},{"fr":"Ce pays m'a appris à être plus patient.","tgt":"ประเทศนี้สอนให้ผมใจเย็นขึ้น","ro":"Prà-thêet níi sǎwn hâi phǒm jai yen khûen."}]},{"title":"Songkran, la fête de l'eau","phrases":[{"fr":"En avril, il fait terriblement chaud à Bangkok.","tgt":"เดือนเมษายนกรุงเทพร้อนมาก","ro":"Duean mee-sǎa-yon krung-thêep ráwn mâak."},{"fr":"C'est justement l'époque de Songkran, le nouvel an thaï.","tgt":"ช่วงนั้นพอดีเป็นสงกรานต์ ปีใหม่ไทย","ro":"Chûang nán phaw-dii pen sǒng-kraan, pii mài thai."},{"fr":"Pendant trois jours, tout le monde s'arrose dans la rue.","tgt":"สามวันนั้นทุกคนสาดน้ำกันบนถนน","ro":"Sǎam wan nán thúk khon sàat náam kan bon thà-nǒn."},{"fr":"Même des inconnus t'aspergent en riant.","tgt":"แม้แต่คนแปลกหน้าก็สาดน้ำใส่เราแล้วหัวเราะ","ro":"Máe-tàe khon plàek-nâa kâw sàat náam sài rao láew hǔa-ráw."},{"fr":"Mets ton téléphone dans un sac en plastique.","tgt":"ใส่โทรศัพท์ไว้ในถุงพลาสติกนะ","ro":"Sài thoo-rá-sàp wái nai thǔng phláat-sà-tìk ná."},{"fr":"Les jeunes versent aussi de l'eau parfumée sur les mains des aînés.","tgt":"วัยรุ่นรดน้ำอบที่มือผู้ใหญ่ด้วย","ro":"Wai-rûn rót náam-òp thîi mue phûu-yài dûai."},{"fr":"C'est une façon de leur montrer du respect.","tgt":"เป็นการแสดงความเคารพต่อผู้ใหญ่","ro":"Pen kaan sà-daeng khwaam khao-róp tàw phûu-yài."},{"fr":"Cette fête mélange amusement, famille et tradition.","tgt":"เทศกาลนี้มีทั้งความสนุก ครอบครัว และประเพณี","ro":"Thêet-sà-kaan níi mii tháng khwaam sà-nùk, khrâwp-khrua, láe prà-phee-nii."},{"fr":"La première fois, je suis rentré chez moi trempé jusqu'aux os.","tgt":"ครั้งแรกผมกลับบ้านเปียกทั้งตัว","ro":"Khráng râek phǒm klàp bâan pìak tháng tua."},{"fr":"C'était sans doute le jour le plus amusant de mon année.","tgt":"วันนั้นน่าจะเป็นวันที่สนุกที่สุดของปีเลย","ro":"Wan nán nâa-jà pen wan thîi sà-nùk thîi-sùt khǎwng pii loei."}]},{"title":"L'amitié à la thaïe","phrases":[{"fr":"Se faire des amis thaïs demande un peu de temps.","tgt":"การมีเพื่อนคนไทยต้องใช้เวลาหน่อย","ro":"Kaan mii phûean khon thai tâwng chái wee-laa nàwy."},{"fr":"Au début, ils sont souvent timides avec les étrangers.","tgt":"ตอนแรกพวกเขามักจะเขินกับคนต่างชาติ","ro":"Tawn râek phûak khǎo mák jà khǒen kàp khon tàang-châat."},{"fr":"Parler un peu thaï ouvre immédiatement les cœurs.","tgt":"พูดไทยได้นิดหน่อยก็ทำให้คนเปิดใจทันที","ro":"Phûut thai dâai nít-nàwy kâw tham hâi khon pòet jai than-thii."},{"fr":"Mes amis m'appellent par un surnom depuis le premier jour.","tgt":"เพื่อนๆเรียกชื่อเล่นผมตั้งแต่วันแรก","ro":"Phûean phûean rîak chûe-lên phǒm tâng-tàe wan râek."},{"fr":"Ici, presque tout le monde a un petit surnom mignon.","tgt":"ที่นี่เกือบทุกคนมีชื่อเล่นสั้นๆน่ารัก","ro":"Thîi-nîi kùeap thúk khon mii chûe-lên sân sân nâa-rák."},{"fr":"Un vrai ami, c'est quelqu'un de généreux qui aide sans rien attendre.","tgt":"เพื่อนแท้คือคนที่มีน้ำใจ ช่วยโดยไม่หวังอะไร","ro":"Phûean tháe khue khon thîi mii nám-jai, chûai dooi mâi wǎng à-rai."},{"fr":"Quand j'étais malade, mes voisins m'ont apporté de la soupe.","tgt":"ตอนผมป่วย เพื่อนบ้านเอาต้มจืดมาให้","ro":"Tawn phǒm pùai, phûean-bâan ao tôm-jùet maa hâi."},{"fr":"Je n'oublierai jamais cette gentillesse.","tgt":"ผมจะไม่มีวันลืมน้ำใจนี้","ro":"Phǒm jà mâi mii wan luem nám-jai níi."},{"fr":"Entre amis, on invite souvent à tour de rôle.","tgt":"เพื่อนกันมักผลัดกันเลี้ยง","ro":"Phûean kan mák phlàt kan líang."},{"fr":"Nos différences de culture n'ont jamais été un problème entre nous.","tgt":"ความต่างทางวัฒนธรรมไม่เคยเป็นปัญหาสำหรับเรา","ro":"Khwaam tàang thaang wát-thá-ná-tham mâi khoei pen pan-hǎa sǎm-ràp rao."}]},{"title":"Les proverbes thaïs","phrases":[{"fr":"Les Thaïs aiment glisser un proverbe dans la conversation.","tgt":"คนไทยชอบใส่สุภาษิตในบทสนทนา","ro":"Khon thai châwp sài sù-phaa-sìt nai bòt-sǒn-thá-naa."},{"fr":"Quand l'eau monte, dépêche-toi de puiser.","tgt":"น้ำขึ้นให้รีบตัก","ro":"Náam khûen hâi rîip tàk."},{"fr":"Cela veut dire qu'il faut saisir les occasions.","tgt":"หมายความว่าต้องรีบคว้าโอกาสไว้","ro":"Mǎai-khwaam wâa tâwng rîip khwáa oo-kàat wái."},{"fr":"Doucement, et l'on obtient une belle serpe.","tgt":"ช้าๆได้พร้าเล่มงาม","ro":"Cháa cháa dâai phráa lêm ngaam."},{"fr":"Mon professeur me cite ce proverbe chaque fois que je veux aller trop vite.","tgt":"ครูพูดสุภาษิตนี้ทุกครั้งที่ผมอยากรีบเกินไป","ro":"Khruu phûut sù-phaa-sìt níi thúk khráng thîi phǒm yàak rîip koen pai."},{"fr":"Dix bouches qui racontent ne valent pas un œil qui voit.","tgt":"สิบปากว่าไม่เท่าตาเห็น","ro":"Sìp pàak wâa mâi thâo taa hěn."},{"fr":"Autrement dit, mieux vaut voir les choses de ses propres yeux.","tgt":"พูดง่ายๆคือ เห็นด้วยตาตัวเองดีกว่า","ro":"Phûut ngâai ngâai khue, hěn dûai taa tua-eng dii kwàa."},{"fr":"En entrant dans la ville des yeux plissés, il faut plisser les yeux aussi.","tgt":"เข้าเมืองตาหลิ่วต้องหลิ่วตาตาม","ro":"Khâo mueang taa lìu tâwng lìu taa taam."},{"fr":"C'est-à-dire qu'il faut suivre les coutumes de l'endroit où l'on vit.","tgt":"คือต้องทำตามธรรมเนียมของที่ที่เราอยู่","ro":"Khue tâwng tham taam tham-niam khǎwng thîi thîi rao yùu."},{"fr":"Placer un proverbe au bon moment fait toujours sourire.","tgt":"ใช้สุภาษิตถูกจังหวะทีไร คนฟังก็ยิ้มทุกที","ro":"Chái sù-phaa-sìt thùuk jang-wà thii-rai, khon fang kâw yím thúk thii."}],"tip":{"title":"Les proverbes thaïs","example":"Quand l'eau monte, dépêche-toi de puiser. — <b>น้ำขึ้นให้รีบตัก</b>","body":"Les Thaïs adorent les proverbes courts, souvent tirés de la vie à la campagne, de l'eau et des rizières. « Náam khûen hâi rîip tàk », eau, monter, qu'on, se dépêcher, puiser, signifie qu'il faut profiter d'une occasion tant qu'elle se présente. « Cháa cháa dâai phráa lêm ngaam », lentement, on obtient une belle serpe, rappelle que la patience donne du beau travail. « Sìp pàak wâa mâi thâo taa hěn », dix bouches qui parlent ne valent pas un œil qui voit, ressemble à notre il faut le voir pour le croire. Ces formules sont rythmées, presque chantées : répétez-les à voix haute en marquant bien chaque syllabe et chaque ton. Placé au bon moment, un proverbe vous vaudra toujours un grand sourire.","exampleRo":"Náam khûen hâi rîip tàk.","lit":"eau · monter · [faire que] · se dépêcher · puiser","say":{"Náam khûen hâi rîip tàk":"น้ำขึ้นให้รีบตัก","Cháa cháa dâai phráa lêm ngaam":"ช้าๆ ได้พร้าเล่มงาม","Sìp pàak wâa mâi thâo taa hěn":"สิบปากว่าไม่เท่าตาเห็น"}}},{"title":"Débattre du tourisme","phrases":[{"fr":"Le tourisme fait vivre des millions de Thaïs.","tgt":"การท่องเที่ยวทำให้คนไทยหลายล้านคนมีรายได้","ro":"Kaan thâwng-thîao tham hâi khon thai lǎai láan khon mii raai-dâai."},{"fr":"Mais certaines îles sont devenues beaucoup trop fréquentées.","tgt":"แต่เกาะบางแห่งคนเยอะเกินไปแล้ว","ro":"Tàe kàw baang hàeng khon yóe koen pai láew."},{"fr":"Aux îles Phi Phi, on a déjà dû fermer une plage pour protéger la nature.","tgt":"ที่พีพีเคยต้องปิดชายหาดเพื่อรักษาธรรมชาติ","ro":"Thîi phii-phii khoei tâwng pìt chaai-hàat phûea rák-sǎa tham-má-châat."},{"fr":"Je pense qu'il faudrait un tourisme plus respectueux de la nature.","tgt":"ผมคิดว่าควรมีการท่องเที่ยวที่เคารพธรรมชาติมากขึ้น","ro":"Phǒm khít wâa khuan mii kaan thâwng-thîao thîi khao-róp tham-má-châat mâak khûen."},{"fr":"Les voyageurs devraient aussi découvrir les petites provinces.","tgt":"นักท่องเที่ยวควรไปเที่ยวจังหวัดเล็กๆด้วย","ro":"Nák-thâwng-thîao khuan pai thîao jang-wàt lék lék dûai."},{"fr":"Nan et Loei sont encore peu connues des étrangers.","tgt":"จังหวัดน่านกับจังหวัดเลยยังไม่ค่อยมีคนต่างชาติรู้จัก","ro":"Jang-wàt nâan kàp jang-wàt loei yang mâi khâwy mii khon tàang-châat rúu-jàk."},{"fr":"Là-bas, les habitants accueillent les visiteurs avec beaucoup de chaleur.","tgt":"คนที่นั่นต้อนรับแขกอย่างอบอุ่น","ro":"Khon thîi-nân tâwn-ráp khàek yàang òp-ùn."},{"fr":"Certains disent que le tourisme abîme la culture locale.","tgt":"บางคนบอกว่าการท่องเที่ยวทำลายวัฒนธรรมท้องถิ่น","ro":"Baang khon bàwk wâa kaan thâwng-thîao tham-laai wát-thá-ná-tham tháwng-thìn."},{"fr":"D'autres pensent qu'il aide à la faire connaître.","tgt":"แต่บางคนคิดว่ามันช่วยให้คนรู้จักวัฒนธรรมมากขึ้น","ro":"Tàe baang khon khít wâa man chûai hâi khon rúu-jàk wát-thá-ná-tham mâak khûen."},{"fr":"Comme souvent, la vérité se trouve sans doute entre les deux.","tgt":"เหมือนหลายๆเรื่อง ความจริงน่าจะอยู่ตรงกลาง","ro":"Mǔean lǎai lǎai rûeang, khwaam-jing nâa-jà yùu trong klaang."}]},{"title":"La famille et les aînés","phrases":[{"fr":"En Thaïlande, on respecte beaucoup les personnes âgées.","tgt":"ที่เมืองไทย คนเคารพผู้สูงอายุมาก","ro":"Thîi mueang thai, khon khao-róp phûu-sǔung-aa-yú mâak."},{"fr":"Dans beaucoup de familles, trois générations vivent ensemble.","tgt":"หลายบ้านมีสามรุ่นอยู่ด้วยกัน","ro":"Lǎai bâan mii sǎam rûn yùu dûai kan."},{"fr":"Les grands-parents aident souvent à élever les petits-enfants.","tgt":"ปู่ย่าตายายมักช่วยเลี้ยงหลาน","ro":"Pùu yâa taa yaai mák chûai líang lǎan."},{"fr":"Les enfants envoient de l'argent à leurs parents chaque mois.","tgt":"ลูกๆส่งเงินให้พ่อแม่ทุกเดือน","ro":"Lûuk lûuk sòng ngoen hâi phâw mâe thúk duean."},{"fr":"Pour eux, c'est une façon naturelle de dire merci.","tgt":"สำหรับพวกเขา นี่เป็นวิธีขอบคุณที่เป็นธรรมชาติ","ro":"Sǎm-ràp phûak khǎo, nîi pen wí-thii khàwp-khun thîi pen tham-má-châat."},{"fr":"On appelle même les inconnus « grand frère » ou « tante ».","tgt":"คนไทยเรียกคนแปลกหน้าว่าพี่หรือป้าด้วย","ro":"Khon thai rîak khon plàek-nâa wâa phîi rǔe pâa dûai."},{"fr":"C'est comme si tout le monde faisait partie de la même famille.","tgt":"เหมือนทุกคนเป็นครอบครัวเดียวกัน","ro":"Mǔean thúk khon pen khrâwp-khrua diao kan."},{"fr":"Ma belle-mère m'a tout de suite traité comme son fils.","tgt":"แม่ยายดูแลผมเหมือนลูกชายตั้งแต่แรก","ro":"Mâe-yaai duu-lae phǒm mǔean lûuk-chaai tâng-tàe râek."},{"fr":"En France, les familles vivent plus souvent séparées.","tgt":"ที่ฝรั่งเศส ครอบครัวมักอยู่แยกกันมากกว่า","ro":"Thîi fà-ràng-sèet, khrâwp-khrua mák yùu yâek kan mâak kwàa."},{"fr":"Les deux modèles ont chacun leurs qualités.","tgt":"ทั้งสองแบบก็มีข้อดีของมัน","ro":"Tháng sǎwng bàep kâw mii khâw-dii khǎwng man."}]},{"title":"Les petits plaisirs du quotidien","phrases":[{"fr":"Un café glacé au coin de la rue, et me voilà heureux.","tgt":"กาแฟเย็นร้านหัวมุมทำให้ผมมีความสุข","ro":"Kaa-fae yen ráan hǔa-mum tham hâi phǒm mii khwaam-sùk."},{"fr":"J'adore me promener au marché de nuit le vendredi.","tgt":"ผมชอบเดินตลาดกลางคืนวันศุกร์มาก","ro":"Phǒm châwp doen tà-làat klaang-khuen wan sùk mâak."},{"fr":"Les fruits sont délicieux ici, surtout la mangue.","tgt":"ผลไม้ที่นี่อร่อยมาก โดยเฉพาะมะม่วง","ro":"Phǒn-lá-máai thîi-nîi à-ròi mâak, dooi chà-phó má-mûang."},{"fr":"Le soir, j'aime regarder le coucher de soleil au bord du fleuve.","tgt":"ตอนเย็นผมชอบดูพระอาทิตย์ตกริมแม่น้ำ","ro":"Tawn yen phǒm châwp duu phrá-aa-thít tòk rim mâe-náam."},{"fr":"Une petite sieste après le déjeuner, rien de plus agréable.","tgt":"งีบหลังกินข้าวเที่ยงนี่สบายที่สุด","ro":"Ngîip lǎng kin khâao thîang nîi sà-baai thîi-sùt."},{"fr":"Bavarder avec la vendeuse de soupe de nouilles me met de bonne humeur.","tgt":"คุยกับป้าขายก๋วยเตี๋ยวทำให้ผมอารมณ์ดี","ro":"Khui kàp pâa khǎai kǔai-tǐao tham hâi phǒm aa-rom dii."},{"fr":"Il pleut, alors on reste à la maison à regarder un film.","tgt":"ฝนตก เลยอยู่บ้านดูหนังกัน","ro":"Fǒn tòk, loei yùu bâan duu nǎng kan."},{"fr":"Le bruit de la pluie sur le toit me détend.","tgt":"เสียงฝนตกบนหลังคาทำให้ผมผ่อนคลาย","ro":"Sǐang fǒn tòk bon lǎng-khaa tham hâi phǒm phàwn-khlaai."},{"fr":"Le bonheur se cache souvent dans les choses toutes simples.","tgt":"ความสุขมักซ่อนอยู่ในเรื่องง่ายๆ","ro":"Khwaam-sùk mák sâwn yùu nai rûeang ngâai ngâai."},{"fr":"Il suffit parfois de ralentir un peu pour le remarquer.","tgt":"บางทีแค่ช้าลงหน่อยก็จะเห็นมัน","ro":"Baang-thii khâe cháa long nàwy kâw jà hěn man."}]},{"title":"Rêves et projets d'avenir","phrases":[{"fr":"Dans cinq ans, je pense que je vivrai encore ici.","tgt":"อีกห้าปีผมคิดว่าคงยังอยู่ที่นี่","ro":"Ìik hâa pii phǒm khít wâa khong yang yùu thîi-nîi."},{"fr":"J'aimerais parler thaï aussi bien qu'un Thaï.","tgt":"ผมอยากพูดไทยให้เก่งเหมือนคนไทย","ro":"Phǒm yàak phûut thai hâi kèng mǔean khon thai."},{"fr":"Ma femme rêve d'ouvrir une petite maison d'hôtes à Pai.","tgt":"ภรรยาผมฝันอยากเปิดโฮมสเตย์เล็กๆที่ปาย","ro":"Phan-rá-yaa phǒm fǎn yàak pòet hoom-sà-tee lék lék thîi paai."},{"fr":"Nous mettons de l'argent de côté chaque mois pour ce projet.","tgt":"เราเก็บเงินทุกเดือนเพื่อโครงการนี้","ro":"Rao kèp ngoen thúk duean phûea khroong-kaan níi."},{"fr":"Bien sûr, rien ne garantit que ça marchera.","tgt":"แน่นอนว่าไม่มีอะไรรับประกันว่าจะสำเร็จ","ro":"Nâe-nawn wâa mâi mii à-rai ráp-prà-kan wâa jà sǎm-rèt."},{"fr":"Mais si on n'essaie pas, on le regrettera toute notre vie.","tgt":"แต่ถ้าไม่ลอง เราคงเสียดายไปทั้งชีวิต","ro":"Tàe thâa mâi lawng, rao khong sǐa-daai pai tháng chii-wít."},{"fr":"Mes parents viendront peut-être nous rendre visite l'an prochain.","tgt":"ปีหน้าพ่อแม่ผมอาจจะมาเยี่ยม","ro":"Pii nâa phâw mâe phǒm àat-jà maa yîam."},{"fr":"Je voudrais leur faire découvrir la vraie Thaïlande.","tgt":"ผมอยากพาพวกท่านไปดูเมืองไทยจริงๆ","ro":"Phǒm yàak phaa phûak thân pai duu mueang thai jing jing."},{"fr":"L'avenir est incertain, mais j'ai confiance.","tgt":"อนาคตไม่แน่นอน แต่ผมมั่นใจ","ro":"À-naa-khót mâi nâe-nawn, tàe phǒm mân-jai."},{"fr":"Petit à petit, comme aiment dire les gens d'ici.","tgt":"ค่อยเป็นค่อยไป อย่างที่คนที่นี่ชอบพูด","ro":"Khâwy pen khâwy pai, yàang thîi khon thîi-nîi châwp phûut."}]},{"title":"Un au revoir difficile","phrases":[{"fr":"Mon meilleur ami thaï déménage à Khon Kaen la semaine prochaine.","tgt":"เพื่อนสนิทคนไทยของผมจะย้ายไปขอนแก่นอาทิตย์หน้า","ro":"Phûean sà-nìt khon thai khǎwng phǒm jà yáai pai khǎwn-kàen aa-thít nâa."},{"fr":"Nous avons organisé une petite fête d'adieu chez moi.","tgt":"เราจัดงานเลี้ยงส่งเล็กๆที่บ้านผม","ro":"Rao jàt ngaan líang sòng lék lék thîi bâan phǒm."},{"fr":"Chacun a apporté un plat à partager.","tgt":"ทุกคนเอาอาหารมาแบ่งกันกิน","ro":"Thúk khon ao aa-hǎan maa bàeng kan kin."},{"fr":"On a ri toute la soirée en racontant nos souvenirs.","tgt":"เราหัวเราะกันทั้งคืนตอนเล่าความหลัง","ro":"Rao hǔa-ráw kan tháng khuen tawn lâo khwaam-lǎng."},{"fr":"Au moment de partir, personne ne voulait dire au revoir.","tgt":"ตอนจะกลับ ไม่มีใครอยากบอกลา","ro":"Tawn jà klàp, mâi mii khrai yàak bàwk laa."},{"fr":"Tu vas beaucoup me manquer, tu sais.","tgt":"ผมจะคิดถึงคุณมากนะ","ro":"Phǒm jà khít-thǔeng khun mâak ná."},{"fr":"Ce n'est pas un adieu, on se reverra bientôt.","tgt":"นี่ไม่ใช่การจากกันตลอดไป แล้วเจอกันใหม่นะ","ro":"Nîi mâi châi kaan jàak kan tà-làwt pai, láew joe kan mài ná."},{"fr":"Khon Kaen n'est qu'à une heure d'avion de Bangkok.","tgt":"ขอนแก่นห่างจากกรุงเทพแค่ชั่วโมงเดียวถ้านั่งเครื่องบิน","ro":"Khǎwn-kàen hàang jàak krung-thêep khâe chûa-moong diao thâa nâng khrûeang-bin."},{"fr":"On s'est promis de s'appeler au moins une fois par mois.","tgt":"เราสัญญากันว่าจะโทรหากันอย่างน้อยเดือนละครั้ง","ro":"Rao sǎn-yaa kan wâa jà thoo hǎa kan yàang náwy duean lá khráng."},{"fr":"Prends bien soin de toi là-bas, et bonne chance.","tgt":"ไปอยู่ที่นั่นดูแลตัวเองดีๆนะ โชคดีครับ","ro":"Pai yùu thîi-nân duu-lae tua-eng dii dii ná, chôok dii khráp."}]},{"title":"Rester en contact malgré la distance","phrases":[{"fr":"Aujourd'hui, c'est facile de garder le lien avec ses amis.","tgt":"ทุกวันนี้การติดต่อกับเพื่อนเป็นเรื่องง่าย","ro":"Thúk wan-níi kaan tìt-tàw kàp phûean pen rûeang ngâai."},{"fr":"On s'envoie des photos de nos repas presque tous les jours.","tgt":"เราส่งรูปอาหารที่กินให้กันแทบทุกวัน","ro":"Rao sòng rûup aa-hǎan thîi kin hâi kan thâep thúk wan."},{"fr":"Il m'a envoyé une vidéo de son nouveau quartier.","tgt":"เขาส่งวิดีโอแถวบ้านใหม่มาให้ผมดู","ro":"Khǎo sòng wí-dii-oo thǎeo bâan mài maa hâi phǒm duu."},{"fr":"Il a l'air heureux là-bas, ça me rassure.","tgt":"เขาดูมีความสุขที่นั่น ผมก็สบายใจ","ro":"Khǎo duu mii khwaam-sùk thîi-nân, phǒm kâw sà-baai-jai."},{"fr":"Les appels vidéo ne remplacent pas un vrai repas ensemble.","tgt":"วิดีโอคอลแทนการกินข้าวด้วยกันจริงๆไม่ได้","ro":"Wí-dii-oo khawn thaen kaan kin khâao dûai kan jing jing mâi dâai."},{"fr":"Je compte aller le voir pendant les vacances du Nouvel An.","tgt":"ผมตั้งใจจะไปหาเขาช่วงปีใหม่","ro":"Phǒm tâng-jai jà pai hǎa khǎo chûang pii mài."},{"fr":"Il m'a déjà promis de me faire goûter la cuisine de sa mère.","tgt":"เขาสัญญาแล้วว่าจะให้ผมชิมฝีมือแม่เขา","ro":"Khǎo sǎn-yaa láew wâa jà hâi phǒm chim fǐi-mue mâe khǎo."},{"fr":"Les vrais amis restent proches du cœur, même de loin.","tgt":"เพื่อนแท้ถึงจะอยู่ไกลก็ยังใกล้ใจ","ro":"Phûean tháe thǔeng jà yùu klai kâw yang klâi jai."},{"fr":"Même éloignés, on sait qu'on peut compter l'un sur l'autre.","tgt":"ถึงจะอยู่ห่างกัน เราก็รู้ว่าพึ่งกันได้","ro":"Thǔeng jà yùu hàang kan, rao kâw rúu wâa phûeng kan dâai."},{"fr":"Envoie-moi un message quand tu seras bien arrivé.","tgt":"ถึงแล้วส่งข้อความมาบอกด้วยนะ","ro":"Thǔeng láew sòng khâw-khwaam maa bàwk dûai ná."}]},{"title":"Regard en arrière sur mon parcours en thaï","phrases":[{"fr":"Quand j'ai commencé le thaï, les tons me faisaient peur.","tgt":"ตอนเริ่มเรียนภาษาไทย ผมกลัววรรณยุกต์มาก","ro":"Tawn rôem rian phaa-sǎa thai, phǒm klua wan-ná-yúk mâak."},{"fr":"Je confondais sans arrêt les mots « proche » et « loin ».","tgt":"ผมสับสนคำว่าใกล้กับไกลตลอดเวลา","ro":"Phǒm sàp-sǒn kham wâa klâi kàp klai tà-làwt wee-laa."},{"fr":"Les gens souriaient gentiment chaque fois que je me trompais.","tgt":"คนไทยยิ้มอย่างใจดีทุกครั้งที่ผมพูดผิด","ro":"Khon thai yím yàang jai-dii thúk khráng thîi phǒm phûut phìt."},{"fr":"Personne ne s'est jamais moqué de moi.","tgt":"ไม่เคยมีใครหัวเราะเยาะผมเลย","ro":"Mâi khoei mii khrai hǔa-ráw yáw phǒm loei."},{"fr":"Petit à petit, j'ai commencé à suivre les conversations.","tgt":"ผมค่อยๆเริ่มฟังบทสนทนารู้เรื่อง","ro":"Phǒm khâwy khâwy rôem fang bòt-sǒn-thá-naa rúu rûeang."},{"fr":"Aujourd'hui, je peux plaisanter avec mes amis en thaï.","tgt":"ตอนนี้ผมพูดตลกกับเพื่อนเป็นภาษาไทยได้แล้ว","ro":"Tawn-níi phǒm phûut tà-lòk kàp phûean pen phaa-sǎa thai dâai láew."},{"fr":"Savoir parler thaï a complètement changé ma vie ici.","tgt":"การพูดไทยได้ทำให้ชีวิตผมที่นี่เปลี่ยนไปเลย","ro":"Kaan phûut thai dâai tham hâi chii-wít phǒm thîi-nîi plìan pai loei."},{"fr":"Les gens me voient maintenant comme un ami, pas comme un touriste.","tgt":"ตอนนี้คนมองผมเป็นเพื่อน ไม่ใช่นักท่องเที่ยว","ro":"Tawn-níi khon mawng phǒm pen phûean, mâi châi nák-thâwng-thîao."},{"fr":"Quand je repense à mes débuts, je suis assez fier de moi.","tgt":"พอนึกถึงตอนเริ่มต้น ผมก็ภูมิใจในตัวเองพอสมควร","ro":"Phaw núek thǔeng tawn rôem-tôn, phǒm kâw phuum-jai nai tua-eng phaw sǒm-khuan."},{"fr":"Il me reste encore beaucoup à apprendre, et c'est tant mieux.","tgt":"ผมยังต้องเรียนอีกเยอะ และนั่นก็เป็นเรื่องดี","ro":"Phǒm yang tâwng rian ìik yóe, láe nân kâw pen rûeang dii."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Ce dernier module nous a fait parler de culture et d'amitié.","tgt":"บทเรียนชุดสุดท้ายนี้ทำให้เราได้พูดเรื่องวัฒนธรรมและมิตรภาพ","ro":"Bòt-rian chút sùt-tháai níi tham hâi rao dâai phûut rûeang wát-thá-ná-tham láe mít-trà-phâap."},{"fr":"Nous savons maintenant parler de plaisir, de bien-être et de calme.","tgt":"ตอนนี้เราพูดเรื่องความสนุก ความสบาย และความใจเย็นได้แล้ว","ro":"Tawn-níi rao phûut rûeang khwaam sà-nùk, khwaam sà-baai, láe khwaam jai yen dâai láew."},{"fr":"Nous avons même appris plusieurs proverbes thaïs.","tgt":"เรายังได้เรียนสุภาษิตไทยอีกหลายบท","ro":"Rao yang dâai rian sù-phaa-sìt thai ìik lǎai bòt."},{"fr":"Depuis les toutes premières salutations, quel chemin parcouru !","tgt":"จากคำทักทายแรกๆ เรามาไกลมากเลย","ro":"Jàak kham thák-thaai râek râek, rao maa klai mâak loei."},{"fr":"Les trois niveaux du parcours sont maintenant terminés.","tgt":"การเรียนทั้งสามระดับจบลงแล้ว","ro":"Kaan rian tháng sǎam rá-dàp jòp long láew."},{"fr":"Le thaï n'est plus une langue lointaine pour nous.","tgt":"ภาษาไทยไม่ใช่เรื่องไกลตัวสำหรับเราอีกต่อไป","ro":"Phaa-sǎa thai mâi châi rûeang klai tua sǎm-ràp rao ìik tàw pai."},{"fr":"Continuez à parler thaï chaque jour, même un tout petit peu.","tgt":"พูดภาษาไทยทุกวันต่อไปนะ ถึงจะนิดเดียวก็ยังดี","ro":"Phûut phaa-sǎa thai thúk wan tàw pai ná, thǔeng jà nít diao kâw yang dii."},{"fr":"Chaque conversation sera une nouvelle petite victoire.","tgt":"ทุกบทสนทนาจะเป็นชัยชนะเล็กๆครั้งใหม่","ro":"Thúk bòt-sǒn-thá-naa jà pen chai-chá-ná lék lék khráng mài."},{"fr":"Bravo, et merci d'avoir fait tout ce chemin avec nous.","tgt":"ยินดีด้วยและขอบคุณที่เดินทางมาด้วยกันจนถึงตรงนี้","ro":"Yin-dii dûai láe khàwp-khun thîi doen-thaang maa dûai kan jon thǔeng trong-níi."},{"fr":"À bientôt, et bonne chance pour la suite en Thaïlande !","tgt":"แล้วเจอกันใหม่ ขอให้โชคดีที่เมืองไทยนะครับ","ro":"Láew joe kan mài, khǎw hâi chôok dii thîi mueang thai ná khráp."}]}]}]}];
